/// Exact shared shape of the two powers which subscribe to
/// `AfterBlockCleared`. The listener array preserves acquisition order; each
/// active keyed power must occur once, and no inactive or unrelated power may
/// occur. Toric deliberately has no generic scalar slot because its duration
/// and retained Decimal live together in the cold keyed record.
pub(crate) fn delayed_block_power_state_is_exact(state: &HotState) -> bool {
    let generic = match state.powers.get(PowerId::BlockNextTurn) {
        None => false,
        Some(slot) if slot.wire == SlotWire::Int && slot.value > 0 => true,
        Some(_) => return false,
    };
    // #3159: Self-Forming Clay's own power is a third keyed listener with the
    // same positive-Int shape as BlockNextTurn.
    let clay = match state.powers.get(PowerId::SelfFormingClayPower) {
        None => false,
        Some(slot) if slot.wire == SlotWire::Int && slot.value > 0 => true,
        Some(_) => return false,
    };
    if state.powers.get(PowerId::ToricToughness).is_some()
        || !state.fanouts.toric_toughness_state_is_exact()
    {
        return false;
    }
    let toric = state.fanouts.toric_toughness().is_some();
    let order = state.fanouts.after_block_cleared_order();
    order.len() == usize::from(generic) + usize::from(toric) + usize::from(clay)
        && order.iter().enumerate().all(|(index, power)| {
            !order[..index].contains(power)
                && match power {
                    PowerId::BlockNextTurn => generic,
                    PowerId::SelfFormingClayPower => clay,
                    PowerId::ToricToughness => toric,
                    _ => false,
                }
        })
}

