#[inline(never)]
fn card_keywords_are_inert(row: &CardRow) -> bool {
    let forge_program_is_exact = !row
        .steps
        .iter()
        .any(|step| step.kind == StepKind::ForgeFamilyExact)
        || crate::steps::regent_forge::forge_writer_program_is_supported(row);
    let unit_c_ally_step = row.steps.iter().any(|step| {
        matches!(
            step.kind,
            StepKind::BlazeExact
                | StepKind::DemonicShieldBlockExact
                | StepKind::BelieveInYouExact
                | StepKind::ConstellationExact
                | StepKind::CoordinateExact
                | StepKind::FadeExact
                | StepKind::EnergySurgeExact
                | StepKind::InterceptExact
                | StepKind::LiftExact
                | StepKind::MimicExact
                | StepKind::RallyExact
                | StepKind::ImitationLearningExact
                | StepKind::HuddleUpExact
                | StepKind::PlotExact
                | StepKind::OneForAllExact
                | StepKind::BladeSymphonyExact
                | StepKind::GlimpseBeyondExact
                | StepKind::TutorExact
        )
    });
    let unit_c_ally_program = matches!(row.target_type, "AnyAlly" | "AllAllies")
        && unit_c_ally_step
        && (!row
            .steps
            .iter()
            .any(|step| step.kind == StepKind::GlimpseBeyondExact)
            || glimpse_beyond_program_is_supported(row))
        && crate::content_tables::card_row(row.id, row.upgrade) == Some(row)
        && (!row
            .steps
            .iter()
            .any(|step| step.kind == StepKind::DemonicShieldBlockExact)
            || crate::steps::ironclad_uncommon::demonic_shield_program_is_exact(row));
    let largesse_program = row.target_type == "AnyAlly"
        && matches!(row.steps, [step] if step.kind == StepKind::LargesseExact)
        && matches!(row.id, CardId::Largesse)
        && matches!(row.upgrade, 0 | 1)
        && crate::content_tables::card_row(row.id, row.upgrade) == Some(row);
    let body_owned_random_enemy = body_owned_random_enemy_program_is_supported(row);
    let dynamic_shiv = row.id == CardId::Shiv && row.target_type == "Dynamic";
    let dynamic_sovereign_blade = row.id == CardId::SovereignBlade
        && row.target_type == "Dynamic"
        && matches!(row.steps, [step] if step.kind == StepKind::SovereignBladeExact);
    // These rows have card-class listeners outside their OnPlay program.
    // Howl and Bombardment have exact AutoPost/AutoPre bodies; every other
    // auto-phase/generated-card hook remains refused, so a
    // generated leaf cannot become admissible merely because its ordinary
    // step program is implemented.
    //
    // Batch139 is no longer in this deny set: `_record_card_play_finished` (frozen Python, deleted #2827), `_validate_batch139_self_return_state`,
    // and `_complete_batch139_before_hand_draw_card_listeners`
    // now have an exact physical-UID Rust quotient and listener tail.
    //
    let has_unmodeled_card_behavior = UNMODELED_PHYSICAL_CARD_LISTENER_DENY_SET.contains(&row.id)
        || (row.id == CardId::Melancholy && !melancholy_program_is_supported(row))
        || (row.id == CardId::Midnight && !midnight_exhaust_program_is_supported(row))
        || (row.id == CardId::RightHandHand && !right_hand_hand_late_program_is_supported(row))
        || (row.id == CardId::Bombardment && !bombardment_program_is_supported(row))
        || (row.id == CardId::MakeItSo && !make_it_so_late_program_is_supported(row))
        || (matches!(row.id, CardId::KinglyKick | CardId::Pinpoint)
            && !physical_cost_listener_program_is_supported(row))
        || (row.id == CardId::RocketPunch
            && !rocket_punch_generated_listener_program_is_supported(row))
        || (matches!(row.id, CardId::ShiningStrike | CardId::ParticleWall)
            && !card_virtual_result_program_is_supported(row))
        || (row.id == CardId::HowlFromBeyond && !howl_from_beyond_program_is_supported(row))
        || (row.id == CardId::IAmInvincible && !i_am_invincible_program_is_supported(row));
    let has_generated_select = row.steps.iter().any(|step| step.kind == StepKind::Select);
    // Purity and Seeker Strike own their native selector inside one exact
    // body step rather than carrying the generated `select` verb. Keep the
    // keyword admission derived from the complete step shape: widening the
    // manifest or mutating either operand cannot silently make a selecting
    // row ordinary.
    let has_body_owned_select = body_owned_select_program_is_supported(row);
    let expertise_shape_is_exact = !row
        .steps
        .iter()
        .any(|step| step.kind == StepKind::ExpertiseExact)
        || matches!(row.steps, [step] if matches!(
            (row.id, row.upgrade, step.kind, step.args),
            (CardId::Expertise, 0, StepKind::ExpertiseExact, [Arg::I(2)])
                | (CardId::Expertise, 1, StepKind::ExpertiseExact, [Arg::I(3)])
        ));
    let hand_cap_shape_is_exact = !row
        .steps
        .iter()
        .any(|step| step.kind == StepKind::HandCapBody)
        || crate::steps::hand_cap::program_is_supported(row);
    let ordinary = row.playable
        && forge_program_is_exact
        && (!unit_c_ally_step || unit_c_ally_program)
        && !has_unmodeled_card_behavior
        && (!row.ethereal
            || (matches!(row.id, CardId::SweepingGaze) && body_owned_random_enemy)
            || static_ethereal_body_program_is_supported(row))
        && (!row.sly || static_sly_body_program_is_supported(row))
        && row.selects == (has_generated_select || has_body_owned_select)
        && expertise_shape_is_exact
        && hand_cap_shape_is_exact
        && (!has_generated_select || generated_select_program_is_supported(row))
        && !row.is_status_curse
        && row.star_cost >= -1
        && (!row.star_x || star_x_program_is_supported(row))
        && (row.play_condition.is_none() || dynamic_play_condition_program_is_supported(row))
        && row.on_draw_energy_loss == 0
        && (row.heal == 0
            || matches!(row.id, CardId::NotYet)
                && matches!(row.upgrade, 0 | 1)
                && crate::content_tables::card_row(row.id, row.upgrade) == Some(row))
        && row.turn_end_dmg == 0
        && row.turn_end_hp_loss == 0
        && row.turn_end_weak == 0
        && row.turn_end_frail == 0
        && !row.turn_end_hp_loss_hand
        && row.cost >= 0
        && (matches!(row.target_type, "Self" | "AnyEnemy" | "AllEnemies")
            || unit_c_ally_program
            || largesse_program
            || body_owned_random_enemy
            || dynamic_shiv
            || dynamic_sovereign_blade)
        && row.targeted
            == (matches!(row.target_type, "AnyEnemy" | "AnyAlly")
                || dynamic_shiv
                || dynamic_sovereign_blade);
    let infection = row.id == CardId::Infection
        && row.upgrade == 0
        && !row.playable
        && row.cost == -1
        && row.steps.is_empty()
        && row.pool.is_none()
        && row.star_cost == -1
        && !row.star_x
        && row.play_condition.is_none()
        && !row.ethereal
        && row.on_draw_energy_loss == 0
        && !row.is_power
        && !row.is_skill
        && !row.strike_tag
        && row.tags.is_empty()
        && !row.exhausts
        && !row.targeted
        && row.target_type == "None"
        && row.heal == 0
        && row.turn_end_dmg == 3
        && row.turn_end_hp_loss == 0
        && row.turn_end_weak == 0
        && row.turn_end_frail == 0
        && !row.turn_end_hp_loss_hand
        && !row.is_status_curse
        && !row.selects
        && !row.innate
        && !row.x_cost
        && !row.retain
        && !row.sly;
    let turn_end_affliction = matches!(row.id, CardId::Doubt | CardId::Shame)
        && row.upgrade == 0
        && !row.playable
        && row.cost == -1
        && row.steps.is_empty()
        && row.pool.is_none()
        && row.star_cost == -1
        && !row.star_x
        && row.play_condition.is_none()
        && !row.ethereal
        && row.on_draw_energy_loss == 0
        && !row.is_power
        && !row.is_skill
        && !row.strike_tag
        && row.tags.is_empty()
        && !row.exhausts
        && !row.targeted
        && row.target_type == "None"
        && row.heal == 0
        && row.turn_end_dmg == 0
        && row.turn_end_hp_loss == 0
        && matches!((row.turn_end_weak, row.turn_end_frail), (1, 0) | (0, 1))
        && !row.turn_end_hp_loss_hand
        && !row.is_status_curse
        && !row.selects
        && !row.innate
        && !row.x_cost
        && !row.retain
        && !row.sly;
    // `_has_turn_end_in_hand_effect` (frozen Python, deleted #2827) and
    // `_run_turn_end_in_hand_body` admit exactly the generated Debt+0
    // row. Equality against the registry row keeps every keyword and the
    // complete one-step `(turn_end_gold_loss_exact, 10)` program mechanical:
    // any mutated field stays a CardKeyword refusal.
    let debt = row.id == CardId::Debt
        && row.upgrade == 0
        && crate::content_tables::card_row(CardId::Debt, 0) == Some(row);
    // Python card_effective_keywords derives native Unplayable/Ethereal
    // from this exact generated Curse row. Existing play rejection and the
    // ordinary-Ethereal hand drain own both behaviors; local keyword payloads
    // cannot manufacture this admission grant (#2453).
    // v0.111.0 DLL 9cb4f1ad: AscendersBane::.ctor 0xd7f14,
    // get_CanonicalKeywords 0xd7f2b, get_MaxUpgradeLevel 0xd7f28.
    let ascenders_bane = row.id == CardId::AscendersBane
        && row.upgrade == 0
        && crate::content_tables::card_row(CardId::AscendersBane, 0) == Some(row);
    // Normality (#2876). v0.111.0 DLL 9cb4f1ad: `.ctor` 0xe66bf fixes cost
    // -1, Curse type/rarity, target None; `get_CanonicalKeywords` 0xe66e6 is
    // `[Unplayable]`; `get_MaxUpgradeLevel` 0xe66e3 is 0; the type declares
    // no OnPlay, no turn-end body and no pile listener. Its only in-combat
    // behavior is `ShouldPlay` 0xe6754, the three-started-play cap owned by
    // `engine::play::normality_blocks_card_plays` for both `can_play` and
    // AutoPlay; `get_CanonicalVars` 0xe66f0 and `get_ShouldGlowRedInternal`
    // 0xe66cd are display-only. Registry equality pins the complete row.
    let normality = row.id == CardId::Normality
        && row.upgrade == 0
        && crate::content_tables::card_row(CardId::Normality, 0) == Some(row);
    // Fixed generated-Status closure. Equality with the generated registry
    // row pins all immutable keywords and the complete body: Wound and Soot
    // are inert,
    // Dazed/Void use the ordinary-Ethereal path, Burn/Toxic/Wither use the
    // generic turn-end damage reader, Debris/Slimed/Toxic use ordinary
    // play/exhaust, and Void's late on-draw Energy loss is in `engine::draw`.
    // Toxic and Wither join this exact set only because R52E's generated
    // Colorless Entropy descendant can transform a live Status into either
    // canonical L0 row; no other Status/Curse row is admitted by this clause.
    let fixed_status = matches!(
        row.id,
        CardId::Wound
            | CardId::Dazed
            | CardId::Debris
            | CardId::Burn
            | CardId::Void
            | CardId::Slimed
            | CardId::Soot
            | CardId::Toxic
            | CardId::Wither
    ) && row.upgrade == 0
        && crate::content_tables::card_row(row.id, 0) == Some(row);
    // Soul Fysh's generated Beckon+0 is the only admitted unblockable
    // turn-end HP-loss leaf. Equality pins its complete immutable keyword
    // shape; the turn wrapper owns Hand -> Play -> Discard/terminal routing.
    let beckon = row.id == CardId::Beckon
        && row.upgrade == 0
        && crate::content_tables::card_row(CardId::Beckon, 0) == Some(row);
    // The Insatiable's generated Frantic Escape+0 is the sole playable
    // Status/Curse carve-out. Registry equality pins its Self target, cost,
    // and one-step body; the whole-catalog walk makes that generated leaf
    // executable before LIQUIFY can be admitted.
    let frantic_escape = row.id == CardId::FranticEscape
        && row.upgrade == 0
        && crate::content_tables::card_row(CardId::FranticEscape, 0) == Some(row);
    // Lethality is the first ordinary playable Ethereal card admitted. Its
    // CardPlayFinished history is represented, and registry equality pins its
    // complete Power/Self/no-target shape plus exact 50/75 body.
    let lethality = row.id == CardId::Lethality
        && matches!(row.upgrade, 0 | 1)
        && crate::content_tables::card_row(row.id, row.upgrade) == Some(row);
    // Void Form L0 is statically Ethereal; L1 is already ordinary. Registry
    // equality pins the complete Self-target Power rows and their sole
    // `(void_form, 2)` body, while the shared Ethereal completion/side-end
    // machinery owns the keyword lifecycle.
    let void_form = row.id == CardId::VoidForm
        && matches!(row.upgrade, 0 | 1)
        && crate::content_tables::card_row(row.id, row.upgrade) == Some(row);
    // Creative AI generates Echo Form L0, whose native Ethereal keyword is
    // consumed by the already-modeled ordinary turn-end/history path. L1 is
    // non-Ethereal and remains in the ordinary clause above. Registry
    // equality pins the complete Power/Self one-step body for both routes.
    let echo_form_ethereal = row.id == CardId::EchoForm
        && row.upgrade == 0
        && crate::content_tables::card_row(row.id, row.upgrade) == Some(row);
    let static_ethereal_attack = static_ethereal_attack_program_is_supported(row);
    let static_sly_attack = static_sly_attack_program_is_supported(row);
    let inert_unplayable = inert_unplayable_program_is_supported(row);
    let spore_mind = spore_mind_program_is_supported(row);
    let bad_luck = bad_luck_program_is_supported(row);
    let enthralled = enthralled_program_is_supported(row);
    let regret = regret_program_is_supported(row);
    ordinary
        || infection
        || turn_end_affliction
        || debt
        || ascenders_bane
        || normality
        || fixed_status
        || beckon
        || frantic_escape
        || lethality
        || void_form
        || echo_form_ethereal
        || static_ethereal_attack
        || static_sly_attack
        || inert_unplayable
        || spore_mind
        || bad_luck
        || enthralled
        || regret
}

/// Exact current-build Unplayable Curse/Quest rows with no in-combat body.
///
/// Current `sts2.dll` SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`. Each
/// row's `get_CanonicalKeywords` returns keyword enum `4` (Unplayable), alone
/// or beside a keyword whose entire effect is outside combat. None of these
/// types declares `OnPlay` or any CardModel callback the combat loop fires;
/// the four that declare a map-, room-, event- or rest-site callback are
/// named individually below:
///
/// - `Clumsy::get_CanonicalKeywords` `0xdb469` → `[Unplayable, Ethereal]`;
///   `.ctor` `0xdb45b`, `get_MaxUpgradeLevel` `0xdb47e`. No other method.
///   The Ethereal half is the same shared turn-end exhaust Ascender's Bane
///   already rides.
/// - `Greed::get_CanonicalKeywords` `0xe1973` → `[Eternal, Unplayable]`;
///   `.ctor` `0xe195f`, `get_CanBeGeneratedByModifiers` `0xe1970` (false),
///   `get_MaxUpgradeLevel` `0xe196d`. No other method.
/// - `Injury::get_CanonicalKeywords` `0xe3558` → `[Unplayable]`; `.ctor`
///   `0xe3547`, `get_MaxUpgradeLevel` `0xe3555`. No other method.
/// - `CurseOfTheBell::get_CanonicalKeywords` `0xdc5cc` → `[Eternal,
///   Unplayable]`; `.ctor` `0xdc5b8`, `get_CanBeGeneratedByModifiers`
///   `0xdc5c6`, `get_MaxUpgradeLevel` `0xdc5c9`. No other method.
/// - `Writhe::get_CanonicalKeywords` `0xf07d0` → `[Innate, Unplayable]`;
///   `.ctor` `0xf07bf`, `get_MaxUpgradeLevel` `0xf07cd`. No other method.
/// - `Decay::get_CanonicalKeywords` `0xdd034` → `[Unplayable]`, with
///   `get_HasTurnEndInHandEffect` `0xdd03c` true and
///   `Decay/<OnTurnEndInHand>d__9::MoveNext` RVA `0x3976b0` exactly
///   `CreatureCmd::Damage(Owner.Creature, DynamicVars.Damage, card, null)`.
///   That is instruction-for-instruction the already-admitted
///   `Burn/<OnTurnEndInHand>d__11` program, and `Decay::get_CanonicalVars`
///   `0xdd020` declares the same `DamageVar(2, 12)` as `Burn::get_CanonicalVars`
///   `0xda43e`, so the generic `turn_end_dmg` reader in `engine::turn` owns it.
/// - `SpoilsMap::get_CanonicalKeywords` `0xec662` → `[Unplayable]`. Its only
///   behavior is map generation: `ModifyGeneratedMap` `0xec69b` and
///   `ModifyGeneratedMapLate` `0xec6cc` both early-return unless the card is
///   live in a `Deck` pile (PileType `6`) on the matching act, and
///   `AfterCreated` `0xec692` only seeds `_spoilsActIndex`. `get_CanonicalVars`
///   `0xec651` is a `GoldVar` read by the map reward, never by combat.
/// - `Dowsing::get_CanonicalKeywords` `0xde0eb` → `[Unplayable]`. Its
///   `BeforeRoomEntered` `0xde13c` and `set_RoomsEntered` `0xde108` run on map
///   traversal, not inside a combat; `get_CanonicalVars` `0xde0d4` is the
///   `Rooms` counter those drive.
/// - `ByrdonisEgg::get_CanonicalKeywords` `0xda665` → `[Unplayable]`; its only
///   other behavior is `TryModifyRestSiteOptions` `0xda66d`, which adds a
///   `HatchRestSiteOption` at a rest site.
/// - `PoorSleep::get_CanonicalKeywords` `0xe7f4f` → `[Unplayable, Retain]`;
///   `.ctor` `0xe7f3b`, `get_MaxUpgradeLevel` `0xe7f4c`. No other callback.
///   The shared effective-Retain hand drain already preserves this card.
///
/// - Folly::.ctor (0xe0631), get_CanonicalKeywords (0xe0645), and
///   get_MaxUpgradeLevel (0xe0642): Unplayable/Innate/Ethereal/Eternal,
///   no callbacks or OnPlay body. Innate has completed before this boundary;
///   the ordinary Ethereal drain owns its only in-combat effect.
///
/// - `LanternKey::get_CanonicalKeywords` `0xe3f59` → `[Unplayable]`
///   (IL_0001 `ldc.i4.4`); `.ctor` `0xe3f48` passes cost `-1`, `CardType` `6`
///   (Quest), `CardRarity` `10` (Quest), target type `1` (Self) — the same
///   base-constructor operands as `SpoilsMap::.ctor` `0xec639` — and
///   `get_MaxUpgradeLevel` `0xe3f56` is 0. Its only two callbacks are
///   map/event hooks gated on act index 2: `ModifyUnknownMapPointRoomTypes`
///   `0xe3f64` (IL_000c..IL_001d compare `RunState.CurrentActIndex`, else
///   IL_001f returns the input set unchanged) and `ModifyNextEvent`
///   `0xe3f95`. Neither fires inside a combat. A whole-DLL operand scan for
///   the `LanternKey` TypeDef (rid 1912) and every TypeSpec/MethodSpec
///   instantiating it finds only model registration
///   (`AbstractModelSubtypes::.cctor`, `QuestCardPool::GenerateAllCards`
///   `0xf253f`) and the two events that grant or consume it
///   (`TheLanternKey::Fight` `0xd0320`, `WarHistorianRepy`'s
///   `get_ShouldGetSecondReward`/`RemoveFirstLanternKey`/
///   `RemoveLanternKeysForSecondChoice` lambdas and
///   `InitialUnlockCage`/`InitialUnlockChest`) — no combat reader (#3091).
///
/// - `Guilty::get_CanonicalKeywords` `0xe1adb` → `[Unplayable]` (IL_0001
///   `ldc.i4.4`); `.ctor` `0xe1ab3` passes cost `-1`, Curse/Curse, target
///   None; `get_MaxUpgradeLevel` `0xe1ac1` is 0 (#2561). Its only callback is
///   `AfterCombatEnd` (`<AfterCombatEnd>d__13::MoveNext` RVA `0x3a2f6c`),
///   which leaves at IL_001d-IL_0037 unless the card's pile is the Deck
///   (PileType `6`) — a combat-pile copy never passes — and otherwise bumps
///   `CombatsSeen` and removes the deck card at five (IL_003c-IL_0065),
///   after the combat. `get_CanonicalVars` `0xe1ac4` / `set_CombatsSeen`
///   `0xe1aeb` only drive that out-of-combat counter.
///
/// Every one of these generated rows is therefore an inert pile resident for
/// the whole fight: unplayable, un-targetable, no OnPlay steps, and no
/// turn-end payload other than Decay's shared damage reader. Registry equality
/// pins each complete immutable row — a mutated keyword, cost or turn-end field
/// stays a `CardKeyword` refusal rather than inheriting this grant.
fn inert_unplayable_program_is_supported(row: &CardRow) -> bool {
    matches!(
        (row.id, row.upgrade),
        (
            CardId::Clumsy
                | CardId::Greed
                | CardId::Injury
                | CardId::CurseOfTheBell
                | CardId::Writhe
                | CardId::Decay
                | CardId::SpoilsMap
                | CardId::Dowsing
                | CardId::ByrdonisEgg
                | CardId::PoorSleep
                | CardId::Folly
                | CardId::LanternKey
                | CardId::Guilty,
            0
        )
    ) && crate::content_tables::card_row(row.id, row.upgrade) == Some(row)
}

/// Exact current-build Bad Luck row (#2561) — an Unplayable Curse whose only
/// in-combat behavior is Beckon's unblockable turn-end HP loss.
///
/// Current `sts2.dll` SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
///
/// - `BadLuck::.ctor` RVA `0xd8383` (IL_0002-IL_0007) fixes cost `-1`,
///   `CardType` `5` (Curse), `CardRarity` `9` (Curse), target type `0`
///   (None); `get_MaxUpgradeLevel` `0xd8394` is 0.
/// - `get_CanonicalKeywords` `0xd8397` is `[7, 4]` = `[Eternal, Unplayable]`
///   (IL_0009 `ldc.i4.7`, IL_000d `ldc.i4.4`; `CardKeyword` = None, Exhaust,
///   Ethereal, Innate, Unplayable, Retain, Sly, Eternal). Eternal only guards
///   deck removal: in a combat pile `CardModel::get_IsTransformable`
///   (`0x7ce20`) is true even for Eternal cards (see Compact's citation in
///   `steps::defect_uncommon`), and Greed / Curse of the Bell already ride
///   the same keyword through `inert_unplayable_program_is_supported`.
/// - `get_HasTurnEndInHandEffect` `0xd83ac` is true and `get_CanonicalVars`
///   `0xd83af` is one `HpLossVar(13)` (IL_0001 `ldc.i4.s 13`).
/// - `<OnTurnEndInHand>d__11::MoveNext` RVA `0x38ae1c` awaits
///   `Cmd.Wait(0.25)` (IL_0024-IL_002a, presentation only), then
///   `CreatureCmd.Damage(choiceContext, Owner.Creature,
///   DynamicVars.HpLoss.BaseValue, ValueProp 14, this, null)`
///   (IL_0084-IL_00a9). That is Beckon's
///   `<OnTurnEndInHand>d__7::MoveNext` RVA `0x38c0b4` call exactly
///   (`get_HpLoss` IL_0034, `ldc.i4.s 14` IL_003e, `Damage` IL_0042): the
///   same unblockable/unpowered/move HP-loss props from the card as source.
///   The generated `turn_end_hp_loss = 13` therefore rides the existing
///   `engine::turn::run_turn_end_in_hand_cards` HP-loss reader (Hand -> Play,
///   unblockable owner damage, then Discard, or stop on a terminal result).
///
/// `get_CanBeGeneratedByModifiers` `0xd8391` (false) is out-of-combat. The
/// type declares no `OnPlay` and no other CardModel callback. Registry
/// equality pins the complete immutable row.
fn bad_luck_program_is_supported(row: &CardRow) -> bool {
    row.id == CardId::BadLuck
        && row.upgrade == 0
        && crate::content_tables::card_row(CardId::BadLuck, 0) == Some(row)
}

