    fn possess_document() -> CanonicalStateV2 {
        let (mut document, _, _) = parts();
        let template = document.monsters[0].clone();
        document.monsters.clear();
        for (index, (kind, max_hp)) in [
            (MonsterKind::TheLost, crate::engine::monsters::THE_LOST_HP),
            (
                MonsterKind::TheForgotten,
                crate::engine::monsters::THE_FORGOTTEN_HP,
            ),
        ]
        .into_iter()
        .enumerate()
        {
            let mut monster = template.clone();
            monster.insert("kind".to_owned(), Value::from(kind.as_str()));
            monster.insert("hp".to_owned(), Value::from(max_hp));
            monster.insert("max_hp".to_owned(), Value::from(max_hp));
            monster.remove("loop_pos");
            if index > 0 {
                monster.insert("slot".to_owned(), Value::from(index as i64));
                monster.insert("uid".to_owned(), Value::from(index as i64));
            }
            document.monsters.push(monster);
        }
        document
    }

    fn generator_document(
        id: CardId,
        owner: RewardPool,
        spectrum_shift: bool,
        seed: u64,
    ) -> CanonicalStateV2 {
        let (_, mut state, base) = parts();
        state.reward_card_pool = Some(owner);
        state.entropy_card_pool = Some(owner);
        state.set_creative_ai_generation_pool(owner == RewardPool::Defect);
        state.fully_unlocked_card_pool_epochs = true;
        state.set_spectrum_shift_generation_pool(spectrum_shift);
        crate::engine::give_a_real_root_s_current_build_provenance(&mut state);
        let seeded = crate::rng::Xoshiro256StarStar::from_seed(seed);
        state.rng.set(
            RngStream::Generation,
            crate::hot::RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        let mut document = HotBoundary::to_canonical(&state, &base);
        let source = &mut document.piles.get_mut("hand").unwrap()[0];
        source.id = id.as_str().to_owned();
        source.upgrade = 0;
        source.physical_state = None;
        document
    }

    fn first_admitted_generator_document(
        id: CardId,
        owner: RewardPool,
        spectrum_shift: bool,
    ) -> CanonicalStateV2 {
        (0..2048)
            .map(|seed| generator_document(id, owner, spectrum_shift, seed))
            .find(|document| {
                let Ok(catalog) = HotBoundary::catalog_from_canonical(document) else {
                    return false;
                };
                let Ok(state) = HotBoundary::from_canonical(document, &catalog) else {
                    return false;
                };
                admit(document, &state, &catalog).is_ok()
            })
            .unwrap_or_else(|| panic!("no current admitting generation prefix for {}", id.as_str()))
    }

    #[track_caller]
    fn assert_admits(document: &CanonicalStateV2) {
        let catalog = HotBoundary::catalog_from_canonical(document).unwrap();
        let state = HotBoundary::from_canonical(document, &catalog).unwrap();
        assert_eq!(admit(document, &state, &catalog), Ok(()));
    }

    fn refuse(document: &CanonicalStateV2) -> AdmissionRefusal {
        let catalog = HotBoundary::catalog_from_canonical(document).unwrap();
        let state = HotBoundary::from_canonical(document, &catalog).unwrap();
        admit(document, &state, &catalog).unwrap_err()
    }

    /// [`refuse`] for an assertion that a particular name is ABSENT, which an
    /// admitted root satisfies. `refuse` itself keeps its `unwrap_err`,
    /// because most of its callers do require a refusal to exist.
    fn maybe_refuse(document: &CanonicalStateV2) -> Option<AdmissionRefusal> {
        let catalog = HotBoundary::catalog_from_canonical(document).unwrap();
        let state = HotBoundary::from_canonical(document, &catalog).unwrap();
        admit(document, &state, &catalog).err()
    }

    /// A live Entropy document with a seeded `Sel` stream, so that consumer
    /// 2's RNG-liveness conjunct cannot confound the provenance conjunct.
    ///
    /// A Regent owner also publishes `spectrum_shift_generation_pool`, which
    /// the predicate's fifth conjunct requires on that class alone — the same
    /// convention `steps::neutral`'s and `engine::turn`'s owner-sweep fixtures
    /// use (`set_spectrum_shift_generation_pool(owner == Regent)`).
    fn live_entropy_document(owner: RewardPool) -> CanonicalStateV2 {
        let (_, mut state, base) = parts();
        state.reward_card_pool = Some(owner);
        state.entropy_card_pool = Some(owner);
        state.fully_unlocked_card_pool_epochs = true;
        state.set_spectrum_shift_generation_pool(owner == RewardPool::Regent);
        crate::engine::give_a_real_root_s_current_build_provenance(&mut state);
        for (stream, seed) in [(RngStream::Generation, 0u64), (RngStream::Sel, 17)] {
            let seeded = crate::rng::Xoshiro256StarStar::from_seed(seed);
            state.rng.set(
                stream,
                crate::hot::RngStreamState {
                    words: seeded.words,
                    counter: seeded.counter,
                },
            );
        }
        let mut document = HotBoundary::to_canonical(&state, &base);
        let source = &mut document.piles.get_mut("hand").unwrap()[0];
        source.id = CardId::Entropy.as_str().to_owned();
        source.upgrade = 0;
        source.physical_state = None;
        document
    }

    /// #2561: the Entropy closure interns all seventeen combat-generable
    /// curses, and none of them costs the root a `CardKeyword` refusal. This
    /// is the widening PR #3096 had to revert while Bad Luck, Enthralled,
    /// Guilty and Regret were unmodeled.
    #[test]
    fn entropy_closure_interns_the_curse_pool_without_keyword_refusals() {
        let curses = crate::content_tables::SHARED_CARD_POOL_ROWS_V1110
            .iter()
            .find(|(name, _)| *name == "CURSE")
            .map(|(_, rows)| *rows)
            .unwrap();
        assert_eq!(curses.len(), 17);
        for owner in RewardPool::ALL {
            let document = live_entropy_document(owner);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            assert!(catalog.entropy_transform_closure_expands(), "{owner:?}");
            for id in curses {
                assert!(
                    catalog
                        .atom(&crate::catalog::CardIdentity {
                            id: *id,
                            upgrade: 0,
                            enchantment: None,
                        })
                        .is_some(),
                    "{owner:?}: Entropy closure omitted {}",
                    id.as_str()
                );
            }
            assert!(catalog.has_enthralled(), "{owner:?}");
            if let Some(refusal) = maybe_refuse(&document) {
                for id in curses {
                    assert!(
                        !refusal.contains(MissingCapability::CardKeyword(*id)),
                        "{owner:?}: {} refused: {refusal}",
                        id.as_str()
                    );
                }
            }
        }
    }

    /// One predicate, four consumers.
    ///
    /// `crate::catalog::entropy_transform_provenance_is_exact` decides whether
    /// a native Entropy transform can execute in a fight, and four places act
    /// on that answer: the transform itself, admission's named guard, the
    /// boundary closure walk that interns the five-class union, and the
    /// checker that demands the union back. They are pinned together here
    /// because they drifted apart once: the closure expanded on
    /// `owner.is_some()` alone while the transform refused on
    /// `multiplayer_ally_key != 0`, so a party document claimed reachability
    /// for cards Entropy provably could not mint, and an unrelated boundary
    /// guard (`Outbreak` / `teammate_present`) refused the document outright
    /// (#2637).
    ///
    /// Two properties this pins that a reviewer should not have to take on
    /// faith:
    ///
    /// * **No pool is narrowed.** Wherever the predicate holds, the closure
    ///   still spans every character pool — asserted here on one card from
    ///   each of the five classes, none of which is the owner's.
    /// * **No refusal moves later, and none is merely renamed.** Every state
    ///   the predicate rejects is refused at admission by name, and never with
    ///   `"Entropy recursive transform closure"`, which is what would happen
    ///   if consumer 4 had not learned the same gate as consumer 3.
    #[test]
    fn entropy_transform_provenance_agrees_across_all_four_consumers() {
        // One card per character pool, none of them Regent — the owner below.
        let foreign_class_witnesses = [
            (RewardPool::Ironclad, CardId::Anger),
            (RewardPool::Silent, CardId::Backflip),
            (RewardPool::Necrobinder, CardId::Graveblast),
            (RewardPool::Defect, CardId::BallLightning),
        ];
        let owner = RewardPool::Regent;

        // The third column is whether the document still names an owner. With
        // no owner there is no pool to check a closure against, so admission's
        // `"Entropy recursive transform closure"` fires on `is_none_or` alone
        // — behaviour this slice does not change and which is not consumer 4
        // disagreeing with consumer 3.
        /// label, expected predicate, whether an owner is still named, mutation.
        type ProvenanceCase = (&'static str, bool, bool, fn(&mut CanonicalStateV2));
        let cases: [ProvenanceCase; 8] = [
            ("exact solo owner", true, true, |_| {}),
            // #3122: every pool an origin routes to is `GetUnlockedCards`
            // under the recorded profile (`0x112960` IL_0048-IL_005f), so a
            // recorded PARTIAL profile is exact provenance. `DEFECT7_EPOCH`
            // gates none of the four foreign witnesses below.
            ("recorded partial profile", true, true, |document| {
                let profile: Vec<Value> = document.player["splash_unlock_epochs"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .filter(|epoch| epoch.as_str() != Some("DEFECT7_EPOCH"))
                    .cloned()
                    .collect();
                document
                    .player
                    .insert("splash_unlock_epochs".to_owned(), Value::Array(profile));
            }),
            // #3122: native reads no Entropy owner; an ABSENT field (what the
            // Rust opening writes for a Defect, Silent or Necrobinder root) is
            // no missing input. A CONTRADICTORY one is "owner-pool drift".
            ("absent entropy owner", true, true, |document| {
                document.player.remove("entropy_card_pool");
            }),
            // The B2 witness. `main` refused a Regent Entropy root whose
            // document did not publish the Colorless pool
            // (`entropy_owner != Some(Regent) ||
            // state.spectrum_shift_generation_pool()`); six sibling consumers
            // of `owner_generation_pool` still do. Removing the field here
            // must still produce the named refusal at the door — if the
            // conjunct is ever dropped again, this case flips and this test
            // fails.
            (
                "Regent colorless pool unpublished",
                false,
                true,
                |document| {
                    document.player.remove("spectrum_shift_generation_pool");
                },
            ),
            ("party topology", false, true, add_minimal_party),
            ("owner-pool drift", false, true, |document| {
                document
                    .player
                    .insert("entropy_card_pool".to_owned(), json!("ironclad"));
            }),
            ("unpublished unlock profile", false, true, |document| {
                document.player.remove("splash_unlock_epochs");
            }),
            ("absent reward pool", false, false, |document| {
                document.player.remove("reward_card_pool");
            }),
        ];

        for (label, expected, owner_is_named, mutate) in cases {
            let mut document = live_entropy_document(owner);
            mutate(&mut document);

            let catalog = HotBoundary::catalog_from_canonical(&document)
                .unwrap_or_else(|refusal| panic!("{label}: catalog refused: {refusal:?}"));
            // The party case exists at all only because the closure gate keeps
            // `Outbreak` out of a state Entropy can never mint it in; before
            // the gate this `from_canonical` refused with
            // `UnrepresentableValue{Player, "teammate_present", …}`.
            let state = HotBoundary::from_canonical(&document, &catalog)
                .unwrap_or_else(|refusal| panic!("{label}: boundary refused: {refusal:?}"));

            // Consumer 3: the flag the closure walk gated on, read off the
            // built catalog.
            assert_eq!(
                catalog.entropy_transform_closure_expands(),
                expected,
                "{label}: closure expansion disagrees with the predicate"
            );
            // The document's decision and the hot state's decision are the
            // same decision. Consumers 1 and 2 read these five hot fields;
            // consumer 3 read the five wire fields they decoded from.
            assert_eq!(
                crate::catalog::entropy_transform_provenance_is_exact(
                    state.reward_card_pool,
                    state.entropy_card_pool,
                    crate::engine::cards::unlock_profile_is_recorded(&state, &catalog),
                    state.multiplayer_ally_key,
                    state.spectrum_shift_generation_pool(),
                ),
                expected,
                "{label}: hot-state provenance disagrees with the wire provenance"
            );

            // Consumer 1: the transform's own gate.
            let original = state.piles.get(PileId::Hand).as_slice()[0];
            let transform = crate::engine::turn::entropy_transform_pool(&state, &catalog, original);
            assert_eq!(
                transform
                    != Err(crate::engine::EngineRefusal::MalformedArgs(
                        "Entropy recorded-profile solo owner pool provenance"
                    )),
                expected,
                "{label}: the transform's own gate disagrees: {transform:?}"
            );

            // Consumer 2: admission's named refusal, and consumer 4 never
            // swapping one name for another.
            let refusal = admit(&document, &state, &catalog).err();
            let names = |name| {
                refusal
                    .as_ref()
                    .is_some_and(|refusal| refusal.contains(MissingCapability::ArgumentShape(name)))
            };
            assert_eq!(
                names("Entropy transform pool provenance"),
                !expected,
                "{label}: admission's named provenance refusal disagrees: {refusal:?}"
            );
            assert!(
                !names("Entropy recursive transform closure") || !owner_is_named,
                "{label}: consumer 4 demanded a union consumer 3 did not intern: {refusal:?}"
            );

            // Consumer 4, and the no-narrowing half: the five-class union is
            // present exactly when the predicate holds.
            assert!(
                crate::boundary::entropy_catalog_closure_is_exact(&catalog, owner),
                "{label}: the closure checker must agree with the walk that built it"
            );
            for (class, id) in foreign_class_witnesses {
                assert_eq!(
                    catalog.is_reachable(CardIdentity {
                        id,
                        upgrade: 0,
                        enchantment: None,
                    }),
                    expected,
                    "{label}: {class:?} witness {id:?} reachability disagrees"
                );
            }
        }
    }

    /// The named witness for the Regent conjunct
    /// ([`crate::catalog::entropy_transform_provenance_is_exact`]).
    ///
    /// The conjunct would be invisible without a state that isolates it: this
    /// document differs from an admitted one in exactly one published field.
    /// Both halves are asserted — with the field the root admits, without it
    /// the root refuses at the door by name and the hot transform refuses
    /// too — so the test cannot rot vacuous in either direction, and it fails
    /// if the guard is dropped again.
    ///
    /// It also pins that the refusal arrives at admission rather than
    /// mid-fight: `"Entropy transform pool provenance"` is present, and the
    /// transform's own gate agrees, so no state exists where `admit` says yes
    /// and the body then says no.
    #[test]
    fn entropy_refuses_a_regent_root_whose_document_omits_the_colorless_pool() {
        let published = live_entropy_document(RewardPool::Regent);
        assert!(
            published
                .player
                .contains_key("spectrum_shift_generation_pool"),
            "the isolating lever must actually be published in the control"
        );
        let refusal_name = MissingCapability::ArgumentShape("Entropy transform pool provenance");
        assert!(
            !maybe_refuse(&published).is_some_and(|refusal| refusal.contains(refusal_name)),
            "a Regent root that publishes the Colorless pool keeps Entropy modeled"
        );

        let mut omitted = published.clone();
        omitted.player.remove("spectrum_shift_generation_pool");
        assert!(
            refuse(&omitted).contains(refusal_name),
            "a Regent root that omits it must refuse at the door, as main did"
        );

        // Consumer 1 agrees, so the refusal cannot arrive mid-fight instead.
        let catalog = HotBoundary::catalog_from_canonical(&omitted).unwrap();
        let state = HotBoundary::from_canonical(&omitted, &catalog).unwrap();
        let original = state.piles.get(PileId::Hand).as_slice()[0];
        assert_eq!(
            crate::engine::turn::entropy_transform_pool(&state, &catalog, original),
            Err(crate::engine::EngineRefusal::MalformedArgs(
                "Entropy recorded-profile solo owner pool provenance"
            ))
        );

        // The asymmetry this guard exists to avoid: Discovery reads the very
        // same `owner_generation_pool(Regent)` table and refuses the same
        // state. Two mechanics over one table, one answer.
        let mut discovery = omitted.clone();
        discovery.piles.get_mut("hand").unwrap()[0].id = CardId::Discovery.as_str().to_owned();
        assert!(
            refuse(&discovery).contains(MissingCapability::ArgumentShape(
                "Discovery generation provenance"
            )),
            "Discovery still requires what Entropy would have stopped requiring"
        );
    }

    #[test]
    fn ordinary_after_card_played_future_order_is_ledger_closed() {
        let mut builder = CatalogBuilder::new();
        for id in [CardId::Panache, CardId::Monologue, CardId::Afterimage] {
            builder
                .intern_reachable(CardIdentity {
                    id,
                    upgrade: 0,
                    enchantment: None,
                })
                .unwrap();
        }
        let catalog = builder.build();
        if let Err(refusal) = admit(&parts().0, &HotState::at_defaults(), &catalog) {
            assert!(!refusal.contains(MissingCapability::ArgumentShape(
                "instanced ordinary AfterCardPlayed prospective acquisition order"
            )));
        }
    }

    fn batch_j_document(kind: MonsterKind, respawn_count: i32) -> CanonicalStateV2 {
        let (mut document, _, _) = parts();
        document.monsters.truncate(1);
        let monster = &mut document.monsters[0];
        monster.insert("kind".to_owned(), Value::from(kind.as_str()));
        monster.remove("loop_pos");
        match kind {
            MonsterKind::FrogKnight => {
                monster.insert("hp".to_owned(), Value::from(199));
                monster.insert("max_hp".to_owned(), Value::from(199));
                monster.insert(PowerId::Mplating.as_str().to_owned(), Value::from(19));
            }
            MonsterKind::Axebot => {
                let stock = crate::engine::monsters::AXEBOT_STOCK - respawn_count;
                let hp = 76 + 10 * respawn_count;
                monster.insert("hp".to_owned(), Value::from(hp));
                monster.insert("max_hp".to_owned(), Value::from(hp));
                if respawn_count > 0 {
                    monster.insert("uid".to_owned(), Value::from(respawn_count));
                    monster.insert("loop_pos".to_owned(), Value::from(2));
                }
                if stock > 0 {
                    monster.insert(PowerId::Stock.as_str().to_owned(), Value::from(stock));
                }
            }
            _ => unreachable!(),
        }
        document
    }

    #[test]
    fn batch_j_admission_is_exactly_two_encounters_and_sensitive() {
        let frog = batch_j_document(MonsterKind::FrogKnight, 0);
        let catalog = HotBoundary::catalog_from_canonical(&frog).unwrap();
        let state = HotBoundary::from_canonical(&frog, &catalog).unwrap();
        assert_eq!(admit(&frog, &state, &catalog), Ok(()));

        for mutation in 0..4 {
            let mut changed = frog.clone();
            match mutation {
                0 => {
                    changed.monsters[0]
                        .insert(PowerId::Mplating.as_str().to_owned(), Value::from(18));
                }
                1 => {
                    changed.monsters[0].insert("loop_pos".to_owned(), Value::from(3));
                    changed.monsters[0].insert("beetle_charged".to_owned(), Value::from(true));
                }
                2 => {
                    changed.monsters[0].insert("max_hp".to_owned(), Value::from(198));
                }
                3 => changed.monsters.push(changed.monsters[0].clone()),
                _ => unreachable!(),
            }
            assert!(
                refuse(&changed).contains(MissingCapability::ArgumentShape(
                    "Frog Knight Plating/charge lifecycle"
                )),
                "Frog mutation {mutation}"
            );
        }

        for respawn_count in 0..=2 {
            let document = batch_j_document(MonsterKind::Axebot, respawn_count);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(admit(&document, &state, &catalog), Ok(()));

            let mut changed = document;
            changed.monsters[0].insert("uid".to_owned(), Value::from(9));
            assert!(
                refuse(&changed)
                    .contains(MissingCapability::ArgumentShape("Axebot Stock lifecycle")),
                "Axebot respawn {respawn_count} uid sensitivity"
            );
        }

        let mut current_initial = batch_j_document(MonsterKind::Axebot, 0);
        current_initial.monsters[0].insert("loop_pos".to_owned(), Value::from(1));
        let catalog = HotBoundary::catalog_from_canonical(&current_initial).unwrap();
        let state = HotBoundary::from_canonical(&current_initial, &catalog).unwrap();
        assert_eq!(admit(&current_initial, &state, &catalog), Ok(()));

        let mut impossible_bootup = batch_j_document(MonsterKind::Axebot, 0);
        impossible_bootup.monsters[0].insert("loop_pos".to_owned(), Value::from(2));
        assert!(
            refuse(&impossible_bootup)
                .contains(MissingCapability::ArgumentShape("Axebot Stock lifecycle")),
            "Stock 2 cannot occupy the BOOT_UP respawn opener"
        );

        // #2494 retires the blanket `Sewer Clam Plating lifecycle` gate: the
        // generated singleton now admits on the same generic Plating reader
        // Frog Knight and Lagavulin Matriarch already use.
        let mut clam = batch_j_document(MonsterKind::FrogKnight, 0);
        clam.monsters[0].insert(
            "kind".to_owned(),
            Value::from(MonsterKind::SewerClam.as_str()),
        );
        clam.monsters[0].insert("hp".to_owned(), Value::from(58));
        clam.monsters[0].insert("max_hp".to_owned(), Value::from(58));
        clam.monsters[0].insert(PowerId::Mplating.as_str().to_owned(), Value::from(9));
        let clam_catalog = HotBoundary::catalog_from_canonical(&clam).unwrap();
        let clam_state = HotBoundary::from_canonical(&clam, &clam_catalog).unwrap();
        assert_eq!(admit(&clam, &clam_state, &clam_catalog), Ok(()));

        // The amount stays pinned above. The cap is the Clam's own (9, A8+; 8
        // below), so one over it and the Frog Knight's own 19 are both out of
        // range on this kind — a `PowerState` refusal from the generic slot
        // validator rather than a kind-shaped one. Zero is not tested here: a
        // zero-valued slot is an absent power, not a malformed one.
        for amount in [10, 19] {
            let mut wrong = clam.clone();
            wrong.monsters[0].insert(PowerId::Mplating.as_str().to_owned(), Value::from(amount));
            assert!(
                refuse(&wrong).contains(MissingCapability::PowerState(PowerId::Mplating)),
                "Sewer Clam Plating {amount}"
            );
        }

        assert!(IMPLEMENTED_POWERS.contains(&PowerId::Mplating));
        assert!(IMPLEMENTED_POWERS.contains(&PowerId::Stock));
    }

    fn replace_first_hand_card(document: &mut CanonicalStateV2, id: CardId, upgrade: i64) {
        let card = &mut document.piles.get_mut("hand").unwrap()[0];
        card.id = id.as_str().to_owned();
        card.upgrade = upgrade;
        card.physical_state = None;
    }

    fn push_physical_card(
        document: &mut CanonicalStateV2,
        pile: &str,
        id: CardId,
        upgrade: i64,
    ) -> u64 {
        let uid = document.player["next_card_uid"]
            .as_u64()
            .expect("fixture next_card_uid");
        let mut card = document.piles["hand"][0].clone();
        card.id = id.as_str().to_owned();
        card.upgrade = upgrade;
        card.uid = Some(uid);
        card.physical_state = None;
        card.sovereign_blade = None;
        document
            .piles
            .entry(pile.to_owned())
            .or_default()
            .push(card);
        document
            .player
            .insert("next_card_uid".to_owned(), json!(uid + 1));
        uid
    }

    #[test]
    fn howl_from_beyond_rows_and_runtime_piles_are_exactly_scoped() {
        for upgrade in 0..=1 {
            let row = *crate::content_tables::card_row(CardId::HowlFromBeyond, upgrade).unwrap();
            assert!(howl_from_beyond_program_is_supported(&row));
            assert!(card_keywords_are_inert(&row));
            for mutation in ["cost", "upgrade", "target", "program"] {
                let mut changed = row;
                match mutation {
                    "cost" => changed.cost -= 1,
                    "upgrade" => changed.upgrade = 1 - upgrade,
                    "target" => changed.target_type = "AnyEnemy",
                    "program" => changed.steps = &[],
                    _ => unreachable!(),
                }
                assert!(
                    !howl_from_beyond_program_is_supported(&changed),
                    "{mutation} mutation escaped"
                );
                assert!(!card_keywords_are_inert(&changed));
            }

            for pile in ["hand", "draw", "discard", "exhaust", "play"] {
                let (mut document, _, _) = parts();
                replace_first_hand_card(&mut document, CardId::HowlFromBeyond, i64::from(upgrade));
                if pile != "hand" {
                    let card = document.piles.get_mut("hand").unwrap().remove(0);
                    document
                        .piles
                        .entry(pile.to_owned())
                        .or_default()
                        .push(card);
                }
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                if pile == "exhaust" {
                    assert!(
                        !catalog.is_reachable(identity(CardId::HowlFromBeyond, upgrade)),
                        "{pile} is listener-executable without ordinary reachability"
                    );
                }
                let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                if pile == "play" {
                    assert!(
                        admit(&document, &state, &catalog)
                            .unwrap_err()
                            .contains(MissingCapability::NonEmptyPile(PileId::Play)),
                        "stable public entry keeps the global active-Play refusal"
                    );
                } else {
                    assert_eq!(admit(&document, &state, &catalog), Ok(()), "{pile}");
                }
            }
        }
    }

    #[test]
    fn howl_catalog_only_and_generated_closure_are_admitted_but_unknown_peer_stays_closed() {
        let (document, state, base) = parts();
        for upgrade in 0..=1 {
            let howl = identity(CardId::HowlFromBeyond, upgrade);

            let mut builder = CatalogBuilder::new();
            for spec in base.specs() {
                builder.intern(spec.identity).unwrap();
            }
            for spec in base.reachable_specs() {
                builder.intern_reachable(spec.identity).unwrap();
            }
            builder.intern(howl).unwrap();
            builder.intern_monster(MonsterKind::Toadpole).unwrap();
            let catalog_only = builder.build();
            assert!(!catalog_only.is_reachable(howl));
            assert_eq!(admit(&document, &state, &catalog_only), Ok(()));

            let generated = catalog_with(&base, howl);
            assert!(generated.is_reachable(howl));
            assert_eq!(admit(&document, &state, &generated), Ok(()));
        }

        for upgrade in 0..=1 {
            let row = crate::content_tables::card_row(CardId::IAmInvincible, upgrade).unwrap();
            assert!(i_am_invincible_program_is_supported(row));
            assert!(card_keywords_are_inert(row));
            assert_eq!(
                admit(
                    &document,
                    &state,
                    &catalog_with(&base, identity(CardId::IAmInvincible, upgrade))
                ),
                Ok(())
            );
        }

        for upgrade in 0..=1 {
            let row = crate::content_tables::card_row(CardId::Bombardment, upgrade).unwrap();
            assert!(bombardment_program_is_supported(row));
            assert_eq!(
                admit(
                    &document,
                    &state,
                    &catalog_with(&base, identity(CardId::Bombardment, upgrade)),
                ),
                Ok(()),
            );
            let mut mutated = *row;
            mutated.cost += 1;
            assert!(!bombardment_program_is_supported(&mutated));
            assert!(!card_keywords_are_inert(&mutated));
        }
    }

    #[test]
    fn armaments_hand_upgrade_closure_is_source_derived_and_fail_closed() {
        let document = parts().0;
        for upgrade in 0..=1 {
            let mut candidate = document.clone();
            replace_first_hand_card(&mut candidate, CardId::Armaments, upgrade);
            assert_admits(&candidate);
        }

        for source_upgrade in 0..=1 {
            let mut builder = CatalogBuilder::new();
            let source_atom = builder
                .intern_reachable(CardIdentity {
                    id: CardId::Armaments,
                    upgrade: source_upgrade,
                    enchantment: None,
                })
                .unwrap();
            let candidate_atom = builder
                .intern_reachable(CardIdentity {
                    id: CardId::DefendIronclad,
                    upgrade: 0,
                    enchantment: None,
                })
                .unwrap();
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.piles.get_mut(PileId::Hand).make_mut().extend([
                crate::hot::HotCard {
                    uid: 7,
                    atom: source_atom,
                    flags: crate::hot::CARD_FLAG_PICK,
                },
                crate::hot::HotCard {
                    uid: 8,
                    atom: candidate_atom,
                    flags: crate::hot::CARD_FLAG_PICK,
                },
            ]);
            let refusal = admit(&document, &state, &catalog).unwrap_err();
            assert!(refusal.contains(MissingCapability::ArgumentShape(
                "Armaments hand upgrade closure"
            )));

            let source = state.piles.get_mut(PileId::Hand).make_mut().remove(0);
            state.piles.get_mut(PileId::Exhaust).make_mut().push(source);
            let refusal = admit(&document, &state, &catalog).unwrap_err();
            assert!(
                !refusal.contains(MissingCapability::ArgumentShape(
                    "Armaments hand upgrade closure"
                )),
                "an Exhaust-only L{source_upgrade} source cannot enter another upgrade walk"
            );
        }

        let mut modeled_native_rung = parts().0;
        replace_first_hand_card(&mut modeled_native_rung, CardId::Armaments, 1);
        let mut gamble = modeled_native_rung.piles["hand"][1].clone();
        gamble.id = CardId::CalculatedGamble.as_str().to_owned();
        gamble.upgrade = 0;
        gamble.physical_state = None;
        modeled_native_rung
            .piles
            .get_mut("hand")
            .unwrap()
            .push(gamble);
        assert_admits(&modeled_native_rung);

        let mut remote_only_target = parts().0;
        replace_first_hand_card(&mut remote_only_target, CardId::Armaments, 1);
        add_minimal_party(&mut remote_only_target);
        remote_only_target
            .player
            .get_mut("multiplayer_allies")
            .unwrap()[0]["fields"]["hand"] = json!([[CardId::CalculatedGamble.as_str(), 0]]);
        assert_admits(&remote_only_target);

        let mut exhausted_target = parts().0;
        replace_first_hand_card(&mut exhausted_target, CardId::Armaments, 1);
        push_physical_card(
            &mut exhausted_target,
            "exhaust",
            CardId::CalculatedGamble,
            0,
        );
        assert_admits(&exhausted_target);

        let mut collision = modeled_native_rung;
        add_minimal_party(&mut collision);
        collision.player.get_mut("multiplayer_allies").unwrap()[0]["fields"]["draw"] =
            json!([[CardId::CalculatedGamble.as_str(), 0]]);
        assert_admits(&collision);
    }

