    #[test]
    fn drain_power_discard_closure_and_selection_provenance_are_source_derived() {
        let mut document = parts().0;
        replace_first_hand_card(&mut document, CardId::DrainPower, 0);
        assert_admits(&document);

        let mut builder = CatalogBuilder::new();
        let source_atom = builder
            .intern_reachable(CardIdentity {
                id: CardId::DrainPower,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let candidate_atom = builder
            .intern_reachable(CardIdentity {
                id: CardId::DefendNecrobinder,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(crate::hot::HotCard {
                uid: 7,
                atom: source_atom,
                flags: crate::hot::CARD_FLAG_PICK,
            });
        state
            .piles
            .get_mut(PileId::Discard)
            .make_mut()
            .push(crate::hot::HotCard {
                uid: 8,
                atom: candidate_atom,
                flags: crate::hot::CARD_FLAG_PICK,
            });
        let seeded = crate::rng::Xoshiro256StarStar::from_seed(17);
        state.rng.set(
            RngStream::Sel,
            crate::hot::RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        let refusal = admit(&document, &state, &catalog).unwrap_err();
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Drain Power discard upgrade closure"
        )));
        assert!(!refusal.contains(MissingCapability::ArgumentShape(
            "Drain Power Selection provenance"
        )));

        let source = state.piles.get_mut(PileId::Hand).make_mut().remove(0);
        state.piles.get_mut(PileId::Exhaust).make_mut().push(source);
        let refusal = admit(&document, &state, &catalog).unwrap_err();
        assert!(!refusal.contains(MissingCapability::ArgumentShape(
            "Drain Power discard upgrade closure"
        )));

        state.piles.get_mut(PileId::Exhaust).make_mut().clear();
        state.piles.get_mut(PileId::Hand).make_mut().push(source);
        let mut closed = CatalogBuilder::new();
        closed
            .intern_reachable(CardIdentity {
                id: CardId::DrainPower,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        closed
            .intern_reachable(CardIdentity {
                id: CardId::DefendNecrobinder,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        closed.intern_all_card_upgrade_closure().unwrap();
        let closed = closed.build();
        state
            .rng
            .set(RngStream::Sel, crate::hot::RngStreamState::default());
        let refusal = admit(&document, &state, &closed).unwrap_err();
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Drain Power Selection provenance"
        )));
    }

