    #[test]
    fn every_independently_admitted_native_upgrade_has_a_modeled_admitted_next_rung_or_refuses() {
        let mut drift = Vec::new();
        let mut missing_rows = Vec::new();
        for row in crate::catalog::variant_free_card_rows() {
            if !native_card_is_upgradable(CardIdentity {
                id: row.id,
                upgrade: row.upgrade,
                enchantment: None,
            }) {
                continue;
            }
            let Some(next_upgrade) = row.upgrade.checked_add(1) else {
                continue;
            };
            if crate::content_tables::card_row(row.id, next_upgrade).is_none() {
                missing_rows.push((row.id, row.upgrade, next_upgrade));
                continue;
            }
            let mut builder = CatalogBuilder::new();
            let base_atom = builder
                .intern(CardIdentity {
                    id: row.id,
                    upgrade: row.upgrade,
                    enchantment: None,
                })
                .unwrap();
            let next_atom = builder
                .intern(CardIdentity {
                    id: row.id,
                    upgrade: next_upgrade,
                    enchantment: None,
                })
                .unwrap();
            let catalog = builder.build();
            let base = catalog.spec(base_atom).unwrap();
            let next = catalog.spec(next_atom).unwrap();
            if card_row_is_admitted(&catalog, base) && !card_row_is_admitted(&catalog, next) {
                drift.push((row.id, row.upgrade, next_upgrade));
            }
        }
        assert_eq!(
            drift,
            [],
            "catalog-wide Armaments closure must not turn an otherwise admitted identity into a newly refused next row"
        );
        assert_eq!(
            missing_rows,
            [],
            "every native-upgradable missing row must remain a named admission refusal"
        );
    }

    #[test]
    fn temp_strength_enemy_admission_partitions_stock_and_enfeebling_review_exactly() {
        for upgrade in 0..=1 {
            // #3326: Mangle and Fight Me follow the frozen `(slot, uid)`
            // identity across a Stock respawn, so live Stock admits.
            let mut stock = batch_j_document(MonsterKind::Axebot, 1);
            replace_first_hand_card(&mut stock, CardId::Mangle, upgrade);
            assert_admits(&stock);

            let mut no_stock = batch_j_document(MonsterKind::Axebot, 2);
            replace_first_hand_card(&mut no_stock, CardId::Mangle, upgrade);
            assert_admits(&no_stock);

            let mut fight_me_stock = batch_j_document(MonsterKind::Axebot, 1);
            replace_first_hand_card(&mut fight_me_stock, CardId::FightMe, upgrade);
            assert_admits(&fight_me_stock);

            let mut fight_me_no_stock = batch_j_document(MonsterKind::Axebot, 2);
            replace_first_hand_card(&mut fight_me_no_stock, CardId::FightMe, upgrade);
            assert_admits(&fight_me_no_stock);

            // Enfeebling Touch's target/debuff lifecycle review is done: its
            // body is instruction-for-instruction Dark Shackles', and the only
            // distinguishing keyword is a static Ethereal the shared turn-end
            // path owns. It now admits like the rest of the carrier set, with
            // or without live Stock.
            let mut enfeebling = batch_j_document(MonsterKind::Axebot, 2);
            replace_first_hand_card(&mut enfeebling, CardId::EnfeeblingTouch, upgrade);
            assert_admits(&enfeebling);

            let mut enfeebling_stock = batch_j_document(MonsterKind::Axebot, 1);
            replace_first_hand_card(&mut enfeebling_stock, CardId::EnfeeblingTouch, upgrade);
            assert_admits(&enfeebling_stock);

            // The grant is registry equality, not an identity carveout: a
            // mutated operand falls back to the generic keyword refusal.
            let mut mutated = *crate::content_tables::card_row(
                CardId::EnfeeblingTouch,
                u8::try_from(upgrade).unwrap(),
            )
            .expect("the generated row exists");
            mutated.cost += 1;
            assert!(!static_ethereal_body_program_is_supported(&mutated));
            assert!(!card_keywords_are_inert(&mutated));
        }

        let no_post_attack_source = batch_j_document(MonsterKind::Axebot, 1);
        assert_admits(&no_post_attack_source);
    }

    #[test]
    fn fight_me_range_closure_is_source_derived_and_exact() {
        let mut level_zero = batch_j_document(MonsterKind::Axebot, 2);
        replace_first_hand_card(&mut level_zero, CardId::FightMe, 0);
        let level_zero_catalog = HotBoundary::catalog_from_canonical(&level_zero).unwrap();
        let mut level_zero_state =
            HotBoundary::from_canonical(&level_zero, &level_zero_catalog).unwrap();
        level_zero_state.powers.set(
            PowerId::Strength,
            crate::powers::SlotWire::Int,
            i32::MAX - 3,
        );
        assert_eq!(
            admit(&level_zero, &level_zero_state, &level_zero_catalog),
            Ok(()),
            "the source-derived L0-only closure must not assume L1's +4"
        );

        let mut document = batch_j_document(MonsterKind::Axebot, 2);
        replace_first_hand_card(&mut document, CardId::FightMe, 1);
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();

        state.powers.set(
            PowerId::Strength,
            crate::powers::SlotWire::Int,
            i32::MAX - 3,
        );
        let refusal = admit(&document, &state, &catalog).unwrap_err();
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Fight Me owner Strength range"
        )));

        state
            .powers
            .set(PowerId::Strength, crate::powers::SlotWire::Int, 0);
        state.monsters_mut()[0].powers.set(
            PowerId::Strength,
            crate::powers::SlotWire::Int,
            i32::MAX,
        );
        let refusal = admit(&document, &state, &catalog).unwrap_err();
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Fight Me enemy Strength range"
        )));

        state.monsters_mut()[0].powers.set(
            PowerId::Strength,
            crate::powers::SlotWire::Int,
            i32::MAX - 1,
        );
        assert_eq!(admit(&document, &state, &catalog), Ok(()));
    }

