    fn rat_document() -> CanonicalStateV2 {
        let (mut document, _, _) = parts();
        let template = document.monsters[0].clone();
        document.monsters.clear();
        for (position, (hp, starter)) in [(18, "SCRATCH"), (19, "DISEASE_BITE"), (20, "SCREECH")]
            .into_iter()
            .enumerate()
        {
            let mut monster = template.clone();
            monster.insert(
                "kind".to_owned(),
                Value::from(MonsterKind::TwoTailedRat.as_str()),
            );
            monster.insert("hp".to_owned(), Value::from(hp));
            monster.insert("max_hp".to_owned(), Value::from(hp));
            monster.remove("loop_pos");
            monster.insert("next_move".to_owned(), Value::from(starter));
            monster.insert(
                "move_log".to_owned(),
                Value::Array(vec![Value::from(starter)]),
            );
            monster.insert("tus".to_owned(), Value::from(2));
            if position > 0 {
                monster.insert("slot".to_owned(), Value::from(position as i64));
                monster.insert("uid".to_owned(), Value::from(position as i64));
            }
            document.monsters.push(monster);
        }
        document
    }

