    fn catalog_with(base: &Catalog, identity: CardIdentity) -> Catalog {
        let mut builder = CatalogBuilder::new();
        for spec in base.specs() {
            builder.intern(spec.identity).unwrap();
        }
        for spec in base.reachable_specs() {
            builder.intern_reachable(spec.identity).unwrap();
        }
        builder.intern_reachable(identity).unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        builder.build()
    }

    /// Glimmer's parked selector, built through the real public Play root.
    /// Glimmer owns a suspend-capable CardPlay Draw (#2667), so a catalog
    /// that can reach it requires ActionReplay and the parked continuation
    /// is only admissible with the receipt the public transition installs.
    /// Suspend hooks are stripped so the awaited Draw completes inline and
    /// the selector itself parks.
    fn glimmer_pending_state(base: &HotState, catalog: &Catalog) -> HotState {
        let mut state = base.clone();
        state.powers.set(PowerId::Hellraiser, SlotWire::Int, 0);
        state.powers.set(PowerId::Stratagem, SlotWire::Int, 0);
        let active = crate::hot::HotCard {
            uid: state.next_card_uid,
            atom: catalog.atom(&identity(CardId::Glimmer, 0)).unwrap(),
            flags: 0,
        };
        state.next_card_uid = state.next_card_uid.checked_add(1).unwrap();
        state.piles.get_mut(PileId::Hand).make_mut().push(active);
        state.energy = state.energy.max(1);
        let played = crate::engine::apply_action(
            &state,
            catalog,
            &crate::engine::Action::Play {
                uid: active.uid,
                target: None,
                selection: crate::engine::SelectionRef::NONE,
            },
        )
        .expect("live Glimmer parks its exact-one selector")
        .state;
        assert!(
            played.pending.is_some(),
            "live Glimmer parks, not completes"
        );
        assert!(
            matches!(
                played.frames.as_slice().first(),
                Some(crate::frame::Frame::ActionReplay { .. })
            ),
            "parking installs the replay receipt"
        );
        played
    }

    #[test]
    fn pending_choice_ownership_gates_admission_and_every_legal_action_counter() {
        let (_, base_state, base_catalog) = parts();
        let catalog = catalog_with(&base_catalog, identity(CardId::Glimmer, 0));
        let valid = glimmer_pending_state(&base_state, &catalog);
        let document = HotBoundary::try_to_canonical(&valid, &catalog).unwrap();
        // The receipt authenticates against the catalog derived from the
        // document itself, matching the imported-continuation path.
        let reload_catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        assert!(reload_catalog.requires_action_replay());
        let reloaded = HotBoundary::from_canonical(&document, &reload_catalog).unwrap();
        assert_eq!(admit(&document, &reloaded, &reload_catalog), Ok(()));

        let pending = valid.pending.as_deref().unwrap();
        assert!(valid.frames.pending_choice_is_valid(pending));
        assert_eq!(
            crate::engine::selection::special_option_count(&valid, &catalog, pending),
            Ok(valid.piles.get(PileId::Hand).len() as u32)
        );
        let mut buffer = crate::engine::LegalActionBuffer::new();
        assert!(!crate::engine::legal_actions_into(&valid, &catalog, &mut buffer).is_empty());

        let mut malformed = Vec::new();

        let mut missing = valid.clone();
        missing.frames = crate::hot::Frames::new();
        malformed.push(("missing owner", missing));

        let mut wrong_uid = valid.clone();
        wrong_uid.frames = crate::hot::Frames::new();
        let wrong_record = crate::hot::CardPlayRecord::pending_for_test(pending.frame_uid + 1);
        wrong_uid
            .frames
            .push_card_play(&wrong_record)
            .expect("valid wrong-uid record");
        malformed.push(("wrong uid owner", wrong_uid));

        let mut duplicate = valid.clone();
        duplicate.frames.push(crate::frame::Frame::CardPlay {
            record: pending.frame_record,
        });
        malformed.push(("duplicate owner", duplicate));

        let mut non_top = valid.clone();
        non_top.frames.push(crate::frame::Frame::JossSideEnd);
        malformed.push(("non-top owner", non_top));

        let mut stale = valid.clone();
        std::sync::Arc::make_mut(stale.pending.as_mut().unwrap()).frame_record =
            crate::hot::WordRecordIndex::from_raw_for_test(99);
        malformed.push(("stale record index", stale));

        let mut omitted_record = valid.clone();
        omitted_record.frames = crate::hot::Frames::new();
        let mut nonpending_record = crate::hot::CardPlayRecord::pending_for_test(pending.frame_uid);
        nonpending_record.pending_choice = false;
        nonpending_record.selection_kind = None;
        nonpending_record
            .selection_cards
            .push(valid.piles.get(PileId::Play).as_slice()[0]);
        let frame_record = omitted_record
            .frames
            .push_card_play(&nonpending_record)
            .expect("valid non-pending record");
        std::sync::Arc::make_mut(omitted_record.pending.as_mut().unwrap()).frame_record =
            frame_record;
        malformed.push(("malformed omitted record", omitted_record));

        let mut manual_force_exhaust = valid.clone();
        let owned_pending = manual_force_exhaust.pending.as_deref().unwrap().clone();
        manual_force_exhaust
            .frames
            .corrupt_card_play_force_exhaust_for_test(&owned_pending);
        malformed.push(("manual force-exhaust", manual_force_exhaust));

        for (name, plays, play_index) in [
            ("zero plays", 0, 0),
            ("too many plays", 257, 0),
            ("play index at count", 1, 1),
            ("max play index", 1, u32::MAX),
        ] {
            let mut invalid_count = valid.clone();
            let owned_pending = invalid_count.pending.as_deref().unwrap().clone();
            invalid_count.frames.corrupt_card_play_counts_for_test(
                &owned_pending,
                plays,
                play_index,
            );
            malformed.push((name, invalid_count));
        }
        for (name, spent) in [
            ("negative spent", -1),
            ("oversized spent", i32::from(i16::MAX) + 1),
        ] {
            let mut invalid_spent = valid.clone();
            let owned_pending = invalid_spent.pending.as_deref().unwrap().clone();
            invalid_spent
                .frames
                .corrupt_card_play_spent_for_test(&owned_pending, spent);
            malformed.push((name, invalid_spent));
        }

        for (name, candidate) in malformed {
            let candidate_pending = candidate.pending.as_deref().unwrap();
            assert!(
                !candidate.frames.pending_choice_is_valid(candidate_pending),
                "{name}"
            );
            assert_eq!(
                crate::engine::selection::special_option_count(
                    &candidate,
                    &catalog,
                    candidate_pending,
                ),
                Err(crate::engine::EngineRefusal::ContinuationNotModeled),
                "{name}"
            );
            assert!(
                crate::engine::legal_actions_into(&candidate, &catalog, &mut buffer).is_empty(),
                "{name}"
            );
            assert!(
                admit(&document, &candidate, &catalog)
                    .unwrap_err()
                    .contains(MissingCapability::ContinuationFrame),
                "{name}"
            );
        }

        let mut physically_malformed = Vec::new();
        let active = valid.piles.get(PileId::Play).as_slice()[0];

        let mut duplicate_physical = valid.clone();
        duplicate_physical
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(active);
        physically_malformed.push(("duplicate physical uid", duplicate_physical));

        let mut stale_next_uid = valid.clone();
        stale_next_uid.next_card_uid = active.uid;
        physically_malformed.push(("stale next uid", stale_next_uid));

        let mut false_in_play = valid.clone();
        let mut record = pending.record(&valid.frames).unwrap().to_owned();
        record.source = crate::hot::CardPlaySource::Auto;
        record.active_play_member = false;
        false_in_play.frames.replace_top_card_play(&record).unwrap();
        physically_malformed.push(("false active marker in Play", false_in_play));

        let mut true_outside_play = valid.clone();
        let moved = true_outside_play
            .piles
            .get_mut(PileId::Play)
            .make_mut()
            .pop()
            .unwrap();
        true_outside_play
            .piles
            .get_mut(PileId::Exhaust)
            .make_mut()
            .push(moved);
        let mut record = pending.record(&valid.frames).unwrap().to_owned();
        record.source = crate::hot::CardPlaySource::Auto;
        record.source_pile = PileId::Exhaust;
        record.active_play_member = true;
        true_outside_play
            .frames
            .replace_top_card_play(&record)
            .unwrap();
        physically_malformed.push(("true active marker outside Play", true_outside_play));

        let mut manual_outside_play = valid.clone();
        let moved = manual_outside_play
            .piles
            .get_mut(PileId::Play)
            .make_mut()
            .pop()
            .unwrap();
        manual_outside_play
            .piles
            .get_mut(PileId::Exhaust)
            .make_mut()
            .push(moved);
        let mut record = pending.record(&valid.frames).unwrap().to_owned();
        record.source = crate::hot::CardPlaySource::Manual;
        record.source_pile = PileId::Exhaust;
        record.active_play_member = true;
        manual_outside_play
            .frames
            .replace_top_card_play(&record)
            .unwrap();
        physically_malformed.push(("manual source outside Play", manual_outside_play));

        let mut duplicate_record_uid = valid.clone();
        let child = pending.record(&valid.frames).unwrap().to_owned();
        let mut parent = child.clone();
        parent.pending_choice = false;
        parent.selection_kind = None;
        duplicate_record_uid.frames = crate::hot::Frames::new();
        duplicate_record_uid.frames.push_card_play(&parent).unwrap();
        let frame_record = duplicate_record_uid.frames.push_card_play(&child).unwrap();
        std::sync::Arc::make_mut(duplicate_record_uid.pending.as_mut().unwrap()).frame_record =
            frame_record;
        physically_malformed.push(("duplicate CardPlay record uid", duplicate_record_uid));

        for (name, candidate) in physically_malformed {
            let candidate_pending = candidate.pending.as_deref().unwrap();
            assert!(
                candidate.pending_card_play(candidate_pending).is_none(),
                "{name}"
            );
            assert_eq!(
                crate::engine::selection::special_option_count(
                    &candidate,
                    &catalog,
                    candidate_pending,
                ),
                Err(crate::engine::EngineRefusal::ContinuationNotModeled),
                "{name}"
            );
            assert!(
                crate::engine::legal_actions_into(&candidate, &catalog, &mut buffer).is_empty(),
                "{name}"
            );
            assert!(
                admit(&document, &candidate, &catalog)
                    .unwrap_err()
                    .contains(MissingCapability::ContinuationFrame),
                "{name}"
            );
        }

        let mut unarmed_lamp = valid.clone();
        let mut record = pending.record(&valid.frames).unwrap().to_owned();
        record.lamp_owner = true;
        unarmed_lamp.frames.replace_top_card_play(&record).unwrap();
        let unarmed_pending = unarmed_lamp.pending.as_deref().unwrap();
        assert!(unarmed_lamp.pending_card_play(unarmed_pending).is_some());
        assert_eq!(
            crate::engine::selection::special_option_count(
                &unarmed_lamp,
                &catalog,
                unarmed_pending,
            ),
            Err(crate::engine::EngineRefusal::ContinuationNotModeled)
        );
        assert!(crate::engine::legal_actions(&unarmed_lamp, &catalog).is_empty());
        assert!(
            admit(&document, &unarmed_lamp, &catalog)
                .unwrap_err()
                .contains(MissingCapability::ContinuationFrame)
        );
        let before = unarmed_lamp.clone();
        // The replay-rooted public path re-derives answer legality before
        // the body runs.
        assert_eq!(
            crate::engine::apply_action(
                &unarmed_lamp,
                &catalog,
                &crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::OptionIndex(0),
                },
            ),
            Err(crate::engine::EngineRefusal::ActionNotLegal(
                "public action legality"
            ))
        );
        assert_eq!(unarmed_lamp, before);

        let enchanted_identity = CardIdentity {
            id: CardId::Glimmer,
            upgrade: 0,
            enchantment: Some(crate::catalog::CardEnchantment {
                id: EnchantmentId::Momentum,
                amount: 1,
            }),
        };
        let enchanted_catalog = catalog_with(&catalog, enchanted_identity);
        let mut enchanted_owner = valid.clone();
        enchanted_owner.piles.get_mut(PileId::Play).make_mut()[0].atom =
            enchanted_catalog.atom(&enchanted_identity).unwrap();
        let enchanted_pending = enchanted_owner.pending.as_deref().unwrap();
        assert_eq!(
            crate::engine::selection::special_option_count(
                &enchanted_owner,
                &enchanted_catalog,
                enchanted_pending,
            ),
            Err(crate::engine::EngineRefusal::ContinuationNotModeled)
        );
        assert!(crate::engine::legal_actions(&enchanted_owner, &enchanted_catalog).is_empty());
        assert!(
            admit(&document, &enchanted_owner, &enchanted_catalog)
                .unwrap_err()
                .contains(MissingCapability::ContinuationFrame)
        );
        let before = enchanted_owner.clone();
        // The replay-rooted public path re-derives answer legality before
        // the body runs.
        assert_eq!(
            crate::engine::apply_action(
                &enchanted_owner,
                &enchanted_catalog,
                &crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::OptionIndex(0),
                },
            ),
            Err(crate::engine::EngineRefusal::ActionNotLegal(
                "public action legality"
            ))
        );
        assert_eq!(enchanted_owner, before);

        let mut ancestor_lamp = valid.clone();
        ancestor_lamp.fanouts.set_unsettling_lamp_available(true);
        let child = pending.record(&valid.frames).unwrap().to_owned();
        let mut parent = child.clone();
        parent.uid = ancestor_lamp.next_card_uid;
        parent.pending_choice = false;
        parent.selection_kind = None;
        parent.selection_amount = 0;
        parent.lamp_owner = true;
        let mut parent_card = active;
        parent_card.uid = parent.uid;
        ancestor_lamp.next_card_uid += 1;
        ancestor_lamp
            .piles
            .get_mut(PileId::Play)
            .make_mut()
            .push(parent_card);
        // The rebuilt nesting stays receipt-less: it exercises the
        // structural lamp-owner validation only. Offering actions for a
        // receipt-less continuation in a replay-requiring catalog is the
        // live receipt's job, covered by the `valid` state above.
        ancestor_lamp.frames = crate::hot::Frames::new();
        ancestor_lamp.frames.push_card_play(&parent).unwrap();
        let child_record = ancestor_lamp.frames.push_card_play(&child).unwrap();
        std::sync::Arc::make_mut(ancestor_lamp.pending.as_mut().unwrap()).frame_record =
            child_record;
        assert_eq!(
            crate::engine::play::persisted_card_play_stack_is_exact(&ancestor_lamp, &catalog),
            Ok(())
        );
        assert_eq!(
            crate::engine::selection::special_option_count(
                &ancestor_lamp,
                &catalog,
                ancestor_lamp.pending.as_deref().unwrap(),
            ),
            Ok(ancestor_lamp.piles.get(PileId::Hand).len() as u32)
        );
        assert!(crate::engine::legal_actions(&ancestor_lamp, &catalog).is_empty());

        let mut duplicate_lamp_owner = ancestor_lamp;
        let mut child = child;
        child.lamp_owner = true;
        duplicate_lamp_owner
            .frames
            .replace_top_card_play(&child)
            .unwrap();
        let duplicate_pending = duplicate_lamp_owner.pending.as_deref().unwrap();
        assert_eq!(
            crate::engine::play::persisted_card_play_stack_is_exact(
                &duplicate_lamp_owner,
                &catalog
            ),
            Err(crate::engine::EngineRefusal::ContinuationNotModeled)
        );
        assert_eq!(
            crate::engine::selection::special_option_count(
                &duplicate_lamp_owner,
                &catalog,
                duplicate_pending,
            ),
            Err(crate::engine::EngineRefusal::ContinuationNotModeled)
        );
        assert!(crate::engine::legal_actions(&duplicate_lamp_owner, &catalog).is_empty());
        assert!(
            admit(&document, &duplicate_lamp_owner, &catalog)
                .unwrap_err()
                .contains(MissingCapability::ContinuationFrame)
        );
        let before = duplicate_lamp_owner.clone();
        // The replay-rooted public path re-derives answer legality before
        // the body runs.
        assert_eq!(
            crate::engine::apply_action(
                &duplicate_lamp_owner,
                &catalog,
                &crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::OptionIndex(0),
                },
            ),
            Err(crate::engine::EngineRefusal::ActionNotLegal(
                "public action legality"
            ))
        );
        assert_eq!(duplicate_lamp_owner, before);
    }

    #[test]
    fn stoke_recursive_closure_admits_public_rows_and_names_transitive_catalog_blockers() {
        for upgrade in [0, 1] {
            let mut document = generator_document(CardId::Stoke, RewardPool::Ironclad, false, 1884);
            document.piles.get_mut("hand").unwrap()[0].upgrade = upgrade;
            assert!(crate::steps::is_implemented(StepKind::StokeExact));
            assert_admits(&document);
        }

        let (document, mut state, base) = parts();
        state.reward_card_pool = Some(RewardPool::Ironclad);
        state.entropy_card_pool = Some(RewardPool::Ironclad);
        state.fully_unlocked_card_pool_epochs = true;
        state.rng.set(
            RngStream::Generation,
            crate::hot::RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        let incomplete = catalog_with(&base, identity(CardId::Stoke, 0));
        let refusal = admit(&document, &state, &incomplete).unwrap_err();
        assert!(refusal.contains(MissingCapability::ArgumentShape("Stoke generation closure")));

        let mut builder = CatalogBuilder::new();
        for spec in base.specs() {
            builder.intern(spec.identity).unwrap();
        }
        for spec in base.reachable_specs() {
            builder.intern_reachable(spec.identity).unwrap();
        }
        builder
            .intern_reachable(identity(CardId::Stoke, 0))
            .unwrap();
        for generated in crate::content_tables::STOKE_CARD_POOL_V109
            .into_iter()
            .chain(std::iter::once(CardId::GiantRock))
            .flat_map(|id| [0, 1].map(move |upgrade| identity(id, upgrade)))
        {
            builder.intern(generated).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let present_but_unreachable = builder.build();
        let refusal = admit(&document, &state, &present_but_unreachable).unwrap_err();
        assert!(refusal.contains(MissingCapability::ArgumentShape("Stoke generation closure")));
    }

    #[test]
    fn spec_registry_row_check_compares_values_not_addresses() {
        let (_, _, base) = parts();
        let stampede = identity(CardId::Stampede, 0);
        let catalog = catalog_with(&base, stampede);
        let atom = catalog.atom(&stampede).unwrap();
        let registry = crate::content_tables::card_row(CardId::Stampede, 0).unwrap();
        let spec = catalog.spec(atom).unwrap();
        assert!(std::ptr::eq(spec.row, registry));
        assert!(spec_carries_registry_row(spec));

        let mut copied = catalog.clone();
        copied.spec_mut_for_test(atom).unwrap().row = Box::leak(Box::new(*registry));
        let spec = copied.spec(atom).unwrap();
        assert!(!std::ptr::eq(spec.row, registry));
        assert!(
            spec_carries_registry_row(spec),
            "an equal row elsewhere must take the deep comparison"
        );

        let mut drifted = catalog.clone();
        drifted.spec_mut_for_test(atom).unwrap().row =
            Box::leak(Box::new(crate::content_tables::CardRow {
                cost: registry.cost + 1,
                ..*registry
            }));
        assert!(!spec_carries_registry_row(drifted.spec(atom).unwrap()));
    }

    #[test]
    fn stampede_identity_closure_uses_only_execution_reachable_sources() {
        let (_, state, base) = parts();
        let stampede = catalog_with(&base, identity(CardId::Stampede, 0));
        assert!(stampede.is_reachable(identity(CardId::Stampede, 0)));
        assert!(stampede_power_model_identity_closure_is_exact(
            &state, &stampede
        ));

        let mut remote_builder = CatalogBuilder::new();
        for spec in stampede.specs() {
            remote_builder.intern(spec.identity).unwrap();
        }
        for spec in stampede.reachable_specs() {
            remote_builder.intern_reachable(spec.identity).unwrap();
        }
        remote_builder
            .intern(identity(CardId::Hellraiser, 0))
            .unwrap();
        remote_builder
            .intern_monster(MonsterKind::Toadpole)
            .unwrap();
        let remote_hellraiser = remote_builder.build();
        assert!(!remote_hellraiser.is_reachable(identity(CardId::Hellraiser, 0)));
        assert!(stampede_power_model_identity_closure_is_exact(
            &state,
            &remote_hellraiser
        ));

        let reachable_hellraiser = catalog_with(&stampede, identity(CardId::Hellraiser, 0));
        assert!(reachable_hellraiser.is_reachable(identity(CardId::Hellraiser, 0)));
        assert!(stampede_power_model_identity_closure_is_exact(
            &state,
            &reachable_hellraiser
        ));

        let mut live = state.clone();
        live.powers.set(PowerId::Stampede, SlotWire::Int, 1);
        live.powers.set(PowerId::Hellraiser, SlotWire::Int, 1);
        assert!(stampede_power_model_identity_closure_is_exact(&live, &base));

        for id in [
            CardId::AllForOne,
            CardId::Jackpot,
            CardId::Headbutt,
            CardId::Rebound,
            CardId::Uproar,
        ] {
            let descendant = catalog_with(&base, identity(id, 0));
            let mut live = state.clone();
            live.powers.set(PowerId::Stampede, SlotWire::Int, 1);
            assert!(
                stampede_power_model_identity_closure_is_exact(&live, &descendant),
                "{id:?} must stay inside the audited Attack descendant closure"
            );
        }

        let abundance = (0..4096)
            .find_map(|seed| {
                let document =
                    generator_document(CardId::Abundance, RewardPool::Ironclad, false, seed);
                let catalog = HotBoundary::catalog_from_canonical(&document).ok()?;
                catalog
                    .is_reachable(identity(CardId::Stampede, 1))
                    .then_some((document, catalog))
            })
            .expect("one exact Abundance prefix offers Stampede L1");
        assert!(abundance.1.is_reachable(identity(CardId::Stampede, 1)));

        let stoke = generator_document(CardId::Stoke, RewardPool::Ironclad, false, 1884);
        let stoke_catalog = HotBoundary::catalog_from_canonical(&stoke).unwrap();
        assert!(stoke_catalog.is_reachable(identity(CardId::Stampede, 0)));
    }

    #[test]
    fn hellraiser_strike_gate_admits_only_the_exact_cardplay_draw_family() {
        let (document, state, base) = parts();
        let hellraiser = catalog_with(&base, identity(CardId::Hellraiser, 0));
        assert!(hellraiser_can_be_live(&state, &hellraiser));
        assert!(hellraiser_synchronous_strike_closure_is_exact(&hellraiser));

        let selecting = catalog_with(&hellraiser, identity(CardId::SculptingStrike, 0));
        assert!(!hellraiser_synchronous_strike_closure_is_exact(&selecting));
        assert_eq!(admit(&document, &state, &selecting), Ok(()));
        let selecting_with_cardplay_draw =
            catalog_with(&selecting, identity(CardId::BattleTrance, 0));
        assert!(selecting_with_cardplay_draw.requires_action_replay());
        assert_eq!(
            admit(&document, &state, &selecting_with_cardplay_draw),
            Ok(())
        );
        for source in [
            CardId::Constellation,
            CardId::HuddleUp,
            CardId::BigBang,
            CardId::EscapePlan,
            CardId::Expertise,
            CardId::CalculatedGamble,
            CardId::Glimmer,
        ] {
            let catalog = catalog_with(&selecting, identity(source, 0));
            assert_eq!(
                admit(&document, &state, &catalog),
                Ok(()),
                "{source:?} has an exact source-specific CardPlay Draw return"
            );
        }

        let mut catalog_only = CatalogBuilder::new();
        for spec in hellraiser.specs() {
            catalog_only.intern(spec.identity).unwrap();
        }
        for spec in hellraiser.reachable_specs() {
            catalog_only.intern_reachable(spec.identity).unwrap();
        }
        catalog_only
            .intern(identity(CardId::SculptingStrike, 0))
            .unwrap();
        catalog_only.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog_only = catalog_only.build();
        assert!(!catalog_only.is_reachable(identity(CardId::SculptingStrike, 0)));
        assert!(hellraiser_synchronous_strike_closure_is_exact(
            &catalog_only
        ));

        let nonselecting = catalog_with(&hellraiser, identity(CardId::PommelStrike, 0));
        assert!(hellraiser_synchronous_strike_closure_is_exact(
            &nonselecting
        ));
    }

    /// `catalog_with`, plus one relic's hook subscription.
    fn catalog_with_relic(base: &Catalog, identity: CardIdentity, relic: RelicId) -> Catalog {
        let mut builder = CatalogBuilder::new();
        for spec in base.specs() {
            builder.intern(spec.identity).unwrap();
        }
        for spec in base.reachable_specs() {
            builder.intern_reachable(spec.identity).unwrap();
        }
        builder.intern_reachable(identity).unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        builder.set_relics(&[relic]).unwrap();
        builder.build()
    }

    fn swift(id: CardId) -> CardIdentity {
        CardIdentity {
            id,
            upgrade: 0,
            enchantment: Some(crate::catalog::CardEnchantment {
                id: crate::ids::EnchantmentId::Swift,
                amount: 2,
            }),
        }
    }

    fn walls_of(
        document: &CanonicalStateV2,
        state: &HotState,
        catalog: &Catalog,
        names: &[&'static str],
    ) -> Vec<&'static str> {
        let refusal = match admit(document, state, catalog) {
            Ok(()) => return Vec::new(),
            Err(refusal) => refusal,
        };
        names
            .iter()
            .copied()
            .filter(|name| refusal.contains(MissingCapability::ArgumentShape(name)))
            .collect()
    }

    const HELLRAISER_DRAW_WALLS: [&str; 5] = [
        "Hellraiser synchronous Strike closure",
        // Retired by #3115, #3114, #3387 and #3201; listed so a revival
        // fails.
        "Hellraiser Swift enchantment Draw",
        "Hellraiser Centennial Puzzle Draw",
        "Hellraiser Gremlin Horn Draw",
        "Hellraiser Joss Paper Draw",
    ];

    const STRATAGEM_DRAW_WALLS: [&str; 5] = [
        "stratagem selection",
        // Retired by #3115, #3114, #3387 and #3201; listed so a revival
        // fails.
        "Stratagem Swift enchantment Draw",
        "Stratagem Centennial Puzzle Draw",
        "Stratagem Gremlin Horn Draw",
        "Stratagem Joss Paper Draw",
    ];

    /// #3110: every non-card-program Draw owner under a selecting Hellraiser
    /// Strike closure refuses by its own name, and a spent Centennial Puzzle
    /// is no Draw source at all.
    #[test]
    fn hellraiser_non_card_program_draw_sources_refuse_by_name() {
        let (document, state, base) = parts();
        let hellraiser = catalog_with(&base, identity(CardId::Hellraiser, 0));
        let selecting = catalog_with(&hellraiser, identity(CardId::SculptingStrike, 0));
        assert!(!hellraiser_synchronous_strike_closure_is_exact(&selecting));
        assert!(walls_of(&document, &state, &selecting, &HELLRAISER_DRAW_WALLS).is_empty());

        let swift_defend = catalog_with(&selecting, swift(CardId::DefendIronclad));
        assert!(swift_enchantment_draw_is_reachable(&swift_defend));
        assert!(!hellraiser_unconverted_card_draw_source_is_reachable(
            &state,
            &swift_defend
        ));
        // #3115: the Swift Draw is receipt-owned.
        assert!(walls_of(&document, &state, &swift_defend, &HELLRAISER_DRAW_WALLS).is_empty());

        let mut armed = state.clone();
        armed.fanouts.set_puzzle_armed(true);
        let mut spent = state.clone();
        spent.fanouts.set_puzzle_armed(false);
        let puzzle = catalog_with_relic(
            &selecting,
            identity(CardId::DefendIronclad, 0),
            RelicId::RelicCentennialPuzzle,
        );
        // #3114: an armed Puzzle's Draw is owned by the ActionReplay carrier.
        assert!(walls_of(&document, &armed, &puzzle, &HELLRAISER_DRAW_WALLS).is_empty());
        assert!(walls_of(&document, &spent, &puzzle, &HELLRAISER_DRAW_WALLS).is_empty());

        let horn = catalog_with_relic(
            &selecting,
            identity(CardId::DefendIronclad, 0),
            RelicId::RelicGremlinHorn,
        );
        // #3387: Gremlin Horn's Draw is owned by the deferred hook-action
        // queue (`engine::hook_action`); what it cannot model refuses at
        // runtime.
        assert!(walls_of(&document, &spent, &horn, &HELLRAISER_DRAW_WALLS).is_empty());
        // #3201: Joss Paper's threshold Draw is receipt-owned.
        let joss = catalog_with_relic(
            &selecting,
            identity(CardId::DefendIronclad, 0),
            RelicId::RelicJossPaper,
        );
        assert!(walls_of(&document, &spent, &joss, &HELLRAISER_DRAW_WALLS).is_empty());

        // An exact synchronous Strike closure needs none of these walls.
        let exact = catalog_with_relic(
            &hellraiser,
            swift(CardId::DefendIronclad),
            RelicId::RelicCentennialPuzzle,
        );
        assert!(hellraiser_synchronous_strike_closure_is_exact(&exact));
        assert!(walls_of(&document, &armed, &exact, &HELLRAISER_DRAW_WALLS).is_empty());
    }

    /// #3110: the Stratagem population wall names each non-card-program Draw
    /// owner, and a spent Centennial Puzzle no longer keeps it up.
    #[test]
    fn stratagem_non_card_program_draw_sources_refuse_by_name() {
        let (document, state, base) = parts();
        let reshufflable = [PileId::Hand, PileId::Draw, PileId::Discard]
            .into_iter()
            .map(|pile| state.piles.get(pile).len())
            .sum::<usize>();
        assert!(
            reshufflable > 1,
            "the fixture must exceed Stratagem's amount"
        );
        let stratagem = catalog_with(&base, identity(CardId::Stratagem, 0));
        assert!(!hellraiser_can_be_live(&state, &stratagem));
        assert!(walls_of(&document, &state, &stratagem, &STRATAGEM_DRAW_WALLS).is_empty());

        let swift_defend = catalog_with(&stratagem, swift(CardId::DefendIronclad));
        // #3115: the Swift Draw is receipt-owned.
        assert!(walls_of(&document, &state, &swift_defend, &STRATAGEM_DRAW_WALLS).is_empty());

        let mut armed = state.clone();
        armed.fanouts.set_puzzle_armed(true);
        let mut spent = state.clone();
        spent.fanouts.set_puzzle_armed(false);
        let puzzle = catalog_with_relic(
            &stratagem,
            identity(CardId::DefendIronclad, 0),
            RelicId::RelicCentennialPuzzle,
        );
        // #3114: an armed Puzzle's Draw is owned by the ActionReplay carrier.
        assert!(walls_of(&document, &armed, &puzzle, &STRATAGEM_DRAW_WALLS).is_empty());
        assert!(walls_of(&document, &spent, &puzzle, &STRATAGEM_DRAW_WALLS).is_empty());

        let horn = catalog_with_relic(
            &stratagem,
            identity(CardId::DefendIronclad, 0),
            RelicId::RelicGremlinHorn,
        );
        // #3387: owned by the deferred hook-action queue.
        assert!(walls_of(&document, &spent, &horn, &STRATAGEM_DRAW_WALLS).is_empty());
        // #3201: Joss Paper's threshold Draw is receipt-owned.
        let joss = catalog_with_relic(
            &stratagem,
            identity(CardId::DefendIronclad, 0),
            RelicId::RelicJossPaper,
        );
        assert!(walls_of(&document, &spent, &joss, &STRATAGEM_DRAW_WALLS).is_empty());

        // Unreachable Stratagem: no population wall for any owner.
        let no_stratagem = catalog_with_relic(
            &base,
            swift(CardId::DefendIronclad),
            RelicId::RelicCentennialPuzzle,
        );
        assert!(walls_of(&document, &armed, &no_stratagem, &STRATAGEM_DRAW_WALLS).is_empty());
    }

    #[test]
    fn ashwater_owned_dark_draw_gate_pins_every_non_ash_exhaust_route() {
        let (_, state, base) = parts();
        assert!(!non_ash_card_exhaust_source_is_reachable(&state, &base));
        for kind in [
            StepKind::Corruption,
            StepKind::ExhaustDraw,
            StepKind::ExhaustNonattacksBlock,
            StepKind::ExhaustRandom,
            StepKind::FiendFireExact,
            StepKind::FlakCannonExact,
            StepKind::Havoc,
            StepKind::PurityExact,
            StepKind::StokeExact,
            StepKind::ThrashExact,
            StepKind::Tyranny,
        ] {
            assert!(non_ash_card_exhaust_step_kind(kind), "{kind:?}");
        }
        for kind in [StepKind::Draw, StepKind::Block, StepKind::Attack] {
            assert!(!non_ash_card_exhaust_step_kind(kind), "{kind:?}");
        }

        for id in [
            CardId::Offering,
            CardId::Dazed,
            CardId::FiendFire,
            CardId::Stoke,
            CardId::Thrash,
            CardId::FlakCannon,
            CardId::Purity,
            CardId::Havoc,
            CardId::Corruption,
            CardId::Tyranny,
            CardId::TrueGrit,
        ] {
            let catalog = catalog_with(&base, identity(id, 0));
            assert!(
                non_ash_card_exhaust_source_is_reachable(&state, &catalog),
                "{id:?} must remain outside Ashwater's owned Dark caller"
            );
        }
        for power in [PowerId::Corruption, PowerId::Tyranny] {
            let mut live = state.clone();
            live.powers.set(power, SlotWire::Int, 1);
            assert!(non_ash_card_exhaust_source_is_reachable(&live, &base));
        }
        for pile in PileId::ALL {
            let mut local_exhaust = state.clone();
            let mut card = local_exhaust
                .piles
                .get_mut(PileId::Hand)
                .make_mut()
                .remove(0);
            card.flags |= crate::hot::CARD_FLAG_LOCAL_EXHAUST;
            local_exhaust.piles.get_mut(pile).make_mut().push(card);
            assert!(
                non_ash_card_exhaust_source_is_reachable(&local_exhaust, &base),
                "local-exhaust physical card in {pile:?}"
            );
        }
    }

    #[test]
    fn hellraiser_strike_registry_and_recursive_program_census_is_closed() {
        let strike_rows = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.strike_tag)
            .map(|row| (row.id, row.upgrade, row.selects))
            .collect::<Vec<_>>();
        // 44 since #2501 gave Blight Strike its native CardTag.Strike
        // (BlightStrike::get_CanonicalTags 0xd91e8 = [CardTag.Strike]); it
        // contributes the two non-selecting L0/L1 rows below.
        assert_eq!(strike_rows.len(), 44);
        assert_eq!(
            strike_rows
                .iter()
                .copied()
                .filter(|(_, _, selects)| *selects)
                .collect::<Vec<_>>(),
            [
                (CardId::SculptingStrike, 0, true),
                (CardId::SculptingStrike, 1, true),
                (CardId::SeekerStrike, 0, true),
                (CardId::SeekerStrike, 1, true),
            ]
        );
        for row in crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.strike_tag && !row.selects)
        {
            assert!(matches!(
                row.id,
                CardId::AdaptiveStrike
                    | CardId::AshenStrike
                    | CardId::BlightStrike
                    | CardId::FocusedStrike
                    | CardId::LeadingStrike
                    | CardId::MeteorStrike
                    | CardId::MinionStrike
                    | CardId::MomentumStrike
                    | CardId::PerfectedStrike
                    | CardId::PommelStrike
                    | CardId::SetupStrike
                    | CardId::ShiningStrike
                    | CardId::SolarStrike
                    | CardId::StrikeDefect
                    | CardId::StrikeIronclad
                    | CardId::StrikeNecrobinder
                    | CardId::StrikeRegent
                    | CardId::StrikeSilent
                    | CardId::TwinStrike
                    | CardId::UltimateStrike
            ));
            assert!(crate::content_tables::card_row(row.id, row.upgrade) == Some(row));
            assert!(row.steps.iter().all(|step| {
                !matches!(
                    step.kind,
                    StepKind::Select
                        | StepKind::ExhaustDraw
                        | StepKind::EidolonExact
                        | StepKind::Stampede
                        | StepKind::Hellraiser
                )
            }));
        }
    }

    #[test]
    fn stampede_power_and_future_unplayable_writer_census_is_closed() {
        let mut builder = CatalogBuilder::new();
        for row in crate::catalog::variant_free_card_rows() {
            builder.intern(identity(row.id, row.upgrade)).unwrap();
        }
        let catalog = builder.build();
        let stampede_or_hellraiser_writers: Vec<_> = catalog
            .specs()
            .filter(|spec| {
                catalog
                    .steps(spec)
                    .iter()
                    .any(|step| matches!(step.kind, StepKind::Stampede | StepKind::Hellraiser))
            })
            .map(|spec| (spec.identity.id, spec.identity.upgrade, spec.is_attack))
            .collect();
        assert_eq!(
            stampede_or_hellraiser_writers,
            [
                (CardId::Hellraiser, 0, false),
                (CardId::Hellraiser, 1, false),
                (CardId::Stampede, 0, false),
                (CardId::Stampede, 1, false),
            ],
            "a new Attack writer invalidates the retained StampedePower identity proof"
        );
        assert!(catalog.specs().filter(|spec| spec.is_attack).all(|spec| {
            catalog.steps(spec).iter().all(|step| {
                !matches!(step.kind, StepKind::Stampede | StepKind::Hellraiser)
                    && !catalog.args(step.args).iter().any(|arg| {
                        matches!(
                            arg,
                            CompiledArg::Power(PowerId::Stampede | PowerId::Hellraiser)
                        )
                    })
            })
        }));

        let conqueror = catalog
            .specs()
            .filter(|spec| spec.identity.id == CardId::Conqueror)
            .map(|spec| (spec.identity.upgrade, spec.is_skill, spec.is_attack))
            .collect::<Vec<_>>();
        assert_eq!(conqueror, [(0, true, false), (1, true, false)]);
        assert_eq!(crate::content_tables::NATIVE_UNPLAYABLE_CARD_ROWS.len(), 27);
        assert_eq!(
            catalog
                .specs()
                .filter(|spec| spec.native_unplayable && spec.is_attack)
                .map(|spec| (spec.identity.id, spec.identity.upgrade))
                .collect::<Vec<_>>(),
            [],
            "a future enum-4 Attack must join Stampede's effective-keyword closure"
        );
    }

