    #[test]
    fn thrash_admits_every_reachable_null_target_modifier_writer() {
        let mut one_for_all = generator_document(CardId::Thrash, RewardPool::Defect, false, 1884);
        one_for_all.piles.get_mut("hand").unwrap()[0].physical_state =
            Some(serde_json::json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
        push_physical_card(&mut one_for_all, "hand", CardId::OneForAll, 0);
        let catalog = HotBoundary::catalog_from_canonical(&one_for_all).unwrap();
        let state = HotBoundary::from_canonical(&one_for_all, &catalog).unwrap();
        assert_eq!(admit(&one_for_all, &state, &catalog), Ok(()));

        let mut shadow_step = generator_document(CardId::Thrash, RewardPool::Ironclad, false, 1884);
        shadow_step.piles.get_mut("hand").unwrap()[0].physical_state =
            Some(serde_json::json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
        push_physical_card(&mut shadow_step, "hand", CardId::ShadowStep, 0);
        let catalog = HotBoundary::catalog_from_canonical(&shadow_step).unwrap();
        let state = HotBoundary::from_canonical(&shadow_step, &catalog).unwrap();
        assert_eq!(admit(&shadow_step, &state, &catalog), Ok(()));

        let mut live_shadow_step =
            generator_document(CardId::Thrash, RewardPool::Ironclad, false, 1884);
        live_shadow_step.piles.get_mut("hand").unwrap()[0].physical_state =
            Some(serde_json::json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
        live_shadow_step.player.insert(
            PowerId::ShadowStep.as_str().to_owned(),
            serde_json::json!(1),
        );
        let catalog = HotBoundary::catalog_from_canonical(&live_shadow_step).unwrap();
        let state = HotBoundary::from_canonical(&live_shadow_step, &catalog).unwrap();
        assert_eq!(admit(&live_shadow_step, &state, &catalog), Ok(()));

        // A generated producer need not have placed its leaf in a physical
        // pile yet. Reachability is the catalog's transitive closure, so a
        // catalog-only exact writer must close the same future composition.
        let mut catalog_only =
            generator_document(CardId::Thrash, RewardPool::Ironclad, false, 1884);
        catalog_only.piles.get_mut("hand").unwrap()[0].physical_state =
            Some(serde_json::json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
        let base = HotBoundary::catalog_from_canonical(&catalog_only).unwrap();
        let state = HotBoundary::from_canonical(&catalog_only, &base).unwrap();
        for writer in [CardId::OneForAll, CardId::ShadowStep] {
            let catalog = catalog_with(&base, identity(writer, 0));
            assert_eq!(admit(&catalog_only, &state, &catalog), Ok(()));
        }
    }

