    fn identity(id: CardId, upgrade: u8) -> CardIdentity {
        CardIdentity {
            id,
            upgrade,
            enchantment: None,
        }
    }

    fn admitted_fixed_star_rows() -> BTreeSet<CardIdentity> {
        ADMITTED_FIXED_STAR_BOTH_UPGRADES
            .iter()
            .flat_map(|id| [identity(*id, 0), identity(*id, 1)])
            .chain([
                identity(CardId::RoyalGamble, 0),
                identity(CardId::RoyalGamble, 1),
            ])
            .collect()
    }

    fn admitted_star_gain_rows() -> BTreeSet<CardIdentity> {
        ADMITTED_STAR_GAIN_BOTH_UPGRADES
            .iter()
            .flat_map(|id| [identity(*id, 0), identity(*id, 1)])
            .chain([
                identity(CardId::RoyalGamble, 0),
                identity(CardId::RoyalGamble, 1),
            ])
            .collect()
    }

    fn play_isolated(identity: CardIdentity) -> Result<(), crate::engine::EngineRefusal> {
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(identity).unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let spec = *catalog.spec(atom).unwrap();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.energy = 20;
        state.stars = 20;
        if identity.id == CardId::Constellation {
            state.multiplayer_ally_key = 1;
            state
                .fanouts
                .set_multiplayer_ally(crate::hot::MultiplayerAllyState {
                    key: 1,
                    ..crate::hot::MultiplayerAllyState::default()
                });
        }
        state.next_card_uid = 2;
        state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(crate::hot::HotCard {
                uid: 1,
                atom,
                flags: crate::hot::CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
        state
            .monsters_mut()
            .push(crate::hot::HotMonster::new(MonsterKind::Toadpole, 1_000));
        crate::engine::play::play_card(
            &mut state,
            &catalog,
            1,
            spec.targeted.then_some(0),
            None,
            &mut Vec::new(),
        )
    }

