    #[test]
    fn fixed_star_cost_admission_includes_the_sealed_throne_rows() {
        let fixed_rows: Vec<CardIdentity> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.star_cost >= 0 && !row.star_x)
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        assert_eq!(
            fixed_rows.len(),
            44,
            "generated fixed-Star row census drifted"
        );

        let (document, state, base) = parts();
        let admitted: BTreeSet<CardIdentity> = fixed_rows
            .iter()
            .copied()
            .filter(|candidate| {
                let catalog = catalog_with(&base, *candidate);
                admit(&document, &state, &catalog).is_ok()
            })
            .collect();
        assert_eq!(admitted, admitted_fixed_star_rows());
        for candidate in &admitted {
            play_isolated(*candidate).unwrap_or_else(|refusal| {
                panic!(
                    "admitted fixed-Star row {}+{} refused at play: {refusal}",
                    candidate.id.as_str(),
                    candidate.upgrade
                )
            });
        }

        let refused: BTreeSet<CardIdentity> = fixed_rows
            .into_iter()
            .filter(|candidate| !admitted.contains(candidate))
            .collect();
        let expected_refused: BTreeSet<CardIdentity> = UNMODELED_FIXED_STAR_STEP_IDS
            .iter()
            .flat_map(|id| [identity(*id, 0), identity(*id, 1)])
            .chain([identity(CardId::Quasar, 0), identity(CardId::Quasar, 1)])
            .collect();
        assert_eq!(refused, expected_refused);

        for candidate in refused {
            let refusal = admit(&document, &state, &catalog_with(&base, candidate)).unwrap_err();
            let row = crate::content_tables::card_row(candidate.id, candidate.upgrade)
                .expect("fixed-Star identity came from the generated table");
            if candidate.id == CardId::Quasar {
                assert!(refusal.contains(MissingCapability::ArgumentShape(
                    "Quasar generation closure"
                )));
            } else if candidate.id == CardId::RoyalGamble
                || row
                    .steps
                    .iter()
                    .any(|step| step.kind == StepKind::ForgeFamilyExact)
                || row.selects && !generated_select_program_is_supported(row)
            {
                assert!(refusal.contains(MissingCapability::CardKeyword(candidate.id)));
            } else {
                assert!(
                    refusal
                        .missing()
                        .any(|capability| matches!(capability, MissingCapability::StepKind(_))),
                    "{}+{} lost its independent step refusal: {refusal}",
                    candidate.id.as_str(),
                    candidate.upgrade
                );
            }
        }
    }

    #[test]
    fn guiding_star_admits_both_rows_and_closes_listener_and_overflow_state() {
        for upgrade in 0..=1 {
            let (document, state, base) = parts();
            let catalog = catalog_with(&base, identity(CardId::GuidingStar, upgrade));
            assert_eq!(
                admit(&document, &state, &catalog),
                Ok(()),
                "Guiding Star+{upgrade}"
            );
        }

        // Keep the generic listener-order shape valid so this isolates the
        // Guiding Star application observer rather than tripping the global
        // order validator first.
        // Exercise both the ordinary Hand entry and the Play-pile shape used
        // by nested AutoPlay. Admission must reject either before an action
        // can spend resources, select a target, or mutate the source card.
        for pile in ["hand", "play"] {
            let (mut observed, _, _) = parts();
            replace_first_hand_card(&mut observed, CardId::GuidingStar, 0);
            if pile == "play" {
                let source = observed.piles.get_mut("hand").unwrap().remove(0);
                observed
                    .piles
                    .entry("play".to_owned())
                    .or_default()
                    .push(source);
            }
            observed.player.insert("shroud".to_owned(), Value::from(1));
            observed.player.insert(
                "after_power_amount_changed_power_order".to_owned(),
                json!(["shroud"]),
            );
            let catalog = HotBoundary::catalog_from_canonical(&observed).unwrap();
            let state = HotBoundary::from_canonical(&observed, &catalog).unwrap();
            let state_before = state.clone();
            let refusal = admit(&observed, &state, &catalog).unwrap_err();
            assert!(refusal.contains(MissingCapability::ArgumentShape(
                "Guiding Star power application listener order"
            )));
            assert_eq!(
                state, state_before,
                "{pile} listener preflight is read-only"
            );

            let (mut overflowing, _, _) = parts();
            replace_first_hand_card(&mut overflowing, CardId::GuidingStar, 1);
            if pile == "play" {
                let source = overflowing.piles.get_mut("hand").unwrap().remove(0);
                overflowing
                    .piles
                    .entry("play".to_owned())
                    .or_default()
                    .push(source);
            }
            overflowing.player.insert(
                "draw_next_turn".to_owned(),
                Value::from(i64::from(i32::MAX - 2)),
            );
            let catalog = HotBoundary::catalog_from_canonical(&overflowing).unwrap();
            let state = HotBoundary::from_canonical(&overflowing, &catalog).unwrap();
            let state_before = state.clone();
            let refusal = admit(&overflowing, &state, &catalog).unwrap_err();
            assert!(refusal.contains(MissingCapability::ArgumentShape(
                "Guiding Star draw next turn range"
            )));
            assert_eq!(state, state_before, "{pile} +3 preflight is read-only");
        }
    }

    #[test]
    fn generated_selection_gate_censuses_shapes_admission_and_mutations() {
        let (document, state, base) = parts();
        let rows: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.selects)
            .collect();
        assert_eq!(rows.len(), 80, "generated select carrier census drifted");

        let supported_shapes: Vec<_> = rows
            .iter()
            .copied()
            .filter(|row| generated_select_program_is_supported(row))
            .collect();
        // +2 (#3291): Transfigure L0/L1's exact-one `transfigure_exact`.
        // +2 (#3374): Dual Wield L0/L1's `("clone_generated", 1 + upgrade)`.
        assert_eq!(
            supported_shapes.len(),
            58,
            "complete generated select shape census drifted"
        );
        for row in &rows {
            if !generated_select_program_is_supported(row)
                && !body_owned_select_program_is_supported(row)
            {
                let candidate = identity(row.id, row.upgrade);
                let refusal =
                    admit(&document, &state, &catalog_with(&base, candidate)).unwrap_err();
                assert!(
                    refusal.contains(MissingCapability::CardKeyword(row.id)),
                    "{}+{} lost its row-derived selector refusal: {refusal}",
                    row.id.as_str(),
                    row.upgrade
                );
            }
        }

        let admitted: BTreeSet<_> = rows
            .iter()
            .filter_map(|row| {
                let candidate = identity(row.id, row.upgrade);
                admit(&document, &state, &catalog_with(&base, candidate))
                    .is_ok()
                    .then_some(candidate)
            })
            .collect();
        let expected: BTreeSet<_> = [
            CardId::DecisionsDecisions,
            CardId::Acrobatics,
            CardId::HandTrick,
            CardId::Begone,
            CardId::Charge,
            CardId::Guards,
            CardId::Brand,
            CardId::Cleanse,
            CardId::CosmicIndifference,
            CardId::DaggerThrow,
            CardId::Dredge,
            CardId::Graveblast,
            CardId::Headbutt,
            CardId::HeirloomHammer,
            CardId::HiddenDaggers,
            CardId::Hologram,
            CardId::PhotonCut,
            CardId::Prepared,
            CardId::Purity,
            CardId::Scavenge,
            CardId::Seance,
            CardId::SecretTechnique,
            CardId::SecretWeapon,
            CardId::SculptingStrike,
            CardId::Snap,
            CardId::Survivor,
            CardId::ThinkingAhead,
            CardId::SeekerStrike,
            CardId::NeowsFury,
            CardId::Glimmer,
            // #3291
            CardId::Transfigure,
            // #3374
            CardId::DualWield,
        ]
        .into_iter()
        .flat_map(|id| [identity(id, 0), identity(id, 1)])
        .chain([
            identity(CardId::Armaments, 0),
            identity(CardId::TrueGrit, 1),
            identity(CardId::Wish, 0),
            identity(CardId::Wish, 1),
        ])
        .collect();
        assert_eq!(
            admitted, expected,
            "the row-derived gate must enumerate every currently admitted row"
        );
        for candidate in &admitted {
            play_isolated(*candidate).unwrap_or_else(|refusal| {
                panic!(
                    "admitted select row {}+{} refused at play: {refusal}",
                    candidate.id.as_str(),
                    candidate.upgrade
                )
            });
        }
        assert!(
            rows.len() > admitted.len(),
            "the complete selecting-row census must retain independent refusals"
        );

        const UPGRADE_ARGS: &[Arg] = &[
            Arg::S("hand"),
            Arg::I(1),
            Arg::I(1),
            Arg::S("upgradable"),
            Arg::Select(SelectOp::Upgrade),
        ];
        const UPGRADE_STEPS: &[crate::content_tables::Step] = &[crate::content_tables::Step {
            kind: StepKind::Select,
            args: UPGRADE_ARGS,
        }];
        let survivor = *crate::content_tables::card_row(CardId::Survivor, 0).unwrap();
        let mut operation_mutation = survivor;
        operation_mutation.steps = UPGRADE_STEPS;
        assert!(!generated_select_program_is_supported(&operation_mutation));
        assert!(!card_keywords_are_inert(&operation_mutation));

        let armaments = *crate::content_tables::card_row(CardId::Armaments, 0).unwrap();
        assert!(generated_select_program_is_supported(&armaments));
        for mutation in 0..7 {
            let mut forged = armaments;
            let mut args = UPGRADE_ARGS.to_vec();
            match mutation {
                0 => forged.id = CardId::Survivor,
                1 => forged.upgrade = 1,
                2 => args[0] = Arg::S("discard"),
                3 => args[1] = Arg::I(0),
                4 => args[2] = Arg::I(2),
                5 => args[3] = Arg::S("attack"),
                6 => args[4] = Arg::S("unsupported_upgrade"),
                _ => unreachable!(),
            }
            let leaked_args = Box::leak(args.into_boxed_slice());
            let leaked_steps = Box::leak(
                vec![
                    crate::content_tables::Step {
                        kind: StepKind::Block,
                        args: &[Arg::I(5)],
                    },
                    crate::content_tables::Step {
                        kind: StepKind::Select,
                        args: leaked_args,
                    },
                ]
                .into_boxed_slice(),
            );
            forged.steps = leaked_steps;
            assert!(
                !generated_select_program_is_supported(&forged),
                "Armaments mutation {mutation}"
            );
        }

        let mut flag_mutation = survivor;
        flag_mutation.selects = false;
        assert!(generated_select_program_is_supported(&flag_mutation));
        assert!(
            !card_keywords_are_inert(&flag_mutation),
            "a stale generated selects flag cannot bypass the gate"
        );

        let mut identity_mutation = survivor;
        identity_mutation.id = CardId::StrikeSilent;
        assert!(
            generated_select_program_is_supported(&identity_mutation),
            "shape support must not be a card-identity allowlist"
        );

        let secret = *crate::content_tables::card_row(CardId::SecretTechnique, 0).unwrap();
        let mut filter_owner_mutation = secret;
        filter_owner_mutation.id = CardId::StrikeSilent;
        assert!(
            !generated_select_program_is_supported(&filter_owner_mutation),
            "the oracle's two source-owned Batch-65 filter readers stay exact"
        );

        for upgrade in 0..=1 {
            let heirloom =
                *crate::content_tables::card_row(CardId::HeirloomHammer, upgrade).unwrap();
            assert!(generated_select_program_is_supported(&heirloom));
            let mut wrong_owner = heirloom;
            wrong_owner.id = CardId::DualWield;
            assert!(
                !generated_select_program_is_supported(&wrong_owner),
                "clone_generated is authenticated by the complete Heirloom row"
            );
        }
        // #3374: Dual Wield owns its own clone seam. Each level's count is
        // `1 + upgrade`; a swapped count, filter, pile, range or owner refuses.
        for upgrade in 0..=1u8 {
            let dual_wield = *crate::content_tables::card_row(CardId::DualWield, upgrade).unwrap();
            assert!(generated_select_program_is_supported(&dual_wield));
            assert_eq!(
                admit(
                    &document,
                    &state,
                    &catalog_with(&base, identity(CardId::DualWield, upgrade)),
                ),
                Ok(())
            );
            let other = *crate::content_tables::card_row(CardId::DualWield, 1 - upgrade).unwrap();
            let mut swapped_count = dual_wield;
            swapped_count.steps = other.steps;
            assert!(
                !generated_select_program_is_supported(&swapped_count),
                "Dual Wield L{upgrade} must not carry the other level's clone count"
            );
            let mut wrong_owner = dual_wield;
            wrong_owner.id = CardId::HeirloomHammer;
            assert!(!generated_select_program_is_supported(&wrong_owner));
        }
    }

    #[test]
    fn unit_c_gate_constellation_and_energy_surge_census_the_complete_shared_keyword_closure() {
        const BATCH_A: &[StepKind] = &[
            StepKind::RestlessnessExact,
            StepKind::FlakCannonExact,
            StepKind::AutoplayDrawX,
            StepKind::GenerateFixedStatus,
            StepKind::GunkUpExact,
            StepKind::Heal,
            StepKind::GenerateShivsThenUpgradeExact,
        ];
        const ALLY_PROGRAMS: &[StepKind] = &[
            StepKind::BelieveInYouExact,
            StepKind::ConstellationExact,
            StepKind::CoordinateExact,
            StepKind::EnergySurgeExact,
            StepKind::FadeExact,
            StepKind::InterceptExact,
            StepKind::LiftExact,
            StepKind::MimicExact,
            StepKind::RallyExact,
            StepKind::ImitationLearningExact,
            StepKind::HuddleUpExact,
            StepKind::PlotExact,
            StepKind::BladeSymphonyExact,
            StepKind::GlimpseBeyondExact,
        ];

        let (document, state, base) = parts();
        let carriers = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.steps.iter().any(|step| BATCH_A.contains(&step.kind)))
            .collect::<Vec<_>>();
        assert_eq!(carriers.len(), 22, "seven leaves have 22 exact source rows");
        assert_eq!(
            carriers
                .iter()
                .flat_map(|row| row.steps.iter().map(|step| step.kind))
                .filter(|kind| BATCH_A.contains(kind))
                .collect::<BTreeSet<_>>(),
            BATCH_A.iter().copied().collect()
        );
        for row in carriers {
            let candidate = identity(row.id, row.upgrade);
            let catalog = catalog_with(&base, candidate);
            assert_eq!(
                admit(&document, &state, &catalog),
                Ok(()),
                "{}+{} must be admitted",
                row.id.as_str(),
                row.upgrade
            );
        }

        let fixed = [
            CardId::Wound,
            CardId::Dazed,
            CardId::Debris,
            CardId::Burn,
            CardId::Void,
            CardId::Slimed,
        ];
        for id in fixed {
            let row = *crate::content_tables::card_row(id, 0).unwrap();
            assert!(card_keywords_are_inert(&row), "{}+0", id.as_str());
            let mut wrong_level = row;
            wrong_level.upgrade = 1;
            assert!(!card_keywords_are_inert(&wrong_level), "{}+1", id.as_str());
        }
        let admitted_fixed = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| fixed.contains(&row.id))
            .filter(|row| card_keywords_are_inert(row))
            .map(|row| (row.id, row.upgrade))
            .collect::<BTreeSet<_>>();
        assert_eq!(
            admitted_fixed,
            fixed.into_iter().map(|id| (id, 0)).collect()
        );

        let mut party = document.clone();
        add_minimal_party(&mut party);
        let mut ally_rows = 0;
        for kind in ALLY_PROGRAMS {
            assert!(crate::steps::is_implemented(*kind));
            let rows = crate::content_tables::CARD_ROWS
                .iter()
                .filter(|row| row.steps.iter().any(|step| step.kind == *kind))
                .collect::<Vec<_>>();
            assert!(!rows.is_empty(), "{} lost every carrier", kind.as_str());
            ally_rows += rows.len();
            for row in rows {
                assert!(
                    card_keywords_are_inert(row),
                    "{}+{} ally keyword shape",
                    row.id.as_str(),
                    row.upgrade
                );
                let candidate = identity(row.id, row.upgrade);
                let catalog = catalog_with(&base, candidate);
                let party_state = HotBoundary::from_canonical(&party, &catalog).unwrap();
                assert_eq!(
                    admit(&party, &party_state, &catalog),
                    Ok(()),
                    "{}+{} must admit in the exact two-Player boundary",
                    row.id.as_str(),
                    row.upgrade,
                );
            }
        }
        assert_eq!(
            ally_rows, 28,
            "fourteen ally kinds have two exact rows each"
        );

        for upgrade in 0..=1 {
            let glimpse = *crate::content_tables::card_row(CardId::GlimpseBeyond, upgrade).unwrap();
            assert!(glimpse_beyond_program_is_supported(&glimpse));

            let mut wrong_target = glimpse;
            wrong_target.target_type = "AnyAlly";
            assert!(!glimpse_beyond_program_is_supported(&wrong_target));
            assert!(!card_keywords_are_inert(&wrong_target));

            let mut wrong_owner = glimpse;
            wrong_owner.id = CardId::BelieveInYou;
            assert!(!glimpse_beyond_program_is_supported(&wrong_owner));
            assert!(!card_keywords_are_inert(&wrong_owner));
        }

        let believe = *crate::content_tables::card_row(CardId::BelieveInYou, 0).unwrap();
        let mut enemy_alias = believe;
        enemy_alias.target_type = "AnyEnemy";
        assert!(
            !card_keywords_are_inert(&enemy_alias),
            "an AnyAlly body cannot inherit monster-roster target bytes"
        );
        let strike = *crate::content_tables::card_row(CardId::StrikeIronclad, 0).unwrap();
        let mut ally_alias = strike;
        ally_alias.target_type = "AnyAlly";
        assert!(
            !card_keywords_are_inert(&ally_alias),
            "an enemy body cannot reinterpret its roster index as a Player key"
        );

        let mut pet_party = party.clone();
        pet_party
            .player
            .insert("ally".to_owned(), json!(["OSTY", 3, 5]));
        let believe_catalog = catalog_with(&base, identity(CardId::BelieveInYou, 0));
        let pet_state = HotBoundary::from_canonical(&pet_party, &believe_catalog).unwrap();
        assert!(
            admit(&pet_party, &pet_state, &believe_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "manual AnyAlly target roster"
                )),
            "local Osty is a same-side creature but never a PlayerCreature target"
        );
        let largesse_catalog = catalog_with(&base, identity(CardId::Largesse, 0));
        let pet_state = HotBoundary::from_canonical(&pet_party, &largesse_catalog).unwrap();
        assert!(
            admit(&pet_party, &pet_state, &largesse_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "manual AnyAlly target roster"
                )),
            "Largesse must own the AnyAlly pet refusal without relying on generated pool peers"
        );

        let osty_writers = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                row.steps.iter().any(|step| {
                    matches!(
                        step.kind,
                        StepKind::OstySummonHeal
                            | StepKind::DirgeXExact
                            | StepKind::DevourLife
                            | StepKind::Summon
                    )
                })
            })
            .collect::<Vec<_>>();
        assert_eq!(osty_writers.len(), 18, "complete live-Osty writer census");
        for row in osty_writers {
            let any_ally_catalog = catalog_with(&base, identity(CardId::BelieveInYou, 0));
            let catalog = catalog_with(&any_ally_catalog, identity(row.id, row.upgrade));
            let state = HotBoundary::from_canonical(&party, &catalog).unwrap();
            assert!(
                admit(&party, &state, &catalog).unwrap_err().contains(
                    MissingCapability::ArgumentShape("manual AnyAlly target roster")
                ),
                "{}+{} can summon an AnyAlly-visible Osty later",
                row.id.as_str(),
                row.upgrade
            );
        }

        let rally_catalog = catalog_with(&base, identity(CardId::Rally, 0));
        let mut lethal_rally = HotBoundary::from_canonical(&party, &rally_catalog).unwrap();
        lethal_rally
            .powers
            .set(PowerId::Juggernaut, crate::powers::SlotWire::Int, 6);
        assert!(
            lethal_rally
                .fanouts
                .set_after_block_gained_order(&[PowerId::Juggernaut])
        );
        lethal_rally.monsters_mut()[0].hp = 7;
        for monster in &mut lethal_rally.monsters_mut()[1..] {
            monster.hp = 0;
        }
        assert!(
            !crate::engine::play::juggernaut_block_can_end_combat(&lethal_rally, 1),
            "entry refusal must cover a currently nonlethal hit that can become lethal later"
        );
        assert!(
            admit(&party, &lethal_rally, &rally_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "Rally remote Juggernaut lifecycle"
                )),
            "party Rally must close over a live Juggernaut's future HP-sensitive reader"
        );

        let constellation_catalog = catalog_with(&base, identity(CardId::Constellation, 0));
        let mut owner_dex = HotBoundary::from_canonical(&party, &constellation_catalog).unwrap();
        owner_dex
            .powers
            .set(PowerId::TempDexterity, SlotWire::Int, 1);
        assert_eq!(
            admit(&party, &owner_dex, &constellation_catalog),
            Ok(()),
            "remote Constellation exactly reads the CardPlay owner's temporary Dexterity"
        );

        let rally_plus_catalog = catalog_with(&base, identity(CardId::Rally, 1));
        let mut owner_dex_range = HotBoundary::from_canonical(&party, &rally_plus_catalog).unwrap();
        owner_dex_range
            .powers
            .set(PowerId::Dexterity, SlotWire::Int, i32::MAX - 17);
        assert_eq!(admit(&party, &owner_dex_range, &rally_plus_catalog), Ok(()));
        owner_dex_range
            .powers
            .set(PowerId::Dexterity, SlotWire::Int, i32::MAX - 16);
        assert!(
            admit(&party, &owner_dex_range, &rally_plus_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "remote powered Block amount range"
                ))
        );

        let mut dead_party = party.clone();
        dead_party.player.insert(
            "multiplayer_allies".to_owned(),
            json!([{
                "type": "MultiplayerAllyState",
                "fields": {"key": 1, "alive": false},
            }]),
        );
        let dead_state = HotBoundary::from_canonical(&dead_party, &believe_catalog).unwrap();
        assert!(
            admit(&dead_party, &dead_state, &believe_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "AutoPlay AnyAlly missing teammate target"
                )),
            "empty non-owner AutoPlay target routing remains a named refusal"
        );

        let callback_catalog = catalog_with(&base, identity(CardId::Inflame, 0));
        let mut callback_state = HotBoundary::from_canonical(&party, &callback_catalog).unwrap();
        assert!(callback_state.fanouts.set_imitation_learning(1, 1));
        callback_state
            .fanouts
            .imitation_clones_mut()
            .push(crate::hot::ImitationClone {
                target_key: 1,
                source_identity: 77,
                clone_uid: 9,
                identity: identity(CardId::Inflame, 0),
                flags: 0,
                instance: crate::hot::CardInstanceState::default(),
            });
        callback_state
            .fanouts
            .set_teammate_power_pending(Some((1, 77)));
        assert!(
            admit(&party, &callback_state, &callback_catalog)
                .unwrap_err()
                .contains(MissingCapability::ContinuationFrame),
            "an unsupported external teammate callback refuses at admission"
        );

        for kind in [
            MonsterKind::Vantom,
            MonsterKind::LeafSlimeM,
            MonsterKind::SlimedBerserker,
        ] {
            let (mut encounter, _, _) = parts();
            encounter.monsters[0].insert("kind".to_owned(), Value::from(kind.as_str()));
            let catalog = HotBoundary::catalog_from_canonical(&encounter).unwrap();
            let state = HotBoundary::from_canonical(&encounter, &catalog).unwrap();
            assert_eq!(
                admit(&encounter, &state, &catalog),
                Ok(()),
                "{kind:?} is the exact generated-Status encounter delta"
            );
        }
        // Mecha Knight's FLAMETHROWER injects Burn. Its loop successor is
        // admitted as of #2481, so the original "refuses on loop control but
        // not on Burn" assertion is now the stronger "admits outright" — the
        // Burn injection still must not raise a card-keyword refusal.
        let (mut mecha, _, _) = parts();
        mecha.monsters[0].insert(
            "kind".to_owned(),
            Value::from(MonsterKind::MechaKnight.as_str()),
        );
        let catalog = HotBoundary::catalog_from_canonical(&mecha).unwrap();
        let state = HotBoundary::from_canonical(&mecha, &catalog).unwrap();
        assert_eq!(
            admit(&mecha, &state, &catalog),
            Ok(()),
            "Mecha Knight's fixed successor and Burn injection both admit"
        );

        // Magi Knight's PREP block and fixed MAGIC_BOMB -> RAM tail are exact.
        let (mut magi, _, _) = parts();
        magi.monsters[0].insert(
            "kind".to_owned(),
            Value::from(MonsterKind::MagiKnight.as_str()),
        );
        let catalog = HotBoundary::catalog_from_canonical(&magi).unwrap();
        let state = HotBoundary::from_canonical(&magi, &catalog).unwrap();
        assert_eq!(admit(&magi, &state, &catalog), Ok(()));
    }

    /// Every kind the `Repeats::Fixed` admission allowlist names must have a
    /// generated loop that is entirely `Absent`/`Fixed`.
    ///
    /// The allowlist is sound only because the *execution* of a fixed
    /// successor is kind-agnostic, which makes admitting a kind a claim about
    /// its generated table rather than about any code in this file. A content
    /// regeneration that gave an allowlisted kind a `Repeats::Conditional`
    /// entry would silently fall through `turn.rs`'s conditional arms into the
    /// generic tail and take the wrong successor — with no refusal and no diff
    /// here to review. So derive the premise from `LOOPS` rather than
    /// restating it: this fails the moment the table stops supporting the
    /// allowlist.
    ///
    /// Deliberately derived and not a hand-list — the same reason
    /// `test_post_submit_lanes_key_concurrency_by_commit` derives its lane set
    /// (root `CLAUDE.md`): a transcribed list drifts from the thing it claims
    /// to describe, and this one would drift silently.
    #[test]
    fn allowlisted_fixed_successor_kinds_have_no_conditional() {
        use crate::content_tables::{LOOPS, Repeats};

        let mut walked = 0;
        for kind in FIXED_SUCCESSOR_ALLOWLIST {
            let moves = LOOPS
                .iter()
                .find(|(loop_kind, _)| *loop_kind == kind)
                .map(|(_, moves)| *moves)
                .unwrap_or_else(|| panic!("{kind:?} is allowlisted but has no generated loop"));
            walked += 1;
            for entry in moves {
                // Interrogate the real gate, not a restatement of it. A
                // regenerated `Conditional` on an allowlisted kind is caught
                // here iff no explicit conditional arm accepts it — which is
                // exactly the condition under which the generic tail would
                // take the wrong successor. FrogKnight, Queen and
                // KnowledgeDemon legitimately carry `Conditional` entries and
                // pass because `successor_is_supported` names their tuples.
                assert!(
                    successor_is_supported(kind, entry.kind, entry.repeats, moves.len()),
                    "{kind:?} move {:?} has a successor the gate cannot resolve \
                     ({:?}), yet the kind is on FIXED_SUCCESSOR_ALLOWLIST. Either \
                     give it an explicit conditional arm in `successor_is_supported` \
                     and `turn.rs`, or drop it from the allowlist — leaving it takes \
                     the generic tail and silently picks the wrong successor.",
                    entry.name,
                    entry.repeats
                );
            }
            assert!(
                moves
                    .iter()
                    .any(|entry| matches!(entry.repeats, Repeats::Fixed(_))),
                "{kind:?} is on FIXED_SUCCESSOR_ALLOWLIST but its regenerated loop no \
                 longer has any fixed successor; the entry is now dead and should be \
                 removed rather than left to rot"
            );
        }
        assert_eq!(walked, FIXED_SUCCESSOR_ALLOWLIST.len());

        // The allowlist is a claim about admission, so a kind that is NOT on
        // it must actually still be refused — otherwise this guard would pass
        // vacuously if the gate stopped consulting the list at all.
        for (kind, moves) in LOOPS
            .iter()
            .filter(|(kind, _)| !FIXED_SUCCESSOR_ALLOWLIST.contains(kind))
        {
            for entry in moves
                .iter()
                .filter(|entry| matches!(entry.repeats, Repeats::Fixed(_)))
            {
                assert!(
                    !successor_is_supported(*kind, entry.kind, entry.repeats, moves.len()),
                    "{kind:?}"
                );
            }
        }
        // #2850 admitted TrackerRubyRaider, the last generated kind whose
        // fixed successor was off the list, so the generated walk above can
        // now be empty. Keep the gate non-vacuous with a synthetic control:
        // an unlisted kind presenting an in-range fixed successor must still
        // be refused by the list alone.
        let (control, control_moves) = LOOPS
            .iter()
            .find(|(kind, moves)| !FIXED_SUCCESSOR_ALLOWLIST.contains(kind) && !moves.is_empty())
            .expect("an unlisted generated loop exists");
        assert!(
            !successor_is_supported(
                *control,
                control_moves[0].kind,
                Repeats::Fixed(0),
                control_moves.len()
            ),
            "{control:?}: an unlisted kind's fixed successor must refuse"
        );
    }

    #[test]
    fn glimpse_party_admits_an_exact_keyed_constrict_carrier() {
        let (mut document, _, base) = parts();
        add_minimal_party(&mut document);
        let mut builder = CatalogBuilder::new();
        for spec in base.specs() {
            builder.intern(spec.identity).unwrap();
        }
        builder.intern(identity(CardId::GlimpseBeyond, 0)).unwrap();
        builder.intern_private_constrict_strangler().unwrap();
        let catalog = builder.build();
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        state.monsters_mut().clear();

        let mut strangler = crate::hot::HotMonster::new(MonsterKind::SlitheringStrangler, 55);
        strangler.max_hp = 55;
        strangler.uid = 31;
        let mut ai = crate::hot::RandomAiState::new();
        assert!(ai.set_next(Some(crate::engine::turn::STRANGLER_CONSTRICT_INDEX)));
        assert!(ai.set_log(&[crate::engine::turn::STRANGLER_CONSTRICT_INDEX]));
        strangler.random_ai = ai;
        state.monsters_mut().push(strangler);
        assert!(state.fanouts.set_constrict_amount(3));
        assert_eq!(
            state.fanouts.register_after_side_turn_end_power(
                crate::hot::AfterSideTurnEndPowerToken::Constrict,
            ),
            Ok(0)
        );
        assert!(crate::moves::spawned::constrict_private_state_is_exact(
            &state
        ));
        assert_eq!(admit(&document, &state, &catalog), Ok(()));
    }

    #[test]
    fn exact_pet_gate_admits_gaze_and_right_hand_after_late_listener_closure() {
        let kinds = [
            StepKind::OstyBody,
            StepKind::OstySummonHeal,
            StepKind::SacrificeOstyExact,
            StepKind::SicEmExact,
            StepKind::RattleExact,
            StepKind::DirgeXExact,
            StepKind::Calcify,
            StepKind::DevourLife,
        ];
        let carriers: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.steps.iter().any(|step| kinds.contains(&step.kind)))
            .collect();
        assert_eq!(carriers.len(), 36, "eight pet kinds lost an exact carrier");
        let (document, state, base) = parts();
        let admitted: BTreeSet<_> = carriers
            .iter()
            .filter_map(|row| {
                let candidate = identity(row.id, row.upgrade);
                admit(&document, &state, &catalog_with(&base, candidate))
                    .is_ok()
                    .then_some(candidate)
            })
            .collect();
        let refused: BTreeSet<_> = carriers
            .iter()
            .map(|row| identity(row.id, row.upgrade))
            .filter(|candidate| !admitted.contains(candidate))
            .collect();
        assert_eq!(admitted.len(), 36);
        assert!(admitted.contains(&identity(CardId::SweepingGaze, 0)));
        assert!(admitted.contains(&identity(CardId::SweepingGaze, 1)));
        assert!(refused.is_empty(), "every exact pet carrier now admits");

        assert!(
            !capability_manifest()
                .steps
                .contains(&StepKind::LegionOfBoneExact)
        );
        assert!(
            capability_manifest()
                .steps
                .contains(&StepKind::NecroMastery)
        );
        assert!(capability_manifest().steps.contains(&StepKind::Summon));
        for upgrade in 0..=1 {
            let refusal = admit(
                &document,
                &state,
                &catalog_with(&base, identity(CardId::LegionOfBone, upgrade)),
            )
            .unwrap_err();
            assert!(refusal.contains(MissingCapability::StepKind(StepKind::LegionOfBoneExact)));
            admit(
                &document,
                &state,
                &catalog_with(&base, identity(CardId::NecroMastery, upgrade)),
            )
            .unwrap();
        }
        for upgrade in 0..=1 {
            admit(
                &document,
                &state,
                &catalog_with(&base, identity(CardId::Melancholy, upgrade)),
            )
            .unwrap();
        }
    }

    #[test]
    fn random_enemy_delta_admits_exact_ricochet_sword_boomerang_volley_and_stardust_rows() {
        let (document, state, base) = parts();
        let random_attack_rows = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                row.target_type == "RandomEnemy"
                    && matches!(
                        row.steps,
                        [step]
                            if matches!(
                                step.kind,
                                StepKind::AttackRandom | StepKind::AttackRandomX
                            )
                    )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            random_attack_rows.len(),
            10,
            "the AttackRandom/AttackRandomX carrier census drifted"
        );
        assert!(
            capability_manifest()
                .steps
                .contains(&StepKind::AttackRandomX)
        );
        let admitted: BTreeSet<_> = random_attack_rows
            .iter()
            .filter_map(|row| {
                let candidate = identity(row.id, row.upgrade);
                admit(&document, &state, &catalog_with(&base, candidate))
                    .is_ok()
                    .then_some(candidate)
            })
            .collect();
        assert_eq!(
            admitted,
            [
                identity(CardId::Ricochet, 0),
                identity(CardId::Ricochet, 1),
                identity(CardId::Stardust, 0),
                identity(CardId::Stardust, 1),
                identity(CardId::SwordBoomerang, 0),
                identity(CardId::SwordBoomerang, 1),
                identity(CardId::Volley, 0),
                identity(CardId::Volley, 1),
            ]
            .into_iter()
            .collect(),
            "only canonical Ricochet, Sword Boomerang, Volley, and Stardust rows have complete RandomEnemy closure"
        );
        for row in random_attack_rows {
            let candidate = identity(row.id, row.upgrade);
            if admitted.contains(&candidate) {
                assert!(body_owned_random_enemy_program_is_supported(row));
                continue;
            }
            let refusal = admit(&document, &state, &catalog_with(&base, candidate)).unwrap_err();
            assert!(
                refusal.contains(MissingCapability::CardKeyword(row.id)),
                "{}+{} escaped through the Unit-C RandomEnemy gate: {refusal}",
                row.id.as_str(),
                row.upgrade
            );
            assert!(
                !refusal.contains(MissingCapability::StepKind(row.steps[0].kind)),
                "the public StepKind must not imply keyword admission: {refusal}"
            );
        }

        let mut mutated = *crate::content_tables::card_row(CardId::Volley, 0).unwrap();
        assert!(body_owned_random_enemy_program_is_supported(&mutated));
        mutated.steps = &[crate::content_tables::Step {
            kind: StepKind::AttackRandomX,
            args: &[Arg::I(11)],
        }];
        assert!(!body_owned_random_enemy_program_is_supported(&mutated));
        mutated = *crate::content_tables::card_row(CardId::Volley, 0).unwrap();
        mutated.x_cost = false;
        assert!(!body_owned_random_enemy_program_is_supported(&mutated));
        mutated = *crate::content_tables::card_row(CardId::Stardust, 0).unwrap();
        assert!(body_owned_random_enemy_program_is_supported(&mutated));
        mutated.star_x = false;
        assert!(!body_owned_random_enemy_program_is_supported(&mutated));
        mutated = *crate::content_tables::card_row(CardId::Ricochet, 1).unwrap();
        assert!(body_owned_random_enemy_program_is_supported(&mutated));
        mutated.steps = &[crate::content_tables::Step {
            kind: StepKind::AttackRandom,
            args: &[Arg::I(3), Arg::I(4)],
        }];
        assert!(!body_owned_random_enemy_program_is_supported(&mutated));

        for parent in [CardId::Cascade, CardId::Havoc, CardId::Mayhem]
            .into_iter()
            .flat_map(|id| [identity(id, 0), identity(id, 1)])
        {
            let parent_only = catalog_with(&base, parent);
            assert_eq!(
                admit(&document, &state, &parent_only),
                Ok(()),
                "the parent row is independently exact: {}+{}",
                parent.id.as_str(),
                parent.upgrade
            );

            let with_armaments = catalog_with(&parent_only, identity(CardId::Armaments, 0));
            assert_eq!(admit(&document, &state, &with_armaments), Ok(()));
        }

        let mut mayhem_power = state.clone();
        mayhem_power.powers.set(PowerId::Mayhem, SlotWire::Int, 1);
        let armaments = catalog_with(&base, identity(CardId::Armaments, 0));
        assert_eq!(
            admit(&document, &mayhem_power, &armaments),
            Ok(()),
            "a live singleton Mayhem owns the exact first-child carrier"
        );
        mayhem_power.powers.set(PowerId::Mayhem, SlotWire::Int, 2);
        assert!(
            admit(&document, &mayhem_power, &armaments)
                .unwrap_err()
                .contains(MissingCapability::ContinuationFrame),
            "a reusable plural Mayhem remains outside the first-child quotient"
        );
    }

    #[test]
    fn parent_autoplay_source_and_caller_census_is_closed() {
        let direct_draw: BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| direct_draw_autoplay_parent_program(row))
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        assert_eq!(
            direct_draw,
            [CardId::Cascade, CardId::Havoc, CardId::Mayhem]
                .into_iter()
                .flat_map(|id| [identity(id, 0), identity(id, 1)])
                .collect(),
            "the complete generated Draw AutoPlay parent census drifted"
        );

        let sly_discard: BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| sly_discard_autoplay_parent_program(row))
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        let expected_sly_discard: BTreeSet<_> = [
            CardId::Acrobatics,
            CardId::DaggerThrow,
            CardId::HiddenDaggers,
            CardId::Prepared,
            CardId::Scrape,
            CardId::ShadowStep,
            CardId::StormOfSteel,
            CardId::Survivor,
        ]
        .into_iter()
        .flat_map(|id| [identity(id, 0), identity(id, 1)])
        .chain([
            identity(CardId::CalculatedGamble, 0),
            identity(CardId::CalculatedGamble, 1),
        ])
        .collect();
        assert_eq!(
            sly_discard, expected_sly_discard,
            "the complete generated discard-to-Sly AutoPlay caller census drifted"
        );

        let recursive_play_parents: BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| autoplay_parent_program_can_spawn_child(row))
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        let expected_recursive_play_parents: BTreeSet<_> = [
            CardId::DecisionsDecisions,
            CardId::Acrobatics,
            CardId::BeatDown,
            CardId::Cascade,
            CardId::Catastrophe,
            CardId::DaggerThrow,
            CardId::Eidolon,
            CardId::Havoc,
            CardId::HiddenDaggers,
            CardId::KnifeTrap,
            CardId::Mayhem,
            CardId::Prepared,
            CardId::Scrape,
            CardId::ShadowStep,
            CardId::StormOfSteel,
            CardId::Survivor,
            CardId::Uproar,
        ]
        .into_iter()
        .flat_map(|id| [identity(id, 0), identity(id, 1)])
        .chain([
            identity(CardId::CalculatedGamble, 0),
            identity(CardId::CalculatedGamble, 1),
        ])
        .collect();
        assert_eq!(
            recursive_play_parents, expected_recursive_play_parents,
            "the complete recursive CardPlay-producing row census drifted"
        );
        let authority_program_rows: BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                row.steps.iter().any(|step| {
                    matches!(
                        step.kind,
                        StepKind::AutoplayDrawX
                            | StepKind::Havoc
                            | StepKind::Mayhem
                            | StepKind::DiscardHandDraw
                            | StepKind::ScrapeExact
                            | StepKind::ShadowStepDiscardExact
                            | StepKind::StormOfSteelExact
                            | StepKind::BeatDownExact
                            | StepKind::CatastropheExact
                            | StepKind::EidolonExact
                            | StepKind::KnifeTrapExact
                            | StepKind::UproarExact
                    ) || matches!(
                        step,
                        crate::content_tables::Step {
                            kind: StepKind::Select,
                            args: [
                                _,
                                _,
                                _,
                                _,
                                Arg::Select(SelectOp::Discard | SelectOp::DiscardAll)
                                    | Arg::List([Arg::S("decisions_replay_exact"), Arg::I(3)])
                            ],
                        }
                    )
                })
            })
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        assert_eq!(
            authority_program_rows, recursive_play_parents,
            "the independent authority StepKind/program census must equal the admission classifier"
        );
        let runtime_families: BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| autoplay_parent_program_can_spawn_child(row))
            .flat_map(|row| {
                let families = DISTILLED_RECURSIVE_FAMILIES
                    .into_iter()
                    .filter(|family| row_has_distilled_recursive_family(row, *family))
                    .collect::<Vec<_>>();
                assert_eq!(
                    families.len(),
                    1,
                    "{}+{} must bind each recursive occurrence to exactly one D2j family",
                    row.id.as_str(),
                    row.upgrade
                );
                families
            })
            .collect();
        assert_eq!(
            runtime_families,
            BTreeSet::from([
                DistilledRecursiveFamily::DrawPileFlip,
                DistilledRecursiveFamily::SlyDiscard,
                DistilledRecursiveFamily::BeatDown,
                DistilledRecursiveFamily::CatastropheLive,
                DistilledRecursiveFamily::Eidolon,
                DistilledRecursiveFamily::KnifeTrap,
                DistilledRecursiveFamily::UproarLive,
                DistilledRecursiveFamily::Decisions,
            ]),
            "every generated recursive source needs an explicit retained D2j owner"
        );
        assert_eq!(
            DISTILLED_RECURSIVE_FAMILIES.map(distilled_recursive_runtime_carrier),
            [
                DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::DrawPileFlip),
                DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::SlyDiscard),
                DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::BeatDown),
                DistilledRecursiveCarrier::Live(crate::hot::CardPlaySource::Catastrophe),
                DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::Eidolon),
                DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::KnifeTrap),
                DistilledRecursiveCarrier::Live(crate::hot::CardPlaySource::Uproar),
                DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::Decisions),
            ],
            "the closed source-family census must bind to the exact D2j carriers"
        );
        // The frozen v0.111.0 Python owner walk
        // (`_record_tools_sly_turn_start_append`) names exactly seven recursive
        // sources: draw-pile flip, Sly discard, Beat Down, Catastrophe,
        // Eidolon, Knife Trap and Uproar. The half of this test that re-parsed
        // them out of `combat_sim.py` was retired with the Python simulator
        // (#2827 item D): the source is frozen, so that census is a constant
        // and the carrier list above is its Rust statement.
        let play_source = include_str!("play.rs")
            .split_once("#[cfg(test)]\nmod tests")
            .unwrap()
            .0;
        for (producer_grammar, count) in [
            (
                "let draw_parent = matches!(step.kind, StepKind::Havoc | StepKind::AutoplayDrawX);",
                2,
            ),
            ("let sly_parent = matches!(", 2),
            ("state.frames.auto_pre_mayhem_phase", 12),
            (
                "parent.kind == crate::hot::TurnStartHandChoiceKind::ToolsOfTheTrade",
                3,
            ),
            ("run_restricted_frozen_batch_if_needed(", 6),
            ("pub(crate) fn autoplay_sly_discard_batch(", 1),
            ("pub(crate) fn decisions_serial_auto_plays(", 1),
        ] {
            assert_eq!(
                play_source.matches(producer_grammar).count(),
                count,
                "production grouped Draw/Sly producer grammar drifted: {producer_grammar}"
            );
        }
        for (needle, count) in [
            ("FrozenAutoBatchSource::DrawPileFlip", 35),
            ("FrozenAutoBatchSource::SlyDiscard", 35),
            ("FrozenAutoBatchSource::BeatDown", 12),
            ("FrozenAutoBatchSource::Eidolon", 14),
            ("FrozenAutoBatchSource::KnifeTrap", 14),
            ("CardPlaySource::Catastrophe", 6),
            ("CardPlaySource::Uproar", 6),
        ] {
            assert_eq!(
                play_source.matches(needle).count(),
                count,
                "production D2j constructor/validator/dispatcher census drifted for {needle}"
            );
        }
        for (constructor, count) in [
            (
                "FrozenAutoBatchSource::DrawPileFlip,\n            force_exhaust,",
                1,
            ),
            ("FrozenAutoBatchSource::SlyDiscard,\n        false,", 1),
            ("FrozenAutoBatchSource::BeatDown,\n        false,", 1),
            ("FrozenAutoBatchSource::Eidolon,\n        true,", 1),
            ("FrozenAutoBatchSource::KnifeTrap,\n        false,", 1),
            ("provenance: PlayProvenance::Catastrophe", 2),
            ("provenance: PlayProvenance::Uproar", 1),
            ("crate::hot::FrozenAutoBatchSource::Decisions,", 1),
        ] {
            assert_eq!(
                play_source.matches(constructor).count(),
                count,
                "production D2j owner construction drifted: {constructor}"
            );
        }
        let production_carriers = [
            DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::DrawPileFlip),
            DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::SlyDiscard),
            DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::BeatDown),
            DistilledRecursiveCarrier::Live(crate::hot::CardPlaySource::Catastrophe),
            DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::Eidolon),
            DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::KnifeTrap),
            DistilledRecursiveCarrier::Live(crate::hot::CardPlaySource::Uproar),
            DistilledRecursiveCarrier::Frozen(crate::hot::FrozenAutoBatchSource::Decisions),
        ];
        assert_eq!(
            production_carriers,
            DISTILLED_RECURSIVE_FAMILIES.map(distilled_recursive_runtime_carrier),
            "the independent production-site carrier set must equal the admission family universe"
        );
        let mut drift = *crate::content_tables::card_row(CardId::Havoc, 0).unwrap();
        drift.steps = &[
            crate::content_tables::Step {
                kind: StepKind::Havoc,
                args: &[],
            },
            crate::content_tables::Step {
                kind: StepKind::BeatDownExact,
                args: &[],
            },
        ];
        assert!(autoplay_parent_program_can_spawn_child(&drift));
        assert!(
            !distilled_recursive_runtime_families_are_exact(&drift),
            "a new recursive occurrence cannot hide behind a row's already-known carrier"
        );

        let (document, state, base) = parts();
        for source in sly_discard {
            let source_only = catalog_with(&base, source);
            assert_eq!(
                admit(&document, &state, &source_only),
                Ok(()),
                "the Sly-discard parent is independently exact: {}+{}",
                source.id.as_str(),
                source.upgrade
            );
            let with_writer = catalog_with(&source_only, identity(CardId::MasterPlanner, 0));
            let with_selecting_child = catalog_with(&with_writer, identity(CardId::Armaments, 0));
            let result = admit(&document, &state, &with_selecting_child);
            if unsupported_sly_frozen_batch_future_is_reachable(&state, &with_selecting_child) {
                assert!(
                    result
                        .unwrap_err()
                        .contains(MissingCapability::ContinuationFrame),
                    "{}+{} retains a mechanically reachable unsupported Sly Draw-prefix child",
                    source.id.as_str(),
                    source.upgrade
                );
            } else {
                assert_eq!(result, Ok(()));
            }
        }
    }

    #[test]
    fn distilled_recursive_closure_authenticates_every_current_source_family() {
        let mut builder = CatalogBuilder::new();
        for id in [
            CardId::Havoc,
            CardId::Survivor,
            CardId::BeatDown,
            CardId::Catastrophe,
            CardId::Eidolon,
            CardId::KnifeTrap,
            CardId::Uproar,
        ] {
            builder
                .intern_reachable(CardIdentity {
                    id,
                    upgrade: 0,
                    enchantment: None,
                })
                .unwrap();
        }
        builder.mark_persistent_action_replay_required();
        let catalog = builder.build();
        let state = HotState::at_defaults();
        assert!(distilled_recursive_source_closure_is_exact(
            &state, &catalog
        ));

        let havoc = catalog
            .atom(&CardIdentity {
                id: CardId::Havoc,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let mut drifted = catalog.clone();
        drifted.spec_mut_for_test(havoc).unwrap().row =
            crate::content_tables::card_row(CardId::Mayhem, 0).unwrap();
        assert!(
            !distilled_recursive_source_closure_is_exact(&state, &drifted),
            "a reachable source row drift must fail before Distilled rehearsal"
        );
    }

    #[test]
    fn outer_autoplay_owners_admit_a_blocking_cardplay_draw_child() {
        let assert_named_admits = |name: &str, document: &CanonicalStateV2| {
            let catalog = HotBoundary::catalog_from_canonical(document).unwrap();
            let state = HotBoundary::from_canonical(document, &catalog).unwrap();
            assert_eq!(admit(document, &state, &catalog), Ok(()), "{name}");
        };
        let draw_fixture = || {
            let (mut document, _, _) = parts();
            push_physical_card(&mut document, "draw", CardId::PommelStrike, 0);
            document
                .player
                .insert(PowerId::Stratagem.as_str().to_owned(), json!(1));
            document
        };

        let direct_child = draw_fixture();
        assert_admits(&direct_child);
        for parent in [CardId::Havoc, CardId::Cascade, CardId::Mayhem] {
            let mut control = direct_child.clone();
            control.player.remove(PowerId::Stratagem.as_str());
            push_physical_card(&mut control, "hand", parent, 0);
            assert_admits(&control);

            let mut document = direct_child.clone();
            push_physical_card(&mut document, "hand", parent, 0);
            assert_named_admits(parent.as_str(), &document);
        }

        let mut live_mayhem = direct_child.clone();
        live_mayhem
            .player
            .insert(PowerId::Mayhem.as_str().to_owned(), json!(1));
        assert_named_admits("live Mayhem", &live_mayhem);
        let mut live_mayhem_control = live_mayhem.clone();
        live_mayhem_control
            .player
            .remove(PowerId::Stratagem.as_str());
        assert_admits(&live_mayhem_control);

        let mut stampede = direct_child.clone();
        push_physical_card(&mut stampede, "hand", CardId::Stampede, 0);
        assert_named_admits("Stampede", &stampede);
        let mut stampede_control = stampede.clone();
        stampede_control.player.remove(PowerId::Stratagem.as_str());
        assert_admits(&stampede_control);

        let mut result_child = parts().0;
        push_physical_card(&mut result_child, "draw", CardId::Pillage, 0);
        result_child
            .player
            .insert(PowerId::Stratagem.as_str().to_owned(), json!(1));
        for parent in [CardId::Havoc, CardId::Stampede] {
            let mut document = result_child.clone();
            push_physical_card(&mut document, "hand", parent, 0);
            assert_named_admits(parent.as_str(), &document);
            document.player.remove(PowerId::Stratagem.as_str());
            assert_admits(&document);
        }

        let mut sly_parent = direct_child.clone();
        let draw_child = sly_parent
            .piles
            .get_mut("draw")
            .unwrap()
            .iter_mut()
            .find(|card| card.id == CardId::PommelStrike.as_str())
            .unwrap();
        draw_child.id = CardId::Scrawl.as_str().to_owned();
        draw_child.upgrade = 0;
        draw_child.local_keywords.push("Sly".to_owned());
        sly_parent
            .player
            .insert(PowerId::MasterPlanner.as_str().to_owned(), json!(1));
        append_singleton_after_card_played_row(&mut sly_parent, PowerId::MasterPlanner);
        push_physical_card(&mut sly_parent, "hand", CardId::Survivor, 0);
        assert_named_admits("Sly parent", &sly_parent);
        let mut sly_control = sly_parent.clone();
        sly_control.player.remove(PowerId::Stratagem.as_str());
        assert_admits(&sly_control);

        let mut tools = direct_child;
        let draw_child = tools
            .piles
            .get_mut("draw")
            .unwrap()
            .iter_mut()
            .find(|card| card.id == CardId::PommelStrike.as_str())
            .unwrap();
        draw_child.id = CardId::Scrawl.as_str().to_owned();
        draw_child.upgrade = 0;
        draw_child.local_keywords.push("Sly".to_owned());
        tools
            .player
            .insert(PowerId::MasterPlanner.as_str().to_owned(), json!(1));
        append_singleton_after_card_played_row(&mut tools, PowerId::MasterPlanner);
        tools
            .player
            .insert(PowerId::ToolsOfTheTrade.as_str().to_owned(), json!(1));
        tools.player.insert(
            "turn_start_hand_choice_order".to_owned(),
            json!([PowerId::ToolsOfTheTrade.as_str()]),
        );
        assert_named_admits("Tools", &tools);

        let mut no_blocking_hook = tools;
        no_blocking_hook.player.remove(PowerId::Stratagem.as_str());
        assert_admits(&no_blocking_hook);
    }

    #[test]
    fn knowledge_demon_debuff_and_autoplay_source_census_is_closed() {
        assert_eq!(
            crate::content_tables::TEMPLATE_RELIC_EFFECT_VERBS,
            [
                "block",
                "damage_all",
                "draw_bonus",
                "energy",
                "heal",
                "max_energy",
                "power_self",
                "stars",
            ],
            "a new relic effect verb needs an independent KD debuff-source audit"
        );
        assert!(
            !IMPLEMENTED_PLAYER_POWERS.contains(&PowerId::Artifact),
            "player Artifact needs exact KD application semantics before admission"
        );
        let direct_power_operands: BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                fn mentions(args: &[Arg]) -> bool {
                    args.iter().any(|arg| match arg {
                        Arg::Power(
                            PowerId::Artifact
                            | PowerId::Disintegration
                            | PowerId::MindRot
                            | PowerId::Sloth
                            | PowerId::WasteAway,
                        ) => true,
                        Arg::List(nested) => mentions(nested),
                        _ => false,
                    })
                }
                row.steps.iter().any(|step| mentions(step.args))
            })
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        assert!(
            direct_power_operands.is_empty(),
            "generated card rows gained direct KD prevention/removal power operands: {direct_power_operands:?}"
        );
        let debuff_sources: BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| knowledge_demon_debuff_prevention_or_removal_source(row))
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        // #3382: Alchemize left the ancestry once its procurement and belt
        // were exact; see `knowledge_demon_debuff_prevention_or_removal_source`
        // for the potion-body IL audit that replaced the wall.
        assert!(
            debuff_sources.is_empty(),
            "the complete generated player debuff-prevention/removal ancestry drifted: {debuff_sources:?}"
        );

        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::KnowledgeDemon).unwrap();
        let alchemize = builder
            .intern_reachable(identity(CardId::Alchemize, 0))
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 80;
        state.max_hp = 80;
        let mut demon = crate::hot::HotMonster::new(MonsterKind::KnowledgeDemon, 399);
        demon.max_hp = 399;
        state.monsters_mut().push(demon);
        assert!(crate::engine::turn::knowledge_demon_state_is_exact(&state));
        assert!(
            knowledge_demon_source_closure_is_exact(&state, &catalog),
            "a reachable Alchemize is no longer a KD debuff-prevention source (#3382)"
        );

        // The two remaining walls, one witness each.
        let mut artifact = state.clone();
        artifact
            .powers
            .set(PowerId::Artifact, crate::powers::SlotWire::Int, 1);
        assert!(
            !knowledge_demon_source_closure_is_exact(&artifact, &catalog),
            "player Artifact stays a KD wall"
        );
        for flag in [
            crate::hot::CARD_FLAG_DUPE,
            crate::hot::CARD_FLAG_LOCAL_EXHAUST,
        ] {
            let mut payload = state.clone();
            payload
                .piles
                .get_mut(PileId::Hand)
                .make_mut()
                .push(crate::hot::HotCard {
                    uid: 1,
                    atom: alchemize,
                    flags: flag,
                });
            assert!(
                !knowledge_demon_source_closure_is_exact(&payload, &catalog),
                "a CreateDupe / local-Exhaust payload stays a KD wall ({flag:#x})"
            );
        }

        let autoplay_parents: BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                direct_draw_autoplay_parent_program(row) || sly_discard_autoplay_parent_program(row)
            })
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        let expected: BTreeSet<_> = [
            CardId::Acrobatics,
            CardId::Cascade,
            CardId::DaggerThrow,
            CardId::Havoc,
            CardId::HiddenDaggers,
            CardId::Mayhem,
            CardId::Prepared,
            CardId::Scrape,
            CardId::ShadowStep,
            CardId::StormOfSteel,
            CardId::Survivor,
        ]
        .into_iter()
        .flat_map(|id| [identity(id, 0), identity(id, 1)])
        .chain([
            identity(CardId::CalculatedGamble, 0),
            identity(CardId::CalculatedGamble, 1),
        ])
        .collect();
        assert_eq!(
            autoplay_parents, expected,
            "every generated AutoPlay parent must continue to converge at the shared early Sloth gate"
        );
    }

    /// The narrowed replay branch, pinned on the predicate itself (#2671 PR 2).
    ///
    /// Before this slice the branch refused a plural Tools listener on
    /// cardinality alone (`tools_plural_parent_reachable && effective_sly.len()
    /// > 1`) and on the mere reachability of a future Sly writer, whatever the
    /// children were. It now keys on exactly the child grammar:
    /// `invalid_current_program || invalid_future_child`. Hidden Daggers is what
    /// makes this catalog require an ActionReplay root, which is the branch
    /// under test; the non-replay branch is pinned unchanged by
    /// `plural_tools_closes_current_and_future_selecting_sly_siblings` below.
    #[test]
    fn the_narrowed_plural_tools_wall_keys_on_child_grammar_not_cardinality() {
        let document = |second: CardId| {
            let (mut document, _, _) = parts();
            push_physical_card(&mut document, "hand", CardId::HiddenDaggers, 0);
            {
                let hand = document.piles.get_mut("hand").unwrap();
                for (slot, id) in [(0, CardId::Hologram), (1, second)] {
                    let card = &mut hand[slot];
                    card.id = id.as_str().to_owned();
                    card.upgrade = 0;
                    card.physical_state = None;
                    card.local_keywords = vec!["Sly".to_owned()];
                }
            }
            document
                .player
                .insert(PowerId::MasterPlanner.as_str().to_owned(), json!(1));
            append_singleton_after_card_played_row(&mut document, PowerId::MasterPlanner);
            document
                .player
                .insert(PowerId::ToolsOfTheTrade.as_str().to_owned(), json!(2));
            document.player.insert(
                "turn_start_hand_choice_order".to_owned(),
                json!([PowerId::ToolsOfTheTrade.as_str()]),
            );
            document
        };

        let certified = document(CardId::Hologram);
        let catalog = HotBoundary::catalog_from_canonical(&certified).unwrap();
        let state = HotBoundary::from_canonical(&certified, &catalog).unwrap();
        assert!(
            catalog.requires_action_replay(),
            "this fixture must exercise the replay branch"
        );
        assert!(
            !unsupported_sly_frozen_batch_future_is_reachable(&state, &catalog),
            "two certified selecting Sly siblings under amount-two Tools are exact"
        );

        let uncertified = document(CardId::Headbutt);
        let catalog = HotBoundary::catalog_from_canonical(&uncertified).unwrap();
        let state = HotBoundary::from_canonical(&uncertified, &catalog).unwrap();
        assert!(catalog.requires_action_replay());
        assert!(
            unsupported_sly_frozen_batch_future_is_reachable(&state, &catalog),
            "one uncertified sibling must still close the whole batch"
        );
    }

    /// The NON-replay branch (`catalog.requires_action_replay() == false`),
    /// which #2671 PR 2 deliberately leaves byte-identical. Its blanket
    /// cardinality and future-writer walls still stand here, because a rootless
    /// fight has no generic per-frame walk to authenticate a plural batch with.
    /// The replay branch's narrowed behaviour is pinned above.
    #[test]
    fn plural_tools_closes_current_and_future_selecting_sly_siblings() {
        const CONTINUATION: MissingCapability = MissingCapability::ContinuationFrame;

        let (mut current, _, _) = parts();
        for card in current.piles.get_mut("hand").unwrap().iter_mut().take(2) {
            card.id = CardId::Purity.as_str().to_owned();
            card.upgrade = 0;
            card.physical_state = None;
            card.local_keywords = vec!["Sly".to_owned()];
        }
        current
            .player
            .insert(PowerId::MasterPlanner.as_str().to_owned(), json!(1));
        append_singleton_after_card_played_row(&mut current, PowerId::MasterPlanner);
        current
            .player
            .insert(PowerId::ToolsOfTheTrade.as_str().to_owned(), json!(1));
        current.player.insert(
            "turn_start_hand_choice_order".to_owned(),
            json!([PowerId::ToolsOfTheTrade.as_str()]),
        );
        assert_admits(&current);

        current
            .player
            .insert(PowerId::ToolsOfTheTrade.as_str().to_owned(), json!(2));
        assert!(
            refuse(&current).contains(CONTINUATION),
            "amount-two Tools can collect both selecting Sly siblings"
        );

        let future_writer_document = |live_tools: bool, live_planner: bool| {
            let (mut document, _, _) = parts();
            replace_first_hand_card(&mut document, CardId::Armaments, 0);
            if live_tools {
                document
                    .player
                    .insert(PowerId::ToolsOfTheTrade.as_str().to_owned(), json!(2));
                document.player.insert(
                    "turn_start_hand_choice_order".to_owned(),
                    json!([PowerId::ToolsOfTheTrade.as_str()]),
                );
            } else {
                push_physical_card(&mut document, "hand", CardId::ToolsOfTheTrade, 0);
            }
            if live_planner {
                document
                    .player
                    .insert(PowerId::MasterPlanner.as_str().to_owned(), json!(1));
                append_singleton_after_card_played_row(&mut document, PowerId::MasterPlanner);
            } else {
                push_physical_card(&mut document, "hand", CardId::MasterPlanner, 0);
            }
            document
        };
        for (live_tools, live_planner) in [(true, false), (false, true), (false, false)] {
            let document = future_writer_document(live_tools, live_planner);
            assert!(
                refuse(&document).contains(CONTINUATION),
                "Tools live={live_tools} and Master Planner live={live_planner} escaped the symmetric future selecting-writer wall"
            );
        }
    }

    #[test]
    fn restricted_batch_future_replay_writers_close_the_whole_trajectory() {
        let (mut exact, _, _) = parts();
        let hand = exact.piles.get_mut("hand").unwrap();
        hand[0].id = CardId::Havoc.as_str().to_owned();
        hand[0].upgrade = 0;
        hand[1].id = CardId::Armaments.as_str().to_owned();
        hand[1].upgrade = 0;
        assert_admits(&exact);

        for writer in [
            CardId::Burst,
            CardId::EchoForm,
            CardId::Rebound,
            CardId::Nostalgia,
            CardId::Corruption,
        ] {
            let mut future = exact.clone();
            let source = &mut future.piles.get_mut("hand").unwrap()[2];
            source.id = writer.as_str().to_owned();
            source.upgrade = 0;
            assert_admits(&future);
        }

        let mut draw_prefix = exact.clone();
        let child = &mut draw_prefix.piles.get_mut("hand").unwrap()[1];
        child.id = CardId::ThinkingAhead.as_str().to_owned();
        child.upgrade = 1;
        assert_admits(&draw_prefix);
        let writer = &mut draw_prefix.piles.get_mut("hand").unwrap()[2];
        writer.id = CardId::Hellraiser.as_str().to_owned();
        writer.upgrade = 0;
        assert_admits(&draw_prefix);
    }

    #[test]
    fn future_master_planner_sly_child_requires_a_discardable_result_route() {
        let mut complete = CatalogBuilder::new();
        for row in crate::catalog::variant_free_card_rows() {
            complete
                .intern_reachable(identity(row.id, row.upgrade))
                .expect("the generated row compiles");
        }
        let complete = complete.build();
        let candidates: BTreeSet<_> = complete
            .reachable_specs()
            .filter(|spec| future_master_planner_selecting_sly_child_is_reachable(&complete, spec))
            .map(|spec| spec.identity)
            .collect();
        let expected_candidates: BTreeSet<_> = [
            CardId::Acrobatics,
            CardId::HandTrick,
            CardId::Begone,
            CardId::Charge,
            CardId::Brand,
            CardId::BurningPact,
            CardId::Cleanse,
            CardId::CosmicIndifference,
            CardId::Glimmer,
            CardId::HiddenDaggers,
            CardId::Prepared,
            CardId::Quasar,
            CardId::Scavenge,
            CardId::Seance,
            CardId::Splash,
            CardId::Survivor,
        ]
        .into_iter()
        .flat_map(|id| [identity(id, 0), identity(id, 1)])
        .chain([
            identity(CardId::Armaments, 0),
            // #3374: Dual Wield is a playable non-Exhaust selecting Skill.
            identity(CardId::DualWield, 0),
            identity(CardId::DualWield, 1),
            identity(CardId::Discovery, 1),
            identity(CardId::Hologram, 1),
            identity(CardId::SecretTechnique, 1),
            identity(CardId::SecretWeapon, 1),
            identity(CardId::ThinkingAhead, 1),
            // #3291: Transfigure+ (`OnUpgrade` RVA `0xef207` drops Exhaust).
            identity(CardId::Transfigure, 1),
            identity(CardId::TrueGrit, 1),
        ])
        .collect();
        assert_eq!(
            candidates, expected_candidates,
            "the playable non-Exhaust selecting-Skill future-writer census drifted"
        );

        let exhausting_candidates: BTreeSet<_> = complete
            .reachable_specs()
            .filter(|spec| {
                spec.is_skill
                    && spec.playable
                    && spec.exhausts
                    && card_row_is_admitted(&complete, spec)
                    && crate::engine::play::autoplay_child_requires_suspension(
                        PileId::Discard,
                        spec,
                        &complete,
                    )
            })
            .map(|spec| spec.identity)
            .collect();
        assert!(
            exhausting_candidates.contains(&identity(CardId::SecretTechnique, 0)),
            "the L0 adjacency witness must remain selecting and admitted before result-route filtering"
        );
        assert!(!exhausting_candidates.contains(&identity(CardId::SecretTechnique, 1)));

        for upgrade in [0, 1] {
            let (mut document, _, _) = parts();
            document.piles.get_mut("hand").unwrap().truncate(1);
            for pile in ["draw", "discard", "exhaust", "play"] {
                if let Some(cards) = document.piles.get_mut(pile) {
                    cards.clear();
                }
            }
            replace_first_hand_card(&mut document, CardId::Acrobatics, 0);
            push_physical_card(&mut document, "hand", CardId::MasterPlanner, 0);
            push_physical_card(&mut document, "hand", CardId::SecretTechnique, upgrade);
            push_physical_card(&mut document, "hand", CardId::StrikeIronclad, 0);
            push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);

            if upgrade == 0 {
                assert_admits(&document);

                let mut live_marker = document.clone();
                let secret = live_marker
                    .piles
                    .get_mut("hand")
                    .unwrap()
                    .iter_mut()
                    .find(|card| card.id == CardId::SecretTechnique.as_str())
                    .unwrap();
                secret.local_keywords.push("Sly".to_owned());
                live_marker
                    .player
                    .insert(PowerId::MasterPlanner.as_str().to_owned(), Value::from(1));
                append_singleton_after_card_played_row(&mut live_marker, PowerId::MasterPlanner);
                // Once the marker is already live, the distinct Acrobatics
                // parent can publish the supported singleton carrier; the
                // child's natural Exhaust route is itself exact.
                assert_admits(&live_marker);
            } else {
                // The rooted driver now owns Acrobatics' nested Hand-select
                // suffix as well as Secret Technique's Draw-pile selection.
                assert_admits(&document);
            }
        }
    }

    #[test]
    fn future_master_planner_same_id_pair_counts_live_and_generated_multiplicity() {
        let exact: CanonicalStateV2 = serde_json::from_str(include_str!(
            "../../fixtures/distraction_zero_multiplicity_v1.json"
        ))
        .unwrap();
        assert_eq!(
            exact.differential_digest(),
            "03c8c4fdc98119e8b493e134c54a667860423926fede6db2eded5a7688933731",
            "the DISTRACTION-ZERO-13 witness drifted"
        );

        let pair_reachable = |document: &CanonicalStateV2| {
            let catalog = HotBoundary::catalog_from_canonical(document).unwrap();
            let state = HotBoundary::from_canonical(document, &catalog).unwrap();
            future_master_planner_sly_parent_child_pair_is_reachable(&state, &catalog)
        };

        assert!(
            !pair_reachable(&exact),
            "one exhausting Distraction can generate only one Acrobatics object"
        );
        assert_admits(&exact);

        let mut two_generators = exact.clone();
        push_physical_card(&mut two_generators, "hand", CardId::Distraction, 0);
        assert!(
            pair_reachable(&two_generators),
            "two exhausting Distractions can mint two Acrobatics objects even with none live"
        );
        // #2677 admits the rooted Hidden Daggers generated-card prefix as a
        // Sly child, so the second generator's Hidden Daggers reach no
        // longer refuses here.
        assert_admits(&two_generators);
        let active_catalog = HotBoundary::catalog_from_canonical(&two_generators).unwrap();
        let mut active_state =
            HotBoundary::from_canonical(&two_generators, &active_catalog).unwrap();
        let source_index = active_state
            .piles
            .get(PileId::Hand)
            .as_slice()
            .iter()
            .rposition(|card| {
                active_catalog
                    .spec(card.atom)
                    .is_some_and(|spec| spec.identity.id == CardId::Distraction)
            })
            .unwrap();
        let active_source = active_state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .remove(source_index);
        active_state
            .piles
            .get_mut(PileId::Play)
            .make_mut()
            .push(active_source);
        assert!(
            future_master_planner_sly_parent_child_pair_is_reachable(
                &active_state,
                &active_catalog,
            ),
            "a later FrozenAutoBatch Distraction in Play remains a future physical generator"
        );

        for upgrade in [0, 1] {
            let mut one_live = exact.clone();
            push_physical_card(&mut one_live, "hand", CardId::Acrobatics, upgrade);
            assert!(
                pair_reachable(&one_live),
                "Distraction can generate a second Acrobatics beside the live L{upgrade} object"
            );
            assert_admits(&one_live);
        }

        for upgrades in [[0, 0], [0, 1]] {
            let mut two_live = exact.clone();
            for upgrade in upgrades {
                push_physical_card(&mut two_live, "hand", CardId::Acrobatics, upgrade);
            }
            assert!(
                pair_reachable(&two_live),
                "two live same-id objects must prove multiplicity across levels {upgrades:?}"
            );
            assert_admits(&two_live);
        }
    }

    #[test]
    fn rooted_sly_draw_prefix_with_empty_draw_admits_and_resumes() {
        let (mut document, _, _) = parts();
        document.piles.get_mut("hand").unwrap().truncate(3);
        for pile in ["exhaust", "play"] {
            document.piles.remove(pile);
        }
        document.piles.insert("draw".to_owned(), Vec::new());
        document.piles.insert("discard".to_owned(), Vec::new());
        let hand = document.piles.get_mut("hand").unwrap();
        hand[0].id = CardId::Survivor.as_str().to_owned();
        hand[0].upgrade = 0;
        hand[1].id = CardId::ThinkingAhead.as_str().to_owned();
        hand[1].upgrade = 0;
        hand[1].local_keywords.push("Sly".to_owned());
        let parent_uid = hand[0].uid.unwrap() as u32;
        document
            .player
            .insert(PowerId::MasterPlanner.as_str().to_owned(), Value::from(1));
        append_singleton_after_card_played_row(&mut document, PowerId::MasterPlanner);

        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        let draw_prefix = state
            .piles
            .get(PileId::Hand)
            .as_slice()
            .iter()
            .find(|card| card.uid != parent_uid && state.card_states.get(card.uid).local_sly)
            .and_then(|card| catalog.spec(card.atom))
            .unwrap();
        assert!(draw_prefix.exhausts);
        assert!(
            !crate::engine::play::restricted_frozen_batch_first_child_program_is_exact(
                PileId::Discard,
                draw_prefix,
                &catalog,
            ),
            "the legacy rootless carrier still cannot own this Draw prefix"
        );
        assert!(crate::engine::legal_actions(&state, &catalog).iter().any(
            |action| matches!(action, crate::engine::Action::Play { uid, .. } if *uid == parent_uid)
        ));
        admit(&document, &state, &catalog).unwrap();
        let parent = crate::engine::apply_action(
            &state,
            &catalog,
            &crate::engine::Action::Play {
                uid: parent_uid,
                target: None,
                selection: crate::engine::SelectionRef::NONE,
            },
        )
        .unwrap()
        .state;
        let pending_actions = crate::engine::legal_actions(&parent, &catalog);
        assert!(
            !pending_actions.is_empty(),
            "the exact recursive runtime parks the local-Sly Draw-prefix child"
        );
        for action in &pending_actions {
            crate::engine::apply_action(&parent, &catalog, action).unwrap_or_else(|error| {
                panic!(
                    "every legal answer to the exact local-Sly Draw-prefix child must resume: \
                     {action:?}: {error:?}"
                )
            });
        }

        let mut with_hellraiser = document.clone();
        let writer = &mut with_hellraiser.piles.get_mut("hand").unwrap()[2];
        writer.id = CardId::Hellraiser.as_str().to_owned();
        writer.upgrade = 0;
        assert_admits(&with_hellraiser);
    }

    /// The classifier's membership, positive and negative, on one catalog.
    ///
    /// #2715 adds Abundance L0/L1 to the six #2678 rows. The negative half is
    /// the part that has teeth: the four OTHER uncertified selecting Sly rows
    /// on this build — Graveblast, Headbutt, Neow's Fury and Seeker Strike,
    /// both levels, the residue of PR #2713's 154-certified/10-uncertified
    /// census once Abundance leaves it — are interned into the SAME rooted
    /// catalog and must still be rejected. Without them an Abundance-shaped
    /// widening could not be told apart from a blanket one.
    #[test]
    fn rooted_sly_generated_offer_classifier_is_exactly_eight_rooted_rows() {
        let mut builder = CatalogBuilder::new();
        for id in [
            CardId::Discovery,
            CardId::Quasar,
            CardId::Splash,
            CardId::Abundance,
            CardId::Graveblast,
            CardId::Headbutt,
            CardId::NeowsFury,
            CardId::SeekerStrike,
        ] {
            for upgrade in 0..=1 {
                builder.intern(identity(id, upgrade)).unwrap();
            }
        }
        // A persistent marker alone must not make a nonselecting catalog
        // rooted. Hidden Daggers is the exact discarded-Sly caller that turns
        // this candidate set into the ActionReplay grammar being classified
        // here.
        builder
            .intern_reachable(identity(CardId::HiddenDaggers, 0))
            .unwrap();
        let rooted = builder.build();
        assert!(rooted.requires_action_replay());
        for id in [
            CardId::Discovery,
            CardId::Quasar,
            CardId::Splash,
            CardId::Abundance,
        ] {
            for upgrade in 0..=1 {
                let spec = rooted
                    .spec(rooted.atom(&identity(id, upgrade)).unwrap())
                    .unwrap();
                assert!(
                    rooted_sly_generated_offer_is_exact(&rooted, spec),
                    "{id:?}+{upgrade} is a certified rooted generated-offer child"
                );
            }
        }
        // Scope item 4 of #2715: the other four uncertified selecting Sly rows
        // stay outside the grammar, and outside every other disjunct of
        // `replay_child_program_is_exact` too.
        for id in [
            CardId::Graveblast,
            CardId::Headbutt,
            CardId::NeowsFury,
            CardId::SeekerStrike,
        ] {
            for upgrade in 0..=1 {
                let spec = rooted
                    .spec(rooted.atom(&identity(id, upgrade)).unwrap())
                    .unwrap();
                assert!(
                    crate::engine::play::autoplay_child_requires_suspension(
                        PileId::Discard,
                        spec,
                        &rooted,
                    ),
                    "{id:?}+{upgrade} must stay a selecting Sly-capable child, or this \
                     control has stopped witnessing anything"
                );
                assert!(
                    !rooted_sly_generated_offer_is_exact(&rooted, spec),
                    "{id:?}+{upgrade} is NOT a generated-offer child and must stay refused"
                );
                assert!(
                    !replay_child_program_is_exact(&rooted, spec),
                    "{id:?}+{upgrade} must remain uncertified across every disjunct"
                );
            }
        }
        let mut rootless_builder = CatalogBuilder::new();
        for id in [CardId::Discovery, CardId::Abundance] {
            rootless_builder.intern(identity(id, 0)).unwrap();
        }
        let rootless = rootless_builder.build();
        for id in [CardId::Discovery, CardId::Abundance] {
            let spec = rootless
                .spec(rootless.atom(&identity(id, 0)).unwrap())
                .unwrap();
            assert!(
                !rooted_sly_generated_offer_is_exact(&rootless, spec),
                "{id:?} needs an ActionReplay root, not merely its own row"
            );
        }
    }

    /// The `invalid_future_child` disjunct of
    /// `unsupported_sly_frozen_batch_future_is_reachable`, measured over the
    /// complete row set rather than over one fixture.
    ///
    /// This is the #2666 claim in its exact form: with every `CARD_ROWS` row
    /// reachable, NO spec is both a reachable future Sly child (via the Hand
    /// Trick or Master Planner arm) and outside
    /// `replay_child_program_is_exact`. On `origin/main` this test fails and
    /// names exactly `Abundance` L0 and L1 — the single offender the
    /// 2026-09-22 EA6 frontier measurement found on floors 30/31/35/38/39/40
    /// with the Entropy draft applied.
    ///
    /// It also records WHY Abundance was the only one. The other nine rows in
    /// PR #2713's uncertified-selecting-Sly census — Graveblast, Headbutt,
    /// Neow's Fury and Seeker Strike, both levels — are all Attacks, and both
    /// future arms require `is_skill`. They can therefore reach the wall only
    /// as CURRENT local-Sly children, which is where `tests/sly_abundance_child.rs`
    /// keeps them as controls.
    #[test]
    fn every_reachable_future_sly_child_is_certified() {
        let mut builder = CatalogBuilder::new();
        for row in crate::catalog::variant_free_card_rows() {
            builder
                .intern_reachable(identity(row.id, row.upgrade))
                .expect("the generated row compiles");
        }
        let catalog = builder.build();
        assert!(
            catalog.requires_action_replay(),
            "the complete-row catalog must be rooted or this census proves nothing"
        );

        let hand_trick_children: BTreeSet<_> = catalog
            .reachable_specs()
            .filter(|spec| future_hand_trick_sly_child_is_reachable(&catalog, spec))
            .map(|spec| (spec.identity.id, spec.identity.upgrade))
            .collect();
        assert!(
            hand_trick_children.contains(&(CardId::Abundance, 0))
                && hand_trick_children.contains(&(CardId::Abundance, 1)),
            "Abundance must stay a Hand Trick child at both levels, or this census has \
             stopped witnessing the wall #2715 closed"
        );
        for id in [
            CardId::Graveblast,
            CardId::Headbutt,
            CardId::NeowsFury,
            CardId::SeekerStrike,
        ] {
            for upgrade in 0..=1 {
                assert!(
                    !hand_trick_children.contains(&(id, upgrade)),
                    "{id:?}+{upgrade} is an Attack; both future-child arms require \
                     `is_skill`, so it cannot be a future Sly child"
                );
            }
        }

        let offenders: BTreeSet<_> = catalog
            .reachable_specs()
            .filter(|spec| {
                (future_hand_trick_sly_child_is_reachable(&catalog, spec)
                    || future_master_planner_selecting_sly_child_is_reachable(&catalog, spec))
                    && !replay_child_program_is_exact(&catalog, spec)
            })
            .map(|spec| (spec.identity.id, spec.identity.upgrade))
            .collect();
        assert!(
            offenders.is_empty(),
            "{offenders:?} are reachable future Sly children outside \
             `replay_child_program_is_exact`. Each one makes `invalid_future_child` \
             fire for EVERY rooted fight whose catalog can reach a Hand Trick or \
             Master Planner writer — the wall the 2026-09-22 EA6 frontier measurement \
             hit on six floors. Certify the row (the #2678/#2715 pattern) or refuse it \
             by name at admission; do not narrow this census."
        );
    }

    /// No *intrinsically* Sly card row is both selecting and uncertified.
    ///
    /// Folded-in item (1) of #2715, deferred from #2671 PR 2. Every other
    /// selecting Sly child in this engine acquires its Sly bit from a writer —
    /// Hand Trick, Master Planner, or a local keyword in the uploaded document
    /// — and every path that can hand such a child to a frozen batch runs
    /// through `replay_child_program_is_exact`. A card whose PRINTED row is
    /// `sly: true` skips all of that: it is Sly the moment it exists, with no
    /// writer to gate, so it would reach a Tools listener's frozen batch
    /// through no admission check this slice can see. Today the seven
    /// intrinsic-Sly rows (Abrasive, Flick Flack, Reflex, Ricochet, Sneaky,
    /// Tactician, Untouchable) are all nonselecting, so the path is provably
    /// empty; this test is what makes a future author notice when it stops
    /// being.
    ///
    /// Derived from `CARD_ROWS` rather than hand-listed on purpose: a
    /// hand-list is exactly what a new row would slip past.
    #[test]
    fn no_intrinsically_sly_row_is_both_selecting_and_uncertified() {
        let mut builder = CatalogBuilder::new();
        for row in crate::catalog::variant_free_card_rows() {
            builder
                .intern_reachable(identity(row.id, row.upgrade))
                .expect("the generated row compiles");
        }
        // Hidden Daggers is already in `CARD_ROWS`, so the complete catalog is
        // rooted; assert it rather than assume it, because every disjunct of
        // `replay_child_program_is_exact` is ActionReplay-conditional and a
        // rootless catalog would make this test vacuously green.
        let catalog = builder.build();
        assert!(
            catalog.requires_action_replay(),
            "the complete-row catalog must be rooted or this census proves nothing"
        );

        let intrinsic: Vec<_> = catalog
            .reachable_specs()
            .filter(|spec| spec.row.sly)
            .collect();
        assert!(
            !intrinsic.is_empty(),
            "the intrinsic-Sly row set must not be empty, or this census is vacuous"
        );
        let offenders: BTreeSet<_> = intrinsic
            .iter()
            .filter(|spec| {
                crate::engine::play::autoplay_child_requires_suspension(
                    PileId::Discard,
                    spec,
                    &catalog,
                ) && !replay_child_program_is_exact(&catalog, spec)
            })
            .map(|spec| (spec.identity.id, spec.identity.upgrade))
            .collect();
        assert!(
            offenders.is_empty(),
            "{offenders:?} print `sly: true` AND select AND fail \
             `replay_child_program_is_exact`. An intrinsically Sly card needs no Sly \
             WRITER, so it reaches a frozen Tools/parent batch without passing any of \
             the reachability gates in `unsupported_sly_frozen_batch_future_is_reachable` \
             — which only ever ask whether a Hand Trick or Master Planner writer can \
             reach a child. That is an ungated future-intrinsic-Sly-child path. Before \
             adding such a row, add an admission gate that puts intrinsically Sly \
             selecting rows through `replay_child_program_is_exact` (or certify the row \
             the way #2678/#2715 certified the generated-offer family). Do NOT delete \
             this assertion."
        );
    }

    /// #2715 adds Abundance to #2678's shared table rather than giving it a
    /// test of its own, because the claim being made is that it is the SAME
    /// shape. Its three native differences are encoded as data here — no Skip
    /// option (`canSkip = 0`, `Abundance/<OnPlay>d__6::MoveNext` RVA
    /// `0x3888ec` `IL_00e7`, against Discovery's `ldc.i4.1` at `0x399254`
    /// `IL_0096`), every offer upgraded once (`CardCmd::Upgrade` at `IL_00b8`)
    /// whatever the source level, and the free-this-turn modifier it shares
    /// with Discovery and Splash (`SetToFreeThisTurn` at `IL_014e`).
    #[test]
    fn rooted_sly_generated_offers_cold_reload_from_a_public_discard_batch() {
        for (id, kind) in [
            (
                CardId::Discovery,
                crate::hot::PendingSelectionKind::Discovery,
            ),
            (CardId::Splash, crate::hot::PendingSelectionKind::Splash),
            (CardId::Quasar, crate::hot::PendingSelectionKind::Quasar),
            (
                CardId::Abundance,
                crate::hot::PendingSelectionKind::Abundance,
            ),
        ] {
            // Native `canSkip`: Discovery/Quasar/Splash publish three offers
            // plus Skip; Abundance publishes three offers and nothing else.
            let skip_option = if id == CardId::Abundance {
                None
            } else {
                Some(3)
            };
            let option_count = 3 + usize::from(skip_option.is_some());
            for upgrade in 0..=1 {
                let mut document = generator_document(id, RewardPool::Ironclad, false, 17);
                document.piles.get_mut("hand").unwrap()[0].upgrade = upgrade;
                let source_uid = document.piles["hand"][0]
                    .uid
                    .expect("the generator fixture has a physical source uid");
                let parent_uid =
                    push_physical_card(&mut document, "hand", CardId::HiddenDaggers, 0);
                push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                state
                    .card_states
                    .set_transient_sly(source_uid.try_into().unwrap());
                let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                assert!(catalog.requires_action_replay(), "{id:?}+{upgrade}");
                assert!(
                    !unsupported_sly_frozen_batch_future_is_reachable(&state, &catalog),
                    "the exact rooted {id:?}+{upgrade} child must close the Sly batch wall"
                );
                assert_eq!(
                    admit(&document, &state, &catalog),
                    Ok(()),
                    "{id:?}+{upgrade}"
                );

                let selected = crate::engine::apply_action(
                    &state,
                    &catalog,
                    &crate::engine::Action::Play {
                        uid: parent_uid.try_into().unwrap(),
                        target: None,
                        selection: crate::engine::SelectionRef::NONE,
                    },
                )
                .unwrap()
                .state;
                let parked = crate::engine::legal_actions(&selected, &catalog)
                    .iter()
                    .filter_map(|answer| {
                        crate::engine::apply_action(&selected, &catalog, answer).ok()
                    })
                    .map(|transition| transition.state)
                    .find(|candidate| {
                        candidate.pending.as_deref().is_some_and(|pending| {
                            candidate
                                .pending_card_play(pending)
                                .and_then(|(record, _)| record.route().ok())
                                .is_some_and(|(_, pending_kind)| pending_kind == kind)
                        })
                    })
                    .unwrap_or_else(|| {
                        panic!(
                            "the public Hidden Daggers batch reaches its local-Sly {id:?}+{upgrade} offer"
                        )
                    });
                let parked_document = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
                let parked_catalog = HotBoundary::catalog_from_canonical(&parked_document).unwrap();
                let reloaded =
                    HotBoundary::from_canonical(&parked_document, &parked_catalog).unwrap();
                assert_eq!(reloaded, parked, "{id:?}+{upgrade}");
                assert_eq!(
                    admit(&parked_document, &reloaded, &parked_catalog),
                    Ok(()),
                    "{id:?}+{upgrade} cold admission"
                );
                assert_eq!(
                    crate::engine::legal_actions(&reloaded, &parked_catalog).len(),
                    option_count,
                    "{id:?}+{upgrade} publishes its native option count"
                );
                let next_uid = reloaded.next_card_uid;
                let generation_after_screen = reloaded.rng.get(RngStream::Generation);
                for (option, action) in crate::engine::legal_actions(&reloaded, &parked_catalog)
                    .iter()
                    .enumerate()
                {
                    let completed = crate::engine::apply_action(&reloaded, &parked_catalog, action)
                        .unwrap_or_else(|error| {
                            panic!("{id:?}+{upgrade} option {option} must resume: {error}")
                        })
                        .state;
                    assert!(
                        completed.pending.is_none(),
                        "{id:?}+{upgrade} option {option}"
                    );
                    assert!(
                        completed.frames.is_empty(),
                        "{id:?}+{upgrade} option {option}"
                    );
                    if skip_option == Some(option) {
                        assert_eq!(
                            completed.next_card_uid,
                            next_uid + 2,
                            "Skip bypasses the offer mint; only Hidden Daggers' fixed two-Shiv suffix remains"
                        );
                        assert_eq!(
                            completed.rng.get(RngStream::Generation),
                            generation_after_screen,
                            "Skip resumes without a second generation shuffle"
                        );
                        continue;
                    }
                    assert_eq!(
                        completed.rng.get(RngStream::Generation),
                        generation_after_screen,
                        "{id:?}+{upgrade} option {option} resumes the already-generated \
                         offer without a second shuffle"
                    );
                    let generated = [PileId::Hand, PileId::Discard]
                        .into_iter()
                        .flat_map(|pile| completed.piles.get(pile).as_slice())
                        .find(|card| card.uid == next_uid)
                        .copied()
                        .unwrap_or_else(|| {
                            panic!("{id:?}+{upgrade} option {option} adds exactly one new uid")
                        });
                    let generated_spec = parked_catalog.spec(generated.atom).unwrap();
                    assert_eq!(
                        generated_spec.identity.upgrade,
                        match id {
                            // Discovery emits its offers at L0 whatever the
                            // source level; Abundance upgrades every offer
                            // once (`IL_00b8`) whatever the source level;
                            // Quasar and Splash carry the source's level.
                            CardId::Discovery => 0,
                            CardId::Abundance => 1,
                            _ => u8::try_from(upgrade).unwrap(),
                        },
                        "{id:?}+{upgrade} preserves its native generated upgrade rule"
                    );
                    if id == CardId::Abundance {
                        assert!(
                            generated_spec.is_power,
                            "Abundance's pool is filtered to Powers by \
                             `Abundance/<>c::<OnPlay>b__6_0` RVA `0x3888de`"
                        );
                    }
                    let cost = crate::engine::play::resolved_energy_cost(
                        &completed,
                        generated,
                        generated_spec,
                    );
                    assert_eq!(
                        cost,
                        if matches!(id, CardId::Discovery | CardId::Splash | CardId::Abundance)
                            && generated_spec.cost >= 0
                        {
                            0
                        } else {
                            generated_spec.cost
                        },
                        "{id:?}+{upgrade} option {option} has its native free modifier"
                    );
                }
            }
        }
    }

    #[test]
    fn rooted_sly_generated_splash_redirects_a_chosen_offer_at_hand_cap() {
        let mut document = generator_document(CardId::Splash, RewardPool::Ironclad, false, 31);
        let source_uid = document.piles["hand"][0]
            .uid
            .expect("the generator fixture has a physical source uid");
        let parent_uid = push_physical_card(&mut document, "hand", CardId::HiddenDaggers, 0);
        // Hidden Daggers leaves the parent and its two selected cards before
        // the local Splash body starts. Ten remaining cards therefore make
        // the chosen generated offer take native Add's Hand-cap redirect.
        for _ in 0..10 {
            push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);
        }
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        state
            .card_states
            .set_transient_sly(source_uid.try_into().unwrap());
        let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let selecting = crate::engine::apply_action(
            &state,
            &catalog,
            &crate::engine::Action::Play {
                uid: parent_uid.try_into().unwrap(),
                target: None,
                selection: crate::engine::SelectionRef::NONE,
            },
        )
        .unwrap()
        .state;
        let parked = crate::engine::legal_actions(&selecting, &catalog)
            .iter()
            .filter_map(|answer| crate::engine::apply_action(&selecting, &catalog, answer).ok())
            .map(|transition| transition.state)
            .find(|candidate| {
                candidate.pending.as_deref().is_some_and(|pending| {
                    candidate
                        .pending_card_play(pending)
                        .and_then(|(record, _)| record.route().ok())
                        .is_some_and(|(_, kind)| kind == crate::hot::PendingSelectionKind::Splash)
                })
            })
            .expect("a public Hidden Daggers answer parks the temporary Splash offer");
        let generated_uid = parked.next_card_uid;
        let completed = crate::engine::apply_action(
            &parked,
            &catalog,
            &crate::engine::legal_actions(&parked, &catalog)[0],
        )
        .unwrap()
        .state;
        assert!(
            completed
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .all(|card| card.uid != generated_uid)
        );
        assert!(
            completed
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .any(|card| card.uid == generated_uid),
            "the selected Splash offer uses Add's live Hand-cap redirect"
        );
        let canonical = HotBoundary::try_to_canonical(&completed, &catalog).unwrap();
        let reloaded_catalog = HotBoundary::catalog_from_canonical(&canonical).unwrap();
        let reloaded = HotBoundary::from_canonical(&canonical, &reloaded_catalog).unwrap();
        assert_eq!(
            HotBoundary::try_to_canonical(&reloaded, &reloaded_catalog).unwrap(),
            canonical
        );
        assert_eq!(admit(&canonical, &reloaded, &reloaded_catalog), Ok(()));
    }

    #[test]
    fn rooted_sly_discovery_l0_exhaust_keeps_nested_draw_before_later_sibling() {
        for permanent_sly in [false, true] {
            let mut document =
                generator_document(CardId::Discovery, RewardPool::Ironclad, false, 37);
            let template = document.piles.get_mut("hand").unwrap().remove(0);
            document.piles.get_mut("hand").unwrap().clear();
            document.piles.get_mut("hand").unwrap().push(template);
            let discovery_uid = push_physical_card(&mut document, "hand", CardId::Discovery, 0);
            let later_uid = push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);
            document.piles.get_mut("hand").unwrap().remove(0);
            let parent_uid = push_physical_card(&mut document, "hand", CardId::HiddenDaggers, 0);
            push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);
            if permanent_sly {
                document
                    .player
                    .insert(PowerId::MasterPlanner.as_str().to_owned(), json!(1));
                append_singleton_after_card_played_row(&mut document, PowerId::MasterPlanner);
            }
            document
                .player
                .insert(PowerId::DarkEmbrace.as_str().to_owned(), json!(1));
            document
                .player
                .insert(PowerId::Stratagem.as_str().to_owned(), json!(1));
            document
                .player
                .insert(PowerId::Hellraiser.as_str().to_owned(), json!(1));
            document.player.insert(
                "after_card_exhausted_power_order".to_owned(),
                json!([PowerId::DarkEmbrace.as_str()]),
            );
            document.player.insert(
                "after_side_turn_end_power_order".to_owned(),
                json!([
                    [PowerId::DarkEmbrace.as_str(), 1],
                    [PowerId::Hellraiser.as_str(), 2]
                ]),
            );
            document
                .player
                .insert("next_after_side_turn_end_power_uid".to_owned(), json!(3));
            document.piles.get_mut("draw").unwrap().clear();
            push_physical_card(&mut document, "discard", CardId::StrikeIronclad, 0);
            push_physical_card(&mut document, "discard", CardId::StrikeSilent, 0);
            // The parent and two frozen children carry different replay states;
            // a public exact-pile root represents their physical membership.
            document
                .player
                .insert("exact_piles".to_owned(), json!(true));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            state
                .card_states
                .set_transient_sly(discovery_uid.try_into().unwrap());
            state
                .card_states
                .set_transient_sly(later_uid.try_into().unwrap());
            let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(admit(&document, &state, &catalog), Ok(()));

            let selecting = crate::engine::apply_action(
                &state,
                &catalog,
                &crate::engine::Action::Play {
                    uid: parent_uid.try_into().unwrap(),
                    target: None,
                    selection: crate::engine::SelectionRef::NONE,
                },
            )
            .unwrap()
            .state;
            let discovery = crate::engine::legal_actions(&selecting, &catalog)
                .iter()
                .filter_map(|answer| crate::engine::apply_action(&selecting, &catalog, answer).ok())
                .map(|transition| transition.state)
                .find(|candidate| {
                    candidate.pending.as_deref().is_some_and(|pending| {
                        candidate
                            .pending_card_play(pending)
                            .and_then(|(record, _)| record.route().ok())
                            .is_some_and(|(_, kind)| {
                                kind == crate::hot::PendingSelectionKind::Discovery
                            })
                    })
                })
                .expect("public Hidden Daggers choice reaches the first Discovery offer");
            let discovery_document = HotBoundary::try_to_canonical(&discovery, &catalog).unwrap();
            let discovery_catalog =
                HotBoundary::catalog_from_canonical(&discovery_document).unwrap();
            let discovery_reloaded =
                HotBoundary::from_canonical(&discovery_document, &discovery_catalog).unwrap();
            assert_eq!(
                admit(&discovery_document, &discovery_reloaded, &discovery_catalog),
                Ok(())
            );

            for discovery_answer in 0..4 {
                let nested = crate::engine::apply_action(
                    &discovery_reloaded,
                    &discovery_catalog,
                    // Each offer answer follows Discovery L0's native Exhaust
                    // wrapper and its nested Dark Embrace Draw.
                    &crate::engine::legal_actions(&discovery_reloaded, &discovery_catalog)
                        [discovery_answer],
                )
                .unwrap()
                .state;
                assert!(
                    nested.pending.is_some(),
                    "Discovery L0 Exhaust parks its draw suffix"
                );
                assert!(nested.frames.as_slice().iter().any(|frame| matches!(
                    frame,
                    crate::frame::Frame::AfterCardExhaustedPower { .. }
                )));
                assert_eq!(
                    nested
                        .card_states
                        .get(u32::try_from(discovery_uid).unwrap())
                        .local_sly,
                    permanent_sly,
                    "Master Planner's permanent Sly write is live rather than the frozen batch snapshot"
                );
                let nested_document =
                    HotBoundary::try_to_canonical(&nested, &discovery_catalog).unwrap();
                let nested_catalog = HotBoundary::catalog_from_canonical(&nested_document).unwrap();
                let nested_reloaded =
                    HotBoundary::from_canonical(&nested_document, &nested_catalog).unwrap();
                assert_eq!(
                    admit(&nested_document, &nested_reloaded, &nested_catalog),
                    Ok(())
                );
                let resumed = crate::engine::apply_action(
                    &nested_reloaded,
                    &nested_catalog,
                    &crate::engine::legal_actions(&nested_reloaded, &nested_catalog)[0],
                )
                .unwrap()
                .state;
                assert!(
                    resumed
                        .piles
                        .get(PileId::Hand)
                        .as_slice()
                        .iter()
                        .any(|card| card.uid == u32::try_from(later_uid).unwrap()),
                    "the later frozen sibling runs after the nested Discovery L0 Exhaust suffix"
                );
                assert_eq!(resumed.block, 5, "the later Sly Defend completes once");
                let resumed_document =
                    HotBoundary::try_to_canonical(&resumed, &nested_catalog).unwrap();
                let resumed_catalog =
                    HotBoundary::catalog_from_canonical(&resumed_document).unwrap();
                let resumed_reloaded =
                    HotBoundary::from_canonical(&resumed_document, &resumed_catalog).unwrap();
                assert_eq!(
                    admit(&resumed_document, &resumed_reloaded, &resumed_catalog),
                    Ok(())
                );
            }
        }
    }

    #[test]
    fn discovery_l0_lifecycle_helper_refuses_unrooted_controls() {
        let mut l1 = generator_document(CardId::Discovery, RewardPool::Ironclad, false, 37);
        l1.piles.get_mut("hand").unwrap()[0].upgrade = 1;
        let l1_catalog = HotBoundary::catalog_from_canonical(&l1).unwrap();
        let l1_state = HotBoundary::from_canonical(&l1, &l1_catalog).unwrap();
        assert!(!authenticated_spent_discovery_l0_source_is_finite(
            &l1,
            &l1_state,
            &l1_catalog
        ));
        assert!(
            l1_catalog
                .owner_generation_pool(RewardPool::Ironclad)
                .iter()
                .all(|id| l1_catalog.atom(&identity(*id, 0)).is_some()),
            "an L1 Discovery retains the gate's complete direct owner closure"
        );

        let mut eidolon = generator_document(CardId::Discovery, RewardPool::Ironclad, false, 37);
        let exhausted_discovery = eidolon.piles.get_mut("hand").unwrap().remove(0);
        eidolon
            .piles
            .entry("exhaust".to_owned())
            .or_default()
            .push(exhausted_discovery);
        push_physical_card(&mut eidolon, "hand", CardId::Eidolon, 0);
        let eidolon_catalog = HotBoundary::catalog_from_canonical(&eidolon).unwrap();
        let eidolon_state = HotBoundary::from_canonical(&eidolon, &eidolon_catalog).unwrap();
        assert!(
            !authenticated_spent_discovery_l0_source_is_finite(
                &eidolon,
                &eidolon_state,
                &eidolon_catalog
            ),
            "an unrooted Eidolon fixture cannot establish an authenticated finished owner"
        );

        let mut second = generator_document(CardId::Discovery, RewardPool::Ironclad, false, 37);
        push_physical_card(&mut second, "hand", CardId::Discovery, 0);
        let second_catalog = HotBoundary::catalog_from_canonical(&second).unwrap();
        let second_state = HotBoundary::from_canonical(&second, &second_catalog).unwrap();
        assert!(
            !authenticated_spent_discovery_l0_source_is_finite(
                &second,
                &second_state,
                &second_catalog
            ),
            "an unrooted second L0 fixture cannot establish a finished owner"
        );
    }

    #[test]
    fn discovery_l0_retirement_keeps_live_and_eidolon_future_bodies() {
        assert!(stale_discovery_catalog_fallback_can_retire(
            [0, 0],
            true,
            0,
            false
        ));
        assert!(
            !stale_discovery_catalog_fallback_can_retire([1, 0], true, 0, false),
            "a live L0 physical source remains a future body"
        );
        assert!(
            !stale_discovery_catalog_fallback_can_retire([0, 1], true, 0, false),
            "a live L1 or Eidolon-counted future source remains a future body"
        );
        assert!(!stale_discovery_catalog_fallback_can_retire(
            [0, 0],
            true,
            1,
            false
        ));
        assert!(!stale_discovery_catalog_fallback_can_retire(
            [0, 0],
            true,
            0,
            true
        ));
    }

    /// A live Master Planner beside an effective-Sly physical L0 Discovery
    /// now refuses with `ContinuationFrame` (#2767).
    ///
    /// This is a consequence of the full owner-pool closure, and it is honest
    /// rather than a regression. `future_writer` in
    /// `unsupported_sly_frozen_batch_future_is_reachable` asks whether a
    /// reachable Master Planner can pair a Sly-discard autoplay parent with a
    /// selecting child; with the complete Ironclad generation pool interned,
    /// owner-pool cards supply that pair, so the plural Sly frozen-batch
    /// future this build does not certify becomes reachable. A Discovery+ deck
    /// already received exactly this refusal — the previous admission rested
    /// on the seeded three-offer preview happening to exclude those cards from
    /// the catalog, which is a fact about one Generation seed and not about the
    /// fight. `unsupported_sly_frozen_batch_future_is_reachable` is
    /// deliberately not weakened to restore it; the sibling test below carries
    /// the #2678 lifecycle proof without Master Planner.
    #[test]
    fn master_planner_sly_discovery_l0_refuses_its_uncertified_plural_future() {
        let (document, discovery_uid) = sly_discovery_burst_document(true);
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        state
            .card_states
            .set_transient_sly(discovery_uid.try_into().unwrap());
        let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert!(crate::boundary::discovery_catalog_closure_is_exact(
            &catalog,
            RewardPool::Ironclad
        ));
        assert!(unsupported_sly_frozen_batch_future_is_reachable(
            &state, &catalog
        ));
        let refusal = admit(&document, &state, &catalog).unwrap_err();
        assert!(
            refusal.contains(MissingCapability::ContinuationFrame),
            "{refusal:?}"
        );
    }

    /// The fixture both Sly-Discovery tests share: Survivor as the fixed-k
    /// Sly-discard parent, a physical L0 Discovery, two Defends, and Burst to
    /// park Survivor's replayed selector. `master_planner` adds the future
    /// Sly writer; the lifecycle proof runs without it, because with the full
    /// owner-pool closure a reachable Master Planner is itself an admission
    /// refusal (see the test above).
    fn sly_discovery_burst_document(master_planner: bool) -> (CanonicalStateV2, u64) {
        let mut document = generator_document(CardId::Survivor, RewardPool::Ironclad, false, 37);
        let discovery_uid = push_physical_card(&mut document, "hand", CardId::Discovery, 0);
        push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);
        push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);
        if master_planner {
            document
                .player
                .insert(PowerId::MasterPlanner.as_str().to_owned(), json!(1));
            append_singleton_after_card_played_row(&mut document, PowerId::MasterPlanner);
        }
        document
            .player
            .insert(PowerId::Burst.as_str().to_owned(), json!(1));
        append_singleton_side_end_row(&mut document, PowerId::Burst);
        document
            .player
            .insert("exact_piles".to_owned(), json!(true));
        (document, discovery_uid)
    }

    #[test]
    fn rooted_sly_discovery_l0_survives_after_its_batch_pops_into_burst_replay() {
        let (document, discovery_uid) = sly_discovery_burst_document(false);
        let survivor_uid = document.piles["hand"][0].uid.unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        state
            .card_states
            .set_transient_sly(discovery_uid.try_into().unwrap());
        let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let survivor_selection = crate::engine::apply_action(
            &state,
            &catalog,
            &crate::engine::Action::Play {
                uid: survivor_uid.try_into().unwrap(),
                target: None,
                selection: crate::engine::SelectionRef::NONE,
            },
        )
        .unwrap()
        .state;
        let discovery = crate::engine::legal_actions(&survivor_selection, &catalog)
            .iter()
            .filter_map(|action| {
                crate::engine::apply_action(&survivor_selection, &catalog, action)
                    .ok()
                    .map(|transition| transition.state)
            })
            .find(|candidate| {
                candidate.pending.as_deref().is_some_and(|pending| {
                    candidate
                        .pending_card_play(pending)
                        .and_then(|(record, _)| record.route().ok())
                        .is_some_and(|(_, kind)| {
                            kind == crate::hot::PendingSelectionKind::Discovery
                        })
                })
            })
            .expect("Survivor's first body can enter its effective-Sly Discovery child");
        let discovery_document = HotBoundary::try_to_canonical(&discovery, &catalog).unwrap();
        let discovery_catalog = HotBoundary::catalog_from_canonical(&discovery_document).unwrap();
        let discovery =
            HotBoundary::from_canonical(&discovery_document, &discovery_catalog).unwrap();
        assert_eq!(
            admit(&discovery_document, &discovery, &discovery_catalog),
            Ok(())
        );
        assert!(
            discovery_has_remaining_body_or_batch(&discovery, &discovery_catalog),
            "the authenticated Discovery offer still owns its current body"
        );

        let replay_selection = crate::engine::legal_actions(&discovery, &discovery_catalog)
            .iter()
            .filter_map(|action| {
                crate::engine::apply_action(&discovery, &discovery_catalog, action)
                    .ok()
                    .map(|transition| transition.state)
            })
            .find(|candidate| {
                candidate.frames.as_slice().iter().all(|frame| {
                    !matches!(frame, crate::frame::Frame::FrozenAutoBatch { .. })
                }) && candidate.pending.as_deref().is_some_and(|pending| {
                    candidate
                        .pending_card_play(pending)
                        .and_then(|(record, _)| record.route().ok())
                        .is_some_and(|(_, kind)| kind == crate::hot::PendingSelectionKind::Program)
                })
            })
            .expect("the skipped Discovery exhausts, its Sly batch pops, and Burst parks Survivor's replay selector");
        let replay_document =
            HotBoundary::try_to_canonical(&replay_selection, &discovery_catalog).unwrap();
        let replay_catalog = HotBoundary::catalog_from_canonical(&replay_document).unwrap();
        let replay = HotBoundary::from_canonical(&replay_document, &replay_catalog).unwrap();
        assert_eq!(
            admit(&replay_document, &replay, &replay_catalog),
            Ok(()),
            "the spent finite Discovery source must not demand a new unbounded owner pool after its Sly batch has popped"
        );
        assert!(
            !discovery_has_remaining_body_or_batch(&replay, &replay_catalog),
            "Survivor's parked replay has no Discovery body after its child exhausted"
        );
        let discovery_card = replay
            .piles
            .get(PileId::Exhaust)
            .as_slice()
            .iter()
            .copied()
            .find(|card| card.uid == u32::try_from(discovery_uid).unwrap())
            .expect("the completed L0 source is in Exhaust");
        assert!(
            discovery_cardplay_obligation_is_live(
                crate::hot::CardPlayStage::AfterNormalHook,
                false,
                2,
                0
            ),
            "a post-body Discovery with another replay remains an obligation"
        );
        assert!(
            !discovery_cardplay_obligation_is_live(
                crate::hot::CardPlayStage::AfterNormalHook,
                false,
                2,
                1
            ),
            "the final post-body replay is not itself a future Discovery body"
        );
        for (source, force_exhaust) in [
            (crate::hot::FrozenAutoBatchSource::SlyDiscard, false),
            (crate::hot::FrozenAutoBatchSource::Eidolon, true),
        ] {
            let mut queued = replay.clone();
            let record = crate::hot::FrozenAutoBatchRecord::from_current(
                &[discovery_card],
                &queued.card_states,
                0,
                force_exhaust,
                source,
            );
            assert!(
                queued.frames.push_frozen_auto_batch(&record).is_some(),
                "the queued {source:?} Discovery record is structurally valid"
            );
            assert!(
                discovery_has_remaining_body_or_batch(&queued, &replay_catalog),
                "an unconsumed {source:?} Discovery entry remains an obligation"
            );
        }
        let completed = crate::engine::apply_action(
            &replay,
            &replay_catalog,
            &crate::engine::legal_actions(&replay, &replay_catalog)[0],
        )
        .unwrap()
        .state;
        let completed_document =
            HotBoundary::try_to_canonical(&completed, &replay_catalog).unwrap();
        let completed_catalog = HotBoundary::catalog_from_canonical(&completed_document).unwrap();
        let completed =
            HotBoundary::from_canonical(&completed_document, &completed_catalog).unwrap();
        assert_eq!(
            admit(&completed_document, &completed, &completed_catalog),
            Ok(())
        );
    }

    #[test]
    fn rooted_sly_generated_offer_terminal_panache_stops_later_sibling() {
        let mut document = generator_document(CardId::Discovery, RewardPool::Ironclad, false, 37);
        let template = document.piles.get_mut("hand").unwrap().remove(0);
        document.piles.get_mut("hand").unwrap().clear();
        document.piles.get_mut("hand").unwrap().push(template);
        let discovery_uid = push_physical_card(&mut document, "hand", CardId::Discovery, 0);
        let later_uid = push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);
        document.piles.get_mut("hand").unwrap().remove(0);
        let parent_uid = push_physical_card(&mut document, "hand", CardId::HiddenDaggers, 0);
        push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);
        for monster in &mut document.monsters {
            monster.insert("hp".to_owned(), json!(10));
        }
        document
            .player
            .insert(PowerId::Panache.as_str().to_owned(), json!(10));
        append_singleton_side_end_row(&mut document, PowerId::Panache);
        document
            .player
            .insert("panache_instances".to_owned(), json!([[0, 10, 1, true]]));
        document.player.insert("panache_left".to_owned(), json!(1));
        document
            .player
            .insert("exact_piles".to_owned(), json!(true));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        state
            .card_states
            .set_transient_sly(discovery_uid.try_into().unwrap());
        state
            .card_states
            .set_transient_sly(later_uid.try_into().unwrap());
        let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let selecting = crate::engine::apply_action(
            &state,
            &catalog,
            &crate::engine::Action::Play {
                uid: parent_uid.try_into().unwrap(),
                target: None,
                selection: crate::engine::SelectionRef::NONE,
            },
        )
        .unwrap()
        .state;
        let discovery = crate::engine::legal_actions(&selecting, &catalog)
            .iter()
            .filter_map(|action| {
                crate::engine::apply_action(&selecting, &catalog, action)
                    .ok()
                    .map(|transition| (action, transition.state))
            })
            .find(|(action, candidate)| {
                // The widened Hidden Daggers enumeration (#2675) parks a
                // Discovery offer from several answers; this slice needs the
                // one that leaves the later physical sibling in hand, which
                // is what the old sub-multiset enumeration's first match
                // discarded.
                let crate::engine::Action::Select { answer } = action else {
                    return false;
                };
                let untouched = crate::engine::selected_card_uids(&selecting, &catalog, *answer)
                    .ok()
                    .flatten()
                    .is_some_and(|picked| !picked.contains(&u32::try_from(later_uid).unwrap()));
                untouched
                    && candidate.pending.as_deref().is_some_and(|pending| {
                        candidate
                            .pending_card_play(pending)
                            .and_then(|(record, _)| record.route().ok())
                            .is_some_and(|(_, kind)| {
                                kind == crate::hot::PendingSelectionKind::Discovery
                            })
                    })
            })
            .map(|(_, candidate)| candidate)
            .expect("the first frozen child owns its public Discovery offer");
        let terminal = crate::engine::legal_actions(&discovery, &catalog)
            .iter()
            .filter_map(|action| {
                crate::engine::apply_action(&discovery, &catalog, action)
                    .ok()
                    .map(|transition| transition.state)
            })
            .find(|candidate| candidate.history.over)
            .expect("Panache's generated-child callback ends the two low-HP targets");
        assert_eq!(
            terminal.block, 0,
            "the later Sly Defend never starts after ending"
        );
        assert!(
            terminal
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .any(|card| card.uid == u32::try_from(later_uid).unwrap()),
            "the terminal batch leaves its later physical sibling unplayed"
        );
        let terminal_document = HotBoundary::try_to_canonical(&terminal, &catalog).unwrap();
        let terminal_catalog = HotBoundary::catalog_from_canonical(&terminal_document).unwrap();
        let terminal = HotBoundary::from_canonical(&terminal_document, &terminal_catalog).unwrap();
        assert_eq!(
            HotBoundary::try_to_canonical(&terminal, &terminal_catalog).unwrap(),
            terminal_document,
            "the terminal public state still has an exact cold projection"
        );
    }

    /// Two frozen generated-offer siblings under one Hidden Daggers batch:
    /// the first parks, answering it advances the cursor to the second, and
    /// the parent's fixed two-Shiv suffix runs once at the end.
    ///
    /// #2715 adds Abundance beside Splash here, which is the "selecting the
    /// child after an earlier sibling" witness #2666 asks for, and also the
    /// per-source generation accounting: each frozen source runs its own
    /// shuffle exactly once (`IL_0097`), and answering either offer never
    /// re-shuffles.
    #[test]
    fn rooted_sly_generated_offer_batch_parks_its_first_and_later_children() {
        for (id, kind_expected) in [
            (CardId::Splash, crate::hot::PendingSelectionKind::Splash),
            (
                CardId::Abundance,
                crate::hot::PendingSelectionKind::Abundance,
            ),
        ] {
            for upgrade in 0..=1 {
                let mut document = generator_document(id, RewardPool::Ironclad, false, 17);
                let template = document.piles.get_mut("hand").unwrap().remove(0);
                document.piles.get_mut("hand").unwrap().clear();
                document.piles.get_mut("hand").unwrap().push(template);
                let first_splash_uid = push_physical_card(&mut document, "hand", id, upgrade);
                let later_splash_uid = push_physical_card(&mut document, "hand", id, upgrade);
                document.piles.get_mut("hand").unwrap().remove(0);
                push_physical_card(&mut document, "hand", CardId::DefendIronclad, 0);
                let parent_uid =
                    push_physical_card(&mut document, "hand", CardId::HiddenDaggers, 0);
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                state
                    .card_states
                    .set_transient_sly(first_splash_uid.try_into().unwrap());
                state
                    .card_states
                    .set_transient_sly(later_splash_uid.try_into().unwrap());
                let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                assert_eq!(admit(&document, &state, &catalog), Ok(()));

                let selecting = crate::engine::apply_action(
                    &state,
                    &catalog,
                    &crate::engine::Action::Play {
                        uid: parent_uid.try_into().unwrap(),
                        target: None,
                        selection: crate::engine::SelectionRef::NONE,
                    },
                )
                .unwrap()
                .state;
                assert!(
                    selecting.pending.as_deref().is_some_and(|pending| {
                        selecting
                            .pending_card_play(pending)
                            .and_then(|(record, _)| record.route().ok())
                            .is_some_and(|(_, kind)| {
                                kind == crate::hot::PendingSelectionKind::Program
                            })
                    }),
                    "the third non-Sly card keeps Hidden Daggers' two-card selector public"
                );
                let first = crate::engine::legal_actions(&selecting, &catalog)
                    .iter()
                    .filter_map(|answer| {
                        crate::engine::apply_action(&selecting, &catalog, answer).ok()
                    })
                    .map(|transition| transition.state)
                    .find(|candidate| {
                        candidate.pending.as_deref().is_some_and(|pending| {
                            candidate
                                .pending_card_play(pending)
                                .and_then(|(record, _)| record.route().ok())
                                .is_some_and(|(_, kind)| kind == kind_expected)
                        }) && candidate.frames.as_slice().iter().any(|frame| {
                            let crate::frame::Frame::FrozenAutoBatch { record } = *frame else {
                                return false;
                            };
                            candidate
                                .frames
                                .frozen_auto_batch(record)
                                .is_some_and(|batch| batch.len() == 2 && batch.cursor == 1)
                        })
                    })
                    .expect("the first frozen temporary-Sly child parks at its generated offer");
                let generation_before_first_offer = selecting.rng.get(RngStream::Generation);
                let batch_len = first
                    .frames
                    .as_slice()
                    .iter()
                    .find_map(|frame| {
                        let crate::frame::Frame::FrozenAutoBatch { record } = *frame else {
                            return None;
                        };
                        first
                            .frames
                            .frozen_auto_batch(record)
                            .map(|batch| batch.len())
                    })
                    .expect("the first offer remains below its frozen Sly owner");
                assert_eq!(batch_len, 2, "both temporary Sly sources are frozen");
                assert!(
                    [
                        u32::try_from(first_splash_uid).unwrap(),
                        u32::try_from(later_splash_uid).unwrap(),
                    ]
                    .contains(&first.pending.as_deref().unwrap().frame_uid),
                    "the first parked offer is owned by a frozen physical generated-offer source"
                );
                let first_document = HotBoundary::try_to_canonical(&first, &catalog).unwrap();
                let first_catalog = HotBoundary::catalog_from_canonical(&first_document).unwrap();
                let first_reloaded =
                    HotBoundary::from_canonical(&first_document, &first_catalog).unwrap();
                assert_eq!(
                    admit(&first_document, &first_reloaded, &first_catalog),
                    Ok(())
                );

                for (first_option, first_answer) in
                    crate::engine::legal_actions(&first_reloaded, &first_catalog)
                        .iter()
                        .enumerate()
                {
                    let second =
                        crate::engine::apply_action(&first_reloaded, &first_catalog, first_answer)
                            .unwrap_or_else(|error| {
                                panic!("{id:?} first option {first_option} must resume: {error}")
                            })
                            .state;
                    assert!(
                        second.pending.as_deref().is_some_and(|pending| {
                            second
                                .pending_card_play(pending)
                                .and_then(|(record, _)| record.route().ok())
                                .is_some_and(|(_, kind)| kind == kind_expected)
                        }),
                        "{id:?} first option {first_option} must park the later frozen Splash source"
                    );
                    let first_generation = first_reloaded.rng.get(RngStream::Generation);
                    let second_generation = second.rng.get(RngStream::Generation);
                    assert_eq!(
                        second_generation.counter - first_generation.counter,
                        first_generation.counter - generation_before_first_offer.counter,
                        "{id:?}+{upgrade} first option {first_option} runs the later source's generation body exactly once"
                    );
                    assert_ne!(
                        second.pending.as_deref().unwrap().frame_uid,
                        first_reloaded.pending.as_deref().unwrap().frame_uid,
                        "{id:?} first option {first_option} must advance to the other physical source"
                    );
                    let second_document =
                        HotBoundary::try_to_canonical(&second, &first_catalog).unwrap();
                    let second_catalog =
                        HotBoundary::catalog_from_canonical(&second_document).unwrap();
                    let second_reloaded =
                        HotBoundary::from_canonical(&second_document, &second_catalog).unwrap();
                    assert_eq!(
                        second_reloaded, second,
                        "{id:?} first option {first_option} cold equality"
                    );
                    assert_eq!(
                        admit(&second_document, &second_reloaded, &second_catalog),
                        Ok(()),
                        "{id:?} first option {first_option} cold admission"
                    );
                    for (second_option, second_answer) in
                        crate::engine::legal_actions(&second_reloaded, &second_catalog)
                            .iter()
                            .enumerate()
                    {
                        let completed = crate::engine::apply_action(
                    &second_reloaded,
                    &second_catalog,
                    second_answer,
                )
                .unwrap_or_else(|error| {
                    panic!(
                        "{id:?} first/second options {first_option}/{second_option} must resume: {error}"
                    )
                })
                .state;
                        assert!(completed.pending.is_none());
                        assert!(completed.frames.is_empty());
                        assert_eq!(
                            completed.rng.get(RngStream::Generation),
                            second_generation,
                            "{id:?}+{upgrade} options {first_option}/{second_option} resume without regenerating the later offer"
                        );
                        let completed_document =
                            HotBoundary::try_to_canonical(&completed, &second_catalog).unwrap();
                        let completed_catalog =
                            HotBoundary::catalog_from_canonical(&completed_document).unwrap();
                        let completed_reloaded =
                            HotBoundary::from_canonical(&completed_document, &completed_catalog)
                                .unwrap();
                        assert_eq!(
                            HotBoundary::try_to_canonical(&completed_reloaded, &completed_catalog)
                                .unwrap(),
                            completed_document,
                            "{id:?}+{upgrade} options {first_option}/{second_option} final cold projection equality"
                        );
                        assert_eq!(
                            admit(&completed_document, &completed_reloaded, &completed_catalog),
                            Ok(()),
                            "{id:?}+{upgrade} options {first_option}/{second_option} final cold admission"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn rooted_sly_generated_offer_two_card_auto_selection_parks_its_first_child() {
        for upgrade in 0..=1 {
            let mut document = generator_document(CardId::Splash, RewardPool::Ironclad, false, 23);
            let template = document.piles.get_mut("hand").unwrap().remove(0);
            document.piles.get_mut("hand").unwrap().clear();
            document.piles.get_mut("hand").unwrap().push(template);
            let first_splash_uid =
                push_physical_card(&mut document, "hand", CardId::Splash, upgrade);
            let later_splash_uid =
                push_physical_card(&mut document, "hand", CardId::Splash, upgrade);
            document.piles.get_mut("hand").unwrap().remove(0);
            let parent_uid = push_physical_card(&mut document, "hand", CardId::HiddenDaggers, 0);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            state
                .card_states
                .set_transient_sly(first_splash_uid.try_into().unwrap());
            state
                .card_states
                .set_transient_sly(later_splash_uid.try_into().unwrap());
            let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();

            let first = crate::engine::apply_action(
                &state,
                &catalog,
                &crate::engine::Action::Play {
                    uid: parent_uid.try_into().unwrap(),
                    target: None,
                    selection: crate::engine::SelectionRef::NONE,
                },
            )
            .unwrap()
            .state;
            assert!(
                first.pending.as_deref().is_some_and(|pending| {
                    first
                        .pending_card_play(pending)
                        .and_then(|(record, _)| record.route().ok())
                        .is_some_and(|(_, kind)| kind == crate::hot::PendingSelectionKind::Splash)
                }),
                "two selectable Splash cards auto-select together and immediately park their first offer"
            );
            let batch = first
                .frames
                .as_slice()
                .iter()
                .find_map(|frame| {
                    let crate::frame::Frame::FrozenAutoBatch { record } = *frame else {
                        return None;
                    };
                    first.frames.frozen_auto_batch(record)
                })
                .expect("the automatic selection retains its frozen Sly owner");
            assert_eq!(batch.len(), 2, "Splash+{upgrade} auto-selects both sources");
            assert_eq!(batch.cursor, 1, "Splash+{upgrade} parked the first source");
            assert!(
                [
                    u32::try_from(first_splash_uid).unwrap(),
                    u32::try_from(later_splash_uid).unwrap(),
                ]
                .contains(&first.pending.as_deref().unwrap().frame_uid),
                "the direct public Play pause belongs to one frozen physical Splash source"
            );
            let canonical = HotBoundary::try_to_canonical(&first, &catalog).unwrap();
            let reloaded_catalog = HotBoundary::catalog_from_canonical(&canonical).unwrap();
            let reloaded = HotBoundary::from_canonical(&canonical, &reloaded_catalog).unwrap();
            assert_eq!(
                reloaded, first,
                "Splash+{upgrade} automatic first-offer cold equality"
            );
            assert_eq!(
                admit(&canonical, &reloaded, &reloaded_catalog),
                Ok(()),
                "Splash+{upgrade} automatic first-offer cold admission"
            );
        }
    }

    /// #2715 runs Abundance through the same four forgeries as Splash: the
    /// rooted driver authenticates the offer ORDER, the frozen source uid, the
    /// batch cursor and the ActionReplay root, and none of that is
    /// card-specific — which is the point of running both through one body.
    #[test]
    fn rooted_sly_generated_offer_forged_cold_carriers_are_rejected_atomically() {
        for id in [CardId::Splash, CardId::Abundance] {
            let mut document = generator_document(id, RewardPool::Ironclad, false, 29);
            let template = document.piles.get_mut("hand").unwrap().remove(0);
            document.piles.get_mut("hand").unwrap().clear();
            document.piles.get_mut("hand").unwrap().push(template);
            let first_splash_uid = push_physical_card(&mut document, "hand", id, 0);
            let later_splash_uid = push_physical_card(&mut document, "hand", id, 0);
            document.piles.get_mut("hand").unwrap().remove(0);
            let parent_uid = push_physical_card(&mut document, "hand", CardId::HiddenDaggers, 0);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            state
                .card_states
                .set_transient_sly(first_splash_uid.try_into().unwrap());
            state
                .card_states
                .set_transient_sly(later_splash_uid.try_into().unwrap());
            let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            let first = crate::engine::apply_action(
                &state,
                &catalog,
                &crate::engine::Action::Play {
                    uid: parent_uid.try_into().unwrap(),
                    target: None,
                    selection: crate::engine::SelectionRef::NONE,
                },
            )
            .unwrap()
            .state;
            let valid = HotBoundary::try_to_canonical(&first, &catalog).unwrap();

            let mut reordered_offers = valid.clone();
            reordered_offers.player.get_mut("pending").unwrap()[3]
                .as_array_mut()
                .unwrap()
                .swap(0, 1);
            let mut forged_source_uid = valid.clone();
            forged_source_uid.continuations[2]
                .fields
                .get_mut("entries")
                .unwrap()[0]["uid"] = json!(later_splash_uid);
            let mut forged_cursor = valid.clone();
            forged_cursor.continuations[2]
                .fields
                .insert("cursor".to_owned(), json!(2));
            let mut missing_replay_root = valid.clone();
            missing_replay_root.continuations.remove(0);

            for (name, forged) in [
                ("offer order", reordered_offers),
                ("source uid", forged_source_uid),
                ("cursor", forged_cursor),
                ("ActionReplay root", missing_replay_root),
            ] {
                let rejected = match HotBoundary::catalog_from_canonical(&forged) {
                    Err(_) => true,
                    Ok(catalog) => match HotBoundary::from_canonical(&forged, &catalog) {
                        Err(_) => true,
                        Ok(state) => admit(&forged, &state, &catalog).is_err(),
                    },
                };
                assert!(
                    rejected,
                    "forged rooted Sly generated-offer {name} must fail before any action \
                 can mutate state ({id:?})"
                );
            }
        }
    }

    #[test]
    fn rooted_sly_discard_retrieval_classifier_is_exactly_two_rows_at_both_levels() {
        let mut rootless_builder = CatalogBuilder::new();
        rootless_builder
            .intern_reachable(identity(CardId::Hologram, 0))
            .unwrap();
        let rootless = rootless_builder.build();
        let rootless_hologram = rootless
            .atom(&identity(CardId::Hologram, 0))
            .and_then(|atom| rootless.spec(atom))
            .unwrap();
        assert!(!rootless.requires_action_replay());
        assert!(
            !rooted_sly_discard_retrieval_child_is_exact(&rootless, rootless_hologram),
            "the legacy rootless carrier remains outside this Sly retrieval slice"
        );

        let mut builder = CatalogBuilder::new();
        for id in [CardId::Hologram, CardId::CosmicIndifference] {
            for upgrade in 0..=1 {
                builder.intern_reachable(identity(id, upgrade)).unwrap();
            }
        }
        builder
            .intern_reachable(identity(CardId::HiddenDaggers, 0))
            .unwrap();
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());
        for id in [CardId::Hologram, CardId::CosmicIndifference] {
            for upgrade in 0..=1 {
                let spec = catalog
                    .atom(&identity(id, upgrade))
                    .and_then(|atom| catalog.spec(atom))
                    .unwrap();
                assert!(rooted_sly_discard_retrieval_child_is_exact(&catalog, spec));
            }
        }
        let other = catalog
            .atom(&identity(CardId::HiddenDaggers, 0))
            .and_then(|atom| catalog.spec(atom))
            .unwrap();
        assert!(!rooted_sly_discard_retrieval_child_is_exact(
            &catalog, other
        ));
    }

