    #[test]
    fn rooted_sly_hidden_daggers_classifier_is_exactly_two_rows() {
        // Unlike Hologram and Dredge, Hidden Daggers inherently requires
        // action replay (its generated select is replay-rooted), so there is
        // no rootless-HD catalog to negatively pin; the replay conjunct still
        // guards the classifier for uniformity with its siblings.
        let mut builder = CatalogBuilder::new();
        for upgrade in 0..=1 {
            builder
                .intern_reachable(identity(CardId::HiddenDaggers, upgrade))
                .unwrap();
        }
        builder
            .intern_reachable(identity(CardId::Dredge, 0))
            .unwrap();
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());
        for upgrade in 0..=1 {
            let daggers = catalog
                .atom(&identity(CardId::HiddenDaggers, upgrade))
                .and_then(|atom| catalog.spec(atom))
                .unwrap();
            assert!(rooted_sly_hidden_daggers_child_is_exact(&catalog, daggers));
        }
        let other = catalog
            .atom(&identity(CardId::Dredge, 0))
            .and_then(|atom| catalog.spec(atom))
            .unwrap();
        assert!(!rooted_sly_hidden_daggers_child_is_exact(&catalog, other));
    }

    #[test]
    fn native_retain_and_sly_widen_only_the_mechanically_complete_rows() {
        let (document, state, base) = parts();
        let retain_rows: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.retain)
            .collect();
        let sly_rows: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.sly)
            .collect();
        assert_eq!(
            retain_rows.len(),
            // #3036 added Misery+ (`Misery::OnUpgrade` RVA 0xe5c23 IL_0018).
            35,
            "native Retain carrier census drifted"
        );
        assert_eq!(sly_rows.len(), 14, "native Sly carrier census drifted");

        let admitted: BTreeSet<_> = retain_rows
            .iter()
            .filter_map(|row| {
                let candidate = identity(row.id, row.upgrade);
                admit(&document, &state, &catalog_with(&base, candidate))
                    .is_ok()
                    .then_some(candidate)
            })
            .collect();
        let expected: BTreeSet<_> = [
            (CardId::Anointed, 1),
            (CardId::CalculatedGamble, 1),
            (CardId::Dredge, 1),
            (CardId::Eradicate, 0),
            (CardId::Eradicate, 1),
            (CardId::GoldAxe, 1),
            (CardId::Luminesce, 0),
            (CardId::Luminesce, 1),
            (CardId::Misery, 1),
            (CardId::Monologue, 1),
            (CardId::PoorSleep, 0),
            (CardId::Purity, 0),
            (CardId::Purity, 1),
            (CardId::Reap, 0),
            (CardId::Reap, 1),
            (CardId::ReaperForm, 1),
            (CardId::Restlessness, 0),
            (CardId::Restlessness, 1),
            (CardId::RoyalGamble, 1),
            (CardId::Sacrifice, 0),
            (CardId::Sacrifice, 1),
            (CardId::Scrawl, 1),
            (CardId::Snakebite, 0),
            (CardId::Snakebite, 1),
            (CardId::SovereignBlade, 0),
            (CardId::SovereignBlade, 1),
            (CardId::Sow, 0),
            (CardId::Sow, 1),
            (CardId::Spur, 0),
            (CardId::Spur, 1),
            (CardId::TimesUp, 1),
            (CardId::Wish, 1),
            (CardId::Wisp, 1),
        ]
        .into_iter()
        .map(|(id, upgrade)| identity(id, upgrade))
        .collect();
        assert_eq!(admitted, expected);

        let admitted_sly: BTreeSet<_> = sly_rows
            .iter()
            .filter_map(|row| {
                let candidate = identity(row.id, row.upgrade);
                admit(&document, &state, &catalog_with(&base, candidate))
                    .is_ok()
                    .then_some(candidate)
            })
            .collect();
        assert_eq!(
            admitted_sly,
            [
                // The static-Sly Skill/Power rows join the two Attack rows:
                // each is one ordinary self-directed body, and the discard
                // AutoPlay lifecycle is the same shared machinery.
                identity(CardId::Abrasive, 0),
                identity(CardId::Abrasive, 1),
                identity(CardId::FlickFlack, 0),
                identity(CardId::FlickFlack, 1),
                identity(CardId::Ricochet, 0),
                identity(CardId::Ricochet, 1),
                identity(CardId::Reflex, 0),
                identity(CardId::Reflex, 1),
                identity(CardId::Untouchable, 0),
                identity(CardId::Untouchable, 1),
                identity(CardId::Tactician, 0),
                identity(CardId::Tactician, 1),
            ]
            .into_iter()
            .collect(),
            "only rows with complete static-Sly lifecycle closure are admitted"
        );

        for row in sly_rows {
            let candidate = identity(row.id, row.upgrade);
            if admitted_sly.contains(&candidate) {
                assert!(
                    static_sly_attack_program_is_supported(row)
                        || static_sly_body_program_is_supported(row)
                );
                play_isolated(candidate).unwrap_or_else(|refusal| {
                    panic!(
                        "{}+{} refused at play: {refusal}",
                        row.id.as_str(),
                        row.upgrade
                    )
                });
                let mut mutated = *row;
                mutated.cost += 1;
                assert!(!static_sly_attack_program_is_supported(&mutated));
                assert!(!static_sly_body_program_is_supported(&mutated));
                assert!(!card_keywords_are_inert(&mutated));
                continue;
            }
            let refusal = admit(&document, &state, &catalog_with(&base, candidate)).unwrap_err();
            assert!(
                refusal.contains(MissingCapability::CardKeyword(row.id)),
                "{}+{} lost its native Sly refusal: {refusal}",
                row.id.as_str(),
                row.upgrade
            );
        }

        let shadow_step = catalog_with(&base, identity(CardId::ShadowStep, 0));
        for id in [CardId::FlickFlack, CardId::Ricochet] {
            let composed = catalog_with(&shadow_step, identity(id, 0));
            assert_eq!(
                admit(&document, &state, &composed),
                Ok(()),
                "non-selecting static Sly must compose with Shadow Step: {}",
                id.as_str()
            );
        }
        let master_planner_admitted: BTreeSet<_> = (0..=1)
            .filter_map(|upgrade| {
                let candidate = identity(CardId::MasterPlanner, upgrade);
                admit(&document, &state, &catalog_with(&base, candidate))
                    .is_ok()
                    .then_some(candidate)
            })
            .collect();
        assert_eq!(
            master_planner_admitted,
            [
                identity(CardId::MasterPlanner, 0),
                identity(CardId::MasterPlanner, 1)
            ]
            .into_iter()
            .collect()
        );
    }

    #[test]
    fn permanent_local_sly_requires_live_master_planner_skill_provenance() {
        let (mut document, _, _) = parts();
        let carrier = &mut document.piles.get_mut("hand").unwrap()[0];
        carrier.id = "DEFEND_IRONCLAD".to_owned();
        carrier.upgrade = 0;
        carrier.local_keywords = vec!["Sly".to_owned()];
        document
            .player
            .insert("master_planner".to_owned(), Value::from(1));
        append_singleton_after_card_played_row(&mut document, PowerId::MasterPlanner);
        document
            .player
            .insert("exact_piles".to_owned(), Value::from(true));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        admit(&document, &state, &catalog).expect("completed Skill with live writer admits");

        document.player.remove("master_planner");
        document.player.remove("after_card_played_power_order");
        document.player.remove("next_after_side_turn_end_power_uid");
        assert!(refuse(&document).contains(MissingCapability::ArgumentShape(
            "master planner local Sly provenance"
        )));

        document
            .player
            .insert("master_planner".to_owned(), Value::from(1));
        append_singleton_after_card_played_row(&mut document, PowerId::MasterPlanner);
        document.piles.get_mut("hand").unwrap()[0].id = "STRIKE_IRONCLAD".to_owned();
        assert!(refuse(&document).contains(MissingCapability::ArgumentShape(
            "master planner local Sly provenance"
        )));
    }

    #[test]
    fn body_owned_selection_gate_censuses_twenty_shapes_and_ten_base_admitted_rows() {
        let (document, state, base) = parts();
        let supported: BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| body_owned_select_program_is_supported(row))
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        let expected: BTreeSet<_> = [
            CardId::Abundance,
            CardId::Discovery,
            CardId::Dredge,
            CardId::Glimmer,
            CardId::NeowsFury,
            CardId::Purity,
            CardId::Quasar,
            CardId::SeekerStrike,
            CardId::Splash,
            CardId::Tutor,
        ]
        .into_iter()
        .flat_map(|id| [identity(id, 0), identity(id, 1)])
        .collect();
        assert_eq!(supported, expected, "body-owned selector census drifted");
        let manifest = capability_manifest();
        assert!(manifest.steps.contains(&StepKind::PurityExact));
        assert!(manifest.steps.contains(&StepKind::SeekerStrikeExact));
        assert!(manifest.steps.contains(&StepKind::AbundanceExact));
        assert!(manifest.steps.contains(&StepKind::DiscoveryExact));
        assert!(manifest.steps.contains(&StepKind::QuasarExact));
        assert!(manifest.steps.contains(&StepKind::HandCapBody));
        assert!(manifest.steps.contains(&StepKind::GlimmerExact));
        assert!(manifest.steps.contains(&StepKind::TutorExact));
        let mut admitted = BTreeSet::new();
        for candidate in supported {
            let result = admit(&document, &state, &catalog_with(&base, candidate));
            if matches!(
                candidate.id,
                CardId::Abundance | CardId::Discovery | CardId::Quasar | CardId::Splash
            ) {
                let refusal =
                    result.expect_err("reachable generated source lacks its exact closure");
                if candidate.id == CardId::Abundance {
                    assert!(refusal.contains(MissingCapability::ArgumentShape(
                        "abundance generation provenance"
                    )));
                    assert!(refusal.contains(MissingCapability::ArgumentShape(
                        "abundance generation closure"
                    )));
                } else if candidate.id == CardId::Discovery {
                    assert!(refusal.contains(MissingCapability::ArgumentShape(
                        "Discovery generation provenance"
                    )));
                } else if candidate.id == CardId::Quasar {
                    assert!(refusal.contains(MissingCapability::ArgumentShape(
                        "Quasar generation provenance"
                    )));
                    assert!(refusal.contains(MissingCapability::ArgumentShape(
                        "Quasar generation closure"
                    )));
                } else {
                    assert!(refusal.contains(MissingCapability::ArgumentShape(
                        "Splash generation provenance"
                    )));
                    assert!(refusal.contains(MissingCapability::ArgumentShape(
                        "Splash generation closure"
                    )));
                }
            } else if candidate.id == CardId::Tutor {
                assert!(
                    result
                        .expect_err("Tutor remains MultiplayerOnly in the solo fixture")
                        .contains(MissingCapability::MultiplayerCard(CardId::Tutor))
                );
            } else {
                assert_eq!(
                    result,
                    Ok(()),
                    "{}+{} must admit with its exact selector shape",
                    candidate.id.as_str(),
                    candidate.upgrade
                );
                admitted.insert(candidate);
            }
            let mut row = *crate::content_tables::card_row(candidate.id, candidate.upgrade)
                .expect("candidate came from generated rows");
            row.selects = false;
            assert!(!card_keywords_are_inert(&row));
            row.selects = true;
            for operand in 0..row.steps[0].args.len() {
                let mut mutated = row;
                let mut args = row.steps[0].args.to_vec();
                match &mut args[operand] {
                    Arg::I(value) => *value += 1,
                    Arg::S(value) => *value = "__mutation__",
                    _ => panic!("exact special selector operands are strings or integers"),
                }
                let steps = [crate::content_tables::Step {
                    kind: row.steps[0].kind,
                    args: Box::leak(args.into_boxed_slice()),
                }];
                mutated.steps = Box::leak(Box::new(steps));
                assert!(!body_owned_select_program_is_supported(&mutated));
                assert!(!card_keywords_are_inert(&mutated));
            }
        }
        assert_eq!(
            admitted,
            [
                identity(CardId::Purity, 0),
                identity(CardId::Purity, 1),
                identity(CardId::SeekerStrike, 0),
                identity(CardId::SeekerStrike, 1),
                identity(CardId::Dredge, 0),
                identity(CardId::Dredge, 1),
                identity(CardId::NeowsFury, 0),
                identity(CardId::NeowsFury, 1),
                identity(CardId::Glimmer, 0),
                identity(CardId::Glimmer, 1),
            ]
            .into_iter()
            .collect()
        );
    }

    #[test]
    fn tutor_remote_selection_horizon_refuses_exact_future_many_card_sources() {
        let (mut document, _, _) = parts();
        add_minimal_party(&mut document);
        let base = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &base).unwrap();
        let tutor = catalog_with(&base, identity(CardId::Tutor, 0));
        assert_eq!(admit(&document, &state, &tutor), Ok(()));
        for source in [
            CardId::GlimpseBeyond,
            CardId::Constellation,
            CardId::HuddleUp,
        ] {
            let catalog = catalog_with(&tutor, identity(source, 0));
            assert!(
                admit(&document, &state, &catalog).unwrap_err().contains(
                    MissingCapability::ArgumentShape("Tutor future remote Draw selection")
                ),
                "{source:?} can make a later remote Tutor require a teammate choice"
            );
        }

        let (mut ball_document, _, _) = parts();
        add_minimal_party(&mut ball_document);
        ball_document.player.get_mut("multiplayer_allies").unwrap()[0]["fields"]["draw"] =
            json!([[CardId::DefendIronclad.as_str(), 0]]);
        ball_document.player.get_mut("multiplayer_allies").unwrap()[0]["fields"]["shuffle_rng"] =
            json!([31, 32, 33, 34, 0]);
        let source = &mut ball_document.piles.get_mut("hand").unwrap()[0];
        source.id = CardId::TheBall.as_str().to_owned();
        source.upgrade = 0;
        source.physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
        let ball_catalog = HotBoundary::catalog_from_canonical(&ball_document).unwrap();
        let ball_state = HotBoundary::from_canonical(&ball_document, &ball_catalog).unwrap();
        assert_eq!(
            admit(&ball_document, &ball_state, &ball_catalog),
            Ok(()),
            "The Ball alone has no future teammate selector"
        );
        let ball_uid = ball_state.piles.get(PileId::Hand).as_slice()[0].uid;
        assert!(crate::engine::legal_actions(&ball_state, &ball_catalog).iter().any(
            |action| matches!(action, crate::engine::Action::Play { uid, .. } if *uid == ball_uid)
        ));

        let mut missing_targets = ball_state.clone();
        missing_targets
            .rng
            .set(RngStream::Targets, crate::hot::RngStreamState::default());
        assert!(
            admit(&ball_document, &missing_targets, &ball_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape("The Ball Targets stream"))
        );
        assert!(!crate::engine::legal_actions(&missing_targets, &ball_catalog).iter().any(
            |action| matches!(action, crate::engine::Action::Play { uid, .. } if *uid == ball_uid)
        ));

        let mut malformed_targets = ball_state.clone();
        malformed_targets.rng.set(
            RngStream::Targets,
            crate::hot::RngStreamState {
                words: [0; 4],
                counter: 1,
            },
        );
        assert!(
            admit(&ball_document, &malformed_targets, &ball_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape("The Ball Targets stream"))
        );
        assert!(!crate::engine::legal_actions(&malformed_targets, &ball_catalog).iter().any(
            |action| matches!(action, crate::engine::Action::Play { uid, .. } if *uid == ball_uid)
        ));

        let mut missing_shuffle = ball_state.clone();
        missing_shuffle.fanouts.multiplayer_ally_mut().shuffle_rng = None;
        assert!(
            admit(&ball_document, &missing_shuffle, &ball_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "The Ball remote Shuffle stream"
                ))
        );
        assert!(!crate::engine::legal_actions(&missing_shuffle, &ball_catalog).iter().any(
            |action| matches!(action, crate::engine::Action::Play { uid, .. } if *uid == ball_uid)
        ));
        let mut malformed_shuffle = ball_state.clone();
        malformed_shuffle.fanouts.multiplayer_ally_mut().shuffle_rng =
            Some(crate::hot::RngStreamState {
                words: [0; 4],
                counter: 1,
            });
        assert!(
            admit(&ball_document, &malformed_shuffle, &ball_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "The Ball remote Shuffle stream"
                ))
        );
        assert!(!crate::engine::legal_actions(&malformed_shuffle, &ball_catalog).iter().any(
            |action| matches!(action, crate::engine::Action::Play { uid, .. } if *uid == ball_uid)
        ));
        let ball_and_tutor = catalog_with(&ball_catalog, identity(CardId::Tutor, 0));
        assert!(
            admit(&ball_document, &ball_state, &ball_and_tutor)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "Tutor future remote Draw selection"
                ))
        );

        let mut largesse_document = ball_document;
        let source = &mut largesse_document.piles.get_mut("hand").unwrap()[0];
        source.id = CardId::Largesse.as_str().to_owned();
        source.physical_state = None;
        largesse_document
            .player
            .get_mut("multiplayer_allies")
            .unwrap()[0]["fields"]
            .as_object_mut()
            .unwrap()
            .remove("shuffle_rng");
        let largesse_catalog = HotBoundary::catalog_from_canonical(&largesse_document).unwrap();
        let largesse_state =
            HotBoundary::from_canonical(&largesse_document, &largesse_catalog).unwrap();
        assert!(
            admit(&largesse_document, &largesse_state, &largesse_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "The Ball remote Shuffle stream"
                )),
            "reachable Largesse can expose a fresh non-dupe local The Ball"
        );
    }

    #[test]
    fn sovereign_blade_is_the_only_new_dynamic_target_shape() {
        let dynamic = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.target_type == "Dynamic")
            .map(|row| (row.id, row.upgrade, card_keywords_are_inert(row)))
            .collect::<Vec<_>>();
        let admitted_sovereign = dynamic
            .iter()
            .filter(|(id, _, admitted)| *id == CardId::SovereignBlade && *admitted)
            .map(|(id, upgrade, _)| (*id, *upgrade))
            .collect::<Vec<_>>();
        assert_eq!(
            admitted_sovereign,
            [(CardId::SovereignBlade, 0), (CardId::SovereignBlade, 1)]
        );
        assert!(dynamic.iter().all(|(id, _, admitted)| {
            *id == CardId::SovereignBlade || *id == CardId::Shiv || !*admitted
        }));
    }

    #[test]
    fn hand_cap_admission_is_exactly_ten_rows_with_debris_provenance() {
        let (document, state, base) = parts();
        let rows: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                row.steps
                    .iter()
                    .any(|step| step.kind == StepKind::HandCapBody)
            })
            .collect();
        assert_eq!(rows.len(), 10, "HandCap carrier census drifted");
        for row in rows {
            assert!(crate::steps::hand_cap::program_is_supported(row));
            let candidate = identity(row.id, row.upgrade);
            assert_eq!(
                admit(&document, &state, &catalog_with(&base, candidate)),
                Ok(()),
                "{}+{} lost exact HandCap admission",
                row.id.as_str(),
                row.upgrade
            );
            play_isolated(candidate).unwrap_or_else(|refusal| {
                panic!(
                    "admitted HandCap row {}+{} refused at play: {refusal}",
                    row.id.as_str(),
                    row.upgrade
                )
            });
        }

        let mut debris_only = document.clone();
        let card = &mut debris_only.piles.get_mut("hand").unwrap()[0];
        card.id = CardId::Debris.as_str().to_owned();
        card.upgrade = 0;
        let refusal = refuse(&debris_only);
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Debris generation provenance"
        )));

        let mut crash_and_debris = debris_only;
        let crash = &mut crash_and_debris.piles.get_mut("hand").unwrap()[1];
        crash.id = CardId::CrashLanding.as_str().to_owned();
        crash.upgrade = 0;
        let catalog = HotBoundary::catalog_from_canonical(&crash_and_debris).unwrap();
        let state = HotBoundary::from_canonical(&crash_and_debris, &catalog).unwrap();
        assert_eq!(admit(&crash_and_debris, &state, &catalog), Ok(()));

        let row = *crate::content_tables::card_row(CardId::CrashLanding, 0).unwrap();
        let mut mutated = row;
        const BAD_ARGS: &[Arg] = &[Arg::S("aoe_debris"), Arg::I(22)];
        const BAD_STEPS: &[crate::content_tables::Step] = &[crate::content_tables::Step {
            kind: StepKind::HandCapBody,
            args: BAD_ARGS,
        }];
        mutated.steps = BAD_STEPS;
        assert!(!crate::steps::hand_cap::program_is_supported(&mutated));
        assert!(!card_keywords_are_inert(&mutated));
    }

    #[test]
    fn synchronous_autoplay_admission_is_exactly_eight_generated_rows() {
        let (document, state, base) = parts();
        let kinds = [
            StepKind::Havoc,
            StepKind::UproarExact,
            StepKind::CatastropheExact,
            StepKind::KnifeTrapExact,
        ];
        let rows = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.steps.iter().any(|step| kinds.contains(&step.kind)))
            .collect::<Vec<_>>();
        assert_eq!(
            rows.iter()
                .map(|row| (row.id, row.upgrade))
                .collect::<Vec<_>>(),
            vec![
                (CardId::Catastrophe, 0),
                (CardId::Catastrophe, 1),
                (CardId::Havoc, 0),
                (CardId::Havoc, 1),
                (CardId::KnifeTrap, 0),
                (CardId::KnifeTrap, 1),
                (CardId::Uproar, 0),
                (CardId::Uproar, 1),
            ]
        );
        for row in rows {
            let candidate = identity(row.id, row.upgrade);
            assert_eq!(
                admit(&document, &state, &catalog_with(&base, candidate)),
                Ok(()),
                "{}+{} lost synchronous AutoPlay admission",
                row.id.as_str(),
                row.upgrade
            );
            play_isolated(candidate).unwrap_or_else(|refusal| {
                panic!(
                    "admitted synchronous AutoPlay row {}+{} refused in its empty-pool control: {refusal}",
                    row.id.as_str(),
                    row.upgrade
                )
            });
        }

        // Python `_auto_play_block_reason` has three additional gates. One
        // cannot inhabit an admitted solo document: SlothPower has no Rust
        // PowerId. Enthralled is admitted since #2561, but it is NOT an
        // AutoPlay gate on this build: `Enthralled::ShouldPlay` RVA 0xdea6f
        // IL_0037-IL_003b passes every nonzero `AutoPlayType`, and no
        // `CardCmd::AutoPlay` call site passes None (witness:
        // `play::enthralled_tests::autoplay_is_not_vetoed_by_enthralled`).
        // The third, Normality, is exact since #2876:
        // `play::normality_blocks_card_plays` is consulted by both `can_play`
        // and the AutoPlay veto, so a Normality root is now deliberately
        // admitted (its AutoPlay witness is
        // `play::normality_tests::autoplay_counts_below_the_cap_and_is_unplayed_at_it`).
        assert!(!PowerId::ALL.iter().any(|power| power.as_str() == "SLOTH"));
        let mut enthralled = document.clone();
        let card = &mut enthralled.piles.get_mut("hand").unwrap()[0];
        card.id = CardId::Enthralled.as_str().to_owned();
        card.upgrade = 0;
        assert!(
            !maybe_refuse(&enthralled).is_some_and(|refusal| {
                refusal.contains(MissingCapability::CardKeyword(CardId::Enthralled))
            }),
            "ENTHRALLED is an admitted card row (#2561)",
        );
        let mut normality = document.clone();
        let card = &mut normality.piles.get_mut("hand").unwrap()[0];
        card.id = CardId::Normality.as_str().to_owned();
        card.upgrade = 0;
        let normality_catalog = HotBoundary::catalog_from_canonical(&normality).unwrap();
        let normality_state = HotBoundary::from_canonical(&normality, &normality_catalog).unwrap();
        assert_eq!(
            admit(&normality, &normality_state, &normality_catalog),
            Ok(()),
            "NORMALITY joins the admitted AutoPlay block-reason surface (#2876)",
        );
        let mut local_unplayable = document.clone();
        local_unplayable.piles.get_mut("hand").unwrap()[0]
            .local_keywords
            .push("Unplayable".to_owned());
        let local_catalog = HotBoundary::catalog_from_canonical(&local_unplayable).unwrap();
        assert!(
            HotBoundary::from_canonical(&local_unplayable, &local_catalog).is_err(),
            "dynamic local Unplayable remains outside the canonical boundary",
        );
    }

    /// #2876: a deck carrying Normality is admitted, its row is the only
    /// Normality shape admission grants, and its started-play count crosses
    /// the canonical boundary exactly.
    #[test]
    fn a_normality_deck_is_admitted_and_its_started_count_round_trips() {
        let row = *crate::content_tables::card_row(CardId::Normality, 0).unwrap();
        assert!(card_keywords_are_inert(&row));
        let mut playable = row;
        playable.playable = true;
        assert!(!card_keywords_are_inert(&playable));
        let mut turn_end = row;
        turn_end.turn_end_dmg = 1;
        assert!(!card_keywords_are_inert(&turn_end));

        let (mut document, _, _) = parts();
        let mut normality = document.piles.get("hand").unwrap()[0].clone();
        normality.id = CardId::Normality.as_str().to_owned();
        normality.upgrade = 0;
        normality.uid = normality.uid.map(|_| 9_001);
        let mut in_draw = normality.clone();
        in_draw.uid = in_draw.uid.map(|_| 9_002);
        document.piles.get_mut("hand").unwrap().push(normality);
        document
            .piles
            .entry("draw".to_owned())
            .or_default()
            .push(in_draw);
        document.player.insert(
            "normality_card_plays_started_this_turn".to_owned(),
            json!(2),
        );
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        assert!(catalog.has_normality());
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(state.fanouts.normality_card_plays_started_this_turn(), 2);
        assert_eq!(admit(&document, &state, &catalog), Ok(()));
        let emitted = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        assert_eq!(
            emitted.player.get("normality_card_plays_started_this_turn"),
            Some(&json!(2))
        );

        let mut zero = document.clone();
        zero.player.insert(
            "normality_card_plays_started_this_turn".to_owned(),
            json!(0),
        );
        assert!(
            HotBoundary::from_canonical(&zero, &catalog).is_err(),
            "the default zero is elided, never spelled"
        );
        for invalid in [json!(-1), json!(2_147_483_648_i64), json!(true)] {
            let mut malformed = document.clone();
            malformed.player.insert(
                "normality_card_plays_started_this_turn".to_owned(),
                invalid.clone(),
            );
            assert!(
                HotBoundary::from_canonical(&malformed, &catalog).is_err(),
                "{invalid} must refuse at the boundary"
            );
        }
    }

