    #[test]
    fn scheduled_retain_friendship_and_invoke_admit_exactly_thirty_two_rows() {
        let (document, state, base) = parts();
        let carriers: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                row.steps.iter().any(|step| {
                    matches!(
                        step.kind,
                        StepKind::EnergyNextTurn
                            | StepKind::BlockNextBody
                            | StepKind::FriendshipExact
                            | StepKind::PhantomBlades
                            | StepKind::RetainHand
                    )
                })
            })
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        assert_eq!(carriers.len(), 32, "complete five-kind carrier census");

        let admitted: BTreeSet<_> = carriers
            .into_iter()
            .filter(|candidate| admit(&document, &state, &catalog_with(&base, *candidate)).is_ok())
            .collect();
        let expected: BTreeSet<_> = [
            CardId::ChargeBattery,
            CardId::Convergence,
            CardId::Delay,
            CardId::DodgeAndRoll,
            CardId::Equilibrium,
            CardId::Friendship,
            CardId::Glitterstream,
            CardId::Hegemony,
            CardId::Invoke,
            CardId::Outmaneuver,
            CardId::PhantomBlades,
            CardId::Prolong,
            CardId::Relax,
            CardId::Salvo,
            CardId::Scavenge,
            CardId::Sidestep,
        ]
        .into_iter()
        .flat_map(|id| [identity(id, 0), identity(id, 1)])
        .collect();
        assert_eq!(admitted, expected);
    }

    #[test]
    fn phantom_blades_requires_exact_local_retain_on_each_current_cycle_shiv() {
        let mut valid = parts().0;
        valid
            .player
            .insert("phantom_blades".to_owned(), Value::from(9));
        valid
            .player
            .insert("retain_hand".to_owned(), Value::from(1));
        append_singleton_side_end_row(&mut valid, PowerId::RetainHand);
        valid
            .player
            .insert("exact_piles".to_owned(), Value::from(true));
        let card = &mut valid.piles.get_mut("hand").unwrap()[0];
        card.id = CardId::Shiv.as_str().to_owned();
        card.upgrade = 0;
        card.local_keywords = vec!["Retain".to_owned()];
        let catalog = HotBoundary::catalog_from_canonical(&valid).unwrap();
        let state = HotBoundary::from_canonical(&valid, &catalog).unwrap();
        assert_eq!(admit(&valid, &state, &catalog), Ok(()));
        assert_eq!(
            HotBoundary::to_canonical(&state, &catalog),
            valid,
            "both power wires and the exact local Retain provenance round-trip"
        );

        let mut missing_keyword = valid.clone();
        missing_keyword.piles.get_mut("hand").unwrap()[0]
            .local_keywords
            .clear();
        assert!(
            refuse(&missing_keyword).contains(MissingCapability::ArgumentShape(
                "phantom blades current Shiv Retain provenance"
            ))
        );

        let mut missing_exact = valid.clone();
        missing_exact.player.remove("exact_piles");
        assert!(
            refuse(&missing_exact).contains(MissingCapability::ArgumentShape(
                "phantom blades current Shiv Retain provenance"
            ))
        );

        let mut exhausted_before_application = valid;
        let mut old_shiv = exhausted_before_application
            .piles
            .get_mut("hand")
            .unwrap()
            .remove(0);
        old_shiv.local_keywords.clear();
        exhausted_before_application
            .piles
            .entry("exhaust".to_owned())
            .or_default()
            .push(old_shiv);
        let catalog = HotBoundary::catalog_from_canonical(&exhausted_before_application).unwrap();
        let state = HotBoundary::from_canonical(&exhausted_before_application, &catalog).unwrap();
        assert_eq!(
            admit(&exhausted_before_application, &state, &catalog),
            Ok(())
        );
    }

    #[test]
    fn supported_fixed_star_rows_admit_from_every_physical_pile_and_catalog_only() {
        for candidate in admitted_fixed_star_rows() {
            let id = candidate.id;
            let upgrade = candidate.upgrade;
            let (document, state, base) = parts();
            let catalog = catalog_with(&base, candidate);
            assert_eq!(
                admit(&document, &state, &catalog),
                Ok(()),
                "catalog-only {}+{upgrade}",
                id.as_str()
            );

            for (pile, _) in crate::boundary::PILE_FIELDS {
                let (mut document, _, _) = parts();
                let mut card = document.piles.get_mut("hand").unwrap().remove(0);
                card.id = id.as_str().to_owned();
                card.upgrade = i64::from(upgrade);
                document
                    .piles
                    .entry(pile.as_str().to_owned())
                    .or_default()
                    .push(card);
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                let result = admit(&document, &state, &catalog);
                if pile == PileId::Play {
                    let refusal = result.expect_err("Play is a continuation snapshot");
                    assert!(refusal.contains(MissingCapability::NonEmptyPile(PileId::Play)));
                    assert!(!refusal.contains(MissingCapability::CardKeyword(id)));
                } else {
                    assert_eq!(
                        result,
                        Ok(()),
                        "{}+{upgrade} in {}",
                        id.as_str(),
                        pile.as_str()
                    );
                }
            }
        }
    }

    #[test]
    fn stars_step_admission_includes_hidden_cache_rows() {
        let rows: Vec<CardIdentity> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.steps.iter().any(|step| step.kind == StepKind::Stars))
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        assert_eq!(rows.len(), 14, "generated Stars-step row census drifted");

        let (document, state, base) = parts();
        let admitted: BTreeSet<CardIdentity> = rows
            .iter()
            .copied()
            .filter(|candidate| admit(&document, &state, &catalog_with(&base, *candidate)).is_ok())
            .collect();
        assert_eq!(admitted, admitted_star_gain_rows());

        let admitted_non_final: BTreeSet<CardIdentity> = admitted
            .iter()
            .copied()
            .filter(|candidate| {
                let row = crate::content_tables::CARD_ROWS
                    .iter()
                    .find(|row| row.id == candidate.id && row.upgrade == candidate.upgrade)
                    .unwrap();
                row.steps.iter().enumerate().any(|(index, step)| {
                    step.kind == StepKind::Stars && index + 1 < row.steps.len()
                })
            })
            .collect();
        assert_eq!(
            admitted_non_final,
            [
                identity(CardId::Glow, 0),
                identity(CardId::Glow, 1),
                identity(CardId::HiddenCache, 0),
                identity(CardId::HiddenCache, 1),
            ]
            .into_iter()
            .collect(),
            "the admitted non-final Stars I5 argument drifted"
        );
        for candidate in &admitted_non_final {
            let row = crate::content_tables::CARD_ROWS
                .iter()
                .find(|row| row.id == candidate.id && row.upgrade == candidate.upgrade)
                .unwrap();
            assert_eq!(
                row.steps.first().map(|step| step.kind),
                Some(StepKind::Stars),
                "non-final Stars must remain the first command of a live play"
            );
        }
        for candidate in admitted {
            play_isolated(candidate).unwrap_or_else(|refusal| {
                panic!(
                    "admitted Stars-step row {}+{} refused at play: {refusal}",
                    candidate.id.as_str(),
                    candidate.upgrade
                )
            });
        }
    }

    #[test]
    fn star_x_admits_only_the_two_canonical_stardust_rows() {
        let (document, state, base) = parts();
        for upgrade in [0, 1] {
            let candidate = identity(CardId::Stardust, upgrade);
            let catalog = catalog_with(&base, candidate);
            assert_eq!(admit(&document, &state, &catalog), Ok(()));
            play_isolated(candidate).unwrap();

            let mut mutated = *crate::content_tables::card_row(CardId::Stardust, upgrade).unwrap();
            assert!(star_x_program_is_supported(&mutated));
            mutated.star_x = false;
            assert!(!star_x_program_is_supported(&mutated));
            assert!(!card_keywords_are_inert(&mutated));

            mutated = *crate::content_tables::card_row(CardId::Stardust, upgrade).unwrap();
            mutated.star_cost = 0;
            assert!(!star_x_program_is_supported(&mutated));
            assert!(!card_keywords_are_inert(&mutated));
        }
    }

    #[test]
    fn card_virtual_result_rows_are_exact_and_mechanically_admitted() {
        for id in [CardId::ShiningStrike, CardId::ParticleWall] {
            for upgrade in [0, 1] {
                let (document, state, base) = parts();
                let catalog = catalog_with(&base, identity(id, upgrade));
                assert_eq!(admit(&document, &state, &catalog), Ok(()));
                play_isolated(identity(id, upgrade)).unwrap_or_else(|refusal| {
                    panic!("{}+{upgrade} refused at play: {refusal}", id.as_str())
                });

                let mut mutated = *crate::content_tables::card_row(id, upgrade).unwrap();
                mutated.cost += 1;
                assert!(!card_virtual_result_program_is_supported(&mutated));
                assert!(!card_keywords_are_inert(&mutated));
            }
        }
    }

