    #[test]
    fn make_it_so_and_right_hand_hand_exact_late_listener_programs_are_pinned() {
        let (document, state, base) = parts();
        let rows: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.id == CardId::MakeItSo)
            .collect();
        assert_eq!(rows.len(), 2);
        for row in rows {
            assert!(make_it_so_late_program_is_supported(row));
            assert_eq!(
                admit(
                    &document,
                    &state,
                    &catalog_with(&base, identity(row.id, row.upgrade)),
                ),
                Ok(()),
            );

            let mut mutated = *row;
            mutated.cost += 1;
            assert!(!make_it_so_late_program_is_supported(&mutated));
            assert!(!card_keywords_are_inert(&mutated));
        }

        for id in [CardId::Melancholy, CardId::Midnight] {
            assert!(
                !crate::content_tables::CARD_ROWS
                    .iter()
                    .any(|row| row.id == id && make_it_so_late_program_is_supported(row))
            );
        }

        for upgrade in 0..=1 {
            let row = crate::content_tables::card_row(CardId::RightHandHand, upgrade).unwrap();
            assert!(right_hand_hand_late_program_is_supported(row));
            assert_eq!(
                admit(
                    &document,
                    &state,
                    &catalog_with(&base, identity(CardId::RightHandHand, upgrade)),
                ),
                Ok(()),
            );
            let mut mutated = *row;
            mutated.cost += 1;
            assert!(!right_hand_hand_late_program_is_supported(&mutated));
            assert!(!card_keywords_are_inert(&mutated));
        }
    }

    #[test]
    fn make_it_so_reachability_requires_the_native_finished_history_chain() {
        for history in [-1, -3] {
            let (document, mut negative, base) = parts();
            negative.history.skill_plays_finished_this_turn = history;
            let catalog = catalog_with(&base, identity(CardId::MakeItSo, 0));
            let refusal = admit(&document, &negative, &catalog).unwrap_err();
            assert!(
                refusal.contains(MissingCapability::ArgumentShape(
                    "Make It So finished-Skill history"
                )),
                "forged history {history} bypassed the reachable listener guard"
            );
        }

        let (document, mut enchanted_negative, base) = parts();
        enchanted_negative.history.skill_plays_finished_this_turn = -3;
        let enchanted = CardIdentity {
            id: CardId::MakeItSo,
            upgrade: 0,
            enchantment: Some(crate::catalog::CardEnchantment {
                id: EnchantmentId::Momentum,
                amount: 2,
            }),
        };
        let enchanted_only = catalog_with(&base, enchanted);
        assert!(enchanted_only.atom(&enchanted).is_some());
        assert!(
            enchanted_only
                .atom(&identity(CardId::MakeItSo, 0))
                .is_none(),
            "the regression must not gain an unenchanted Make It So atom"
        );
        let refusal = admit(&document, &enchanted_negative, &enchanted_only).unwrap_err();
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Make It So finished-Skill history"
        )));

        for (skills, owner_cards, combat_cards) in [(2, 0, 0), (2, 2, 0)] {
            let (document, mut forged, base) = parts();
            forged.history.skill_plays_finished_this_turn = skills;
            forged.history.owner_card_plays_finished_this_turn = owner_cards;
            forged.history.card_plays_finished_combat = combat_cards;
            let refusal = admit(
                &document,
                &forged,
                &catalog_with(&base, identity(CardId::MakeItSo, 0)),
            )
            .unwrap_err();
            assert!(
                refusal.contains(MissingCapability::ArgumentShape(
                    "Make It So finished-Skill history"
                )),
                "forged chain {skills}/{owner_cards}/{combat_cards} admitted"
            );
        }

        let (document, zero, base) = parts();
        assert_eq!(zero.history.skill_plays_finished_this_turn, 0);
        assert_eq!(
            admit(
                &document,
                &zero,
                &catalog_with(&base, identity(CardId::MakeItSo, 0)),
            ),
            Ok(()),
            "native zero is a safe non-triggering Late counter"
        );

        let (document, mut positive, base) = parts();
        positive.history.skill_plays_finished_this_turn = 2;
        positive.history.owner_card_plays_finished_this_turn = 2;
        positive.history.card_plays_finished_combat = 2;
        assert_eq!(
            admit(
                &document,
                &positive,
                &catalog_with(&base, identity(CardId::MakeItSo, 0)),
            ),
            Ok(()),
            "native 2 <= 2 <= 2 history remains admitted"
        );
    }

    #[test]
    fn melancholy_physical_markers_are_derived_and_authenticated_in_every_pile() {
        for upgrade in [0, 1] {
            for (pile, _) in crate::boundary::PILE_FIELDS {
                let (mut document, _, _) = parts();
                let mut card = document.piles.get_mut("hand").unwrap().remove(0);
                card.id = "MELANCHOLY".to_owned();
                card.upgrade = upgrade;
                card.physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
                document
                    .piles
                    .entry(pile.as_str().to_owned())
                    .or_default()
                    .push(card);
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                if pile == PileId::Play {
                    assert!(
                        admit(&document, &state, &catalog)
                            .unwrap_err()
                            .contains(MissingCapability::NonEmptyPile(PileId::Play))
                    );
                } else {
                    admit(&document, &state, &catalog).unwrap();
                }
                assert!(super::super::cards::melancholy_identity_markers_are_exact(
                    &state, &catalog
                ));
                let mut forged = state.clone();
                forged
                    .piles
                    .get_mut(pile)
                    .make_mut()
                    .iter_mut()
                    .find(|card| catalog.spec(card.atom).unwrap().identity.id == CardId::Melancholy)
                    .unwrap()
                    .flags &= !crate::hot::CARD_FLAG_MELANCHOLY;
                assert!(admit(&document, &forged, &catalog).unwrap_err().contains(
                    MissingCapability::ArgumentShape("Melancholy physical identity marker")
                ));
                assert!(HotBoundary::try_to_canonical(&forged, &catalog).is_err());
            }
            let (document, state, base) = parts();
            let catalog = catalog_with(&base, identity(CardId::Melancholy, upgrade as u8));
            admit(&document, &state, &catalog).unwrap();
            let mut forged = state.clone();
            forged.piles.get_mut(PileId::Hand).make_mut()[0].flags |=
                crate::hot::CARD_FLAG_MELANCHOLY;
            assert!(admit(&document, &forged, &catalog).unwrap_err().contains(
                MissingCapability::ArgumentShape("Melancholy physical identity marker")
            ));
            assert!(HotBoundary::try_to_canonical(&forged, &catalog).is_err());
            let row = crate::content_tables::card_row(CardId::Melancholy, upgrade as u8).unwrap();
            assert!(melancholy_program_is_supported(row));
            let mut changed = *row;
            changed.cost -= 1;
            assert!(!melancholy_program_is_supported(&changed));
            assert!(!card_keywords_are_inert(&changed));
        }
    }

