    #[test]
    fn kingly_kick_and_pinpoint_exact_rows_close_catalog_and_instance_admission() {
        let (base_document, base_state, base_catalog) = parts();
        for id in [CardId::KinglyKick, CardId::Pinpoint] {
            assert!(!UNMODELED_PHYSICAL_CARD_LISTENER_DENY_SET.contains(&id));
            for upgrade in [0, 1] {
                let row = crate::content_tables::card_row(id, upgrade).unwrap();
                assert!(physical_cost_listener_program_is_supported(row));
                assert_eq!(
                    admit(
                        &base_document,
                        &base_state,
                        &catalog_with(&base_catalog, identity(id, upgrade)),
                    ),
                    Ok(()),
                    "catalog-only {}+{upgrade} closure",
                    id.as_str()
                );

                let (mut document, _, _) = parts();
                replace_first_hand_card(&mut document, id, i64::from(upgrade));
                if id == CardId::Pinpoint {
                    document
                        .player
                        .insert("skill_plays_finished_this_turn".to_owned(), json!(3));
                }
                let card = &mut document.piles.get_mut("hand").unwrap()[0];
                card.physical_state = Some(if id == CardId::KinglyKick {
                    json!(["PHYSICAL_CARD_STATE", [[2, -1, 0, false]], 0, false, []])
                } else {
                    json!(["PHYSICAL_CARD_STATE", [[2, -3, 2, false]], 0, false, []])
                });
                assert_admits(&document);
                play_isolated(identity(id, upgrade)).unwrap_or_else(|refusal| {
                    panic!("{}+{upgrade} refused at play: {refusal}", id.as_str())
                });

                let mut mutated = *row;
                mutated.cost += 1;
                assert!(!physical_cost_listener_program_is_supported(&mutated));
                assert!(!card_keywords_are_inert(&mutated));
            }
        }

        let (mut undrawn_kick, _, _) = parts();
        replace_first_hand_card(&mut undrawn_kick, CardId::KinglyKick, 0);
        undrawn_kick.piles.get_mut("hand").unwrap()[0].physical_state = None;
        assert_admits(&undrawn_kick);

        let mut forged_kick = undrawn_kick;
        forged_kick.piles.get_mut("hand").unwrap()[0].physical_state = Some(json!([
            "PHYSICAL_CARD_STATE",
            [[2, -2, 0, false]],
            0,
            false,
            []
        ]));
        assert!(
            refuse(&forged_kick)
                .missing()
                .any(|item| matches!(item, MissingCapability::CardInstanceState(_)))
        );

        let (mut forged_pinpoint, _, _) = parts();
        replace_first_hand_card(&mut forged_pinpoint, CardId::Pinpoint, 0);
        forged_pinpoint.piles.get_mut("hand").unwrap()[0].physical_state = Some(json!([
            "PHYSICAL_CARD_STATE",
            [[2, -1, 0, false]],
            0,
            false,
            []
        ]));
        assert!(
            refuse(&forged_pinpoint)
                .missing()
                .any(|item| matches!(item, MissingCapability::CardInstanceState(_)))
        );

        for (history, amount, admitted) in [
            (0, 0, true),
            (1, -1, true),
            (3, -3, true),
            (3, -2, false),
            (i16::MAX, -i64::from(i16::MAX), true),
            (i16::MAX, -i64::from(i16::MAX) - 1, false),
            (i16::MAX, i64::MIN, false),
        ] {
            let (mut document, _, _) = parts();
            replace_first_hand_card(&mut document, CardId::Pinpoint, 0);
            if history != 0 {
                document
                    .player
                    .insert("skill_plays_finished_this_turn".to_owned(), json!(history));
            }
            document.piles.get_mut("hand").unwrap()[0].physical_state = Some(json!([
                "PHYSICAL_CARD_STATE",
                if amount == 0 {
                    json!([])
                } else {
                    json!([[2, amount, 2, false]])
                },
                0,
                false,
                []
            ]));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(
                admit(&document, &state, &catalog).is_ok(),
                admitted,
                "Pinpoint history={history} amount={amount}"
            );
        }

        for (rows, admitted) in [
            (vec![-4], true),
            (vec![-2, -1, -1], true),
            (vec![-1, -1, -1, -1], true),
            (vec![-2, -2], false),
            (vec![-1, -2, -1], false),
        ] {
            let (mut document, _, _) = parts();
            replace_first_hand_card(&mut document, CardId::Pinpoint, 0);
            document
                .player
                .insert("skill_plays_finished_this_turn".to_owned(), json!(4));
            let modifiers = rows
                .iter()
                .map(|amount| json!([2, amount, 2, false]))
                .collect::<Vec<_>>();
            document.piles.get_mut("hand").unwrap()[0].physical_state =
                Some(json!(["PHYSICAL_CARD_STATE", modifiers, 0, false, []]));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(
                admit(&document, &state, &catalog).is_ok(),
                admitted,
                "Pinpoint history=4 rows={rows:?}"
            );
        }
    }

