    fn physical_card_document(id: CardId, growth: i64, modifiers: Value) -> CanonicalStateV2 {
        let (mut document, _, _) = parts();
        let card = &mut document.piles.get_mut("hand").unwrap()[0];
        card.id = id.as_str().to_owned();
        card.upgrade = 0;
        card.physical_state = Some(json!(["PHYSICAL_CARD_STATE", modifiers, growth, false, []]));
        document
    }

    #[test]
    fn growth_admission_is_exactly_the_python_demand_set() {
        // Every ordinary growth owner accepts its represented payload even
        // when another, independent step or keyword still refuses the whole
        // card. Wither is intentionally excluded: its fake growth is exact
        // only under the authenticated Aeonglass lifecycle below.
        for (id, growth) in [
            (CardId::Claw, 7),
            (CardId::KinglyPunch, 4),
            (CardId::Maul, 7),
            (CardId::Rampage, 7),
            (CardId::TheBall, 7),
            (CardId::TheScythe, 7),
            (CardId::Thrash, 7),
        ] {
            let document = physical_card_document(id, growth, json!([]));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            if let Err(refusal) = admit(&document, &state, &catalog) {
                assert!(
                    !refusal
                        .missing()
                        .any(|item| matches!(item, MissingCapability::CardInstanceState(_))),
                    "{id:?} gained a spurious instance-state refusal: {refusal}"
                );
            }
        }

        // These rows have no independent refusal and must admit completely.
        for (id, growth) in [
            (CardId::Claw, 7),
            (CardId::KinglyPunch, 4),
            (CardId::Maul, 7),
            (CardId::Rampage, 7),
            (CardId::TheBall, 7),
            (CardId::Thrash, 7),
        ] {
            let document = physical_card_document(id, growth, json!([]));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(admit(&document, &state, &catalog), Ok(()), "{id:?}");
        }

        let orphan_wither = physical_card_document(CardId::Wither, 6, json!([]));
        let catalog = HotBoundary::catalog_from_canonical(&orphan_wither).unwrap();
        assert!(
            HotBoundary::from_canonical(&orphan_wither, &catalog).is_err(),
            "orphan Wither growth must not bypass the Aeonglass owner/countdown proof"
        );

        for (id, growth) in [
            // Identity-mutate the exact The Scythe row so the owner census is
            // sensitive to its presence rather than accepting any `+7` row.
            (CardId::StrikeIronclad, 7),
            (CardId::MomentumStrike, 1),
        ] {
            let refusal = refuse(&physical_card_document(id, growth, json!([])));
            assert!(
                refusal
                    .missing()
                    .any(|item| matches!(item, MissingCapability::CardInstanceState(_))),
                "{id:?}/{growth} bypassed the growth owner rule: {refusal}"
            );
        }
        let malformed_wither = physical_card_document(CardId::Wither, 1, json!([]));
        let catalog = HotBoundary::catalog_from_canonical(&malformed_wither).unwrap();
        assert!(
            HotBoundary::from_canonical(&malformed_wither, &catalog).is_err(),
            "non-three-aligned Wither growth must fail at the lifecycle boundary"
        );
    }

