    #[test]
    fn largesse_admission_closes_every_live_target_pool_and_self_only_entry() {
        let mut complete = generator_document(CardId::Largesse, RewardPool::Regent, true, 17);
        add_minimal_party(&mut complete);
        complete.player.get_mut("multiplayer_allies").unwrap()[0]["fields"]["colorless_unlock_epochs"] =
            json!([
                "COLORLESS1_EPOCH",
                "COLORLESS2_EPOCH",
                "COLORLESS3_EPOCH",
                "COLORLESS4_EPOCH",
                "COLORLESS5_EPOCH",
            ]);
        let catalog = HotBoundary::catalog_from_canonical(&complete).unwrap();
        let state = HotBoundary::from_canonical(&complete, &catalog).unwrap();
        let complete_refusal = admit(&complete, &state, &catalog).unwrap_err();
        assert!(!complete_refusal.contains(MissingCapability::ArgumentShape(
            "Largesse selected-player generation provenance"
        )));
        assert!(!complete_refusal.contains(MissingCapability::ArgumentShape(
            "Largesse generation closure"
        )));
        assert!(!complete_refusal.contains(MissingCapability::MultiplayerCard(CardId::Largesse)));

        let mut missing_local = complete.clone();
        missing_local.player.remove("splash_unlock_epochs");
        assert!(
            refuse(&missing_local).contains(MissingCapability::ArgumentShape(
                "Largesse selected-player generation provenance"
            ))
        );

        let mut dead_remote = complete.clone();
        dead_remote.player.get_mut("multiplayer_allies").unwrap()[0]["fields"]["alive"] =
            json!(false);
        assert!(
            refuse(&dead_remote).contains(MissingCapability::MultiplayerCard(CardId::Largesse))
        );

        let mut missing_remote = complete;
        missing_remote.player.get_mut("multiplayer_allies").unwrap()[0]["fields"]
            .as_object_mut()
            .unwrap()
            .remove("colorless_unlock_epochs");
        assert!(
            refuse(&missing_remote).contains(MissingCapability::ArgumentShape(
                "Largesse selected-player generation provenance"
            ))
        );

        let mut self_only = generator_document(CardId::Largesse, RewardPool::Regent, true, 17);
        let complete_solo_refusal = refuse(&self_only);
        assert!(
            complete_solo_refusal.contains(MissingCapability::MultiplayerCard(CardId::Largesse))
        );
        self_only.player.remove("splash_unlock_epochs");
        let refusal = refuse(&self_only);
        assert!(refusal.contains(MissingCapability::MultiplayerCard(CardId::Largesse)));
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Largesse selected-player generation provenance"
        )));
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Largesse generation closure"
        )));

        let mut persisted_play = self_only;
        let source = persisted_play.piles.get_mut("hand").unwrap().remove(0);
        persisted_play
            .piles
            .entry("play".to_owned())
            .or_default()
            .push(source);
        let refusal = refuse(&persisted_play);
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Largesse selected-player generation provenance"
        )));
        assert!(refusal.contains(MissingCapability::ArgumentShape(
            "Largesse generation closure"
        )));
    }

