    /// #2510 retires the `Decimillipede revive_stage lifecycle` gate PR #2508
    /// installed: the segment now has a writer, two readers and a shared-stream
    /// roll, so the entry contract is the stage/HP pairing rather than the kind.
    #[test]
    fn segment_revive_stage_admits_only_its_three_reachable_stage_hp_pairings() {
        let segment = MonsterKind::DecimillipedeSegment.as_str();
        for (stage, hp, admits) in [
            (0, 40, true),
            (super::super::monsters::SEGMENT_REVIVE_DEAD, 0, true),
            (super::super::monsters::SEGMENT_REVIVE_REATTACH, 0, true),
            (super::super::monsters::SEGMENT_REVIVE_RAND, 25, true),
            // A corpse cannot be waiting on the RAND: `DoReattach` heals first.
            (super::super::monsters::SEGMENT_REVIVE_RAND, 0, false),
            // Nor can a live segment be parked in DEAD or REATTACH.
            (super::super::monsters::SEGMENT_REVIVE_DEAD, 40, false),
            (super::super::monsters::SEGMENT_REVIVE_REATTACH, 40, false),
            // 4.. is not a stage of the three-step cycle at all.
            (4, 40, false),
        ] {
            let (mut document, _, _) = parts();
            document.monsters[0].insert("kind".to_owned(), Value::from(segment));
            document.monsters[0].insert("hp".to_owned(), Value::from(hp));
            document.monsters[0].insert("max_hp".to_owned(), Value::from(48));
            if stage != 0 {
                document.monsters[0].insert("revive_stage".to_owned(), Value::from(stage));
            }
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            let verdict = admit(&document, &state, &catalog);
            if admits {
                assert_eq!(verdict, Ok(()), "stage {stage} at hp {hp} must admit");
                continue;
            }
            let refusal = verdict.unwrap_err();
            assert!(
                !refusal.contains(MissingCapability::ArgumentShape(
                    "Decimillipede revive_stage lifecycle"
                )),
                "the retired kind gate came back for stage {stage}"
            );
            assert!(
                refusal.contains(MissingCapability::ArgumentShape(
                    "illusion revive lifecycle"
                )),
                "stage {stage} at hp {hp} must refuse by name"
            );
        }
    }

