    /// #3357: a lone Battle Friend carrying its live timer admits; a timer
    /// outside `1..=3` or on another owner fails its power gate, and a
    /// Battle Friend without a timer or beside another creature keeps the
    /// named lifecycle refusal.
    #[test]
    fn battleworn_dummy_admits_only_its_lone_timed_roster() {
        const LIFECYCLE: MissingCapability =
            MissingCapability::ArgumentShape("Battleworn Dummy timer lifecycle");
        const TIMER: &str = "battleworn_time_limit";
        for kind in ["BATTLE_FRIEND_V1", "BATTLE_FRIEND_V2", "BATTLE_FRIEND_V3"] {
            let (mut document, _, _) = parts();
            document.monsters.truncate(1);
            document.monsters[0].insert("kind".to_owned(), Value::from(kind));
            document.monsters[0].insert(TIMER.to_owned(), Value::from(3));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(admit(&document, &state, &catalog), Ok(()), "{kind}");

            document.monsters[0].insert(TIMER.to_owned(), Value::from(4));
            let over = refuse(&document);
            assert!(over.contains(MissingCapability::PowerState(PowerId::BattlewornTimeLimit)));
            assert!(over.contains(LIFECYCLE));

            document.monsters[0].remove(TIMER);
            assert_eq!(refuse(&document).missing().collect::<Vec<_>>(), [LIFECYCLE]);
        }

        let (mut pair, _, _) = parts();
        assert!(pair.monsters.len() > 1);
        pair.monsters[0].insert("kind".to_owned(), Value::from("BATTLE_FRIEND_V2"));
        pair.monsters[0].insert(TIMER.to_owned(), Value::from(3));
        assert_eq!(refuse(&pair).missing().collect::<Vec<_>>(), [LIFECYCLE]);

        let (mut foreign, _, _) = parts();
        foreign.monsters.truncate(1);
        foreign.monsters[0].insert(TIMER.to_owned(), Value::from(3));
        let refusal = refuse(&foreign);
        assert!(refusal.contains(MissingCapability::PowerState(PowerId::BattlewornTimeLimit)));
        assert!(refusal.contains(LIFECYCLE));
    }

