    /// #3366: the admitted Plow amount and the PLOW/STUN HP split read the
    /// fight's tier (`get_PlowAmount` `0xb0c33`, `GetValueIfAscension(9, 160,
    /// 150)`), independent of the HP tier's gate at 8. A8 is the tier where
    /// the two gates disagree: 262 HP with a 150 threshold.
    #[test]
    fn ceremonial_beast_plow_threshold_admits_at_the_fights_tier() {
        for (ascension, max_hp, threshold, other) in
            [(6, 252, 150, 160), (8, 262, 150, 160), (9, 262, 160, 150)]
        {
            let mut plowing = ceremonial_beast_document();
            plowing
                .player
                .insert("ascension".to_owned(), Value::from(ascension));
            plowing.monsters[0].insert("max_hp".to_owned(), Value::from(max_hp));
            plowing.monsters[0].insert("hp".to_owned(), Value::from(threshold + 1));
            plowing.monsters[0].insert("loop_pos".to_owned(), Value::from(1));
            let mut stunned = plowing.clone();
            plowing.monsters[0].insert(
                PowerId::PlowThreshold.as_str().to_owned(),
                Value::from(threshold),
            );
            assert_admits(&plowing);

            let mut wrong_tier = plowing.clone();
            wrong_tier.monsters[0].insert(
                PowerId::PlowThreshold.as_str().to_owned(),
                Value::from(other),
            );
            assert!(
                refuse(&wrong_tier).contains(MissingCapability::PowerState(PowerId::PlowThreshold)),
                "A{ascension} Plow {other}"
            );

            stunned.monsters[0].insert("override".to_owned(), Value::from("STUN_MOVE"));
            stunned.monsters[0]
                .insert("forced_follow_up".to_owned(), Value::from("BEAST_CRY_MOVE"));
            stunned.monsters[0].insert("hp".to_owned(), Value::from(threshold));
            assert_admits(&stunned);
            // A stun above the tier's threshold is not a Plow crossing.
            stunned.monsters[0].insert("hp".to_owned(), Value::from(threshold + 1));
            assert!(refuse(&stunned).contains(MissingCapability::ArgumentShape(
                "Ceremonial Beast Plow/Ringing lifecycle"
            )));
        }
    }

