    #[test]
    fn complete_queen_roster_is_admitted_after_the_puppet_strings_body() {
        for kinds in [&[MonsterKind::TorchHeadAmalgam, MonsterKind::Queen][..]] {
            let (mut document, _, _) = parts();
            let template = document.monsters[0].clone();
            document.monsters.clear();
            for (index, kind) in kinds.iter().enumerate() {
                let mut monster = template.clone();
                monster.insert("kind".to_owned(), Value::from(kind.as_str()));
                monster.insert(
                    "max_hp".to_owned(),
                    Value::from(if *kind == MonsterKind::TorchHeadAmalgam {
                        super::super::monsters::TORCH_HEAD_AMALGAM_HP
                    } else {
                        super::super::monsters::QUEEN_HP
                    }),
                );
                monster.insert(
                    "hp".to_owned(),
                    Value::from(if *kind == MonsterKind::TorchHeadAmalgam {
                        super::super::monsters::TORCH_HEAD_AMALGAM_HP
                    } else {
                        super::super::monsters::QUEEN_HP
                    }),
                );
                if *kind == MonsterKind::TorchHeadAmalgam {
                    monster.insert("secondary".to_owned(), Value::from(true));
                } else {
                    monster.remove("loop_pos");
                }
                if index > 0 {
                    monster.insert("slot".to_owned(), Value::from(index as i64));
                    monster.insert("uid".to_owned(), Value::from(index as i64));
                }
                document.monsters.push(monster);
            }
            assert_admits(&document);
            // #3404: the root's pile mode is no longer a Queen precondition;
            // Puppet Strings promotes it.
            let mut exact = document.clone();
            exact
                .player
                .insert("exact_piles".to_owned(), Value::from(true));
            assert_admits(&exact);
        }
    }

