    #[test]
    fn burrowed_and_dizzy_are_owner_and_lifecycle_validated() {
        let (mut document, _, _) = parts();
        let monster = &mut document.monsters[0];
        monster.insert("kind".to_owned(), Value::from("TUNNELER"));
        monster.insert("burrowed".to_owned(), Value::from(true));

        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        document.monsters[0].insert("override".to_owned(), Value::from("DIZZY"));
        assert!(refuse(&document).contains(MissingCapability::ArgumentShape("monster override")));

        document.monsters[0].remove("burrowed");
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let (mut bowlbug, _, _) = parts();
        let monster = &mut bowlbug.monsters[0];
        monster.insert(
            "kind".to_owned(),
            Value::from(MonsterKind::BowlbugRock.as_str()),
        );
        monster.remove("loop_pos");
        monster.insert("override".to_owned(), Value::from("DIZZY"));
        let catalog = HotBoundary::catalog_from_canonical(&bowlbug).unwrap();
        let state = HotBoundary::from_canonical(&bowlbug, &catalog).unwrap();
        assert_eq!(admit(&bowlbug, &state, &catalog), Ok(()));

        let mut wrong_loop = bowlbug.clone();
        wrong_loop.monsters[0].insert("loop_pos".to_owned(), Value::from(1));
        assert!(refuse(&wrong_loop).contains(MissingCapability::ArgumentShape("monster override")));
        let mut dead = bowlbug;
        dead.monsters[0].insert("hp".to_owned(), Value::from(0));
        assert!(refuse(&dead).contains(MissingCapability::ArgumentShape("monster override")));
    }

    /// #2647 D2 / §5.4 — the document-level half of the collapsed latch.
    ///
    /// `ImbalancedPower` `0x33cd60` sets `BowlbugRock::_isOffBalance`, a durable
    /// latch read only at the end of `HeadbuttMove` `0x354048` IL_00bf. Rust
    /// collapses it into the immediate `Dizzy` state, which is exact only while
    /// Bowlbug cannot deal a fully blocked result outside that move. Its loop is
    /// the single HEADBUTT row and `buff_thorns` is self-only, so a Thorns
    /// retaliation is the one other dealer path a *document* could claim.
    #[test]
    fn bowlbug_rock_may_not_carry_thorns() {
        let (mut document, _, _) = parts();
        let monster = &mut document.monsters[0];
        monster.insert(
            "kind".to_owned(),
            Value::from(MonsterKind::BowlbugRock.as_str()),
        );
        monster.remove("loop_pos");
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let mut thorny = document.clone();
        thorny.monsters[0].insert("thorns".to_owned(), Value::from(1));
        assert!(refuse(&thorny).contains(MissingCapability::ArgumentShape(
            "Imbalanced owner carrying Thorns"
        )));

        // A non-carrier keeps Thorns, so this is the carrier predicate and not
        // a new blanket refusal of monster Thorns.
        let (mut toadpole, _, _) = parts();
        toadpole.monsters[0].insert("thorns".to_owned(), Value::from(1));
        let catalog = HotBoundary::catalog_from_canonical(&toadpole).unwrap();
        let state = HotBoundary::from_canonical(&toadpole, &catalog).unwrap();
        assert_eq!(admit(&toadpole, &state, &catalog), Ok(()));
    }

    /// #2647 slice A — the generic `STUNNED` + parked-telegraph state is
    /// admitted for an eligible owner, and only for one.
    #[test]
    fn the_generic_stun_state_is_admitted_only_for_an_eligible_owner() {
        let (mut document, _, _) = parts();
        let monster = &mut document.monsters[0];
        monster.insert(
            "kind".to_owned(),
            Value::from(MonsterKind::BowlbugEgg.as_str()),
        );
        monster.remove("loop_pos");
        monster.insert("override".to_owned(), Value::from("STUNNED"));
        monster.insert("forced_follow_up".to_owned(), Value::from("BITE"));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        // A follow-up that is not the parked row refuses (#2647 §6 witness 23).
        let mut mismatched = document.clone();
        mismatched.monsters[0].insert("forced_follow_up".to_owned(), Value::from("BUFF"));
        assert!(refuse(&mismatched).contains(MissingCapability::ArgumentShape("monster override")));

        // A corpse cannot carry it: `StunInternal` `0x11d7cc` IL_0028.
        let mut dead = document.clone();
        dead.monsters[0].insert("hp".to_owned(), Value::from(0));
        assert!(refuse(&dead).contains(MissingCapability::ArgumentShape("monster override")));

        // Terror Eel's follow-up-free STUNNED keeps its sole reading, and the
        // generic state may not give it a second one (#2647 §5.7).
        let (mut eel, _, _) = parts();
        let monster = &mut eel.monsters[0];
        monster.insert(
            "kind".to_owned(),
            Value::from(MonsterKind::TerrorEel.as_str()),
        );
        monster.remove("loop_pos");
        monster.insert("override".to_owned(), Value::from("STUNNED"));
        monster.insert("forced_follow_up".to_owned(), Value::from("BITE"));
        assert!(refuse(&eel).contains(MissingCapability::ArgumentShape("monster override")));
    }

