    #[test]
    fn a_mismatched_rampart_owner_refuses_by_power_state() {
        let (mut document, _, _) = parts();
        // Rampart is modeled only for the exact Living Shield / Turret
        // Operator A8+ pair. A scalar on this unrelated fixture cannot gain
        // a reader merely because the vocabulary is now implemented.
        document.monsters[0].insert("rampart".to_owned(), Value::from(3));
        assert!(refuse(&document).contains(MissingCapability::PowerState(PowerId::Rampart)));
        // The player's registry is its own (#1364): Strength is read by
        // `player_attack`'s additive fold and admits, while a power nothing
        // reads off the player still refuses by name — on the *player* side,
        // even though monsters may carry it.
        let (mut document, _, _) = parts();
        document.player.insert("poison".to_owned(), Value::from(2));
        assert!(refuse(&document).contains(MissingCapability::Power(PowerId::Poison)));
    }

