    #[test]
    fn shadow_step_pair_and_power_lifecycle_are_one_exact_admission_unit() {
        assert!(IMPLEMENTED_PLAYER_POWERS.contains(&PowerId::ShadowStep));
        assert!(IMPLEMENTED_PLAYER_POWERS.contains(&PowerId::DoubleDamage));
        assert!(
            capability_manifest()
                .steps
                .contains(&StepKind::ShadowStepDiscardExact)
        );
        assert!(
            capability_manifest()
                .steps
                .contains(&StepKind::ShadowStepPowerExact)
        );

        for upgrade in [0, 1] {
            let (mut document, _, _) = parts();
            replace_first_hand_card(&mut document, CardId::ShadowStep, upgrade);
            assert_admits(&document);
        }
        for power in [PowerId::ShadowStep, PowerId::DoubleDamage] {
            let (mut document, _, _) = parts();
            document
                .player
                .insert(power.as_str().to_owned(), Value::from(2));
            if power == PowerId::DoubleDamage {
                append_singleton_side_end_row(&mut document, power);
            }
            assert_admits(&document);

            document
                .player
                .insert(power.as_str().to_owned(), Value::from(-1));
            assert!(refuse(&document).contains(MissingCapability::PowerState(power)));
        }

        let (mut selecting_sly, _, _) = parts();
        replace_first_hand_card(&mut selecting_sly, CardId::ShadowStep, 0);
        let mut master = selecting_sly.piles["hand"][0].clone();
        master.id = CardId::MasterPlanner.as_str().to_owned();
        master.upgrade = 0;
        master.uid = Some(400);
        master.physical_state = None;
        let mut selecting = master.clone();
        selecting.id = CardId::SecretTechnique.as_str().to_owned();
        selecting.upgrade = 1;
        selecting.uid = Some(401);
        selecting_sly
            .piles
            .get_mut("hand")
            .unwrap()
            .extend([master, selecting]);
        selecting_sly
            .player
            .insert("next_card_uid".to_owned(), Value::from(402));
        assert_admits(&selecting_sly);

        let mut power_only = selecting_sly.clone();
        power_only.piles.get_mut("hand").unwrap().remove(0);
        for power in [PowerId::ShadowStep, PowerId::DoubleDamage] {
            let mut document = power_only.clone();
            document
                .player
                .insert(power.as_str().to_owned(), Value::from(1));
            if power == PowerId::DoubleDamage {
                append_singleton_side_end_row(&mut document, power);
            }
            assert_admits(&document);
        }
    }

    #[test]
    fn static_ethereal_rows_and_live_lethality_amount_are_one_exact_admission_unit() {
        assert!(IMPLEMENTED_PLAYER_POWERS.contains(&PowerId::Lethality));
        assert!(capability_manifest().steps.contains(&StepKind::Lethality));

        let mut complete = CatalogBuilder::new();
        for row in crate::catalog::variant_free_card_rows() {
            complete
                .intern(identity(row.id, row.upgrade))
                .expect("the generated row compiles");
        }
        let complete = complete.build();
        let playable_ethereal: Vec<_> = complete
            .specs()
            .filter(|spec| spec.playable && spec.ethereal && card_row_is_admitted(&complete, spec))
            .map(|spec| spec.identity)
            .collect();
        assert_eq!(
            playable_ethereal,
            [
                identity(CardId::Defile, 0),
                identity(CardId::Defile, 1),
                // Defy, Demesne and Enfeebling Touch are the static-Ethereal
                // Skill/Power rows admitted by
                // `static_ethereal_body_program_is_supported`: ordinary bodies
                // on the already-implemented step vocabulary, riding the same
                // shared turn-end exhaust as the Attack rows beside them.
                identity(CardId::Defy, 0),
                identity(CardId::Defy, 1),
                identity(CardId::Demesne, 0),
                identity(CardId::Demesne, 1),
                identity(CardId::DyingStar, 0),
                identity(CardId::DyingStar, 1),
                identity(CardId::EchoForm, 0),
                identity(CardId::EnfeeblingTouch, 0),
                identity(CardId::EnfeeblingTouch, 1),
                identity(CardId::Fear, 0),
                identity(CardId::Fear, 1),
                identity(CardId::Lethality, 0),
                identity(CardId::Lethality, 1),
                identity(CardId::Parse, 0),
                identity(CardId::Parse, 1),
                identity(CardId::Seance, 0),
                identity(CardId::Seance, 1),
                identity(CardId::SweepingGaze, 0),
                identity(CardId::SweepingGaze, 1),
                identity(CardId::VoidForm, 0)
            ],
            "the terminal-sensitive Ethereal history path must widen deliberately"
        );

        for upgrade in [0, 1] {
            let (mut document, _, _) = parts();
            replace_first_hand_card(&mut document, CardId::Lethality, upgrade);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(admit(&document, &state, &catalog), Ok(()));

            state.powers.set(PowerId::Lethality, SlotWire::Int, 50);
            assert_eq!(admit(&document, &state, &catalog), Ok(()));

            let mut invalid = document.clone();
            invalid
                .player
                .insert(PowerId::Lethality.as_str().to_owned(), Value::from(-1));
            let invalid_catalog = HotBoundary::catalog_from_canonical(&invalid).unwrap();
            let invalid_state = HotBoundary::from_canonical(&invalid, &invalid_catalog).unwrap();
            let refusal = admit(&invalid, &invalid_state, &invalid_catalog).unwrap_err();
            assert!(refusal.contains(MissingCapability::PowerState(PowerId::Lethality)));
        }
    }

    /// The 15 cards that were the entire `card_keyword` blocker set on the
    /// 2026-09-15 real-fight census (#2482), at every generated level. All 20
    /// rows were admitted by registry-equality clauses. Folly adds one more
    /// native inert-Curse row for the EA6 run; Reflex and Untouchable add four
    /// static-Sly rows reachable through later generated catalogs.
    const CARD_KEYWORD_GAP_ROWS: [(CardId, u8); 26] = [
        // inert Unplayable Curse/Quest residents
        (CardId::Clumsy, 0),
        (CardId::LanternKey, 0),
        (CardId::Folly, 0),
        (CardId::Greed, 0),
        (CardId::Injury, 0),
        (CardId::CurseOfTheBell, 0),
        (CardId::Writhe, 0),
        (CardId::Decay, 0),
        (CardId::SpoilsMap, 0),
        (CardId::Dowsing, 0),
        (CardId::ByrdonisEgg, 0),
        // static-Ethereal Skill/Power
        (CardId::Defy, 0),
        (CardId::Defy, 1),
        (CardId::EnfeeblingTouch, 0),
        (CardId::EnfeeblingTouch, 1),
        (CardId::Demesne, 0),
        (CardId::Demesne, 1),
        // static-Sly Skill/Power
        (CardId::Tactician, 0),
        (CardId::Tactician, 1),
        (CardId::Abrasive, 0),
        (CardId::Abrasive, 1),
        (CardId::Reflex, 0),
        (CardId::Reflex, 1),
        (CardId::Untouchable, 0),
        (CardId::Untouchable, 1),
        // the playable Status/Curse leaf
        (CardId::SporeMind, 0),
    ];

    #[test]
    fn card_keyword_gap_rows_admit_and_stay_registry_pinned() {
        for (id, upgrade) in CARD_KEYWORD_GAP_ROWS {
            let row = crate::content_tables::card_row(id, upgrade)
                .unwrap_or_else(|| panic!("{}+{upgrade} has no generated row", id.as_str()));
            assert!(
                card_keywords_are_inert(row),
                "{}+{upgrade} must be keyword-inert",
                id.as_str()
            );

            // Every grant here is registry equality, never an identity
            // carveout: a forged row with the same identity stays refused.
            for mutated in [
                {
                    let mut mutated = *row;
                    mutated.cost += 1;
                    mutated
                },
                {
                    let mut mutated = *row;
                    mutated.turn_end_hp_loss += 1;
                    mutated
                },
                {
                    let mut mutated = *row;
                    mutated.exhausts = !mutated.exhausts;
                    mutated
                },
            ] {
                assert!(
                    !card_keywords_are_inert(&mutated),
                    "{}+{upgrade} inherited its grant through a mutated row",
                    id.as_str()
                );
            }

            let (mut document, _, _) = parts();
            replace_first_hand_card(&mut document, id, i64::from(upgrade));
            assert_admits(&document);
            document
                .player
                .insert("exact_piles".to_owned(), Value::from(true));
            assert_admits(&document);

            if row.playable {
                play_isolated(identity(id, upgrade)).unwrap_or_else(|refusal| {
                    panic!("{}+{upgrade} refused at play: {refusal}", id.as_str())
                });
            }
        }

        // The already-admitted siblings each clause was measured against.
        // A regression in the shared machinery shows up here rather than
        // only in a census.
        for (id, upgrade) in [
            (CardId::AscendersBane, 0),
            (CardId::Burn, 0),
            (CardId::DarkShackles, 0),
            (CardId::DarkShackles, 1),
            (CardId::FranticEscape, 0),
        ] {
            let row = crate::content_tables::card_row(id, upgrade).unwrap();
            assert!(
                card_keywords_are_inert(row),
                "{}+{upgrade} lost its existing admission",
                id.as_str()
            );
        }
    }

    #[test]
    fn the_four_card_keyword_gap_clauses_partition_their_rows_exactly() {
        // Every row each new clause claims across the whole generated
        // registry, and nothing else.
        type RowPredicate = fn(&CardRow) -> bool;
        type ClaimedRows = Vec<(CardId, u8)>;
        let by_clause: [(&str, RowPredicate, ClaimedRows); 3] = [
            (
                "inert_unplayable",
                inert_unplayable_program_is_supported as RowPredicate,
                vec![
                    (CardId::ByrdonisEgg, 0),
                    (CardId::Clumsy, 0),
                    (CardId::CurseOfTheBell, 0),
                    (CardId::Decay, 0),
                    (CardId::Dowsing, 0),
                    (CardId::Folly, 0),
                    (CardId::Greed, 0),
                    (CardId::Guilty, 0),
                    (CardId::Injury, 0),
                    (CardId::LanternKey, 0),
                    (CardId::PoorSleep, 0),
                    (CardId::SpoilsMap, 0),
                    (CardId::Writhe, 0),
                ],
            ),
            (
                "static_ethereal_body",
                static_ethereal_body_program_is_supported as RowPredicate,
                vec![
                    (CardId::Defy, 0),
                    (CardId::Defy, 1),
                    (CardId::Demesne, 0),
                    (CardId::Demesne, 1),
                    (CardId::EnfeeblingTouch, 0),
                    (CardId::EnfeeblingTouch, 1),
                    (CardId::Parse, 0),
                    (CardId::Parse, 1),
                    (CardId::Seance, 0),
                    (CardId::Seance, 1),
                ],
            ),
            (
                "static_sly_body",
                static_sly_body_program_is_supported as RowPredicate,
                vec![
                    (CardId::Abrasive, 0),
                    (CardId::Abrasive, 1),
                    (CardId::Tactician, 0),
                    (CardId::Tactician, 1),
                    (CardId::Reflex, 0),
                    (CardId::Reflex, 1),
                    (CardId::Untouchable, 0),
                    (CardId::Untouchable, 1),
                ],
            ),
        ];
        for (name, predicate, mut expected) in by_clause {
            let mut claimed: Vec<_> = crate::content_tables::CARD_ROWS
                .iter()
                .filter(|row| predicate(row))
                .map(|row| (row.id, row.upgrade))
                .collect();
            claimed.sort_by_key(|(id, upgrade)| (id.as_str(), *upgrade));
            expected.sort_by_key(|(id, upgrade)| (id.as_str(), *upgrade));
            assert_eq!(claimed, expected, "{name} claims a different row set");
        }

        let spore: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| spore_mind_program_is_supported(row))
            .map(|row| (row.id, row.upgrade))
            .collect();
        assert_eq!(spore, [(CardId::SporeMind, 0)]);

        // #2561: each curse-keyword clause claims exactly its one row.
        for (name, predicate, id) in [
            (
                "bad_luck",
                bad_luck_program_is_supported as RowPredicate,
                CardId::BadLuck,
            ),
            (
                "enthralled",
                enthralled_program_is_supported,
                CardId::Enthralled,
            ),
            ("regret", regret_program_is_supported, CardId::Regret),
        ] {
            let claimed: Vec<_> = crate::content_tables::CARD_ROWS
                .iter()
                .filter(|row| predicate(row))
                .map(|row| (row.id, row.upgrade))
                .collect();
            assert_eq!(claimed, [(id, 0)], "{name} claims a different row set");
        }
    }

    #[test]
    fn curse_keyword_rows_admit_by_exact_registry_equality() {
        // #2561: Bad Luck, Enthralled, Guilty and Regret admit; any mutated
        // immutable field stays a CardKeyword refusal.
        for id in [
            CardId::BadLuck,
            CardId::Enthralled,
            CardId::Guilty,
            CardId::Regret,
        ] {
            let row = *crate::content_tables::card_row(id, 0).unwrap();
            assert!(card_keywords_are_inert(&row), "{}", id.as_str());
            for mutation in [
                "upgrade",
                "hp_loss",
                "cost",
                "hp_loss_hand",
                "playable",
                "ethereal",
            ] {
                let mut changed = row;
                match mutation {
                    "upgrade" => changed.upgrade = 1,
                    "hp_loss" => changed.turn_end_hp_loss += 1,
                    "cost" => changed.cost += 1,
                    "hp_loss_hand" => changed.turn_end_hp_loss_hand = !row.turn_end_hp_loss_hand,
                    "playable" => changed.playable = !row.playable,
                    "ethereal" => changed.ethereal = !row.ethereal,
                    _ => unreachable!(),
                }
                assert!(
                    !card_keywords_are_inert(&changed),
                    "{} {mutation} escaped",
                    id.as_str()
                );
            }
        }
        // The IL facts each clause rests on, pinned on the generated rows.
        let bad_luck = crate::content_tables::card_row(CardId::BadLuck, 0).unwrap();
        let beckon = crate::content_tables::card_row(CardId::Beckon, 0).unwrap();
        assert_eq!(bad_luck.turn_end_hp_loss, 13);
        assert!(!bad_luck.playable && bad_luck.steps.is_empty() && !bad_luck.ethereal);
        assert_eq!(
            (beckon.turn_end_dmg, beckon.turn_end_hp_loss_hand),
            (bad_luck.turn_end_dmg, bad_luck.turn_end_hp_loss_hand)
        );
        let enthralled = crate::content_tables::card_row(CardId::Enthralled, 0).unwrap();
        assert!(enthralled.playable && enthralled.steps.is_empty() && !enthralled.exhausts);
        assert_eq!((enthralled.cost, enthralled.target_type), (2, "None"));
        let regret = crate::content_tables::card_row(CardId::Regret, 0).unwrap();
        assert!(!regret.playable && regret.steps.is_empty() && regret.turn_end_hp_loss_hand);
        assert_eq!((regret.turn_end_dmg, regret.turn_end_hp_loss), (0, 0));
        assert_eq!(
            crate::content_tables::CARD_ROWS
                .iter()
                .filter(|row| row.turn_end_hp_loss_hand)
                .map(|row| row.id)
                .collect::<Vec<_>>(),
            [CardId::Regret],
            "the turn-end wrapper's Regret arm assumes Regret is the only hand-count row"
        );
    }

    #[test]
    fn inert_unplayable_rows_carry_no_body_and_only_the_shared_turn_end_reader() {
        for row in crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| inert_unplayable_program_is_supported(row))
        {
            // The IL read behind this clause is that each of these types has
            // no OnPlay program and no CardModel listener the combat loop
            // fires. Pin the generated consequences of that read, so a later
            // content regeneration cannot silently give one of them a body
            // while the identity list still admits it.
            let id = row.id;
            assert!(!row.playable, "{} became playable", id.as_str());
            assert!(row.steps.is_empty(), "{} grew a body", id.as_str());
            assert!(!row.targeted);
            assert!(!row.selects);
            assert!(!row.sly);
            assert!(!row.exhausts);
            assert_eq!(row.retain, id == CardId::PoorSleep);
            assert!(!row.x_cost);
            assert!(!row.star_x);
            assert!(row.play_condition.is_none());
            assert_eq!(row.cost, -1);
            assert_eq!(row.heal, 0);
            assert_eq!(row.on_draw_energy_loss, 0);
            assert_eq!(row.turn_end_hp_loss, 0);
            assert_eq!(row.turn_end_weak, 0);
            assert_eq!(row.turn_end_frail, 0);
            assert!(!row.turn_end_hp_loss_hand);
            // Decay is the sole turn-end payload in the set, and it is Burn's
            // exact generic reader rather than a body of its own.
            if id == CardId::Decay {
                let burn = crate::content_tables::card_row(CardId::Burn, 0).unwrap();
                assert_eq!(row.turn_end_dmg, burn.turn_end_dmg);
                assert_eq!(row.turn_end_dmg, 2);
            } else {
                assert_eq!(row.turn_end_dmg, 0, "{} grew a turn-end", id.as_str());
            }
            assert!(!UNMODELED_PHYSICAL_CARD_LISTENER_DENY_SET.contains(&id));
        }
    }

    #[test]
    fn static_ethereal_attack_rows_admit_exactly_and_keep_unmodeled_readers_closed() {
        for id in [CardId::Defile, CardId::DyingStar, CardId::Fear] {
            for upgrade in [0, 1] {
                let row = crate::content_tables::card_row(id, upgrade).unwrap();
                assert!(row.ethereal);
                assert!(static_ethereal_attack_program_is_supported(row));
                assert!(card_keywords_are_inert(row));

                let mut mutated = *row;
                mutated.cost += 1;
                assert!(!static_ethereal_attack_program_is_supported(&mutated));

                let (mut document, _, _) = parts();
                replace_first_hand_card(&mut document, id, i64::from(upgrade));
                assert_admits(&document);
                document
                    .player
                    .insert("exact_piles".to_owned(), Value::from(true));
                assert_admits(&document);
                play_isolated(identity(id, upgrade)).unwrap_or_else(|refusal| {
                    panic!("{}+{upgrade} refused at play: {refusal}", id.as_str())
                });
            }
        }

        let (mut banshee, _, _) = parts();
        replace_first_hand_card(&mut banshee, CardId::Defile, 0);
        let mut listener = banshee.piles["hand"][0].clone();
        listener.id = CardId::BansheesCry.as_str().to_owned();
        listener.uid = Some(99);
        listener.physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
        banshee
            .piles
            .entry("discard".to_owned())
            .or_default()
            .push(listener);
        banshee
            .player
            .insert("next_card_uid".to_owned(), Value::from(100));
        assert_admits(&banshee);

        let mut dark_embrace = banshee;
        dark_embrace.piles.get_mut("discard").unwrap().clear();
        let mut power = dark_embrace.piles["hand"][0].clone();
        power.id = CardId::DarkEmbrace.as_str().to_owned();
        power.uid = Some(99);
        dark_embrace
            .piles
            .entry("draw".to_owned())
            .or_default()
            .push(power);
        assert_admits(&dark_embrace);
    }

    #[test]
    fn banshees_cry_rows_and_physical_cost_vocabulary_are_exactly_scoped() {
        for upgrade in [0, 1] {
            let row = crate::content_tables::card_row(CardId::BansheesCry, upgrade).unwrap();
            assert_eq!(row.cost, if upgrade == 0 { 9 } else { 7 });
            assert!(matches!(
                row.steps,
                [step]
                    if step.kind == StepKind::AttackAll
                        && step.args == [Arg::I(33), Arg::I(1)]
            ));
            assert!(!row.ethereal && row.target_type == "AllEnemies");

            let (mut document, _, _) = parts();
            replace_first_hand_card(&mut document, CardId::BansheesCry, i64::from(upgrade));
            document.piles.get_mut("hand").unwrap()[0].physical_state =
                Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
            assert_admits(&document);
            play_isolated(identity(CardId::BansheesCry, upgrade)).unwrap();

            document.piles.get_mut("hand").unwrap()[0].physical_state = None;
            assert!(
                refuse(&document)
                    .missing()
                    .any(|item| matches!(item, MissingCapability::CardInstanceState(_)))
            );
        }

        let (mut forged, _, _) = parts();
        replace_first_hand_card(&mut forged, CardId::BansheesCry, 0);
        forged.piles.get_mut("hand").unwrap()[0].physical_state = Some(json!([
            "PHYSICAL_CARD_STATE",
            [[2, -2, 2, false]],
            0,
            false,
            []
        ]));
        assert!(
            refuse(&forged)
                .missing()
                .any(|item| matches!(item, MissingCapability::CardInstanceState(_)))
        );
    }

    #[test]
    fn remote_strength_is_the_exact_checked_blaze_writer_projection() {
        let (mut document, _, _) = parts();
        let mut solo_mayhem = document.clone();
        let mut blaze = solo_mayhem.piles.get_mut("hand").unwrap().remove(0);
        blaze.id = CardId::Blaze.as_str().to_owned();
        blaze.upgrade = 1;
        solo_mayhem.piles.get_mut("draw").unwrap().push(blaze);
        solo_mayhem
            .player
            .insert(PowerId::Mayhem.as_str().to_owned(), Value::from(1));
        let solo_catalog = HotBoundary::catalog_from_canonical(&solo_mayhem).unwrap();
        let solo_state = HotBoundary::from_canonical(&solo_mayhem, &solo_catalog).unwrap();
        assert!(
            admit(&solo_mayhem, &solo_state, &solo_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape(
                    "AutoPlay AnyAlly missing teammate target"
                )),
            "solo Mayhem must not admit a physical Draw-pile Blaze whose native AutoPlay has no non-owner target",
        );

        add_minimal_party(&mut document);
        document
            .player
            .get_mut("multiplayer_allies")
            .and_then(Value::as_array_mut)
            .and_then(|allies| allies.first_mut())
            .and_then(Value::as_object_mut)
            .and_then(|ally| ally.get_mut("fields"))
            .and_then(Value::as_object_mut)
            .expect("the minimal party has one typed ally row")
            .insert("strength".to_owned(), Value::from(4));

        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(state.fanouts.multiplayer_ally().strength, 4);
        assert_eq!(admit(&document, &state, &catalog), Ok(()));
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);

        let carriers: std::collections::BTreeSet<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                row.steps
                    .iter()
                    .any(|step| step.kind == StepKind::BlazeExact)
            })
            .map(|row| identity(row.id, row.upgrade))
            .collect();
        assert_eq!(
            carriers,
            [identity(CardId::Blaze, 0), identity(CardId::Blaze, 1)]
                .into_iter()
                .collect()
        );
        assert!(capability_manifest().steps.contains(&StepKind::BlazeExact));

        for upgrade in 0..=1 {
            let mut with_writer = document.clone();
            let card = &mut with_writer.piles.get_mut("hand").unwrap()[0];
            card.id = CardId::Blaze.as_str().to_owned();
            card.upgrade = upgrade;
            assert_admits(&with_writer);

            let max_body: i32 = if upgrade == 0 { 5 } else { 7 };
            with_writer
                .player
                .get_mut("multiplayer_allies")
                .and_then(Value::as_array_mut)
                .and_then(|allies| allies.first_mut())
                .and_then(Value::as_object_mut)
                .and_then(|ally| ally.get_mut("fields"))
                .and_then(Value::as_object_mut)
                .expect("the minimal party has one typed ally row")
                .insert("strength".to_owned(), Value::from(i32::MAX - 3 * max_body));
            assert_admits(&with_writer);
            let fields = with_writer
                .player
                .get_mut("multiplayer_allies")
                .and_then(Value::as_array_mut)
                .and_then(|allies| allies.first_mut())
                .and_then(Value::as_object_mut)
                .and_then(|ally| ally.get_mut("fields"))
                .and_then(Value::as_object_mut)
                .expect("the minimal party has one typed ally row");
            fields.insert(
                "strength".to_owned(),
                Value::from(i32::MAX - (3 * max_body - 1)),
            );
            assert!(
                refuse(&with_writer)
                    .contains(MissingCapability::ArgumentShape("Blaze Strength range"))
            );
        }
    }

    #[test]
    fn demonic_shield_publishes_only_its_two_complete_generated_rows() {
        let rows = crate::content_tables::card_rows(CardId::DemonicShield);
        assert_eq!(rows.len(), 2);
        for row in rows {
            assert!(crate::steps::ironclad_uncommon::demonic_shield_program_is_exact(row));
            assert!(card_keywords_are_inert(row));

            let mut forged = *row;
            forged.target_type = "Self";
            assert!(!card_keywords_are_inert(&forged));

            let mut forged = *row;
            forged.steps = &[crate::content_tables::Step {
                kind: StepKind::DemonicShieldBlockExact,
                args: &[],
            }];
            assert!(!card_keywords_are_inert(&forged));

            let mut forged = *row;
            forged.steps = &[
                crate::content_tables::Step {
                    kind: StepKind::HpLoss,
                    args: &[Arg::I(2)],
                },
                crate::content_tables::Step {
                    kind: StepKind::DemonicShieldBlockExact,
                    args: &[],
                },
            ];
            assert!(!card_keywords_are_inert(&forged));
        }
        assert!(
            capability_manifest()
                .steps
                .contains(&StepKind::DemonicShieldBlockExact)
        );

        for upgrade in 0..=1 {
            let (mut document, _, _) = parts();
            add_minimal_party(&mut document);
            replace_first_hand_card(&mut document, CardId::DemonicShield, upgrade);
            assert_admits(&document);
        }

        let (mut solo_autoplay, _, _) = parts();
        let mut card = solo_autoplay.piles.get_mut("hand").unwrap().remove(0);
        card.id = CardId::DemonicShield.as_str().to_owned();
        card.upgrade = 0;
        solo_autoplay.piles.get_mut("draw").unwrap().push(card);
        solo_autoplay
            .player
            .insert(PowerId::Mayhem.as_str().to_owned(), Value::from(1));
        assert!(
            refuse(&solo_autoplay).contains(MissingCapability::ArgumentShape(
                "AutoPlay AnyAlly missing teammate target"
            ))
        );
    }

    #[test]
    fn coordinate_and_fade_reserve_the_complete_three_body_series() {
        let (document, mut state, base) = parts();
        state.multiplayer_ally_key = 1;
        assert!(
            state
                .fanouts
                .set_multiplayer_ally(crate::hot::MultiplayerAllyState {
                    key: 1,
                    ..crate::hot::MultiplayerAllyState::default()
                })
        );

        let coordinate = catalog_with(&base, identity(CardId::Coordinate, 1));
        for remote in [false, true] {
            state.temp_strength = 0;
            state.fanouts.multiplayer_ally_mut().temp_strength = 0;
            if remote {
                state.fanouts.multiplayer_ally_mut().temp_strength = i32::MAX - 24;
            } else {
                state.temp_strength = i32::MAX - 24;
            }
            assert_eq!(admit(&document, &state, &coordinate), Ok(()));
            if remote {
                state.fanouts.multiplayer_ally_mut().temp_strength += 1;
            } else {
                state.temp_strength += 1;
            }
            assert!(admit(&document, &state, &coordinate).unwrap_err().contains(
                MissingCapability::ArgumentShape("Coordinate temporary Strength range")
            ));
        }

        state.temp_strength = 0;
        state.fanouts.multiplayer_ally_mut().temp_strength = 0;
        let fade = catalog_with(&base, identity(CardId::Fade, 1));
        for remote in [false, true] {
            state.powers.set(PowerId::TempDexterity, SlotWire::Int, 0);
            state.fanouts.multiplayer_ally_mut().temp_dexterity = 0;
            if remote {
                state.fanouts.multiplayer_ally_mut().temp_dexterity = i32::MAX - 27;
            } else {
                state
                    .powers
                    .set(PowerId::TempDexterity, SlotWire::Int, i32::MAX - 27);
            }
            assert_eq!(admit(&document, &state, &fade), Ok(()));
            if remote {
                state.fanouts.multiplayer_ally_mut().temp_dexterity += 1;
            } else {
                state
                    .powers
                    .set(PowerId::TempDexterity, SlotWire::Int, i32::MAX - 26);
            }
            assert!(admit(&document, &state, &fade).unwrap_err().contains(
                MissingCapability::ArgumentShape("Fade temporary Dexterity range")
            ));
        }
    }

