    fn catalog_with_relics(
        base: &Catalog,
        extra: Option<CardIdentity>,
        relics: &[RelicId],
    ) -> Catalog {
        let mut builder = CatalogBuilder::new();
        for spec in base.specs() {
            builder.intern(spec.identity).unwrap();
        }
        for spec in base.reachable_specs() {
            builder.intern_reachable(spec.identity).unwrap();
        }
        if let Some(identity) = extra {
            builder.intern_reachable(identity).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        builder.set_relics(relics).unwrap();
        builder.build()
    }

    /// #3208: a nested Power action series reserves one Duplication body per
    /// action while stacks remain (`DuplicationPower::ModifyCardPlayCount`
    /// `0xa1dd9` +1, `<AfterModifyingCardPlayCount>d__5` `0x3399f8`
    /// IL_001e Decrement), and one Throwing Axe body for the whole series
    /// (`0x9c7bf`, spent by `UsedThisCombat`). Imitation 1 gives 2 actions.
    #[test]
    fn necro_mastery_range_reserves_duplication_and_throwing_axe_bodies() {
        let (document, mut state, base) = parts();
        let necro = identity(CardId::NecroMastery, 1);
        state.fanouts.set_osty(Some((10, 10))).unwrap();
        assert!(state.fanouts.set_imitation_learning(0, 1));
        assert_eq!(power_action_body_count(&state), 2);
        for (duplication, axe, bodies) in [
            (1, false, 3_i32),
            (2, false, 4),
            (5, false, 4),
            (0, true, 3),
            (1, true, 4),
        ] {
            let catalog = if axe {
                catalog_with_relics(&base, Some(necro), &[RelicId::RelicThrowingAxe])
            } else {
                catalog_with(&base, necro)
            };
            let mut candidate = state.clone();
            assert!(candidate.fanouts.set_duplication(duplication));
            candidate.fanouts.set_throwing_axe_available(axe);
            assert_eq!(
                power_action_body_count(&candidate),
                i64::from(bodies),
                "duplication={duplication} axe={axe}"
            );
            candidate
                .powers
                .set(PowerId::NecroMastery, SlotWire::Int, i32::MAX - bodies);
            assert_eq!(
                admit(&document, &candidate, &catalog),
                Ok(()),
                "duplication={duplication} axe={axe}"
            );
            candidate
                .powers
                .set(PowerId::NecroMastery, SlotWire::Int, i32::MAX - bodies + 1);
            assert!(
                admit(&document, &candidate, &catalog)
                    .unwrap_err()
                    .contains(MissingCapability::ArgumentShape(
                        "Necro Mastery power range"
                    )),
                "duplication={duplication} axe={axe}"
            );
        }
    }

    /// #3208: the future-replay wall sees the two type-blind consumed
    /// modifiers: live Duplication, a held Duplicator (`<OnUse>d__6`
    /// `0x34d154` IL_003a), and an unused Throwing Axe.
    #[test]
    fn future_generated_play_count_sees_duplication_and_throwing_axe() {
        let (_, state, catalog) = parts();
        let strike = catalog
            .specs()
            .find(|spec| spec.identity.id == CardId::StrikeIronclad)
            .expect("fixture catalog carries Strike");
        assert!(!future_generated_play_count_exceeds_one(
            &state, &catalog, strike
        ));

        let mut live = state.clone();
        assert!(live.fanouts.set_duplication(1));
        assert!(future_generated_play_count_exceeds_one(
            &live, &catalog, strike
        ));

        let mut belt = state.clone();
        assert!(belt.fanouts.set_potion_belt(
            vec![Some(PotionId::Duplicator)],
            false,
            false,
            false,
            false,
            true,
        ));
        assert!(future_generated_play_count_exceeds_one(
            &belt, &catalog, strike
        ));

        let mut axe = state;
        axe.fanouts.set_throwing_axe_available(true);
        assert!(future_generated_play_count_exceeds_one(
            &axe, &catalog, strike
        ));
    }

    #[test]
    fn summon_and_necro_mastery_ranges_close_every_generated_body() {
        let (document, mut state, base) = parts();
        let reanimate = catalog_with(&base, identity(CardId::Reanimate, 1));
        state
            .fanouts
            .set_osty(Some((i32::MAX - 75, i32::MAX - 75)))
            .unwrap();
        assert_eq!(admit(&document, &state, &reanimate), Ok(()));
        state
            .fanouts
            .set_osty(Some((i32::MAX - 74, i32::MAX - 74)))
            .unwrap();
        assert!(
            admit(&document, &state, &reanimate)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape("Osty summon range"))
        );

        let necro = catalog_with(&base, identity(CardId::NecroMastery, 1));
        state.fanouts.set_osty(Some((10, 10))).unwrap();
        assert!(state.fanouts.set_imitation_learning(0, 1));
        state.powers.set(PowerId::SignalBoost, SlotWire::Int, 1);
        state.powers.set(PowerId::EchoForm, SlotWire::Int, 1);
        state
            .powers
            .set(PowerId::NecroMastery, SlotWire::Int, i32::MAX - 4);
        assert_eq!(admit(&document, &state, &necro), Ok(()));
        state
            .powers
            .set(PowerId::NecroMastery, SlotWire::Int, i32::MAX - 3);
        assert!(admit(&document, &state, &necro).unwrap_err().contains(
            MissingCapability::ArgumentShape("Necro Mastery power range")
        ));

        state.powers.set(PowerId::NecroMastery, SlotWire::Int, 0);
        state
            .fanouts
            .set_osty(Some((i32::MAX - 32, i32::MAX - 32)))
            .unwrap();
        assert_eq!(admit(&document, &state, &necro), Ok(()));
        state
            .fanouts
            .set_osty(Some((i32::MAX - 31, i32::MAX - 31)))
            .unwrap();
        assert!(
            admit(&document, &state, &necro)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape("Osty summon range"))
        );
    }

