    #[test]
    fn accelerant_range_reserves_replay_and_recursive_imitation_bodies() {
        let (mut physical, _, _) = parts();
        replace_first_hand_card(&mut physical, CardId::Accelerant, 0);
        physical
            .player
            .insert("accelerant".to_owned(), Value::from(i32::MAX));
        let physical_catalog = HotBoundary::catalog_from_canonical(&physical).unwrap();
        let physical_state = HotBoundary::from_canonical(&physical, &physical_catalog).unwrap();
        assert_eq!(
            physical_state.powers.value(PowerId::Accelerant),
            i32::MAX,
            "the exact boundary preserves the frozen Int32 scalar"
        );
        let physical_uid = physical_state.piles.get(PileId::Hand).as_slice()[0].uid;
        let action = crate::engine::Action::Play {
            uid: physical_uid,
            target: None,
            selection: crate::engine::SelectionRef::NONE,
        };
        assert!(
            crate::engine::legal_actions(&physical_state, &physical_catalog).contains(&action),
            "the native-legal physical play proves admission must close the writer range"
        );
        assert!(
            admit(&physical, &physical_state, &physical_catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape("Accelerant power range"))
        );

        let (document, mut state, base) = parts();
        let catalog = catalog_with(&base, identity(CardId::Accelerant, 1));
        state
            .powers
            .set(PowerId::Accelerant, SlotWire::Int, i32::MAX - 6);
        state.powers.set(PowerId::SignalBoost, SlotWire::Int, 1);
        state.powers.set(PowerId::EchoForm, SlotWire::Int, 1);
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        state
            .powers
            .set(PowerId::Accelerant, SlotWire::Int, i32::MAX - 5);
        assert!(
            admit(&document, &state, &catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape("Accelerant power range"))
        );

        state.powers.set(PowerId::SignalBoost, SlotWire::Int, 0);
        state.powers.set(PowerId::EchoForm, SlotWire::Int, 0);
        assert!(state.fanouts.set_imitation_learning(0, 1));
        state
            .powers
            .set(PowerId::Accelerant, SlotWire::Int, i32::MAX - 4);
        assert_eq!(admit(&document, &state, &catalog), Ok(()));
        state
            .powers
            .set(PowerId::Accelerant, SlotWire::Int, i32::MAX - 3);
        assert!(
            admit(&document, &state, &catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape("Accelerant power range"))
        );

        state.hp = 0;
        state.multiplayer_ally_key = 1;
        state
            .fanouts
            .set_multiplayer_ally(crate::hot::MultiplayerAllyState {
                key: 1,
                alive: true,
                ..crate::hot::MultiplayerAllyState::default()
            });
        state.powers.set(PowerId::Accelerant, SlotWire::Int, 2);
        assert!(
            admit(&document, &state, &catalog)
                .unwrap_err()
                .contains(MissingCapability::ArgumentShape("dead Accelerant owner"))
        );
    }

