    #[test]
    fn one_for_all_is_the_exact_admitted_all_allies_power_program() {
        assert!(IMPLEMENTED_PLAYER_POWERS.contains(&PowerId::OneForAll));
        assert!(
            capability_manifest()
                .steps
                .contains(&StepKind::OneForAllExact)
        );
        for upgrade in 0..=1 {
            let row = *crate::content_tables::card_row(CardId::OneForAll, upgrade).unwrap();
            assert!(card_keywords_are_inert(&row));
            for mutation in ["cost", "target", "power", "program"] {
                let mut changed = row;
                match mutation {
                    "cost" => changed.cost = 0,
                    "target" => changed.target_type = "AnyAlly",
                    "power" => changed.is_power = false,
                    "program" => changed.steps = &[],
                    _ => unreachable!(),
                }
                assert!(!card_keywords_are_inert(&changed), "{mutation}");
            }

            let (mut document, _, _) = parts();
            replace_first_hand_card(&mut document, CardId::OneForAll, i64::from(upgrade));
            add_minimal_party(&mut document);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(admit(&document, &state, &catalog), Ok(()));
        }

        let (mut live_power, _, _) = parts();
        live_power
            .player
            .insert("one_for_all".to_owned(), Value::from(3));
        let catalog = HotBoundary::catalog_from_canonical(&live_power).unwrap();
        let state = HotBoundary::from_canonical(&live_power, &catalog).unwrap();
        assert_eq!(admit(&live_power, &state, &catalog), Ok(()));

        live_power
            .player
            .insert("one_for_all".to_owned(), Value::from(-1));
        let catalog = HotBoundary::catalog_from_canonical(&live_power).unwrap();
        let state = HotBoundary::from_canonical(&live_power, &catalog).unwrap();
        assert!(
            admit(&live_power, &state, &catalog)
                .unwrap_err()
                .contains(MissingCapability::PowerState(PowerId::OneForAll))
        );
    }

