    #[test]
    fn void_form_rows_publish_only_the_exact_static_keyword_and_private_tuple() {
        assert!(step_is_implemented(StepKind::VoidForm));
        assert!(IMPLEMENTED_PLAYER_POWERS.contains(&PowerId::VoidForm));
        for upgrade in [0, 1] {
            let (mut document, _, _) = parts();
            let source = &mut document.piles.get_mut("hand").unwrap()[0];
            source.id = CardId::VoidForm.as_str().to_owned();
            source.upgrade = upgrade;
            source.enchantment = None;
            assert_admits(&document);

            let mut mutated = document.clone();
            mutated.piles.get_mut("hand").unwrap()[0].enchantment =
                Some(json!([EnchantmentId::Momentum.as_str(), 1]));
            assert!(
                refuse(&mutated)
                    .contains(MissingCapability::CardEnchantment(EnchantmentId::Momentum))
            );
        }

        let (mut active, _, _) = parts();
        active.player.insert("void_form".to_owned(), json!(2));
        append_singleton_after_card_played_row(&mut active, PowerId::VoidForm);
        active
            .player
            .insert("void_form_cards_played_this_turn".to_owned(), json!(3));
        assert_admits(&active);

        let mut forged_request = active;
        forged_request
            .player
            .insert("end_turn_requested".to_owned(), json!(true));
        assert!(matches!(
            HotBoundary::catalog_from_canonical(&forged_request)
                .and_then(|catalog| HotBoundary::from_canonical(&forged_request, &catalog)),
            Err(crate::boundary::BoundaryRefusal::UnrepresentableValue { .. })
        ));
    }

    #[test]
    fn independent_bounded_and_live_generators_charge_future_alchemize_writers() {
        let fixture = |source: CardId, owner: RewardPool, target: CardId, counter: u64| {
            (0..4096)
                .find_map(|seed| {
                    let mut document = generator_document(source, owner, false, seed);
                    let catalog = HotBoundary::catalog_from_canonical(&document).ok()?;
                    if !catalog
                        .reachable_specs()
                        .any(|spec| spec.identity.id == target)
                    {
                        return None;
                    }
                    let mut alchemize = document.piles.get("hand")?.first()?.clone();
                    alchemize.uid = Some(992);
                    alchemize.id = CardId::Alchemize.as_str().to_owned();
                    alchemize.upgrade = 0;
                    document.piles.get_mut("hand")?.push(alchemize);
                    document.player.insert(
                        "potion_slots".to_owned(),
                        json!([PotionId::BlockPotion.as_str()]),
                    );
                    document.player.insert(
                        "potions".to_owned(),
                        json!([PotionId::BlockPotion.as_str()]),
                    );
                    document.player.insert("sozu".to_owned(), json!(true));
                    document
                        .player
                        .insert("fully_unlocked_potion_pool".to_owned(), json!(true));
                    document.rng.insert(
                        RngStream::PotionGeneration.as_str().to_owned(),
                        crate::canonical::CanonicalRngV2 {
                            words: [1, 2, 3, 4],
                            counter,
                        },
                    );
                    Some(document)
                })
                .expect("one finite generation prefix reaches the replay writer")
        };

        for (source, owner, target) in [
            (CardId::Distraction, RewardPool::Silent, CardId::Burst),
            (CardId::WhiteNoise, RewardPool::Defect, CardId::EchoForm),
        ] {
            assert_admits(&fixture(source, owner, target, u64::MAX - 4));
            assert!(
                refuse(&fixture(source, owner, target, u64::MAX - 3)).contains(
                    MissingCapability::ArgumentShape("Alchemize generation provenance")
                )
            );
        }

        let mut live = generator_document(CardId::Alchemize, RewardPool::Defect, false, 9);
        live.player.insert(
            "potion_slots".to_owned(),
            json!([PotionId::BlockPotion.as_str()]),
        );
        live.player.insert(
            "potions".to_owned(),
            json!([PotionId::BlockPotion.as_str()]),
        );
        live.player.insert("sozu".to_owned(), json!(true));
        live.player
            .insert("fully_unlocked_potion_pool".to_owned(), json!(true));
        live.player
            .insert(PowerId::CreativeAi.as_str().to_owned(), json!(1));
        live.player.insert(
            "before_hand_draw_power_order".to_owned(),
            json!([PowerId::CreativeAi.as_str()]),
        );
        live.rng.insert(
            RngStream::PotionGeneration.as_str().to_owned(),
            crate::canonical::CanonicalRngV2 {
                words: [1, 2, 3, 4],
                counter: u64::MAX - 4,
            },
        );
        assert_admits(&live);
        live.rng
            .get_mut(RngStream::PotionGeneration.as_str())
            .unwrap()
            .counter = u64::MAX - 3;
        assert!(refuse(&live).contains(MissingCapability::ArgumentShape(
            "Alchemize generation provenance"
        )));
    }

    #[test]
    fn live_entropy_and_spectrum_shift_reach_heirloom_before_alchemize() {
        let fixture = |power: PowerId, owner: RewardPool, counter: u64| {
            // A Regent root publishes `spectrum_shift_generation_pool`
            // whatever the live power is: Entropy's provenance predicate
            // requires it on that class (the guard `main` spelled inline), so
            // without it the Entropy rows below would be gated off and this
            // test would silently stop measuring Entropy's headroom.
            let mut document = generator_document(
                CardId::Alchemize,
                owner,
                power == PowerId::SpectrumShift || owner == RewardPool::Regent,
                9,
            );
            document
                .player
                .insert("potion_slots".to_owned(), json!([null]));
            document
                .player
                .insert("fully_unlocked_potion_pool".to_owned(), json!(true));
            document.player.insert(power.as_str().to_owned(), json!(1));
            match power {
                PowerId::SpectrumShift => {
                    document.player.insert(
                        "before_hand_draw_power_order".to_owned(),
                        json!([power.as_str()]),
                    );
                }
                PowerId::Entropy => {
                    document.player.insert(
                        "after_player_turn_start_power_order".to_owned(),
                        json!([power.as_str()]),
                    );
                    document.rng.insert(
                        RngStream::Sel.as_str().to_owned(),
                        crate::canonical::CanonicalRngV2 {
                            words: [5, 6, 7, 8],
                            counter: 0,
                        },
                    );
                }
                _ => unreachable!(),
            }
            document.rng.insert(
                RngStream::PotionGeneration.as_str().to_owned(),
                crate::canonical::CanonicalRngV2 {
                    words: [1, 2, 3, 4],
                    counter,
                },
            );
            document
        };

        for (power, owner) in [
            (PowerId::SpectrumShift, RewardPool::Regent),
            (PowerId::Entropy, RewardPool::Ironclad),
            (PowerId::Entropy, RewardPool::Regent),
        ] {
            // Entropy's foreign-card closure also reaches Burst and Echo
            // Form. Spectrum Shift can generate Entropy, so both reserve
            // four Alchemize bodies (ordinary, Duplicator, Burst, Echo).
            //
            // Counted off the catalog the BOUNDARY rebuilds for this very
            // fixture, exactly as the `engine/mod.rs` sibling does, so the
            // number tracks the closure instead of asserting a literal that
            // would quietly stop matching it (#2637 landing pass, N5). The
            // one-draw-short assertion below still pins it as the exact
            // boundary rather than merely a large enough one.
            let reservation_catalog =
                HotBoundary::catalog_from_canonical(&fixture(power, owner, u64::MAX - 8)).unwrap();
            let bodies = 2 + [CardId::Burst, CardId::EchoForm]
                .into_iter()
                .filter(|id| {
                    reservation_catalog.is_reachable(CardIdentity {
                        id: *id,
                        upgrade: 0,
                        enchantment: None,
                    })
                })
                .count() as u64;
            let draws = 2 * bodies;
            assert!(!refuse(&fixture(power, owner, u64::MAX - draws)).contains(
                MissingCapability::ArgumentShape("Alchemize generation provenance")
            ));
            assert!(
                refuse(&fixture(power, owner, u64::MAX - (draws - 1))).contains(
                    MissingCapability::ArgumentShape("Alchemize generation provenance")
                )
            );
        }
    }

