    #[test]
    fn undeath_admits_exact_replay_enchantments_but_not_legacy_state() {
        let (mut ordinary, _, _) = parts();
        let source = &mut ordinary.piles.get_mut("hand").unwrap()[0];
        source.id = CardId::Undeath.as_str().to_owned();
        source.upgrade = 0;
        source.enchantment = None;
        assert_admits(&ordinary);
        let ordinary_catalog = HotBoundary::catalog_from_canonical(&ordinary).unwrap();
        assert!(
            ordinary_catalog
                .specs()
                .all(|spec| spec.identity.enchantment.is_none()),
            "every admitted generated/catalog closure remains unenchanted"
        );
        assert_eq!(EnchantmentId::from_str("GLAM_USED"), None);

        let mut glam = ordinary.clone();
        glam.piles.get_mut("hand").unwrap()[0].enchantment =
            Some(json!([EnchantmentId::Glam.as_str(), 2]));
        assert_admits(&glam);

        let mut spent_glam = ordinary;
        spent_glam.piles.get_mut("hand").unwrap()[0].enchantment = Some(json!(["GLAM_USED", 2]));
        assert_admits(&spent_glam);
        let spent_catalog = HotBoundary::catalog_from_canonical(&spent_glam).unwrap();
        let spent_hot = HotBoundary::from_canonical(&spent_glam, &spent_catalog).unwrap();
        assert_eq!(
            HotBoundary::to_canonical(&spent_hot, &spent_catalog),
            spent_glam
        );

        let mut legacy = glam;
        let legacy_source = &mut legacy.piles.get_mut("hand").unwrap()[0];
        legacy_source.enchantment = None;
        legacy_source.uid = None;
        let legacy_refusal = refuse(&legacy);
        assert!(
            legacy_refusal.contains(MissingCapability::CardInstanceState(u32::MAX)),
            "{legacy_refusal:?}"
        );

        let source = include_str!("admission.rs");
        assert!(source.contains("if spec.identity.enchantment.is_some()"));
    }

    /// #3135 witnesses 1 and 7: Glam on a Power (natively legal per
    /// `EnchantmentModel::CanEnchant` `0x7f40c`, which refuses only Status,
    /// Curse and Quest) admits in draw pile and hand at both Stone Armor
    /// levels, fresh and spent, raising neither `CardEnchantment(Glam)` nor
    /// `CardInstanceState(uid)`, and both wire spellings round-trip
    /// bijectively. This was the WQQ1NTPA1BW3 Waterfall Giant refusal.
    #[test]
    fn glam_on_a_power_admits_fresh_and_spent_and_round_trips() {
        for upgrade in [0, 1] {
            for pile in ["hand", "draw"] {
                for spelling in ["GLAM", "GLAM_USED"] {
                    let (mut document, _, _) = parts();
                    let mut source = document.piles.get_mut("hand").unwrap().remove(0);
                    source.id = CardId::StoneArmor.as_str().to_owned();
                    source.upgrade = upgrade;
                    source.enchantment = Some(json!([spelling, 1]));
                    document
                        .piles
                        .get_mut(pile)
                        .expect("fixture pile")
                        .insert(0, source);
                    let label = format!("STONE_ARMOR+{upgrade} {spelling} in {pile}");
                    if let Some(refusal) = maybe_refuse(&document) {
                        panic!("{label}: {refusal:?}");
                    }
                    let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                    let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                    let uid = state
                        .piles
                        .get(if pile == "hand" {
                            crate::hot::PileId::Hand
                        } else {
                            crate::hot::PileId::Draw
                        })
                        .as_slice()[0]
                        .uid;
                    assert_eq!(
                        state.card_states.get(uid).enchantment_state.get(),
                        (spelling == "GLAM_USED").then_some(1),
                        "{label}"
                    );
                    assert_eq!(
                        HotBoundary::to_canonical(&state, &catalog),
                        document,
                        "{label}"
                    );
                }
            }
        }
    }

    #[test]
    fn debt_is_the_only_exact_gold_loss_carrier_and_every_shape_mutation_refuses() {
        let carriers: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                row.steps
                    .iter()
                    .any(|step| step.kind == StepKind::TurnEndGoldLossExact)
            })
            .collect();
        assert_eq!(carriers.len(), 1);
        let exact = carriers[0];
        assert_eq!((exact.id, exact.upgrade), (CardId::Debt, 0));
        assert!(card_keywords_are_inert(exact));

        const WRONG_ARGS: &[crate::content_tables::Arg] = &[crate::content_tables::Arg::I(9)];
        const WRONG_STEPS: &[crate::content_tables::Step] = &[crate::content_tables::Step {
            kind: StepKind::TurnEndGoldLossExact,
            args: WRONG_ARGS,
        }];
        const EXTRA_STEPS: &[crate::content_tables::Step] = &[
            crate::content_tables::Step {
                kind: StepKind::Block,
                args: &[crate::content_tables::Arg::I(1)],
            },
            crate::content_tables::Step {
                kind: StepKind::TurnEndGoldLossExact,
                args: &[crate::content_tables::Arg::I(10)],
            },
        ];
        let mut mutations = Vec::new();
        let mut foreign_identity = *exact;
        foreign_identity.id = CardId::Doubt;
        mutations.push(foreign_identity);
        let mut wrong_cost = *exact;
        wrong_cost.cost = -2;
        mutations.push(wrong_cost);
        let mut wrong_upgrade = *exact;
        wrong_upgrade.upgrade = 1;
        mutations.push(wrong_upgrade);
        let mut extra_keyword = *exact;
        extra_keyword.turn_end_weak = 1;
        mutations.push(extra_keyword);
        let mut missing_program = *exact;
        missing_program.steps = &[];
        mutations.push(missing_program);
        let mut wrong_operand = *exact;
        wrong_operand.steps = WRONG_STEPS;
        mutations.push(wrong_operand);
        let mut reordered_extra_program = *exact;
        reordered_extra_program.steps = EXTRA_STEPS;
        mutations.push(reordered_extra_program);
        for row in mutations {
            assert!(
                !card_keywords_are_inert(&row),
                "mutated Debt row escaped the exact keyword gate: {row:?}"
            );
        }

        let (mut document, _, _) = parts();
        let card = &mut document.piles.get_mut("hand").unwrap()[0];
        card.id = "DEBT".to_owned();
        card.upgrade = 0;
        document.player.insert("gold".to_owned(), json!(17));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
        assert!(card_row_is_admitted(
            &catalog,
            catalog
                .spec(catalog.atom(&identity(CardId::Debt, 0)).unwrap())
                .unwrap()
        ));
        assert_eq!(admit(&document, &state, &catalog), Ok(()));
    }

    /// Mechanical union of deterministic and random-AI generated move tables
    /// for every slice-6 kind. A claimed body must disappear from every
    /// carrier's refusal even when an independent AI, successor, power, card,
    /// or neighboring-move gap keeps the actual encounter out. The six
    /// admitted singleton identities are deliberately not an encounter claim:
    /// the Python roster sweep and smoke probes preserve initial powers and
    /// companions (only Vine Shambler is a newly admitted full encounter).
    #[test]
    fn player_affliction_carrier_admission_sweep_is_total() {
        const KINDS: &[MoveKind] = &[
            MoveKind::AttackFrail,
            MoveKind::AttackSmoggy,
            MoveKind::AttackTangle,
            MoveKind::AttackWeakFrail,
            MoveKind::AttackWeakPlayer,
            MoveKind::FrailPlayer,
            MoveKind::Haunt,
            MoveKind::QueenYoureMine,
            MoveKind::Scream,
            MoveKind::Shrink,
            MoveKind::VulnPlayer,
            MoveKind::WeakPlayer,
            MoveKind::WeakPlayerStrength,
        ];
        let mut carriers = Vec::new();
        let mut carried_kinds = BTreeSet::new();
        let mut singly_admitted = Vec::new();
        for kind in MonsterKind::ALL {
            let carried: Vec<_> = crate::content_tables::monster_loop(kind)
                .into_iter()
                .flatten()
                .chain(
                    crate::content_tables::random_moves(kind)
                        .into_iter()
                        .flatten(),
                )
                .filter(|entry| KINDS.contains(&entry.kind))
                .map(|entry| entry.kind)
                .collect();
            if carried.is_empty() {
                continue;
            }
            carriers.push(kind);
            carried_kinds.extend(carried.iter().copied());
            let (mut document, _, _) = parts();
            document.monsters.truncate(1);
            document.monsters[0].insert("kind".to_owned(), Value::from(kind.as_str()));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            match admit(&document, &state, &catalog) {
                Ok(()) => singly_admitted.push(kind),
                Err(refusal) => {
                    for move_kind in &carried {
                        assert!(
                            !refusal.contains(MissingCapability::MoveKind(*move_kind)),
                            "slice-6 carrier {:?} still refused its newly claimed {:?}: {refusal}",
                            kind.as_str(),
                            move_kind.as_str()
                        );
                    }
                }
            }
        }
        assert_eq!(carried_kinds, KINDS.iter().copied().collect());
        assert_eq!(
            carriers,
            [
                MonsterKind::Axebot,
                MonsterKind::BowlbugSilk,
                MonsterKind::CorpseSlug,
                MonsterKind::Crusher,
                MonsterKind::DecimillipedeSegment,
                MonsterKind::FakeMerchantMonster,
                MonsterKind::Flyconid,
                MonsterKind::FossilStalker,
                MonsterKind::FrogKnight,
                MonsterKind::GlobeHead,
                MonsterKind::HauntedShip,
                MonsterKind::KinPriest,
                MonsterKind::LivingFog,
                MonsterKind::Mawler,
                MonsterKind::PunchConstruct,
                MonsterKind::Queen,
                MonsterKind::ShrinkerBeetle,
                MonsterKind::SlimedBerserker,
                MonsterKind::SludgeSpinner,
                MonsterKind::SoulFysh,
                MonsterKind::Stabbot,
                MonsterKind::TrackerRubyRaider,
                MonsterKind::TwoTailedRat,
                MonsterKind::VineShambler,
            ]
        );
        // Haunted Ship and Shrinker Beetle join as singleton identities in
        // #2481: both loops are purely Absent/Fixed with every body already
        // implemented, so admitting their fixed successors removed the last
        // gap on the singleton. As the doc comment above says, a singleton
        // identity is deliberately NOT an encounter claim — the corpus census
        // is what shows their real encounters admitting.
        assert_eq!(
            singly_admitted,
            [
                MonsterKind::BowlbugSilk,
                MonsterKind::CorpseSlug,
                // The Decimillipede segment left this list in #2494 — its loop
                // bodies were implemented, so it stayed a slice-6 move carrier
                // above, but #2498's unported death branch meant the identity
                // did not admit. #2510 ports that branch, its two readers and
                // the shared-stream reattach roll, so the identity is back.
                MonsterKind::DecimillipedeSegment,
                // #3300 gives Globe Head's intrinsic Galvanic a reader, exact
                // for the lone roster this sweep builds.
                MonsterKind::GlobeHead,
                MonsterKind::HauntedShip,
                MonsterKind::LivingFog,
                MonsterKind::PunchConstruct,
                MonsterKind::ShrinkerBeetle,
                MonsterKind::SlimedBerserker,
                // #2850 admits its HOUNDS -> HOUNDS fixed successor, the
                // identity's only gap (TRACK_MOVE's `frail_player` was
                // already claimed).
                MonsterKind::TrackerRubyRaider,
                MonsterKind::VineShambler,
            ]
        );
    }

    #[test]
