    #[test]
    fn shroud_admission_is_exactly_two_native_rows_and_complete_live_order() {
        let (document, state, base) = parts();
        let rows: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| row.steps.iter().any(|step| step.kind == StepKind::Shroud))
            .collect();
        assert_eq!(rows.len(), 2, "Shroud carrier census drifted");
        for row in rows {
            let expected = 3 + i64::from(row.upgrade);
            assert_eq!(row.id, CardId::Shroud);
            assert_eq!(row.steps.len(), 1);
            assert_eq!(row.steps[0].args, &[Arg::I(expected)]);
            assert_eq!(
                admit(
                    &document,
                    &state,
                    &catalog_with(&base, identity(row.id, row.upgrade)),
                ),
                Ok(()),
                "Shroud+{} lost exact admission",
                row.upgrade
            );
        }

        let (mut live, _, _) = parts();
        live.player.insert("shroud".to_owned(), Value::from(7));
        live.player.insert(
            "after_power_amount_changed_power_order".to_owned(),
            json!(["shroud"]),
        );
        let catalog = HotBoundary::catalog_from_canonical(&live).unwrap();
        let hot = HotBoundary::from_canonical(&live, &catalog).unwrap();
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), live);
        assert_eq!(admit(&live, &hot, &catalog), Ok(()));

        live.player.remove("after_power_amount_changed_power_order");
        assert!(refuse(&live).contains(MissingCapability::ArgumentShape(
            "after-power-amount-changed power order"
        )));

        let (mut order_without_power, _, _) = parts();
        order_without_power.player.insert(
            "after_power_amount_changed_power_order".to_owned(),
            json!(["shroud"]),
        );
        assert!(
            refuse(&order_without_power).contains(MissingCapability::ArgumentShape(
                "after-power-amount-changed power order"
            ))
        );

        let (mut duplicate_document, _, _) = parts();
        duplicate_document
            .player
            .insert("shroud".to_owned(), Value::from(7));
        duplicate_document
            .player
            .insert("sleight_of_flesh".to_owned(), Value::from(9));
        duplicate_document.player.insert(
            "after_power_amount_changed_power_order".to_owned(),
            json!(["shroud", "sleight_of_flesh"]),
        );
        let duplicate_catalog = HotBoundary::catalog_from_canonical(&duplicate_document).unwrap();
        let mut duplicate_state =
            HotBoundary::from_canonical(&duplicate_document, &duplicate_catalog).unwrap();
        assert!(
            duplicate_state
                .fanouts
                .set_after_power_amount_changed_order(&[PowerId::Shroud, PowerId::Shroud,])
        );
        let duplicate_refusal =
            admit(&duplicate_document, &duplicate_state, &duplicate_catalog).unwrap_err();
        assert!(
            duplicate_refusal.contains(MissingCapability::ArgumentShape(
                "after-power-amount-changed power order"
            )),
            "a duplicate listener cannot stand in for the other live observer"
        );
    }

