    /// #3159 witness: SelfFormingClayPower is its own keyed
    /// `AfterBlockCleared` listener beside BlockNextTurn. Both orders round
    /// trip and admit; an order that omits it, or a listener without its
    /// positive amount, refuses.
    #[test]
    fn self_forming_clay_power_admits_only_with_matching_amount_and_order() {
        for order in [
            json!(["block_next_turn", "self_forming_clay_power"]),
            json!(["self_forming_clay_power", "block_next_turn"]),
        ] {
            let (mut document, _, _) = parts();
            document
                .player
                .insert("block_next_turn".to_owned(), Value::from(8));
            document
                .player
                .insert("self_forming_clay_power".to_owned(), Value::from(6));
            document
                .player
                .insert("block_next_turn_order".to_owned(), order);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(state.powers.value(PowerId::SelfFormingClayPower), 6);
            assert_eq!(state.fanouts.after_block_cleared_order().len(), 2);
            assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
            assert_eq!(admit(&document, &state, &catalog), Ok(()));
        }

        let (mut document, _, _) = parts();
        document
            .player
            .insert("self_forming_clay_power".to_owned(), Value::from(3));
        document.player.insert(
            "block_next_turn_order".to_owned(),
            json!(["block_next_turn"]),
        );
        assert!(refuse(&document).contains(MissingCapability::ArgumentShape(
            "after-block-cleared power order"
        )));

        let (mut document, _, _) = parts();
        document.player.insert(
            "block_next_turn_order".to_owned(),
            json!(["self_forming_clay_power"]),
        );
        assert!(refuse(&document).contains(MissingCapability::ArgumentShape(
            "after-block-cleared power order"
        )));
    }

    /// #3427 witness: a positive Int Curious round-trips and admits alone; a
    /// non-positive or Bool one is a power-state refusal; beside a live
    /// Borrowed Time the root refuses by name; beside an owned Spiked
    /// Gauntlets it does not (#3437).
    #[test]
    fn curious_admits_alone_and_refuses_beside_another_power_cost_listener() {
        let (mut document, _, _) = parts();
        document.player.insert("curious".to_owned(), Value::from(2));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(state.powers.value(PowerId::Curious), 2);
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let mut borrowed = document.clone();
        borrowed
            .player
            .insert("borrowed_time".to_owned(), Value::from(1));
        borrowed.player.insert(
            "after_side_turn_end_power_order".to_owned(),
            json!([["borrowed_time", 0]]),
        );
        borrowed
            .player
            .insert("next_after_side_turn_end_power_uid".to_owned(), json!(1));
        assert!(refuse(&borrowed).contains(MissingCapability::ArgumentShape(
            "Curious energy-cost listener order"
        )));

        let mut gauntlets = document.clone();
        gauntlets.player.insert(
            "relics_entering".to_owned(),
            json!(["RELIC.SPIKED_GAUNTLETS"]),
        );
        gauntlets
            .player
            .insert("spiked_gauntlets".to_owned(), json!(true));
        // #3437: the relic folds after Curious in a fixed order, so the pair
        // admits, nor is the relic alone refused. The boundary hydrates the
        // cost fold's ownership cache from the catalog and refuses to
        // serialize a state whose cache disagrees with it.
        let catalog = HotBoundary::catalog_from_canonical(&gauntlets).unwrap();
        let state = HotBoundary::from_canonical(&gauntlets, &catalog).unwrap();
        assert!(state.fanouts.spiked_gauntlets_owned());
        assert_eq!(admit(&gauntlets, &state, &catalog), Ok(()));
        let mut stale = state.clone();
        stale.fanouts.set_spiked_gauntlets_owned(false);
        assert!(HotBoundary::try_to_canonical(&stale, &catalog).is_err());
        let plain = HotBoundary::catalog_from_canonical(&document).unwrap();
        assert!(
            !HotBoundary::from_canonical(&document, &plain)
                .unwrap()
                .fanouts
                .spiked_gauntlets_owned()
        );
        gauntlets.player.remove("curious");
        assert!(
            maybe_refuse(&gauntlets).is_none_or(|refusal| !refusal.contains(
                MissingCapability::ArgumentShape("Curious energy-cost listener order")
            ))
        );
    }

