    #[test]
    fn black_hole_terminal_order_refuses_only_uncertified_roots() {
        const ORDER_REFUSAL: MissingCapability =
            MissingCapability::ArgumentShape("terminal star/orb AfterEnergyReset order");
        let has_order_refusal = |document: &CanonicalStateV2| {
            let catalog = HotBoundary::catalog_from_canonical(document).unwrap();
            let state = HotBoundary::from_canonical(document, &catalog).unwrap();
            admit(document, &state, &catalog)
                .err()
                .is_some_and(|refusal| refusal.contains(ORDER_REFUSAL))
        };
        let star_document = || {
            let (mut document, _, _) = parts();
            document
                .player
                .insert("black_hole".to_owned(), Value::from(1));
            append_singleton_after_card_played_row(&mut document, PowerId::BlackHole);
            document.player.insert("genesis".to_owned(), Value::from(1));
            document
                .player
                .insert("star_energy_reset_order".to_owned(), json!(["genesis"]));
            document
        };

        let safe = star_document();
        assert!(!has_order_refusal(&safe));

        let mut radiance = star_document();
        radiance
            .player
            .insert("radiance".to_owned(), Value::from(1));
        assert!(has_order_refusal(&radiance));

        // Potion/card reachability participates in the same future-closure
        // proof. In particular, acquisition order is observable when the
        // belt can publish Radiance before a reachable Genesis is played.
        //
        // #2669: a belted RadiantTincture is only reachable, not live, so
        // the only live listener is Genesis and the unified ledger infers
        // the certified singleton [Genesis]. The root admits; using the
        // potion later appends Radiance explicitly, keeping the future
        // walk certified too.
        let mut radiant_belt = star_document();
        radiant_belt.player.insert(
            "potion_slots".to_owned(),
            json!([PotionId::RadiantTincture.as_str()]),
        );
        radiant_belt.player.insert(
            "potions".to_owned(),
            json!([PotionId::RadiantTincture.as_str()]),
        );
        radiant_belt
            .player
            .insert("fully_unlocked_potion_pool".to_owned(), json!(true));
        assert!(!has_order_refusal(&radiant_belt));

        // #2669: the hand Genesis is only reachable, not live, so the only
        // live listener is Radiance and the ledger infers the certified
        // singleton [Radiance]. Playing Genesis later appends explicitly.
        let mut future_genesis = parts().0;
        future_genesis
            .player
            .insert("black_hole".to_owned(), Value::from(1));
        append_singleton_after_card_played_row(&mut future_genesis, PowerId::BlackHole);
        future_genesis
            .player
            .insert("radiance".to_owned(), Value::from(1));
        replace_first_hand_card(&mut future_genesis, CardId::Genesis, 0);
        assert!(!has_order_refusal(&future_genesis));

        // #2669: likewise, a peer card in hand is not a live listener. The
        // only live listener is Genesis ([Genesis] inferred), so these
        // admit; attaching the peer later appends it explicitly.
        for peer in [CardId::ChargeBattery, CardId::LightningRod, CardId::Spinner] {
            let mut future_peer = star_document();
            replace_first_hand_card(&mut future_peer, peer, 0);
            assert!(!has_order_refusal(&future_peer), "future peer {peer:?}");
        }

        let mut future_black_hole = parts().0;
        future_black_hole
            .player
            .insert("genesis".to_owned(), Value::from(1));
        future_black_hole
            .player
            .insert("star_energy_reset_order".to_owned(), json!(["genesis"]));
        future_black_hole
            .player
            .insert("radiance".to_owned(), Value::from(1));
        replace_first_hand_card(&mut future_black_hole, CardId::BlackHole, 0);
        assert!(has_order_refusal(&future_black_hole));

        // Python's legacy Lightning Rod fallback is effective even when the
        // raw acquisition-order field is absent. Keep admission and the live
        // orb walk on the same helper so this cannot silently admit again.
        let mut lightning_rod = star_document();
        lightning_rod
            .player
            .insert("lightning_rod".to_owned(), Value::from(1));
        assert!(!lightning_rod.player.contains_key("orb_energy_reset_order"));
        assert!(has_order_refusal(&lightning_rod));

        let mut spinner = star_document();
        spinner.player.insert("spinner".to_owned(), Value::from(1));
        spinner
            .player
            .insert("orb_energy_reset_order".to_owned(), json!(["spinner"]));
        assert!(has_order_refusal(&spinner));

        // This power is still refused by its own registry gate, but pin the
        // interaction before the scheduled EnergyNextTurn batch admits it.
        let mut energy_next_turn = star_document();
        energy_next_turn
            .player
            .insert("energy_next_turn".to_owned(), Value::from(1));
        assert!(has_order_refusal(&energy_next_turn));

        let mut no_black_hole = lightning_rod.clone();
        no_black_hole.player.remove("black_hole");
        no_black_hole.player.remove("after_card_played_power_order");
        assert!(!has_order_refusal(&no_black_hole));

        let mut no_star_reader = lightning_rod;
        no_star_reader.player.remove("genesis");
        no_star_reader.player.remove("star_energy_reset_order");
        assert!(!has_order_refusal(&no_star_reader));
    }

    #[test]
    fn legacy_empty_charge_battery_cold_reload_then_genesis_stays_admitted_and_ordered() {
        let (mut entry, _, _) = parts();
        replace_first_hand_card(&mut entry, CardId::ChargeBattery, 0);
        let genesis = &mut entry.piles.get_mut("hand").unwrap()[1];
        genesis.id = CardId::Genesis.as_str().to_owned();
        genesis.upgrade = 0;
        assert!(!entry.player.contains_key("after_energy_reset_order"));

        let catalog = HotBoundary::catalog_from_canonical(&entry).unwrap();
        let mut warm = HotBoundary::from_canonical(&entry, &catalog).unwrap();
        assert_eq!(admit(&entry, &warm, &catalog), Ok(()));
        let charge_uid = warm.piles.get(PileId::Hand).as_slice()[0].uid;
        warm = crate::engine::apply_action(
            &warm,
            &catalog,
            &crate::engine::Action::Play {
                uid: charge_uid,
                target: None,
                selection: crate::engine::SelectionRef::NONE,
            },
        )
        .unwrap()
        .state;
        assert_eq!(
            warm.fanouts.after_energy_reset_order(),
            Some(&[crate::hot::AfterEnergyResetPower::EnergyNextTurn][..])
        );
        assert!(!warm.fanouts.after_energy_reset_order_is_explicit());

        let cold_document = HotBoundary::try_to_canonical(&warm, &catalog).unwrap();
        assert!(
            !cold_document
                .player
                .contains_key("after_energy_reset_order")
        );
        let cold_catalog = HotBoundary::catalog_from_canonical(&cold_document).unwrap();
        let mut cold = HotBoundary::from_canonical(&cold_document, &cold_catalog).unwrap();
        assert_eq!(
            HotBoundary::try_to_canonical(&cold, &cold_catalog).unwrap(),
            cold_document
        );
        assert_eq!(admit(&cold_document, &cold, &cold_catalog), Ok(()));

        let genesis_uid = cold
            .piles
            .get(PileId::Hand)
            .as_slice()
            .iter()
            .find(|card| cold_catalog.spec(card.atom).unwrap().identity.id == CardId::Genesis)
            .unwrap()
            .uid;
        cold = crate::engine::apply_action(
            &cold,
            &cold_catalog,
            &crate::engine::Action::Play {
                uid: genesis_uid,
                target: None,
                selection: crate::engine::SelectionRef::NONE,
            },
        )
        .unwrap()
        .state;
        assert_eq!(
            cold.fanouts.after_energy_reset_order(),
            Some(
                &[
                    crate::hot::AfterEnergyResetPower::EnergyNextTurn,
                    crate::hot::AfterEnergyResetPower::Genesis,
                ][..]
            )
        );
        assert!(cold.fanouts.after_energy_reset_order_is_explicit());
        let final_document = HotBoundary::try_to_canonical(&cold, &cold_catalog).unwrap();
        let final_catalog = HotBoundary::catalog_from_canonical(&final_document).unwrap();
        let reloaded = HotBoundary::from_canonical(&final_document, &final_catalog).unwrap();
        assert_eq!(
            HotBoundary::try_to_canonical(&reloaded, &final_catalog).unwrap(),
            final_document
        );
        assert_eq!(admit(&final_document, &reloaded, &final_catalog), Ok(()));
    }

    #[test]
    fn legacy_mixed_reset_order_normalizes_when_the_public_turn_consumes_to_singleton() {
        let (mut document, _, _) = parts();
        document.player.insert("genesis".to_owned(), Value::from(1));
        document
            .player
            .insert("energy_next_turn".to_owned(), Value::from(2));
        document
            .player
            .insert("star_energy_reset_order".to_owned(), json!(["genesis"]));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(state.fanouts.after_energy_reset_order(), None);
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        state = crate::engine::apply_action(&state, &catalog, &crate::engine::Action::EndTurn)
            .unwrap()
            .state;
        assert_eq!(
            state.fanouts.after_energy_reset_order(),
            Some(&[crate::hot::AfterEnergyResetPower::Genesis][..])
        );
        assert!(!state.fanouts.after_energy_reset_order_is_explicit());
        let cold_document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        assert!(
            !cold_document
                .player
                .contains_key("after_energy_reset_order")
        );
        let cold_catalog = HotBoundary::catalog_from_canonical(&cold_document).unwrap();
        let reloaded = HotBoundary::from_canonical(&cold_document, &cold_catalog).unwrap();
        assert_eq!(
            HotBoundary::try_to_canonical(&reloaded, &cold_catalog).unwrap(),
            cold_document
        );
        assert_eq!(admit(&cold_document, &reloaded, &cold_catalog), Ok(()));
    }

    #[test]
    fn public_end_turn_owner_death_cannot_resurrect_lightning_rod_or_reset_orders() {
        let document: CanonicalStateV2 =
            serde_json::from_str(include_str!("../../fixtures/ea6_reset_owner_death.json"))
                .unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let ended = crate::engine::apply_action(&state, &catalog, &crate::engine::Action::EndTurn)
            .unwrap()
            .state;
        assert!(ended.history.over);
        assert!(ended.fanouts.player_hooks_deactivated());
        assert_eq!(ended.powers.value(PowerId::LightningRod), 0);
        assert!(ended.orbs.reset_order().is_empty());
        // This fixture is a legacy inferred Rod root. Actual removal restores
        // its absence rather than manufacturing an explicit empty wire fact.
        assert_eq!(ended.fanouts.after_energy_reset_order(), None);
        let projected = HotBoundary::try_to_canonical(&ended, &catalog).unwrap();
        assert!(!projected.player.contains_key("after_energy_reset_order"));
    }

    #[test]
    fn public_end_turn_reset_death_controls_preserve_prevention_and_illusion_veto() {
        for (fixture, expected_rod, hooks_deactivated) in [
            ("../../fixtures/ea6_reset_owner_lizard_tail.json", 1, false),
            ("../../fixtures/ea6_reset_owner_illusion.json", 2, true),
        ] {
            let text = match fixture {
                "../../fixtures/ea6_reset_owner_lizard_tail.json" => {
                    include_str!("../../fixtures/ea6_reset_owner_lizard_tail.json")
                }
                "../../fixtures/ea6_reset_owner_illusion.json" => {
                    include_str!("../../fixtures/ea6_reset_owner_illusion.json")
                }
                _ => unreachable!(),
            };
            let document: CanonicalStateV2 = serde_json::from_str(text).unwrap();
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(admit(&document, &state, &catalog), Ok(()));
            let ended =
                crate::engine::apply_action(&state, &catalog, &crate::engine::Action::EndTurn)
                    .unwrap()
                    .state;
            assert_eq!(ended.powers.value(PowerId::LightningRod), expected_rod);
            assert_eq!(ended.fanouts.player_hooks_deactivated(), hooks_deactivated);
            assert_eq!(
                ended.fanouts.after_energy_reset_order(),
                Some(&[crate::hot::AfterEnergyResetPower::LightningRod][..])
            );
            assert_eq!(
                ended.orbs.reset_order(),
                &[crate::hot::OrbResetPower::LightningRod]
            );
        }
    }

