    #[test]
    fn foregone_admits_its_persisted_choice_population() {
        let (mut document, _, _) = parts();
        let first = document.piles.get("hand").unwrap()[0].clone();
        let second = document.piles.get("hand").unwrap()[1].clone();
        for pile in ["hand", "draw", "discard"] {
            document.piles.get_mut(pile).unwrap().clear();
        }
        document.piles.get_mut("draw").unwrap().push(first.clone());
        document
            .player
            .insert("foregone".to_owned(), Value::from(1));
        document.player.insert(
            "before_hand_draw_power_order".to_owned(),
            json!(["foregone"]),
        );

        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
        assert_eq!(admit(&document, &state, &catalog), Ok(()));
        assert!(IMPLEMENTED_PLAYER_POWERS.contains(&PowerId::Foregone));

        for (label, mutate) in [
            (
                "orphan",
                (|candidate: &mut CanonicalStateV2| {
                    candidate.player.remove("foregone");
                }) as fn(&mut CanonicalStateV2),
            ),
            ("bool wire", |candidate: &mut CanonicalStateV2| {
                candidate
                    .player
                    .insert("foregone".to_owned(), Value::from(true));
            }),
            ("negative", |candidate: &mut CanonicalStateV2| {
                candidate
                    .player
                    .insert("foregone".to_owned(), Value::from(-1));
            }),
        ] {
            let mut malformed = document.clone();
            mutate(&mut malformed);
            assert!(
                refuse(&malformed).contains(MissingCapability::ArgumentShape(
                    "before-hand-draw power order"
                )),
                "{label} escaped the shared exact order validator"
            );
        }

        document
            .piles
            .get_mut("discard")
            .unwrap()
            .push(second.clone());
        assert_admits(&document);

        document.player.remove("foregone");
        document.player.remove("before_hand_draw_power_order");
        document.piles.get_mut("discard").unwrap().clear();
        document.piles.get_mut("draw").unwrap()[0].id = "FOREGONE_CONCLUSION".to_owned();
        document.piles.get_mut("draw").unwrap()[0].upgrade = 0;
        document
            .piles
            .get_mut("discard")
            .unwrap()
            .push(second.clone());
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let mut third = second;
        third.uid = Some(third.uid.unwrap() + 100);
        document.piles.get_mut("hand").unwrap().push(third);
        assert_admits(&document);
    }

