    #[test]
    fn hit_hook_powers_admit_exact_ordered_compositions_with_osty() {
        for field in [
            "buffer",
            "colossus",
            "flame_barrier",
            "intangible",
            "reflect",
            "rupture",
            "the_gambit",
            "thorns",
        ] {
            let (mut document, _, _) = parts();
            document.player.insert(field.to_owned(), Value::from(1));
            if field == PowerId::Rupture.as_str() {
                append_singleton_after_card_played_row(&mut document, PowerId::Rupture);
            }
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
            assert_eq!(admit(&document, &state, &catalog), Ok(()), "{field}");

            document.player.insert(field.to_owned(), Value::from(-1));
            if field == PowerId::Rupture.as_str() {
                document.player.remove("after_card_played_power_order");
                document.player.remove("next_after_side_turn_end_power_uid");
            }
            assert!(
                refuse(&document)
                    .missing()
                    .any(|item| matches!(item, MissingCapability::PowerState(_))),
                "negative {field} did not refuse"
            );
        }

        for field in ["flame_barrier", "reflect", "the_gambit"] {
            let (mut document, _, _) = parts();
            document
                .player
                .insert("ally".to_owned(), serde_json::json!(["OSTY", 3, 5]));
            document.player.insert(field.to_owned(), Value::from(1));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(
                admit(&document, &state, &catalog),
                Ok(()),
                "live Osty + {field}"
            );
        }

        let osty_writers = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                row.steps.iter().any(|step| {
                    matches!(
                        step.kind,
                        StepKind::OstySummonHeal
                            | StepKind::DirgeXExact
                            | StepKind::DevourLife
                            | StepKind::Summon
                    )
                })
            })
            .collect::<Vec<_>>();
        assert_eq!(osty_writers.len(), 18, "complete live-Osty writer census");
        for row in osty_writers {
            let (mut document, _, _) = parts();
            document
                .player
                .insert("flame_barrier".to_owned(), Value::from(1));
            let writer = &mut document.piles.get_mut("hand").unwrap()[0];
            writer.id = row.id.as_str().to_owned();
            writer.upgrade = i64::from(row.upgrade);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(
                admit(&document, &state, &catalog),
                Ok(()),
                "{}+{} future Osty",
                row.id.as_str(),
                row.upgrade
            );
        }

        let (mut document, _, _) = parts();
        document
            .player
            .insert("flame_barrier".to_owned(), Value::from(4));
        document.player.insert("reflect".to_owned(), Value::from(1));
        document.player.insert(
            "after_damage_received_power_order".to_owned(),
            serde_json::json!(["reflect", "flame_barrier"]),
        );
        assert_admits(&document);

        let (mut document, _, _) = parts();
        let first = &mut document.piles.get_mut("hand").unwrap()[0];
        first.id = "FLAME_BARRIER".to_owned();
        first.upgrade = 0;
        let second = &mut document.piles.get_mut("hand").unwrap()[1];
        second.id = "REFLECT".to_owned();
        second.upgrade = 0;
        assert_admits(&document);

        let (mut document, _, _) = parts();
        document.player.insert("rupture".to_owned(), Value::from(1));
        append_singleton_after_card_played_row(&mut document, PowerId::Rupture);
        let card = &mut document.piles.get_mut("hand").unwrap()[0];
        card.id = "BLOODLETTING".to_owned();
        card.upgrade = 0;
        // #3298: the originless path batches active-card Rupture itself.
        assert_admits(&document);

        let (mut document, _, _) = parts();
        add_minimal_party(&mut document);
        let first = &mut document.piles.get_mut("hand").unwrap()[0];
        first.id = "RUPTURE".to_owned();
        first.upgrade = 0;
        let second = &mut document.piles.get_mut("hand").unwrap()[1];
        second.id = "DEMONIC_SHIELD".to_owned();
        second.upgrade = 0;
        // The complete Demonic Shield composite publishes its preceding
        // active-card HpLoss, which Rupture now batches (#3298).
        assert_admits(&document);
    }

