    #[test]
    fn card_event_powers_admit_only_with_complete_order_and_private_state() {
        for (field, site) in [
            ("speedster", "after-card-drawn power order"),
            ("feel_no_pain", "after-card-exhausted power order"),
            ("infinite_blades", "before-hand-draw power order"),
        ] {
            let (mut document, _, _) = parts();
            document.player.insert(field.to_owned(), Value::from(1));
            assert!(
                refuse(&document).contains(MissingCapability::ArgumentShape(site)),
                "cold legacy singleton {field} was admitted without its native order"
            );
        }

        let (mut document, _, _) = parts();
        for (field, value) in [
            ("afterimage", 1),
            ("automation", 1),
            ("cacophony", 3),
            ("corrosive_wave", 2),
            ("danse_macabre", 4),
            ("dark_embrace", 1),
            ("feel_no_pain", 3),
            ("infinite_blades", 1),
            ("iteration", 1),
            ("pagestorm", 1),
            ("pale_blue_dot", 1),
            ("rage", 3),
            ("sneaky", 1),
            ("speedster", 2),
            ("spirit_of_ash", 4),
            ("subroutine", 1),
        ] {
            document.player.insert(field.to_owned(), Value::from(value));
        }
        for power in [PowerId::Afterimage, PowerId::Sneaky, PowerId::Subroutine] {
            append_singleton_after_card_played_row(&mut document, power);
        }
        document.player.insert(
            "after_card_drawn_power_order".to_owned(),
            json!([
                "speedster",
                "corrosive_wave",
                "automation",
                "cacophony",
                "pagestorm",
                "iteration"
            ]),
        );
        document.player.insert(
            "after_card_exhausted_power_order".to_owned(),
            json!(["feel_no_pain", "dark_embrace"]),
        );
        document.player.insert(
            "before_hand_draw_power_order".to_owned(),
            json!(["infinite_blades"]),
        );
        append_singleton_side_end_rows(
            &mut document,
            [
                PowerId::CorrosiveWave,
                PowerId::DarkEmbrace,
                PowerId::PaleBlueDot,
                PowerId::Rage,
            ],
        );
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let (mut panache_only, _, _) = parts();
        panache_only
            .player
            .insert("panache".to_owned(), Value::from(10));
        panache_only
            .player
            .insert("panache_instances".to_owned(), json!([[0, 10, 5, true]]));
        panache_only.player.insert(
            "next_after_side_turn_end_power_uid".to_owned(),
            Value::from(1),
        );
        panache_only.player.insert(
            "after_side_turn_end_power_order".to_owned(),
            json!([["panache", 0]]),
        );
        panache_only.player.insert(
            "after_card_played_power_order".to_owned(),
            json!([["panache", 0]]),
        );
        assert_admits(&panache_only);

        let mut mixed = panache_only;
        mixed.player.insert("afterimage".to_owned(), Value::from(1));
        append_singleton_after_card_played_row(&mut mixed, PowerId::Afterimage);
        assert_admits(&mixed);

        let (mut document, _, _) = parts();
        document
            .player
            .insert("automation".to_owned(), Value::from(1));
        document
            .player
            .insert("pagestorm".to_owned(), Value::from(1));
        assert!(refuse(&document).contains(MissingCapability::ArgumentShape(
            "after-card-drawn power order"
        )));

        let (mut document, _, _) = parts();
        document
            .player
            .insert("automation_left".to_owned(), Value::from(0));
        assert!(
            refuse(&document).contains(MissingCapability::ArgumentShape("automation countdown"))
        );

        // #3021: two live Automation objects, the later one out of step.
        let (mut two_automations, _, _) = parts();
        two_automations
            .player
            .insert("automation".to_owned(), Value::from(2));
        two_automations
            .player
            .insert("automation_left".to_owned(), Value::from(4));
        two_automations
            .player
            .insert("automation_later_instances".to_owned(), json!([[1, 9]]));
        two_automations.player.insert(
            "after_card_drawn_power_order".to_owned(),
            json!(["automation"]),
        );
        assert_admits(&two_automations);
        // The later rows may not claim the whole scalar: the first object
        // would have no amount of its own.
        let mut rows_exceed_scalar = two_automations.clone();
        rows_exceed_scalar
            .player
            .insert("automation".to_owned(), Value::from(1));
        assert!(
            refuse(&rows_exceed_scalar)
                .contains(MissingCapability::ArgumentShape("automation instances"))
        );

        let (mut document, _, _) = parts();
        document
            .player
            .insert("cacophony_resets_completed".to_owned(), Value::from(-1));
        assert!(refuse(&document).contains(MissingCapability::ArgumentShape(
            "cacophony reset generation"
        )));

        let (mut document, _, _) = parts();
        document
            .player
            .insert("dark_embrace_ethereal".to_owned(), Value::from(1));
        assert!(refuse(&document).contains(MissingCapability::ArgumentShape(
            "dark embrace ethereal tally"
        )));

        let (mut document, _, _) = parts();
        document.player.insert("storm".to_owned(), Value::from(1));
        document
            .player
            .insert("panache".to_owned(), Value::from(10));
        document
            .player
            .insert("panache_instances".to_owned(), json!([[0, 10, 5, true]]));
        document.player.insert(
            "next_after_side_turn_end_power_uid".to_owned(),
            Value::from(1),
        );
        document.player.insert(
            "after_side_turn_end_power_order".to_owned(),
            json!([["panache", 0]]),
        );
        document.player.insert(
            "after_card_played_power_order".to_owned(),
            json!([["panache", 0], ["storm", 1]]),
        );
        document.player.insert(
            "next_after_side_turn_end_power_uid".to_owned(),
            Value::from(2),
        );
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));

        let (mut document, _, _) = parts();
        let mut storm = document.piles["hand"][0].clone();
        storm.id = "STORM".to_owned();
        storm.uid = Some(100);
        let mut panache = storm.clone();
        panache.id = "PANACHE".to_owned();
        panache.uid = Some(101);
        document
            .piles
            .get_mut("hand")
            .unwrap()
            .extend([storm, panache]);
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));
    }

    #[test]
    fn unkeyed_turn_start_peer_orders_refuse_but_aggression_retain_and_amount_admit() {
        let unkeyed_boundary_refuses = |document: &CanonicalStateV2| {
            let catalog = HotBoundary::catalog_from_canonical(document).unwrap();
            HotBoundary::from_canonical(document, &catalog).is_err()
        };
        let (mut document, _, _) = parts();
        document.player.insert("loop".to_owned(), Value::from(1));
        document
            .player
            .insert("rolling_boulder".to_owned(), Value::from(5));
        assert!(unkeyed_boundary_refuses(&document));

        // Current source has exactly the two row-derived writes plus one read
        // of each field in the inactive-side validation added by #1931. This
        // census must expand before any modifier can broaden the reachable
        // pair domain below; the extra spelling is not another writer.
        // (Measured on the frozen v0.111.0 source: one `crimson_mantle +=
        // step[1]` and one `crimson_self += 1` writer, 4 and 7 total
        // spellings. The re-count against `combat_sim.py` was retired with
        // the Python simulator, #2827 item D; the source is frozen.)

        for (amount, self_damage) in [(7, 1), (10, 1), (14, 2), (17, 2), (20, 2)] {
            let (mut document, _, _) = parts();
            document
                .player
                .insert("crimson_mantle".to_owned(), Value::from(amount));
            document
                .player
                .insert("crimson_self".to_owned(), Value::from(self_damage));
            document.player.insert(
                "after_player_turn_start_power_order".to_owned(),
                json!(["crimson_mantle"]),
            );
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let hot = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(admit(&document, &hot, &catalog), Ok(()));
            assert_eq!(hot.powers.value(PowerId::CrimsonMantle), amount);
            assert_eq!(hot.powers.value(PowerId::CrimsonSelf), self_damage);
            assert_eq!(HotBoundary::to_canonical(&hot, &catalog), document);
        }
        for (amount, self_damage) in [(0, 1), (7, 0), (8, 1), (13, 2), (21, 2)] {
            let (mut document, _, _) = parts();
            if amount != 0 {
                document
                    .player
                    .insert("crimson_mantle".to_owned(), Value::from(amount));
            }
            if self_damage != 0 {
                document
                    .player
                    .insert("crimson_self".to_owned(), Value::from(self_damage));
            }
            if amount != 0 {
                document.player.insert(
                    "after_player_turn_start_power_order".to_owned(),
                    json!(["crimson_mantle"]),
                );
            }
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let refused = match HotBoundary::from_canonical(&document, &catalog) {
                Ok(state) => admit(&document, &state, &catalog).is_err(),
                Err(_) => true,
            };
            assert!(
                refused,
                "impossible pair ({amount}, {self_damage}) admitted"
            );
        }

        let (mut document, _, _) = parts();
        document
            .player
            .insert("crimson_mantle".to_owned(), Value::from(7));
        document
            .player
            .insert("crimson_self".to_owned(), Value::from(1));

        document.player.insert("inferno".to_owned(), Value::from(6));
        document
            .player
            .insert("inferno_self".to_owned(), Value::from(1));
        assert!(unkeyed_boundary_refuses(&document));

        // Crimson's body intentionally stores the two hot fields directly;
        // any live native AfterPowerAmountChanged observer therefore refuses
        // before manual or nested AutoPlay can mutate the source or energy.
        for upgrade in 0..=1 {
            let (mut document, _, _) = parts();
            replace_first_hand_card(&mut document, CardId::CrimsonMantle, upgrade);
            document.player.insert("shroud".to_owned(), Value::from(1));
            document.player.insert(
                "after_power_amount_changed_power_order".to_owned(),
                json!(["shroud"]),
            );
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            let before = state.clone();
            let refusal = admit(&document, &state, &catalog).unwrap_err();
            assert!(refusal.contains(MissingCapability::ArgumentShape(
                "Crimson Mantle power application listener order"
            )));
            assert_eq!(state, before, "listener refusal must be read-only");
        }

        let exact_local_rows: Vec<_> = crate::content_tables::CARD_ROWS
            .iter()
            .filter(|row| {
                row.steps.iter().any(|step| {
                    matches!(
                        step.kind,
                        StepKind::CreativeAi
                            | StepKind::Feral
                            | StepKind::NecroMastery
                            | StepKind::TrashToTreasure
                    )
                })
            })
            .collect();
        assert_eq!(
            exact_local_rows
                .iter()
                .map(|row| (row.id, row.upgrade))
                .collect::<Vec<_>>(),
            [
                (CardId::CreativeAi, 0),
                (CardId::CreativeAi, 1),
                (CardId::Feral, 0),
                (CardId::Feral, 1),
                (CardId::NecroMastery, 0),
                (CardId::NecroMastery, 1),
                (CardId::TrashToTreasure, 0),
                (CardId::TrashToTreasure, 1),
            ],
            "the direct exact-power writer census drifted"
        );
        for row in exact_local_rows {
            for (observer, field) in [
                (PowerId::Shroud, "shroud"),
                (PowerId::SleightOfFlesh, "sleight_of_flesh"),
            ] {
                let (mut document, _, _) = parts();
                replace_first_hand_card(&mut document, row.id, i64::from(row.upgrade));
                document.player.insert(field.to_owned(), Value::from(1));
                document.player.insert(
                    "after_power_amount_changed_power_order".to_owned(),
                    json!([observer.as_str()]),
                );
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                let before = state.clone();
                let refusal = admit(&document, &state, &catalog).unwrap_err();
                assert!(refusal.contains(MissingCapability::ArgumentShape(
                    "exact local power application listener order"
                )));
                assert_eq!(state, before, "listener refusal must be read-only");
            }
        }

        let (mut document, _, _) = parts();
        document.player.insert("loop".to_owned(), Value::from(1));
        document.player.insert(
            "after_player_turn_start_power_order".to_owned(),
            json!(["loop"]),
        );
        let mut crimson = document.piles["hand"][0].clone();
        crimson.id = CardId::CrimsonMantle.as_str().to_owned();
        crimson.uid = Some(100);
        document.piles.get_mut("hand").unwrap().push(crimson);
        assert_admits(&document);

        let (mut document, _, _) = parts();
        document
            .player
            .insert("aggression".to_owned(), Value::from(1));
        document
            .player
            .insert("well_laid_plans".to_owned(), Value::from(true));
        assert_admits(&document);

        let (mut document, _, _) = parts();
        document
            .player
            .insert("aggression".to_owned(), Value::from(1));
        document
            .player
            .insert("retain_hand".to_owned(), Value::from(1));
        append_singleton_side_end_row(&mut document, PowerId::RetainHand);
        assert_admits(&document);

        for (id, local_retain, transient_retain) in [
            (CardId::Purity, false, false),
            (CardId::SculptingStrike, false, false),
            (CardId::SculptingStrike, true, false),
            (CardId::SculptingStrike, false, true),
        ] {
            let (mut document, _, _) = parts();
            document
                .player
                .insert("aggression".to_owned(), Value::from(1));
            let carrier = &mut document.piles.get_mut("hand").unwrap()[0];
            carrier.id = id.as_str().to_owned();
            if local_retain {
                carrier.local_keywords = vec!["Retain".to_owned()];
            }
            if transient_retain {
                carrier.transient_keywords = vec!["Retain".to_owned()];
            }
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(
                admit(&document, &state, &catalog),
                Ok(()),
                "{} retain carrier must admit with Aggression",
                id.as_str()
            );
        }

        let (mut document, _, _) = parts();
        document
            .player
            .insert("aggression".to_owned(), Value::from(11));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(admit(&document, &state, &catalog), Ok(()));
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
    }

    #[test]
    fn hibernate_admission_closes_exact_rows_power_and_every_unkeyed_peer() {
        const HIBERNATE_ORDER: MissingCapability =
            MissingCapability::ArgumentShape("Hibernate AfterPlayerTurnStart order");

        for upgrade in 0..=1 {
            let (mut document, _, _) = parts();
            add_minimal_party(&mut document);
            replace_first_hand_card(&mut document, CardId::Hibernate, upgrade);
            assert_admits(&document);

            let mut live = document.clone();
            live.player.insert("hibernate".to_owned(), Value::from(2));
            assert_admits(&live);
            let catalog = HotBoundary::catalog_from_canonical(&live).unwrap();
            let state = HotBoundary::from_canonical(&live, &catalog).unwrap();
            assert_eq!(state.powers.value(PowerId::Hibernate), 2);
            assert_eq!(HotBoundary::to_canonical(&state, &catalog), live);

            let mut negative = document.clone();
            negative
                .player
                .insert("hibernate".to_owned(), Value::from(-1));
            assert!(refuse(&negative).contains(MissingCapability::PowerState(PowerId::Hibernate)));

            let mut summon = document.clone();
            summon
                .player
                .insert("summon_next_turn".to_owned(), Value::from(2));
            summon.player.insert(
                "after_player_turn_start_power_order".to_owned(),
                json!(["summon_next_turn"]),
            );
            assert_admits(&summon);
        }

        for (field, amount, companion) in [
            ("loop", 1, None),
            ("rolling_boulder", 5, None),
            ("entropy", 1, None),
            ("tools_of_the_trade", 1, None),
            ("tyranny", 1, None),
            ("inferno", 6, Some(("inferno_self", 1))),
            ("crimson_mantle", 7, Some(("crimson_self", 1))),
        ] {
            let (mut document, _, _) = parts();
            add_minimal_party(&mut document);
            replace_first_hand_card(&mut document, CardId::Hibernate, 0);
            document
                .player
                .insert(field.to_owned(), Value::from(amount));
            if let Some((companion, amount)) = companion {
                document
                    .player
                    .insert(companion.to_owned(), Value::from(amount));
            }
            if matches!(
                field,
                "loop" | "rolling_boulder" | "inferno" | "crimson_mantle"
            ) {
                document.player.insert(
                    "after_player_turn_start_power_order".to_owned(),
                    json!([field]),
                );
            } else if matches!(field, "tools_of_the_trade" | "tyranny") {
                document
                    .player
                    .insert("turn_start_hand_choice_order".to_owned(), json!([field]));
            }
            assert!(
                refuse(&document).contains(HIBERNATE_ORDER),
                "live peer {field} escaped Hibernate's order wall"
            );
        }

        for orphan in ["inferno_self", "crimson_self"] {
            let (mut document, _, _) = parts();
            add_minimal_party(&mut document);
            replace_first_hand_card(&mut document, CardId::Hibernate, 0);
            document.player.insert(orphan.to_owned(), Value::from(1));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            assert!(
                HotBoundary::from_canonical(&document, &catalog).is_err(),
                "composite orphan {orphan} escaped the exact ordered boundary"
            );
        }

        for peer in [
            CardId::Loop,
            CardId::RollingBoulder,
            CardId::Entropy,
            CardId::ToolsOfTheTrade,
            CardId::Tyranny,
            CardId::Inferno,
            CardId::CrimsonMantle,
        ] {
            let (mut document, _, _) = parts();
            add_minimal_party(&mut document);
            replace_first_hand_card(&mut document, CardId::Hibernate, 0);
            let mut future = document.piles["hand"][0].clone();
            future.id = peer.as_str().to_owned();
            future.upgrade = 0;
            future.uid = Some(2780);
            document.piles.get_mut("hand").unwrap().push(future);
            assert!(
                refuse(&document).contains(HIBERNATE_ORDER),
                "future peer {peer:?} escaped Hibernate's source-derived wall"
            );

            let (mut live_hibernate, _, _) = parts();
            live_hibernate
                .player
                .insert("hibernate".to_owned(), Value::from(2));
            let mut future = live_hibernate.piles["hand"][0].clone();
            future.id = peer.as_str().to_owned();
            future.upgrade = 0;
            future.uid = Some(2781);
            live_hibernate.piles.get_mut("hand").unwrap().push(future);
            assert!(
                refuse(&live_hibernate).contains(HIBERNATE_ORDER),
                "live Hibernate with future peer {peer:?} escaped the symmetric wall"
            );
        }

        let (mut observed, _, _) = parts();
        add_minimal_party(&mut observed);
        replace_first_hand_card(&mut observed, CardId::Hibernate, 0);
        observed.player.insert("shroud".to_owned(), Value::from(1));
        observed.player.insert(
            "after_power_amount_changed_power_order".to_owned(),
            json!(["shroud"]),
        );
        assert_admits(&observed);
    }

    #[test]
    fn tools_and_tyranny_share_the_full_summon_carrier_symmetrically() {
        for choice in [CardId::ToolsOfTheTrade, CardId::Tyranny] {
            let power = match choice {
                CardId::ToolsOfTheTrade => PowerId::ToolsOfTheTrade,
                CardId::Tyranny => PowerId::Tyranny,
                _ => unreachable!("loop contains only choice cards"),
            };
            // A reachable choice writer plus live Summon is admitted because
            // the full carrier now preserves either later application.
            let (mut source_choice, _, _) = parts();
            add_minimal_party(&mut source_choice);
            replace_first_hand_card(&mut source_choice, choice, 0);
            source_choice
                .player
                .insert("summon_next_turn".to_owned(), Value::from(2));
            source_choice.player.insert(
                "after_player_turn_start_power_order".to_owned(),
                json!(["summon_next_turn"]),
            );
            assert_admits(&source_choice);

            // The converse live-choice/source-Summon shape is refused by the
            // same source-derived guard before Invoke can mutate either
            // power. This is carrier exactness, not a native ordering claim.
            let (mut live_choice, _, _) = parts();
            add_minimal_party(&mut live_choice);
            replace_first_hand_card(&mut live_choice, CardId::Invoke, 0);
            live_choice
                .player
                .insert(power.as_str().to_owned(), Value::from(1));
            live_choice.player.insert(
                "turn_start_hand_choice_order".to_owned(),
                json!([power.as_str()]),
            );
            let catalog = HotBoundary::catalog_from_canonical(&live_choice).unwrap();
            let state = HotBoundary::from_canonical(&live_choice, &catalog)
                .unwrap_or_else(|error| panic!("{choice:?}: {error:?}"));
            assert_eq!(admit(&live_choice, &state, &catalog), Ok(()));
        }
    }

    #[test]
    fn choice_carrier_validation_preserves_legacy_only_states_and_refuses_orphans() {
        for (field, amount, companion) in [
            ("summon_next_turn", 2, None),
            ("inferno", 6, Some(("inferno_self", 1))),
            ("crimson_mantle", 7, Some(("crimson_self", 1))),
        ] {
            let (mut legacy, _, _) = parts();
            legacy.player.insert(field.to_owned(), Value::from(amount));
            if let Some((companion, amount)) = companion {
                legacy
                    .player
                    .insert(companion.to_owned(), Value::from(amount));
            }
            // With exactly one live listener the old wireless shape proves a
            // unique order; boundary migration materializes the hot carrier
            // before admission validates it.
            assert_admits(&legacy);
        }

        for field in ["tools_of_the_trade", "tyranny"] {
            let (mut legacy, _, _) = parts();
            legacy.player.insert(field.to_owned(), Value::from(1));
            assert_admits(&legacy);
        }

        let (mut ambiguous_live, _, _) = parts();
        ambiguous_live
            .player
            .insert("loop".to_owned(), Value::from(1));
        ambiguous_live
            .player
            .insert("tools_of_the_trade".to_owned(), Value::from(1));
        let catalog = HotBoundary::catalog_from_canonical(&ambiguous_live).unwrap();
        assert!(HotBoundary::from_canonical(&ambiguous_live, &catalog).is_err());

        for field in ["tools_of_the_trade", "tyranny"] {
            let (mut orphan, _, _) = parts();
            orphan
                .player
                .insert("turn_start_hand_choice_order".to_owned(), json!([field]));
            assert!(
                HotBoundary::catalog_from_canonical(&orphan)
                    .and_then(|catalog| HotBoundary::from_canonical(&orphan, &catalog))
                    .is_err(),
                "orphaned {field} carrier row admitted"
            );
        }

        let (mut both_families, _, _) = parts();
        both_families
            .player
            .insert("summon_next_turn".to_owned(), Value::from(1));
        both_families.player.insert(
            "after_player_turn_start_power_order".to_owned(),
            json!(["summon_next_turn"]),
        );
        both_families.player.insert(
            "turn_start_hand_choice_order".to_owned(),
            json!(["tools_of_the_trade"]),
        );
        assert!(
            HotBoundary::from_canonical(
                &both_families,
                &HotBoundary::catalog_from_canonical(&both_families).unwrap(),
            )
            .is_err()
        );
    }

    #[test]
    fn summon_next_turn_and_each_ordered_or_future_turn_start_peer_admit() {
        let (mut summon_only, _, _) = parts();
        summon_only
            .player
            .insert("summon_next_turn".to_owned(), Value::from(2));
        summon_only.player.insert(
            "after_player_turn_start_power_order".to_owned(),
            json!(["summon_next_turn"]),
        );
        assert_admits(&summon_only);
        let catalog = HotBoundary::catalog_from_canonical(&summon_only).unwrap();
        let hot = HotBoundary::from_canonical(&summon_only, &catalog).unwrap();
        assert_eq!(hot.powers.value(PowerId::SummonNextTurn), 2);
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), summon_only);

        for peer in [
            CardId::Loop,
            CardId::RollingBoulder,
            CardId::Inferno,
            CardId::CrimsonMantle,
        ] {
            let mut live_pair = summon_only.clone();
            match peer {
                CardId::Loop => {
                    live_pair.player.insert("loop".to_owned(), Value::from(1));
                }
                CardId::RollingBoulder => {
                    live_pair
                        .player
                        .insert("rolling_boulder".to_owned(), Value::from(5));
                }
                CardId::Inferno => {
                    live_pair
                        .player
                        .insert("inferno".to_owned(), Value::from(6));
                    live_pair
                        .player
                        .insert("inferno_self".to_owned(), Value::from(1));
                }
                CardId::CrimsonMantle => {
                    live_pair
                        .player
                        .insert("crimson_mantle".to_owned(), Value::from(7));
                    live_pair
                        .player
                        .insert("crimson_self".to_owned(), Value::from(1));
                }
                _ => unreachable!(),
            }
            let peer_wire = match peer {
                CardId::Loop => "loop",
                CardId::RollingBoulder => "rolling_boulder",
                CardId::Inferno => "inferno",
                CardId::CrimsonMantle => "crimson_mantle",
                _ => unreachable!(),
            };
            live_pair.player.insert(
                "after_player_turn_start_power_order".to_owned(),
                json!(["summon_next_turn", peer_wire]),
            );
            assert_admits(&live_pair);

            let mut catalog_pair = summon_only.clone();
            let mut peer_card = catalog_pair.piles["hand"][0].clone();
            peer_card.id = peer.as_str().to_owned();
            peer_card.uid = Some(700 + peer as u64);
            catalog_pair.piles.get_mut("hand").unwrap().push(peer_card);
            assert_admits(&catalog_pair);

            let (mut invoke_pair, _, _) = parts();
            let mut invoke = invoke_pair.piles["hand"][0].clone();
            invoke.id = CardId::Invoke.as_str().to_owned();
            invoke.uid = Some(800);
            let mut peer_card = invoke.clone();
            peer_card.id = peer.as_str().to_owned();
            peer_card.uid = Some(801 + peer as u64);
            invoke_pair
                .piles
                .get_mut("hand")
                .unwrap()
                .extend([invoke, peer_card]);
            assert_admits(&invoke_pair);
        }
    }

